export type SalonEmployeeAccess = {
  user: typeof usersTable.$inferSelect;
  employee: typeof employeesTable.$inferSelect;
  salon: typeof salonsTable.$inferSelect;
};

/**
 * Resolves an employee's current location independently of the legacy
 * employees.salonId column. The latter remains the historic location, while
 * employee_location_assignments is the sole authorization source for a
 * multi-location employee.
 */
async function resolveActiveEmployeeSalon(employeeId: string, selectedSalonId: string | null) {
  if (selectedSalonId) {
    const [selected] = await db.select().from(employeeLocationAssignmentsTable).where(and(
      eq(employeeLocationAssignmentsTable.employeeId, employeeId),
      eq(employeeLocationAssignmentsTable.salonId, selectedSalonId),
      eq(employeeLocationAssignmentsTable.active, true),
    )).limit(1);
    if (selected) {
      const [salon] = await db.select().from(salonsTable).where(eq(salonsTable.id, selected.salonId)).limit(1);
      if (salon) return salon;
    }
  }
  const [assignment] = await db.select().from(employeeLocationAssignmentsTable)
    .where(and(
      eq(employeeLocationAssignmentsTable.employeeId, employeeId),
      eq(employeeLocationAssignmentsTable.active, true),
    ))
    .orderBy(
      desc(employeeLocationAssignmentsTable.isDefault),
      asc(employeeLocationAssignmentsTable.createdAt),
      asc(employeeLocationAssignmentsTable.salonId),
    )
    .limit(1);
  if (!assignment) return null;

  const [salon] = await db.select().from(salonsTable)
    .where(eq(salonsTable.id, assignment.salonId))
    .limit(1);
  return salon ?? null;
}

export async function requireSalonEmployee(req: Request, res: Response): Promise<SalonEmployeeAccess | null> {
  const user = await current(req, res);
  if (!user) return null;
  if (user.role !== "SALON_EMPLOYEE") {
    res.status(403).json({ error: "Ova funkcija je dostupna samo zaposlenima salona." });
    return null;
  }
  if (user.mustChangePassword) {
    res.status(428).json({ error: "Promenite privremenu lozinku pre pristupa portalu.", code: "PASSWORD_CHANGE_REQUIRED" });
    return null;
  }
  const [employee] = await db.select().from(employeesTable)
    .where(and(eq(employeesTable.userId, user.id), eq(employeesTable.active, true))).limit(1);
  if (!employee) {
    res.status(403).json({ error: "Nalog zaposlenog nije povezan sa aktivnim profilom." });
    return null;
  }
  // Employees never inherit an owner's activeSalonId. Their portal is pinned to
  // their active default assignment (with a deterministic assigned fallback).
  const salon = await resolveActiveEmployeeSalon(employee.id, user.activeSalonId);
  if (!salon) {
    res.status(403).json({ error: "Profil zaposlenog nije povezan sa salonom." });
    return null;
  }
  return { user, employee, salon };
}

router.get("/employee/locations", async (req, res): Promise<void> => {
  const access = await requireSalonEmployee(req, res); if (!access) return;
  const rows = await db.select({
    salonId: salonsTable.id, name: salonsTable.name, active: employeeLocationAssignmentsTable.active,
    isDefault: employeeLocationAssignmentsTable.isDefault,
  }).from(employeeLocationAssignmentsTable)
    .innerJoin(salonsTable, eq(salonsTable.id, employeeLocationAssignmentsTable.salonId))
    .where(and(eq(employeeLocationAssignmentsTable.employeeId, access.employee.id), eq(employeeLocationAssignmentsTable.active, true)))
    .orderBy(desc(employeeLocationAssignmentsTable.isDefault), asc(salonsTable.name));
  res.json({ activeSalonId: access.salon.id, locations: rows.map((row) => ({ salonId: row.salonId, name: row.name, isDefault: row.isDefault })) });
});

router.patch("/employee/active-location", async (req, res): Promise<void> => {
  const access = await requireSalonEmployee(req, res); if (!access) return;
  const salonId = req.body?.salonId;
  if (typeof salonId !== "string") { res.status(400).json({ error: "salonId je obavezan." }); return; }
  const [assignment] = await db.select({ salonId: employeeLocationAssignmentsTable.salonId })
    .from(employeeLocationAssignmentsTable).where(and(
      eq(employeeLocationAssignmentsTable.employeeId, access.employee.id),
      eq(employeeLocationAssignmentsTable.salonId, salonId),
      eq(employeeLocationAssignmentsTable.active, true),
    )).limit(1);
  if (!assignment) { res.status(403).json({ error: "Zaposleni nije aktivno raspoređen na ovu lokaciju." }); return; }
  await db.update(usersTable).set({ activeSalonId: salonId, updatedAt: new Date() }).where(eq(usersTable.id, access.user.id));
  res.json({ activeSalonId: salonId });
});

type ShopAccess = {
  user: typeof usersTable.$inferSelect;
  salon: typeof salonsTable.$inferSelect;
  employee: typeof employeesTable.$inferSelect | null;
};

async function requireShopAccess(req: Request, res: Response): Promise<ShopAccess | null> {
  const user = await current(req, res);
  if (!user) return null;
  if (user.role === "SALON_OWNER") {
    const salon = await ownedSalon(user.id);
    if (!salon) {
      res.status(403).json({ error: "Nalog nije povezan sa salonom." });
      return null;
    }
    return { user, salon, employee: null };
  }
  if (user.role !== "SALON_EMPLOYEE") {
    res.status(403).json({ error: "Ova funkcija je dostupna salonima i njihovim zaposlenima." });
    return null;
  }
  if (user.mustChangePassword) {
    res.status(428).json({ error: "Promenite privremenu lozinku pre pristupa portalu.", code: "PASSWORD_CHANGE_REQUIRED" });
    return null;
  }
  const [employee] = await db.select().from(employeesTable)
    .where(and(eq(employeesTable.userId, user.id), eq(employeesTable.active, true))).limit(1);
  if (!employee) {
    res.status(403).json({ error: "Nalog zaposlenog nije povezan sa aktivnim profilom." });
    return null;
  }
  // Keep shop operations in precisely the same assignment-scoped location as
  // the employee portal; employees.salonId is a legacy/historic location and
  // must never authorize a fallback here.
  const salon = await resolveActiveEmployeeSalon(employee.id, user.activeSalonId);
  if (!salon) {
    res.status(403).json({ error: "Profil zaposlenog nije povezan sa salonom." });
    return null;
  }
  return { user, salon, employee };
}

function card(
  salon: typeof salonsTable.$inferSelect,
  services: (typeof servicesTable.$inferSelect)[] = [],
  hours: (typeof salonHoursTable.$inferSelect)[] = [],
  earliestSlot: string | null = null,
  lastBookedAtOverride?: Date | null,
) {
  const lastBookedAt = lastBookedAtOverride ?? null;
  return {
    id: salon.id,
    slug: salon.slug,
    name: salon.name,
    city: salon.city,
    municipality: salon.municipality,
    imageUrl: salon.imageUrl,
    rating: salon.rating / 10,
    reviewCount: salon.reviewCount,
    shortDescription: salon.shortDescription,
    popularServices: services.slice(0, 3).map((item) => item.name),
    startingPrice: services.length ? Math.min(...services.map((item) => item.promoPrice ?? item.price)) : 0,
    earliestSlot,
    homeService: services.some((service) => service.active && service.homeServiceAvailable),
    featured: salon.featured,
    isVerified: salon.isVerified,
    topSalon: salon.topSalon,
    acceptsCards: salon.acceptsCards,
    instantBooking: salon.instantBooking,
    servesMen: salon.servesMen,
    hasDiscount: services.some((item) => item.promoPrice !== null && item.promoPrice < item.price),
    openSunday: hours.some((item) => item.weekday === 7 && !item.closed),
    lastBookedAt: safeIsoTimestamp(lastBookedAt),
    createdAt: safeIsoTimestamp(salon.createdAt),
  };
}

async function salonHasActiveHomeService(salonId: string): Promise<boolean> {
  const [service] = await db.select({ id: servicesTable.id }).from(servicesTable).where(and(
    eq(servicesTable.salonId, salonId),
    eq(servicesTable.active, true),
    eq(servicesTable.homeServiceAvailable, true),
  )).limit(1);
  return Boolean(service);
}

const SALON_CARD_LOOK_BACK_DAYS = 90;

async function salonCards(
  salons: (typeof salonsTable.$inferSelect)[],
  earliestSlotBySalon: ReadonlyMap<string, string | null> = new Map(),
) {
  if (!salons.length) return [];
  const ids = salons.map((salon) => salon.id);
  const lastBookedSince = new Date(Date.now() - SALON_CARD_LOOK_BACK_DAYS * 24 * 60 * 60 * 1000);
  const [allServices, allHours, lastBookedRows, paidPlacementRows] = await Promise.all([
    db.select().from(servicesTable).where(and(inArray(servicesTable.salonId, ids), eq(servicesTable.active, true))),
    db.select().from(salonHoursTable).where(inArray(salonHoursTable.salonId, ids)),
    db.select({ salonId: appointmentsTable.salonId, lastBookedAt: sql<Date | null>`max(${appointmentsTable.createdAt})` })
      .from(appointmentsTable)
      .where(and(inArray(appointmentsTable.salonId, ids), gte(appointmentsTable.createdAt, lastBookedSince)))
      .groupBy(appointmentsTable.salonId),
    db.select({ salonId: educationPlacementsTable.salonId }).from(educationPlacementsTable).where(and(
      inArray(educationPlacementsTable.salonId, ids),
      eq(educationPlacementsTable.kind, "featured_salon"),
      eq(educationPlacementsTable.status, "active"),
      lte(educationPlacementsTable.startsAt, new Date()),
      gt(educationPlacementsTable.endsAt, new Date()),
    )),
  ]);
  // Replace per-salon array filters with grouped maps so card assembly stays
  // O(n) instead of O(salons * appointments).
  const servicesBySalon = groupBySalon(allServices);
  const hoursBySalon = groupBySalon(allHours);
  const lastBookedBySalon = new Map<string, Date | null>();
  for (const row of lastBookedRows) lastBookedBySalon.set(row.salonId, row.lastBookedAt ? new Date(row.lastBookedAt) : null);
  const paidFeaturedSalonIds = new Set(paidPlacementRows.flatMap((row) => row.salonId ? [row.salonId] : []));
  return salons.map((salon) => ({
    ...card(
    salon,
    servicesBySalon.get(salon.id) ?? [],
    hoursBySalon.get(salon.id) ?? [],
    earliestSlotBySalon.get(salon.id) ?? null,
    lastBookedBySalon.get(salon.id) ?? null,
    ),
    featured: paidFeaturedSalonIds.has(salon.id),
  }));
}

function groupBySalon<T extends { salonId: string }>(rows: T[]): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const row of rows) {
    const bucket = map.get(row.salonId);
    if (bucket) bucket.push(row); else map.set(row.salonId, [row]);
  }
  return map;
}

