const integrationDefinitions: Record<IntegrationName, { keys: string[]; required: string[] }> = {
  sms: { keys: ["apiKey", "senderName", "baseUrl", "webhookSecret"], required: ["apiKey", "senderName"] },
  brevo: { keys: ["apiKey", "senderEmail", "senderName", "webhookSecret"], required: ["apiKey", "senderEmail"] },
  google_oauth: { keys: ["clientId", "clientSecret"], required: ["clientId", "clientSecret"] },
  facebook_oauth: { keys: ["clientId", "clientSecret"], required: ["clientId", "clientSecret"] },
  cloudflare: { keys: ["apiKey", "zoneId", "domain"], required: ["apiKey", "zoneId", "domain"] },
  web_push: { keys: ["publicKey", "privateKey", "subject"], required: ["publicKey", "privateKey", "subject"] },
};

function integrationName(value: string): value is IntegrationName {
  return value in integrationDefinitions;
}

async function webhookConfirmationMetadata(integration: "sms" | "brevo") {
  const verifiedAt = await webhookVerifiedAt(integration);
  return {
    webhookVerifiedAt: verifiedAt?.toISOString() ?? null,
    webhookVerificationStale: webhookVerificationIsStale(verifiedAt),
    webhookConfirmationMaxAgeDays: WEBHOOK_CONFIRMATION_MAX_AGE_DAYS,
    ...(integration === "brevo" ? { brevoRegistrationMissingEvents: await brevoRegistrationMissingEvents() } : {}),
  };
}

function requestOrigin(req: Request) {
  const host = req.get("host") ?? "localhost";
  return `${req.protocol}://${host}`;
}

router.get("/admin/integrations", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const [entries, deliveryReportsByProvider, reachableAdmins] = await Promise.all([
    Promise.all(Object.entries(integrationDefinitions).map(async ([name, definition]) => {
      const webhookIntegration = name === "sms" || name === "brevo" ? name : null;
      return [
        name,
        {
          ...(await integrationDisplay(name as IntegrationName, definition.keys, definition.required)),
          // Persisted server-side, so the "secret changed, registration not yet
          // re-confirmed" reminder survives page reloads and later sessions.
          ...(webhookIntegration
            ? {
              webhookSecretPendingReconfirmation: await webhookSecretPendingReconfirmation(webhookIntegration),
              ...(await webhookConfirmationMetadata(webhookIntegration)),
            }
            : {}),
        },
      ];
    })),
    deliveryReportStatuses(),
    smsFallbackReachableAdmins(),
  ]);
  // Standing registration verdict for the Infobip delivery-report webhook —
  // Infobip's API cannot list the configured report URL, so the verdict is
  // derived from verifiable evidence (secret age vs. accepted real reports
  // vs. report silence). See smsWebhookRegistrationState.
  const smsWebhookRegistration = await smsWebhookRegistrationStatus(deliveryReportsByProvider.infobip);
  const origin = normalizedRequestOrigin(req);
  const redirectUriWarning = oauthRedirectUriWarning(origin);
  res.json({
    integrations: Object.fromEntries(entries),
    deliveryReports: {
      providers: deliveryReportsByProvider,
      windowHours: DELIVERY_REPORT_WINDOW_HOURS,
      graceMinutes: DELIVERY_REPORT_GRACE_MINUTES,
      rejectionAlertThreshold: WEBHOOK_REJECTION_ALERT_THRESHOLD,
    },
    // Emergency-SMS audience health: how many active administrators the
    // total-email-outage SMS fallback could reach (same audience + phone
    // predicate as the send path). Zero → the admin panel shows a standing
    // warning to add a phone number, because a total email outage would
    // otherwise degrade to an unseen log line.
    smsFallback: {
      reachableAdminCount: reachableAdmins.length,
      reachableAdmins,
    },
    smsWebhookRegistration,
    redirectUris: {
      google: `${origin}/api/auth/oauth/google/callback`,
      facebook: `${origin}/api/auth/oauth/facebook/callback`,
    },
    ...(redirectUriWarning ? { redirectUriWarning } : {}),
    smsReminder: {
      command: "pnpm --filter @workspace/scripts run sms-reminders",
      active: false,
      instructions: [
        "U Replit Deployments izaberite Create deployment, zatim Scheduled deployment.",
        "Podesite jutarnji raspored, na primer 08:00 po vremenu Beograda.",
        "Kao komandu unesite prikazanu komandu ispod.",
        "Dodajte LUMERA_API_BASE_URL i SMS_REMINDER_JOB_SECRET u podešavanja scheduled deployment-a.",
      ],
    },
  });
});

