router.put("/admin/integrations/:integration", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  if (!integrationName(req.params.integration)) { res.status(404).json({ error: "Nepoznata integracija." }); return; }
  const body = req.body as { enabled?: unknown; values?: unknown; expectedVersion?: unknown };
  if (typeof body.enabled !== "boolean" || !body.values || typeof body.values !== "object" || Array.isArray(body.values)
    || (typeof body.expectedVersion !== "string" && body.expectedVersion !== null)) {
    res.status(400).json({ error: "Pošaljite enabled vrednost, verziju učitanih podešavanja i polja integracije." }); return;
  }
  const definition = integrationDefinitions[req.params.integration];
  const submittedValues = Object.entries(body.values as Record<string, unknown>)
    .filter(([key, value]) => definition.keys.includes(key) && typeof value === "string");
  if (submittedValues.some(([, value]) => (value as string).length > 0 && !(value as string).trim())) {
    res.status(400).json({ error: "Vrednosti integracije ne mogu sadržati samo razmake." }); return;
  }
  const values = Object.fromEntries(submittedValues
    .filter(([key, value]) => definition.keys.includes(key) && typeof value === "string")
    .map(([key, value]) => [key, value as string]));
  if (req.params.integration === "sms" && values.baseUrl) {
    try { infobipBaseUrl(values.baseUrl); } catch (error) { res.status(400).json({ error: error instanceof Error ? error.message : "SMS base URL nije ispravan." }); return; }
  }
  if (req.params.integration === "web_push") {
    const currentSettings = await integrationSettings("web_push");
    const nonBlankValues = Object.fromEntries(
      Object.entries(values).filter(([, value]) => value.trim().length > 0),
    );
    const effectiveValues = {
      ...(currentSettings.configuredInDatabase ? {} : {
        publicKey: process.env["VAPID_PUBLIC_KEY"],
        privateKey: process.env["VAPID_PRIVATE_KEY"],
        subject: process.env["VAPID_SUBJECT"],
      }),
      ...currentSettings.values,
      ...nonBlankValues,
    };
    const configuration = parseWebPushConfiguration(effectiveValues);
    if (body.enabled && !configuration.configured) {
      res.status(400).json({ error: `Web Push konfiguracija nije ispravna: ${configuration.reason}.` });
      return;
    }
  }
  // A saved webhookSecret that differs from the EFFECTIVE secret (database or
  // env fallback) invalidates the URL registered at the provider. Persist that
  // moment so the re-registration reminder survives reloads; re-saving an
  // identical secret changes nothing and must not raise the reminder.
  const webhookIntegration = req.params.integration === "sms" || req.params.integration === "brevo" ? req.params.integration : null;
  try {
    await saveIntegrationSettings({
      integration: req.params.integration,
      enabled: body.enabled,
      values,
      updatedByUserId: user.id,
      expectedVersion: body.expectedVersion,
    });
  } catch (error) {
    if (error instanceof IntegrationSettingsVersionConflictError) {
      res.status(409).json({
        error: error.message,
        code: error.code,
        expectedVersion: error.expectedVersion,
        currentVersion: error.currentVersion,
      });
      return;
    }
    throw error;
  }
  res.json({
    ...(await integrationDisplay(req.params.integration, definition.keys, definition.required)),
    ...(webhookIntegration
      ? {
        webhookSecretPendingReconfirmation: await webhookSecretPendingReconfirmation(webhookIntegration),
        ...(await webhookConfirmationMetadata(webhookIntegration)),
      }
      : {}),
  });
});

router.post("/admin/integrations/:integration/test", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  if (!integrationName(req.params.integration)) { res.status(404).json({ error: "Nepoznata integracija." }); return; }
  const recipient = typeof req.body?.recipient === "string" ? req.body.recipient.trim() : "";
  try {
    if (req.params.integration === "sms") {
      if (!recipient) { res.status(400).json({ error: "Unesite broj za test SMS." }); return; }
      await sendTestSms(recipient);
      res.json({ message: "Test SMS je poslat." }); return;
    }
    if (req.params.integration === "brevo") {
      if (!recipient || !recipient.includes("@")) { res.status(400).json({ error: "Unesite ispravnu e-mail adresu za test." }); return; }
      const result = await sendTransactionalEmail({
        eventKey: `integration-test-email:${Date.now()}`, emailType: "integration_test", to: { email: recipient, name: "LUMERA administrator" },
        subject: "LUMERA — test Brevo integracije", htmlContent: lumeraEmailHtml("Test e-mail", "<p>Brevo integracija je uspešno povezana.</p>"),
      });
      if ("failed" in result || "skipped" in result) throw new Error("Brevo nije poslao test e-mail. Proverite podešavanja.");
      res.json({ message: "Test e-mail je poslat." }); return;
    }
    if (req.params.integration === "web_push") {
      const configuration = await webPushConfiguration();
      if (!configuration.configured) throw new Error(`Web Push konfiguracija nije spremna: ${configuration.reason}.`);
      res.json({ message: "Web Push konfiguracija je potpuna i aktivna." }); return;
    }
    if (req.params.integration === "cloudflare") {
      const [apiKey, zoneId, domain] = await Promise.all([
        integrationValue("cloudflare", "apiKey"),
        integrationValue("cloudflare", "zoneId"),
        integrationValue("cloudflare", "domain"),
      ]);
      if (!apiKey || !zoneId || !domain) throw new Error("Sačuvajte i aktivirajte Cloudflare API ključ, Zone ID i javni domen pre provere.");
      if (!/^[a-f0-9]{32}$/i.test(zoneId)) throw new Error("Cloudflare Zone ID mora sadržati 32 heksadecimalna znaka.");
      let parsedDomain: URL;
      try { parsedDomain = new URL(domain); } catch { throw new Error("Javni domen mora biti ispravan HTTPS URL."); }
      if (parsedDomain.protocol !== "https:" || parsedDomain.username || parsedDomain.password || parsedDomain.pathname !== "/" || parsedDomain.search || parsedDomain.hash) {
        throw new Error("Javni domen mora biti bezbedan HTTPS URL bez putanje.");
      }
      res.json({ message: "Cloudflare konfiguracija je sačuvana. Brisanje CDN keša će se izvršiti pri deaktivaciji salona." }); return;
    }
    const config = await integrationSettings(req.params.integration);
    const definition = integrationDefinitions[req.params.integration];
    if (!config.enabled || !definition.required.every((key) => Boolean(config.values[key]))) throw new Error("Popunite i aktivirajte obavezna OAuth polja pre testa.");
    res.json({ message: "OAuth konfiguracija je potpuna. Redirect URI je spreman za unos kod provajdera." });
  } catch (error) {
    res.status(400).json({ error: error instanceof Error ? error.message : "Test integracije nije uspeo." });
  }
});

/**
 * Admin webhook self-check ("Proveri webhook"): posts one synthetic delivery
 * event to the app's OWN provider webhook endpoint over the loopback
 * interface, using the currently saved webhook secret as the path token. This
 * exercises the full production path — routing, JSON body parsing, the
 * timing-safe token comparison, and event processing — end to end, without
 * weakening security (no token-check bypass) and without touching delivery
 * state (the synthetic reference can never match a persisted outbound send,
 * and verification-only batches never count as provider delivery reports).
 */
/**
 * Loopback webhook self-check shared by the "Proveri webhook" button and the
 * SMS registration check: posts one synthetic delivery event to the app's own
 * provider webhook endpoint with the currently saved secret, exercising
 * routing, JSON parsing, the timing-safe token comparison, and event
 * processing end to end. Returns a Serbian error when any step fails.
 */
async function runWebhookSelfCheck(
  req: Request,
  integration: "sms" | "brevo",
  secret: string,
): Promise<{ ok: true } | { ok: false; error: string }> {
  const webhookPath = integration === "sms" ? "infobip" : "brevo";
  // Unmatched by construction: no persisted outbound send ever carries this
  // reference, so the synthetic event cannot alter any delivery state.
  const reference = `${WEBHOOK_VERIFICATION_REFERENCE_PREFIX}${randomUUID()}`;
  const payload = integration === "sms"
    ? { results: [{ messageId: reference, status: { groupName: "DELIVERED", name: "DELIVERED_TO_HANDSET" }, doneAt: new Date().toISOString() }] }
    : [{ event: "delivered", "message-id": reference, ts_event: Math.floor(Date.now() / 1000) }];

  // Loopback to the same bound server this admin request arrived on — works
  // identically in development and in the production deployment.
  const localPort = req.socket.localPort;
  if (!localPort) return { ok: false, error: "Provera nije moguća: port servera nije poznat. Pokušajte ponovo." };
  let response: globalThis.Response;
  try {
    response = await fetch(`http://127.0.0.1:${localPort}/api/webhooks/${webhookPath}/${encodeURIComponent(secret)}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(10_000),
    });
  } catch {
    return { ok: false, error: "Webhook endpoint nije odgovorio na probni događaj. Proverite da li aplikacija radi, pa pokušajte ponovo." };
  }

  const body = await response.json().catch(() => null) as Record<string, unknown> | null;
  if (response.status === 401) {
    return { ok: false, error: "Webhook endpoint je odbio sačuvanu tajnu. Sačuvajte webhook tajnu ponovo, pa kod provajdera registrujte URL sa istom tajnom." };
  }
  if (response.status === 503) {
    return { ok: false, error: "Webhook endpoint prijavljuje da tajna nije konfigurisana. Sačuvajte webhook tajnu, pa pokušajte ponovo." };
  }
  if (!response.ok || !body || body["processed"] !== 1 || body["unmatched"] !== 1) {
    return { ok: false, error: `Webhook endpoint nije prihvatio probni događaj (status ${response.status}). Proverite podešavanja, pa pokušajte ponovo.` };
  }
  return { ok: true };
}

router.post("/admin/integrations/:integration/verify-webhook", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const integration = req.params.integration;
  if (integration !== "sms" && integration !== "brevo") {
    res.status(404).json({ error: "Provera webhook-a je dostupna samo za SMS i Brevo integracije." }); return;
  }
  const secret = await resolveWebhookSecret(integration);
  if (!secret) {
    res.status(400).json({ error: "Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo." }); return;
  }
  const selfCheck = await runWebhookSelfCheck(req, integration, secret);
  if (!selfCheck.ok) { res.status(502).json({ error: selfCheck.error }); return; }
  // Successful self-check re-confirms the current secret — clear the persisted
  // "secret changed, registration not re-confirmed" reminder.
  await markWebhookReconfirmed(integration, user.id);
  const confirmedAt = await webhookVerifiedAt(integration);
  res.json({
    message: integration === "sms"
      ? "Infobip webhook radi: sačuvana tajna se poklapa i endpoint prihvata izveštaje o isporuci. Probni događaj nije promenio nijednu isporuku."
      : "Brevo webhook radi: sačuvana tajna se poklapa i endpoint prihvata događaje. Probni događaj nije promenio nijednu isporuku.",
    webhookVerifiedAt: confirmedAt?.toISOString() ?? null,
    webhookVerificationStale: false,
    webhookConfirmationMaxAgeDays: WEBHOOK_CONFIRMATION_MAX_AGE_DAYS,
  });
});

/**
 * Admin copy helper: returns the COMPLETE provider webhook URL with the
 * currently saved secret substituted, so admins never assemble it by hand
 * (hand-assembly is the main source of URL/secret mismatches). The secret is
 * only returned on demand to an authenticated admin; the page fetches it on
 * click and copies it without persistently rendering it.
 */
router.get("/admin/integrations/:integration/webhook-url", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const integration = req.params.integration;
  if (integration !== "sms" && integration !== "brevo") {
    res.status(404).json({ error: "Webhook URL je dostupan samo za SMS i Brevo integracije." }); return;
  }
  const secret = await resolveWebhookSecret(integration);
  if (!secret) {
    res.status(400).json({ error: "Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo." }); return;
  }
  const webhookPath = integration === "sms" ? "infobip" : "brevo";
  const origin = normalizedRequestOrigin(req);
  // The URL is assembled from the address the admin is browsing from. From a
  // development/preview address that is the development URL — registering it
  // at the provider would redirect production delivery reports to the
  // preview, so the response carries an explicit warning the page surfaces.
  const warning = isDevelopmentBrowsingOrigin(origin)
    ? `Ovaj URL sadrži razvojnu adresu sa koje trenutno pristupate (${origin}). Ne registrujte ga kod provajdera za objavljenu aplikaciju — izveštaji o isporuci bi prestali da stižu u produkciju. Za produkcioni URL otvorite ovu stranicu iz objavljene aplikacije.`
    : null;
  res.json({
    url: `${origin}/api/webhooks/${webhookPath}/${encodeURIComponent(secret)}`,
    ...(warning ? { warning } : {}),
  });
});

/**
 * Admin webhook registration check ("Proveri registraciju na Brevo"): asks the
 * Brevo API (saved apiKey) which transactional webhooks are actually
 * registered at the provider and compares them SERVER-SIDE against this
 * deployment's public webhook URL and the currently saved secret. Complements
 * the loopback self-check above — that proves the app's own endpoint accepts
 * the saved secret, while this catches the failure modes the loopback cannot
 * see: webhook deleted at Brevo, registered for a stale domain, or still
 * carrying an old secret, or subscribed to only a subset of delivery events
 * (a webhook registered with only "delivered" silently drops opens and
 * bounces). The saved secret is never returned; tokens found at Brevo are
 * compared timing-safe and reported only with the token masked.
 */
/**
 * Keep only registrations that look like a LUMERA Brevo webhook URL and
 * classify each by origin + timing-safe secret comparison. The token itself
 * is never echoed back — masked URLs only.
 */
function brevoRegistrationCandidates(webhooks: Array<{ id: number; url: string; events: string[] }>, secret: string) {
  return webhooks.flatMap((hook) => {
    let parsed: URL;
    try { parsed = new URL(hook.url); } catch { return []; }
    const match = /^\/api\/webhooks\/brevo\/([^/]+)\/?$/.exec(parsed.pathname);
    if (!match) return [];
    let token = match[1]!;
    try { token = decodeURIComponent(token); } catch { /* compare raw token */ }
    return [{
      id: hook.id,
      origin: parsed.origin,
      maskedUrl: `${parsed.origin}/api/webhooks/brevo/…`,
      secretMatches: webhookTokenMatches(secret, token),
      events: hook.events,
    }];
  });
}

/**
 * Origins that count as "this deployment" when comparing provider-side
 * registrations. The admin request's own origin is always included; on top of
 * that, REPLIT_DOMAINS lists every public domain the running deployment
 * answers on (in production e.g. the .replit.app domain alongside a custom
 * domain), so a webhook registered for any of them is recognized even when
 * the admin happens to be browsing from a different one.
 */
function deploymentAcceptedOrigins(origin: string): Set<string> {
  const origins = new Set([origin]);
  for (const domain of (process.env["REPLIT_DOMAINS"] ?? "").split(",")) {
    const trimmed = domain.trim();
    if (!trimmed) continue;
    try { origins.add(new URL(`https://${trimmed}`).origin); } catch { /* skip malformed entries */ }
  }
  return origins;
}

/**
 * True when the admin is browsing through a development/preview address
 * (Replit dev preview domain, localhost). Registration verdicts compare
 * provider-side webhook URLs against the request origin, which is correct in
 * production but from a development address would classify a healthy
 * PRODUCTION registration as "wrong domain" — and re-registering it for the
 * development URL would break production delivery reports. Detected from the
 * request host so verdicts can be softened and re-registration instructions
 * suppressed.
 */
function isDevelopmentBrowsingOrigin(origin: string): boolean {
  let hostname: string;
  try { hostname = new URL(origin).hostname; } catch { return false; }
  const devDomain = process.env["REPLIT_DEV_DOMAIN"]?.trim();
  if (devDomain && hostname === devDomain) return true;
  if (hostname.endsWith(".replit.dev")) return true;
  return hostname === "localhost" || hostname === "127.0.0.1" || hostname === "0.0.0.0" || hostname === "::1" || hostname === "[::1]";
}

/** Per-request comparison context shared by the registration check and the
 * one-click registration re-check. */
function brevoVerdictContext(req: Request): { origin: string; acceptedOrigins: Set<string>; developmentOrigin: boolean } {
  const origin = normalizedRequestOrigin(req);
  return { origin, acceptedOrigins: deploymentAcceptedOrigins(origin), developmentOrigin: isDevelopmentBrowsingOrigin(origin) };
}

/**
 * Shared verdict for the registration check and the post-registration
 * re-check: compares the classified candidates against this deployment's
 * accepted origins and reports the exact mismatch in Serbian.
 *
 * When the admin is browsing from a development/preview address the verdict
 * is explicitly relative to that address: a registration carrying the CURRENT
 * secret at another domain is treated as the (most likely healthy) production
 * registration instead of an error, and every failure instruction names the
 * published application's domain placeholder instead of the development URL —
 * so an admin can never be told to re-register a healthy production webhook
 * for the development preview.
 */
function brevoRegistrationVerdict(
  candidates: ReturnType<typeof brevoRegistrationCandidates>,
  context: { origin: string; acceptedOrigins: Set<string>; developmentOrigin: boolean },
): { ok: true; message: string } | { ok: false; error: string; missingEvents?: string[] } {
  const { origin, acceptedOrigins, developmentOrigin } = context;
  const expectedUrlHint = developmentOrigin
    ? "https://<domen-objavljene-aplikacije>/api/webhooks/brevo/<tajna>"
    : `${origin}/api/webhooks/brevo/<tajna>`;
  const devNote = developmentOrigin
    ? ` Napomena: proveru ste pokrenuli sa razvojne adrese (${origin}), pa se poređenje domena i sačuvane tajne odnosi na razvojno okruženje — za pouzdanu presudu pokrenite proveru iz objavljene aplikacije i nemojte registrovati webhook za razvojnu adresu.`
    : "";
  const missingEventsError = (maskedUrl: string | null, missingEvents: string[]) => ({
    ok: false as const,
    error: `Webhook je registrovan na Brevo${maskedUrl ? ` (${maskedUrl})` : " sa ispravnim URL-om i tajnom"}, ali registracija ne prati sve potrebne događaje. Nedostaju: ${missingEvents.join(", ")}. Bez njih se praćenje otvaranja i upozorenja o neisporučenim porukama tiho gube. Ažurirajte registraciju webhook-a na Brevo (Transactional → Settings → Webhooks) i uključite navedene događaje.`,
    missingEvents,
  });
  const matching = candidates.filter((candidate) => candidate.secretMatches && acceptedOrigins.has(candidate.origin));
  if (matching.length) {
    // URL and secret are correct — now confirm the registration subscribes to
    // every delivery event the app processes. Events are unioned across
    // matching registrations: each event only needs ONE registration to
    // deliver it. A partial subscription is a warning, not a hard failure —
    // delivered events may still flow — but it silently degrades open
    // tracking and failure alerts, so it must not read as full success.
    const missingEvents = missingBrevoWebhookEvents(matching.flatMap((candidate) => candidate.events));
    if (missingEvents.length) {
      return missingEventsError(null, missingEvents);
    }
    const devMatchNote = developmentOrigin
      ? ` Napomena: registracija pokazuje na razvojnu adresu sa koje trenutno pristupate (${origin}) — izveštaji o isporuci objavljene aplikacije stižu samo ako je webhook registrovan za njen domen.`
      : "";
    return { ok: true, message: `Webhook je registrovan na Brevo: URL pokazuje na ovu aplikaciju i nosi aktuelnu webhook tajnu.${devMatchNote}` };
  }
  const secretElsewhere = candidates.filter((candidate) => candidate.secretMatches);
  const wrongOrigin = secretElsewhere[0];
  if (wrongOrigin) {
    if (developmentOrigin) {
      // From a development address, a foreign-origin registration carrying
      // the CURRENT secret is in all likelihood the healthy production
      // registration — never instruct re-registering it for the dev URL.
      // The event subscription is still checked: that advice is
      // origin-independent and updating events cannot break delivery.
      const missingEvents = missingBrevoWebhookEvents(secretElsewhere.flatMap((candidate) => candidate.events));
      if (missingEvents.length) {
        return missingEventsError(wrongOrigin.maskedUrl, missingEvents);
      }
      return { ok: true, message: `Webhook sa aktuelnom tajnom je registrovan na Brevo za ${wrongOrigin.maskedUrl}. Proveru ste pokrenuli sa razvojne adrese (${origin}), pa se domen ne može potvrditi odavde — ako je to adresa objavljene aplikacije, registracija je ispravna i nemojte je ponovo registrovati za razvojnu adresu. Za konačnu potvrdu pokrenite proveru iz objavljene aplikacije.` };
    }
    return { ok: false, error: `Webhook sa aktuelnom tajnom postoji na Brevo, ali je registrovan za drugi domen (${wrongOrigin.maskedUrl}). Na Brevo ponovo registrujte URL ${expectedUrlHint} i zamenite <tajna> sačuvanom webhook tajnom.` };
  }
  if (candidates.some((candidate) => acceptedOrigins.has(candidate.origin))) {
    return { ok: false, error: `Na Brevo je registrovan webhook za ovaj domen, ali sa zastarelom tajnom — događaji će biti odbijani. Ažurirajte registraciju na Brevo tako da URL ${expectedUrlHint} nosi sačuvanu webhook tajnu.${devNote}` };
  }
  if (candidates.length) {
    return { ok: false, error: `Na Brevo postoji webhook u LUMERA formatu (${candidates[0]!.maskedUrl}), ali se ni domen ni tajna ne poklapaju sa ovom aplikacijom. Na Brevo registrujte URL ${expectedUrlHint} i zamenite <tajna> sačuvanom webhook tajnom.${devNote}` };
  }
  return { ok: false, error: `Webhook nije registrovan na Brevo. U Brevo podešavanjima (Transactional → Settings → Webhooks) registrujte URL ${expectedUrlHint} i zamenite <tajna> sačuvanom webhook tajnom.${devNote}` };
}

/**
 * LUMERA-format registrations at Brevo that are NOT this deployment's healthy
 * registration (current secret at an accepted origin): leftovers from old
 * domains or old secrets that keep receiving events which are then rejected
 * or lost. Listed to the admin (masked URLs only) after a successful
 * one-click repair, and re-derived fresh before any deletion. From a
 * development/preview address the set is always empty — the development
 * environment's saved secret can differ from production's, so a healthy
 * PRODUCTION registration would be misread as stale and offered for
 * deletion. Non-LUMERA webhooks never appear here: they are filtered out by
 * brevoRegistrationCandidates before classification.
 */
function staleBrevoRegistrations(
  candidates: ReturnType<typeof brevoRegistrationCandidates>,
  context: { acceptedOrigins: Set<string>; developmentOrigin: boolean },
): Array<{ id: number; maskedUrl: string }> {
  if (context.developmentOrigin) return [];
  return candidates
    .filter((candidate) => !(candidate.secretMatches && context.acceptedOrigins.has(candidate.origin)))
    .map((candidate) => ({ id: candidate.id, maskedUrl: candidate.maskedUrl }));
}

/** Normalized public origin of THIS deployment, as seen by the admin request
 * (trust proxy is enabled, so this is the public domain in production). */
function normalizedRequestOrigin(req: Request) {
  try { return new URL(requestOrigin(req)).origin; } catch { return requestOrigin(req); }
}

/** The deployment-owned origin used by production OAuth callbacks. */
function configuredAppOrigin(): string | null {
  const configured = process.env["APP_BASE_URL"]?.trim();
  if (!configured) return null;
  try { return new URL(configured).origin; } catch { return null; }
}

/**
 * Explain which OAuth origin the administrator is looking at without returning
 * any provider credentials. Preview requests keep their existing guidance;
 * production requests additionally detect a stale APP_BASE_URL after a
 * published-domain change.
 */
function oauthRedirectUriWarning(origin: string): string | null {
  if (isDevelopmentBrowsingOrigin(origin)) {
    return `Ove OAuth redirect adrese sadrže razvojnu adresu sa koje trenutno pristupate (${origin}). Ne unosite ih u Google ili Facebook podešavanja za objavljenu aplikaciju — time biste pokvarili prijavu u produkciji. Za produkcioni URL otvorite ovu stranicu iz objavljene aplikacije.`;
  }
  if (process.env.NODE_ENV !== "production") return null;

  const configuredOrigin = configuredAppOrigin();
  if (!configuredOrigin) {
    return "APP_BASE_URL nije validno podešen za produkciju. Pre korišćenja ovog domena podesite APP_BASE_URL i registrujte prikazane Google i Facebook callback adrese kod odgovarajućih provajdera.";
  }
  if (configuredOrigin === origin) return null;
  return `APP_BASE_URL je podešen na ${configuredOrigin}, ali ovu stranicu otvarate sa ${origin}. Pre korišćenja novog domena ažurirajte APP_BASE_URL i Google/Facebook callback registracije na prikazane adrese — u suprotnom prijava društvenim nalozima može prestati da radi.`;
}

/** Shared Serbian error responses for Brevo webhook-listing failures. */
function respondBrevoListingFailure(res: Response, error: unknown) {
  // Local configuration problems (e.g. integration disabled) carry their own
  // Serbian instruction — surface them directly instead of wrapping them in
  // a provider-error message.
  if (error instanceof BrevoConfigurationError) {
    res.status(400).json({ error: error.message }); return;
  }
  const detail = error instanceof Error ? error.message.slice(0, 200) : "nepoznata greška";
  res.status(502).json({ error: `Spisak webhook-ova nije učitan sa Brevo API-ja (${detail}). Proverite Brevo API ključ, pa pokušajte ponovo.` });
}

/**
 * Read the current stale Brevo registrations for an admin-facing refresh.
 * This intentionally shares the same provider listing, candidate filtering,
 * origin rules, and masked response shape as the registration check.
 */
async function readStaleBrevoRegistrations(req: Request) {
  const context = brevoVerdictContext(req);
  // Development/preview must never inspect credentials or provider state:
  // its configuration can differ from production, and a production webhook
  // could otherwise be exposed as a removable leftover. An empty list keeps
  // the page's destructive control unavailable even before Brevo is set up
  // locally.
  if (context.developmentOrigin) return [];
  const secret = await resolveWebhookSecret("brevo");
  if (!secret) {
    throw new BrevoConfigurationError("Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo.");
  }
  const webhooks = await listBrevoTransactionalWebhooks();
  return staleBrevoRegistrations(brevoRegistrationCandidates(webhooks, secret), context);
}

router.get("/admin/integrations/brevo/stale-webhooks", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  try {
    res.json({ staleWebhooks: await readStaleBrevoRegistrations(req) });
  } catch (error) {
    respondBrevoListingFailure(res, error);
  }
});

router.post("/admin/integrations/brevo/verify-registration", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const secret = await resolveWebhookSecret("brevo");
  if (!secret) {
    res.status(400).json({ error: "Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo." }); return;
  }
  let webhooks: Awaited<ReturnType<typeof listBrevoTransactionalWebhooks>>;
  try {
    webhooks = await listBrevoTransactionalWebhooks();
  } catch (error) {
    respondBrevoListingFailure(res, error); return;
  }
  const context = brevoVerdictContext(req);
  const candidates = brevoRegistrationCandidates(webhooks, secret);
  const verdict = brevoRegistrationVerdict(candidates, context);
  const staleWebhooks = staleBrevoRegistrations(candidates, context);
  if (verdict.ok) {
    // A development-origin verdict is intentionally softened: it can
    // recognize the production registration, but the preview cannot prove
    // that this deployment's public origin is the one Brevo will call.
    // Only a strict production-origin success re-confirms the new secret.
    await clearBrevoRegistrationIncomplete();
    if (!context.developmentOrigin) await markWebhookReconfirmed("brevo", user.id);
    res.json({ message: verdict.message, reconfirmed: !context.developmentOrigin, staleWebhooks }); return;
  }
  if (verdict.missingEvents) {
    await markBrevoRegistrationIncomplete(verdict.missingEvents, user.id);
  } else {
    await clearBrevoRegistrationIncomplete();
  }
  // Keep the response structured so the admin-error normalizer preserves the
  // stale list alongside the Serbian conflict message. This lets the page
  // offer cleanup even when the current registration itself still needs repair.
  res.status(409).json({
    error: verdict.error,
    code: "CONFLICT",
    staleWebhooks,
    ...("missingEvents" in verdict ? { missingEvents: verdict.missingEvents } : {}),
  });
});

/**
 * Admin SMS registration check ("Proveri registraciju") — the Infobip
 * counterpart of the Brevo registration check above. Infobip's public API
 * cannot list the account-level delivery-report webhook URL (it is configured
 * in the Infobip portal / by Infobip support), so a provider-side listing is
 * impossible; instead the check combines everything the app CAN verify:
 *   1. the loopback self-check — this deployment's endpoint accepts the saved
 *      secret and processes reports end to end, and
 *   2. the evidence-based registration verdict (smsWebhookRegistrationState):
 *      a real verified report accepted since the secret was last saved proves
 *      Infobip calls this endpoint with the CURRENT secret; silence despite
 *      recent grace-aged sends proves it does not; a report older than the
 *      last secret change flags the stale-token case.
 * A misconfigured or missing registration (409) is therefore always
 * distinguishable from "no recent SMS sends" (200 with verified: false).
 * Failure verdicts name the exact URL shape to configure at Infobip with the
 * <tajna> placeholder — the secret itself is never echoed (admins use
 * „Kopiraj kompletan URL“ for the complete URL). From a development/preview
 * browsing address the instruction names the published-domain placeholder,
 * mirroring the Brevo check, and the verdict is qualified as relative to the
 * development environment (its receipts/sends live in the development
 * database).
 */
router.post("/admin/integrations/sms/verify-registration", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const secret = await resolveWebhookSecret("sms");
  if (!secret) {
    res.status(400).json({ error: "Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo." }); return;
  }
  const origin = normalizedRequestOrigin(req);
  const developmentOrigin = isDevelopmentBrowsingOrigin(origin);
  const expectedUrlHint = developmentOrigin
    ? "https://<domen-objavljene-aplikacije>/api/webhooks/infobip/<tajna>"
    : `${origin}/api/webhooks/infobip/<tajna>`;
  const devNote = developmentOrigin
    ? ` Napomena: proveru ste pokrenuli sa razvojne adrese (${origin}), pa se nalaz odnosi na razvojno okruženje — za pouzdanu presudu pokrenite proveru iz objavljene aplikacije i nemojte registrovati razvojni URL kod Infobip-a.`
    : "";
  const setupInstruction = `Svaka naredna SMS poruka automatski šalje Infobip-u aktuelni delivery-report URL ${expectedUrlHint} sa sačuvanom tajnom, pa će prvi stvarni izveštaj potvrditi prijem. Account-level report URL u Infobip portalu je i dalje podržan za naloge koji ga koriste — upotrebite „Kopiraj kompletan URL“ ako želite da ga podesite unapred. Infobip API ne omogućava aplikaciji da tu portal registraciju očita ili podesi umesto vas.`;

  const selfCheck = await runWebhookSelfCheck(req, "sms", secret);
  if (!selfCheck.ok) {
    res.status(502).json({ error: `Provera registracije nije završena — probni događaj na sopstveni endpoint nije prošao: ${selfCheck.error}` }); return;
  }

  const registration = await smsWebhookRegistrationStatus((await deliveryReportStatuses()).infobip);
  const formatTs = (iso: string) => new Date(iso).toLocaleString("sr-RS", { timeZone: "Europe/Belgrade" });

  if (registration.state === "confirmed") {
    res.json({
      verified: true,
      state: registration.state,
      message: `Registracija na Infobip je potvrđena: endpoint prihvata sačuvanu tajnu (probni događaj je prošao), a Infobip zaista dostavlja izveštaje o isporuci sa aktuelnom tajnom — poslednji stvarni izveštaj je primljen ${formatTs(registration.lastReportAt!)}.${devNote}`,
    }); return;
  }
  if (registration.state === "unconfirmed") {
    res.json({
      verified: false,
      state: registration.state,
      message: `Endpoint i sačuvana tajna rade (probni događaj je prihvaćen), ali registracija kod Infobip-a još nije potvrđena: nema nedavnih automatskih SMS poruka po kojima bi se videlo da Infobip zaista šalje izveštaje. To ne znači da nešto ne radi — potvrda stiže sa prvim stvarnim izveštajem o isporuci. ${setupInstruction}${devNote}`,
    }); return;
  }
  // The 409 bodies carry the structured contract's code themselves so the
  // admin error normalizer passes verified/state through to the panel.
  if (registration.state === "stale_secret") {
    res.status(409).json({
      verified: false,
      state: registration.state,
      code: "CONFLICT",
      error: `Webhook tajna je promenjena ${formatTs(registration.secretSavedAt!)}, a poslednji potvrđeni Infobip izveštaj je stariji (${formatTs(registration.lastReportAt!)}) — registracija kod Infobip-a najverovatnije još nosi staru tajnu, pa endpoint sada odbija izveštaje. ${setupInstruction}${devNote}`,
    }); return;
  }
  // "misconfigured" (recent sends, no reports). "no_secret" is unreachable —
  // the saved secret already resolved above.
  res.status(409).json({
    verified: false,
    state: registration.state,
    code: "CONFLICT",
    error: `Endpoint i sačuvana tajna rade (probni događaj je prihvaćen), ali automatske SMS poruke su nedavno poslate, a Infobip nije dostavio nijedan izveštaj o isporuci u očekivanom roku${registration.lastReportAt ? ` (poslednji stvarni izveštaj: ${formatTs(registration.lastReportAt)})` : " (nijedan stvarni izveštaj do sada)"}. Webhook najverovatnije nije registrovan kod Infobip-a ili pokazuje na pogrešan domen. ${setupInstruction}${devNote}`,
  });
});

/**
 * One-click webhook registration ("Registruj webhook na Brevo"): repairs the
 * provider-side registration directly through the Brevo API instead of
 * sending the admin to the Brevo dashboard. Creates the transactional webhook
 * when no LUMERA-format registration exists, or updates the best-matching
 * existing one in place (same origin first — the stale-secret case — then
 * matching secret on a stale domain, then any LUMERA-format leftover), always
 * pointing it at THIS deployment's URL with the currently saved secret and
 * subscribing every event class the endpoint consumes. The saved secret is
 * used server-side only and never returned. Afterwards the registration check
 * re-runs against a fresh provider listing so the reported outcome reflects
 * what Brevo actually stored, not what we asked for.
 *
 * Refused outright from a development/preview browsing origin, BEFORE any
 * provider contact: the write always targets the requesting origin, so from a
 * dev address the matching-secret fallback could select the healthy
 * PRODUCTION registration and rewrite it to the development URL — silently
 * redirecting production delivery reports to the preview. The read-only
 * verdict softening cannot protect the write path; only refusing to write can.
 */
router.post("/admin/integrations/brevo/register-webhook", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const context = brevoVerdictContext(req);
  if (context.developmentOrigin) {
    res.status(400).json({ error: `Registracija webhook-a je pokrenuta sa razvojne adrese (${context.origin}). Registracija sa razvojne adrese bi mogla da presnimi produkcionu registraciju i preusmeri izveštaje o isporuci na razvojno okruženje, pa je moguća samo iz objavljene aplikacije. Otvorite ovu stranicu iz objavljene aplikacije, pa pokušajte ponovo.` }); return;
  }
  const secret = await resolveWebhookSecret("brevo");
  if (!secret) {
    res.status(400).json({ error: "Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo." }); return;
  }
  let webhooks: Awaited<ReturnType<typeof listBrevoTransactionalWebhooks>>;
  try {
    webhooks = await listBrevoTransactionalWebhooks();
  } catch (error) {
    respondBrevoListingFailure(res, error); return;
  }

  const origin = context.origin;
  const targetUrl = `${origin}/api/webhooks/brevo/${encodeURIComponent(secret)}`;
  const candidates = brevoRegistrationCandidates(webhooks, secret);
  const existing = candidates.find((candidate) => candidate.origin === origin)
    ?? candidates.find((candidate) => candidate.secretMatches)
    ?? candidates[0];

  let action: "registrovan" | "ažuriran";
  try {
    if (existing) {
      await updateBrevoTransactionalWebhook(existing.id, targetUrl);
      action = "ažuriran";
    } else {
      await createBrevoTransactionalWebhook(targetUrl);
      action = "registrovan";
    }
  } catch (error) {
    if (error instanceof BrevoConfigurationError) {
      res.status(400).json({ error: error.message }); return;
    }
    const detail = error instanceof Error ? error.message.slice(0, 200) : "nepoznata greška";
    res.status(502).json({ error: `Registracija webhook-a na Brevo nije uspela (${detail}). Proverite Brevo API ključ, pa pokušajte ponovo.` }); return;
  }

  // Re-run the registration check against a FRESH provider listing so the
  // outcome reports what Brevo actually stored.
  let refreshed: Awaited<ReturnType<typeof listBrevoTransactionalWebhooks>>;
  try {
    refreshed = await listBrevoTransactionalWebhooks();
  } catch {
    res.status(502).json({ error: `Webhook je ${action} na Brevo, ali ponovna provera registracije nije uspela. Pokrenite „Proveri registraciju na Brevo“ da potvrdite ishod.` }); return;
  }
  const refreshedCandidates = brevoRegistrationCandidates(refreshed, secret);
  const verdict = brevoRegistrationVerdict(refreshedCandidates, context);
  if (verdict.ok) {
    // One-click registration wrote the current secret to the provider and the
    // re-check confirmed it — clear the persisted re-registration reminder.
    await Promise.all([
      markWebhookReconfirmed("brevo", user.id),
      clearBrevoRegistrationIncomplete(),
    ]);
    const confirmedAt = await webhookVerifiedAt("brevo");
    // Surface any stale LUMERA-format duplicates still registered at Brevo
    // (old domains, old secrets) so the admin can remove them — they keep
    // receiving events that are rejected or lost. The freshly repaired
    // registration (current secret at an accepted origin) is never listed.
    const staleWebhooks = staleBrevoRegistrations(refreshedCandidates, context);
    const staleNote = staleWebhooks.length
      ? ` Na Brevo su pronađene i zaostale LUMERA registracije (${staleWebhooks.length}) sa starih domena ili sa starim tajnama — možete ih ukloniti na ovoj stranici da više ne primaju događaje koji se odbacuju.`
      : "";
    res.json({
      message: `Webhook je ${action} na Brevo sa URL-om ove aplikacije i sačuvanom tajnom, uz pretplatu na događaje isporuke, otvaranja, bounce-ova, blokada i grešaka. Ponovna provera je potvrdila registraciju.${staleNote}`,
      staleWebhooks,
      webhookVerifiedAt: confirmedAt?.toISOString() ?? null,
      webhookVerificationStale: false,
      webhookConfirmationMaxAgeDays: WEBHOOK_CONFIRMATION_MAX_AGE_DAYS,
    }); return;
  }
  if (verdict.missingEvents) {
    await markBrevoRegistrationIncomplete(verdict.missingEvents, user.id);
  } else {
    await clearBrevoRegistrationIncomplete();
  }
  res.status(502).json({
    code: "BREVO_REGISTRATION_INCOMPLETE",
    error: `Webhook je ${action} na Brevo, ali ponovna provera i dalje prijavljuje problem: ${verdict.error}`,
    staleWebhooks: staleBrevoRegistrations(refreshedCandidates, context),
    ...("missingEvents" in verdict ? { missingEvents: verdict.missingEvents } : {}),
  });
});

/**
 * Cleanup of stale LUMERA-format webhook registrations left behind at Brevo
 * ("Ukloni zaostale registracije"). After a one-click repair, leftovers from
 * old domains or old secrets stay registered at Brevo and keep receiving
 * events that are rejected or lost; Brevo supports DELETE /v3/webhooks/{id}.
 * The route NEVER trusts the client's ids alone: it re-lists the provider's
 * webhooks fresh and deletes only ids still classified as stale LUMERA-format
 * registrations — never a non-LUMERA webhook (filtered out before
 * classification) and never this deployment's healthy registration (current
 * secret at an accepted origin). Refused from a development/preview address,
 * where the saved secret may differ from production's and a healthy
 * production registration would be misread as stale. Serbian messages;
 * masked URLs only, tokens are never echoed.
 */
router.post("/admin/integrations/brevo/cleanup-webhooks", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const rawIds: unknown = req.body?.ids;
  if (!Array.isArray(rawIds) || !rawIds.length || !rawIds.every((id) => typeof id === "number" && Number.isInteger(id))) {
    res.status(400).json({ error: "Izaberite bar jednu zaostalu registraciju za uklanjanje." }); return;
  }
  const requestedIds = new Set<number>(rawIds as number[]);
  const context = brevoVerdictContext(req);
  if (context.developmentOrigin) {
    res.status(400).json({ error: `Uklanjanje registracija nije dostupno sa razvojne adrese (${context.origin}): sačuvana tajna razvojnog okruženja može da se razlikuje od produkcione, pa bi ispravna produkciona registracija mogla biti pogrešno obrisana. Otvorite ovu stranicu iz objavljene aplikacije.` }); return;
  }
  const secret = await resolveWebhookSecret("brevo");
  if (!secret) {
    res.status(400).json({ error: "Webhook tajna nije sačuvana. Unesite i sačuvajte webhook tajnu, pa pokušajte ponovo." }); return;
  }
  let webhooks: Awaited<ReturnType<typeof listBrevoTransactionalWebhooks>>;
  try {
    webhooks = await listBrevoTransactionalWebhooks();
  } catch (error) {
    respondBrevoListingFailure(res, error); return;
  }
  const stale = staleBrevoRegistrations(brevoRegistrationCandidates(webhooks, secret), context);
  const deletable = stale.filter((candidate) => requestedIds.has(candidate.id));
  // Requested ids that are no longer stale are SKIPPED, never deleted: they
  // may be the freshly repaired registration, a non-LUMERA webhook, or
  // already removed at Brevo.
  const skippedCount = requestedIds.size - deletable.length;
  if (!deletable.length) {
    res.json({
      message: "Nijedna od izabranih registracija više nije zaostala na Brevo — nema šta da se ukloni.",
      removedIds: [],
      staleWebhooks: stale,
    }); return;
  }
  const removed: Array<{ id: number; maskedUrl: string }> = [];
  const failed: Array<{ id: number; maskedUrl: string }> = [];
  for (const candidate of deletable) {
    try {
      await deleteBrevoTransactionalWebhook(candidate.id);
      removed.push(candidate);
    } catch (error) {
      if (error instanceof BrevoConfigurationError) {
        res.status(400).json({ error: error.message }); return;
      }
      req.log.warn({ err: error, webhookId: candidate.id }, "Brevo stale webhook deletion failed");
      failed.push(candidate);
    }
  }
  const remaining = stale.filter((candidate) => !removed.some((item) => item.id === candidate.id));
  if (failed.length) {
    res.status(502).json({
      error: `Uklonjeno je ${removed.length} od ${deletable.length} izabranih zaostalih registracija sa Brevo. Nije uspelo uklanjanje: ${failed.map((item) => item.maskedUrl).join(", ")}. Pokušajte ponovo.`,
      removedIds: removed.map((item) => item.id),
      staleWebhooks: remaining,
    }); return;
  }
  const skippedNote = skippedCount
    ? ` Preskočeno: ${skippedCount} izabranih više nije zaostalo (sveža registracija i webhook-ovi van LUMERA formata se nikada ne diraju).`
    : "";
  res.json({
    message: `Uklonjene su zaostale registracije sa Brevo (${removed.length}): ${removed.map((item) => item.maskedUrl).join(", ")}. Aktuelna registracija nije dirana.${skippedNote}`,
    removedIds: removed.map((item) => item.id),
    staleWebhooks: remaining,
  });
});

