router.post("/auth/business-register", async (req, res): Promise<void> => {
  await ensureDemoData();
  const parsed = RegisterBusinessBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const input = parsed.data;
  if (input.businessType === "EDUCATION_CENTER" && !input.description?.trim()) {
    res.status(400).json({ error: "Opis edukativnih programa i sertifikacija je obavezan." });
    return;
  }
  if (input.businessType === "EDUCATION_CENTER" && (!input.planId || !input.billingCycle)) {
    res.status(400).json({ error: "Izbor aktivnog Education plana i ciklusa naplate je obavezan." });
    return;
  }
  if (input.businessType === "EDUCATION_CENTER" && (!input.registrationNumber?.trim() || !input.bankAccount?.trim())) {
    res.status(400).json({ error: "Matični broj i poslovni račun edukativnog centra su obavezni." });
    return;
  }
  const [educationPlan] = input.businessType === "EDUCATION_CENTER"
    ? await db.select().from(subscriptionPlansTable).where(and(eq(subscriptionPlansTable.id, input.planId!), eq(subscriptionPlansTable.active, true), eq(subscriptionPlansTable.audience, "education"), gt(subscriptionPlansTable.price, 0))).limit(1)
    : [];
  if (input.businessType === "EDUCATION_CENTER" && !educationPlan) {
    res.status(400).json({ error: "Izabrani Education plan nije aktivan." });
    return;
  }
  if (!input.pib?.trim()) {
    res.status(400).json({ error: "PIB pravnog lica je obavezan." });
    return;
  }
  const email = input.email.toLowerCase();
  const [existing] = await db.select().from(usersTable).where(eq(usersTable.email, email)).limit(1);
  const signedIn = await getCurrentUser(req);
  const [linkedIdentity, existingSalon, existingCenter] = existing && signedIn?.id === existing.id ? await Promise.all([
    db.select({ id: oauthIdentitiesTable.id }).from(oauthIdentitiesTable).where(eq(oauthIdentitiesTable.userId, existing.id)).limit(1),
    db.select({ id: salonsTable.id }).from(salonsTable).where(eq(salonsTable.ownerId, existing.id)).limit(1),
    db.select({ id: educationCentersTable.id }).from(educationCentersTable).where(eq(educationCentersTable.ownerId, existing.id)).limit(1),
  ]) : [[], [], []];
  const socialBusinessCompletion = Boolean(
    existing && signedIn?.id === existing.id && existing.role === "CUSTOMER"
    && linkedIdentity.length && !existingSalon.length && !existingCenter.length,
  );
  if (existing && !socialBusinessCompletion) { res.status(409).json({ error: "Nalog sa ovom e-mail adresom već postoji." }); return; }
  if (!existing && !input.password) { res.status(400).json({ error: "Lozinka je obavezna za registraciju e-mailom." }); return; }

  try {
    const user = await db.transaction(async (tx) => {
      const role = input.businessType === "SALON" ? "SALON_OWNER" : "EDUKATIVNI_CENTAR";
      const created = existing
        ? (await tx.update(usersTable).set({ role, phone: input.phone }).where(eq(usersTable.id, existing.id)).returning())[0]!
        : (await tx.insert(usersTable).values({
          firstName: input.firstName,
          lastName: input.lastName,
          email,
          phone: input.phone,
          passwordHash: await hashPassword(input.password!),
          passwordSetAt: new Date(),
          role,
        }).returning())[0]!;

      const [workspace] = input.businessType === "SALON" ? await tx.insert(salonsTable).values({
          ownerId: created!.id,
          name: input.businessName,
          slug: businessSlug(input.businessName, created!.id),
          city: input.city,
          municipality: input.municipality,
          address: input.address,
          postalCode: input.postalCode,
          phone: input.phone,
          email,
          shortDescription: `${input.businessName} je novi LUMERA partner.`,
          description: `Poslovni profil za ${input.businessName}. Dopunite ponudu, tim i radno vreme iz poslovnog portala.`,
          imageUrl: "https://images.unsplash.com/photo-1560066984-138dadb4c035?q=80&w=1200&auto=format&fit=crop",
          active: false,
          companyName: input.businessName,
          companyTaxId: input.pib,
          provisioningSource: "business_registration_salon",
        }).returning({ id: salonsTable.id }) : [];
      let referredEducationCenterId: string | null = null;
      if (input.businessType === "EDUCATION_CENTER") {
        const centerId = randomUUID();
        const [center] = await tx.insert(educationCentersTable).values({
           id: centerId,
          ownerId: created!.id,
          name: input.businessName,
          city: input.city,
          description: input.description!.trim(),
          imageUrl: "https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?q=80&w=1200&auto=format&fit=crop",
          contactEmail: input.contactEmail?.trim() || email,
          contactPhone: input.contactPhone?.trim() || input.phone,
          contactAddress: input.contactAddress?.trim() || input.address,
          pib: input.pib,
           registrationNumber: normalizeTrialRegistrationNumber(input.registrationNumber),
           bankAccount: normalizeTrialBankAccount(input.bankAccount),
           paymentReferenceNumber: educationPaymentReference("EDU", centerId),
          websiteUrl: input.websiteUrl?.trim() || undefined,
          instagramUrl: input.instagramUrl?.trim() || undefined,
        }).returning({ id: educationCentersTable.id });
        referredEducationCenterId = center!.id;
        const now = new Date();
        const claim = await tx.insert(educationTrialClaimsTable).values({
          normalizedEmailHash: hashTrialIdentifier(normalizeTrialEmail(email))!,
          normalizedPhoneHash: hashTrialIdentifier(normalizeTrialPhone(input.phone)),
          normalizedPibHash: hashTrialIdentifier(normalizeTrialPib(input.pib)),
          normalizedRegistrationNumberHash: hashTrialIdentifier(normalizeTrialRegistrationNumber(input.registrationNumber)),
          normalizedBankAccountHash: hashTrialIdentifier(normalizeTrialBankAccount(input.bankAccount)),
          userId: created.id,
          centerId: center!.id,
        }).onConflictDoNothing().returning({ id: educationTrialClaimsTable.id });
        const trial = claim.length > 0 && educationPlan!.trialDays > 0;
        const trialEndsAt = trial ? addEducationBelgradeCalendarDays(now, educationPlan!.trialDays) : null;
        const [subscription] = await tx.insert(educationCenterSubscriptionsTable).values({
          centerId: center!.id,
          planId: educationPlan!.id,
          status: trial ? "trial" : "past_due",
          dueAmount: trial ? 0 : educationCycleAmount(educationPlan!.price, input.billingCycle!),
          billingCycle: input.billingCycle!,
          currentPeriodStart: trial ? now : null,
          currentPeriodEnd: trialEndsAt,
           currentPriceSnapshot: trial ? educationPlan!.price : null,
           currentCourseLimitSnapshot: trial ? (educationPlan!.courseLimit ?? educationPlan!.limits["courses"] ?? null) : null,
          trialStartedAt: trial ? now : null,
          trialEndsAt,
        }).returning({ id: educationCenterSubscriptionsTable.id });
        await recordEducationFinancialAudit(tx, {
          actorUserId: created.id,
          action: "education_subscription_created_at_registration",
          entityType: "education_center_subscription",
          entityId: subscription!.id,
          newValue: { planId: educationPlan!.id, billingCycle: input.billingCycle, status: trial ? "trial" : "past_due" },
          reason: trial ? "Jednokratni Education probni period" : "Trial je već iskorišćen; potrebna je uplata",
        });
      }
      const legalBinding = await bindLegalEntityBusinessInTx(tx, {
        pib: input.pib, legalName: input.businessName, ownerUserId: created.id,
        salonId: input.businessType === "SALON" ? workspace!.id : null,
        educationCenterId: referredEducationCenterId,
      });
      if (input.businessType === "SALON") {
        await tx.update(salonsTable).set({ companyTaxId: legalBinding.normalizedPib }).where(eq(salonsTable.id, workspace!.id));
      } else {
        await tx.update(educationCentersTable).set({ pib: legalBinding.normalizedPib }).where(eq(educationCentersTable.id, referredEducationCenterId!));
      }
      await captureReferralAttributionInTx(tx, {
        referralCode: input.referralCode, referredUserId: created!.id,
        phoneNormalized: normalizedPhone(input.phone),
        referredSalonId: input.businessType === "SALON" ? workspace!.id : null,
        referredEducationCenterId,
        registrationContext: input.businessType === "SALON"
          ? socialBusinessCompletion ? "oauth_business_salon" : "business_salon"
          : socialBusinessCompletion ? "oauth_business_education" : "business_education",
      });
      return (await tx.update(usersTable).set({
        activeSalonId: input.businessType === "SALON" ? workspace!.id : null,
        updatedAt: new Date(),
      })
        .where(eq(usersTable.id, created!.id)).returning())[0]!;
    });

    const token = await createSession(user.id);
    res.cookie(sessionCookieName, token, cookieOptions());
    res.status(201).json(RegisterResponse.parse({ user: publicUser(user), message: "Poslovni nalog je kreiran." }));
  } catch (error) {
    if (["40001", "40P01"].includes((error as { code?: string }).code ?? "")) {
      res.status(409).json({ error: "Istovremena poslovna promena je u toku. Osvežite podatke i pokušajte ponovo." });
      return;
    }
    if (error instanceof LegalEntityOwnerConflictError) {
      res.status(409).json({
        error: error.message, code: error.code, normalizedPib: error.normalizedPib,
        outcome: "cross_account_conflict", conflictingOwnerCount: error.existingOwnerUserIds.length,
      });
      return;
    }
    if (error instanceof ReferralChannelContextError) {
      res.status(400).json({ error: error.message, code: error.code });
      return;
    }
    if ((error as { code?: string }).code === "23505") {
      res.status(409).json({ error: "Nalog ili poslovni profil sa ovim podacima već postoji." });
      return;
    }
    throw error;
  }
});

router.post("/auth/login", async (req, res): Promise<void> => {
  await ensureDemoData();
  const parsed = LoginBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const [user] = await db.select().from(usersTable).where(eq(usersTable.email, parsed.data.email.toLowerCase())).limit(1);
  if (user?.role === "SALON_EMPLOYEE" && !user.active) {
    res.status(403).json({ error: "Nalog zaposlenog je deaktiviran. Obratite se vlasniku salona." }); return;
  }
  if (!user || !user.active || !(await verifyPassword(parsed.data.password, user.passwordHash))) {
    res.status(401).json({ error: "E-mail ili lozinka nisu ispravni." }); return;
  }
  const token = await createSession(user.id);
  res.cookie(sessionCookieName, token, cookieOptions());
  if (isRetailAccount(user)) await claimRecentlyViewedForUser(req, res, user.id);
  res.json(LoginResponse.parse({ user: publicUser(user), message: "Uspešno ste prijavljeni." }));
});

router.post("/auth/customer-password-setup/validate", async (req, res): Promise<void> => {
  const admitted = await admitCustomerSetupRequest(
    "validate",
    customerSetupRequestIdentity(req),
    30,
    CUSTOMER_SETUP_TTL_MS,
  );
  if (!admitted) {
    res.setHeader("Retry-After", "900");
    res.status(429).json({ error: CUSTOMER_SETUP_INVALID_MESSAGE });
    return;
  }
  const parsed = ValidateCustomerPasswordSetupBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: CUSTOMER_SETUP_INVALID_MESSAGE });
    return;
  }
  const tokenHash = customerSetupDigest(parsed.data.token);
  const now = new Date();
  const result = await db.transaction(async (tx) => {
    const [setup] = await tx.select()
      .from(customerPasswordSetupTokensTable)
      .where(eq(customerPasswordSetupTokensTable.tokenHash, tokenHash))
      .for("update")
      .limit(1);
    const valid = setup && activeCustomerSetupToken(setup, now);
    if (valid) return { valid: true as const, expiresAt: setup.expiresAt };
    return { valid: false as const };
  });
  if (!result.valid) {
    res.status(400).json({ error: CUSTOMER_SETUP_INVALID_MESSAGE });
    return;
  }
  res.json({ valid: true, expiresAt: result.expiresAt.toISOString() });
});

router.post("/auth/customer-password-setup/complete", async (req, res): Promise<void> => {
  const admitted = await admitCustomerSetupRequest(
    "complete",
    customerSetupRequestIdentity(req),
    10,
    CUSTOMER_SETUP_TTL_MS,
  );
  if (!admitted) {
    res.setHeader("Retry-After", "900");
    res.status(429).json({ error: CUSTOMER_SETUP_INVALID_MESSAGE });
    return;
  }
  const tokenInput = ValidateCustomerPasswordSetupBody.safeParse(req.body);
  if (!tokenInput.success) {
    res.status(400).json({ error: CUSTOMER_SETUP_INVALID_MESSAGE });
    return;
  }
  const tokenHash = customerSetupDigest(tokenInput.data.token);
  const parsed = CompleteCustomerPasswordSetupBody.safeParse(req.body);
  if (!parsed.success || parsed.data.password !== parsed.data.passwordConfirmation) {
    await failActiveCustomerSetupToken(tokenHash);
    res.status(400).json({ error: parsed.success ? "Lozinke se ne podudaraju." : "Lozinka ne ispunjava uslove." });
    return;
  }
  const passwordHash = await hashPassword(parsed.data.password);
  const now = new Date();
  const completed = await db.transaction(async (tx) => {
    const [setup] = await tx.select()
      .from(customerPasswordSetupTokensTable)
      .where(eq(customerPasswordSetupTokensTable.tokenHash, tokenHash))
      .for("update")
      .limit(1);
    if (!setup || !activeCustomerSetupToken(setup, now)) return false;
    const [target] = await tx.select({
      id: usersTable.id,
      role: usersTable.role,
      active: usersTable.active,
      passwordSetAt: usersTable.passwordSetAt,
    })
      .from(usersTable)
      .where(eq(usersTable.id, setup.userId))
      .for("update")
      .limit(1);
    if (!target || target.role === "SUPER_ADMIN" || !target.active || target.passwordSetAt) {
      await recordActiveCustomerSetupFailure(tx, setup, now);
      return false;
    }

    await tx.update(customerPasswordSetupTokensTable)
      .set({ consumedAt: now })
      .where(eq(customerPasswordSetupTokensTable.id, setup.id));
    await tx.update(usersTable)
      .set({ passwordHash, passwordSetAt: now, mustChangePassword: false, updatedAt: now })
      .where(eq(usersTable.id, setup.userId));
    await tx.delete(sessionsTable).where(eq(sessionsTable.userId, setup.userId));
    await tx.insert(customerPasswordSetupAuditsTable).values({
      administratorUserId: setup.issuedByUserId,
      targetUserId: setup.userId,
      action: "PASSWORD_SET",
      createdAt: now,
    });
    return true;
  });
  if (!completed) {
    res.status(400).json({ error: CUSTOMER_SETUP_INVALID_MESSAGE });
    return;
  }
  res.json({ success: true, loginPath: "/prijava" });
});

