const GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT = 20;
const GROUPED_AVAILABILITY_CALENDAR_BRANCH_LIMIT = 100;
const GROUPED_AVAILABILITY_LIST_LIMIT = GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT;

function sendGroupedAvailabilityResponse(
  res: Response,
  payload: {
    salonId: string;
    generatedAt: string;
    candidates: Array<{
      date: string;
      startTime: string;
      endTime: string;
      treatments: Array<{
        position: number;
        serviceId: string;
        date: string;
        employeeId: string | null;
        startTime: string;
        endTime: string;
        bufferMinutes: number;
      }>;
    }>;
    calendarDays?: Array<{
      date: string;
      candidates: Array<{
        date: string;
        startTime: string;
        endTime: string;
        treatments: Array<{
          position: number;
          serviceId: string;
          date: string;
          employeeId: string | null;
          startTime: string;
          endTime: string;
          bufferMinutes: number;
        }>;
      }>;
      truncated: boolean;
    }>;
  },
) {
  GetGroupedBookingAvailabilityResponse.parse(payload);
  res.json(payload);
}

router.post("/salons/:salonId/grouped-availability", async (req, res): Promise<void> => {
  const params = GetGroupedBookingAvailabilityParams.safeParse(req.params);
  const body = GetGroupedBookingAvailabilityBody.safeParse(req.body);
  const rawBody = req.body && typeof req.body === "object" ? req.body as Record<string, unknown> : null;
  const fromDate = rawDateOnlyInput(rawBody?.fromDate);
  const toDate = rawDateOnlyInput(rawBody?.toDate);
  if (!params.success || !body.success || !fromDate || !toDate) { res.status(400).json({ error: "Podaci za grupnu dostupnost nisu ispravni." }); return; }
  if (fromDate > toDate) { res.status(400).json({ error: "Opseg datuma nije ispravan." }); return; }
  const requestedDayCount = Math.floor((Date.parse(`${toDate}T00:00:00Z`) - Date.parse(`${fromDate}T00:00:00Z`)) / 86_400_000) + 1;
  if (body.data.resultMode === "calendar" && requestedDayCount > 14) {
    res.status(400).json({ error: "Kalendarski prikaz podržava opseg od najviše 14 dana." }); return;
  }
  const [salon] = await db.select().from(salonsTable).where(and(eq(salonsTable.id, params.data.salonId), eq(salonsTable.active, true))).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return; }
  const services = await db.select().from(servicesTable).where(and(eq(servicesTable.salonId, salon.id), eq(servicesTable.active, true), inArray(servicesTable.id, body.data.treatments.map((x) => x.serviceId))));
  if (services.length !== new Set(body.data.treatments.map((x) => x.serviceId)).size) { res.status(404).json({ error: "Jedna ili više usluga nisu dostupne u salonu." }); return; }
  const settings = await bookingSettingsView(salon.id);
  const dates: string[] = [];
  for (let d = new Date(`${fromDate}T12:00:00Z`); d <= new Date(`${toDate}T12:00:00Z`) && dates.length < 31; d.setUTCDate(d.getUTCDate() + 1)) dates.push(d.toISOString().slice(0, 10));
  const serviceById = new Map(services.map((service) => [service.id, service]));
  const distinctServiceIds = [...new Set(body.data.treatments.map((item) => item.serviceId))];
  // Persisted facts (including each distinct service's resource requirements)
  // are loaded once; candidate branches only rerun the canonical pure engine.
  const availabilityContext = await preloadCanonicalAvailability({
    salonId: salon.id, dates, serviceIds: distinctServiceIds,
  });
  const requirementsByServiceId = availabilityContext.requirementsByServiceId;
  const candidates: Array<{ date: string; startTime: string; endTime: string; treatments: Array<{ position: number; serviceId: string; date: string; employeeId: string | null; startTime: string; endTime: string; bufferMinutes: number }> }> = [];
  const first = body.data.treatments[0]!;
  const initialService = serviceById.get(first.serviceId)!;

  if (body.data.resultMode === "calendar") {
    const calendarDays = [];
    for (const startingDate of dates) {
      const dayCandidates: typeof candidates = [];
      let truncated = false;
      let evaluatedBranches = 1;
      let branchBudgetExhausted = false;
      const firstSlots = await canonicalAvailability({
        salonId: salon.id, service: initialService, dates: [startingDate],
        employeeId: first.employeeId ?? null, granularityMinutes: settings.slotGranularityMinutes,
        resourceRequirements: requirementsByServiceId.get(first.serviceId),
        context: availabilityContext,
      });

      const extendCandidate = async (
        treatmentIndex: number,
        planned: (typeof candidates)[number]["treatments"],
        reservedAppointments: Array<{ employeeId: string; date: string; startTime: string; endTime: string; bufferMinutes: number; resourceIds: string[] }>,
        resourceReservations: Array<{ resourceId: string; quantity: number; date: string; startTime: string; endTime: string; bufferMinutes: number }>,
        cursorDate: string,
        cursor: string,
      ): Promise<void> => {
        if (dayCandidates.length > GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT || branchBudgetExhausted) return;
        if (treatmentIndex === body.data.treatments.length) {
          dayCandidates.push({
            date: startingDate,
            startTime: planned[0]!.startTime,
            endTime: cursor,
            treatments: planned,
          });
          if (dayCandidates.length > GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT) truncated = true;
          return;
        }

        const treatment = body.data.treatments[treatmentIndex]!;
        const service = serviceById.get(treatment.serviceId)!;
        const candidateDates = body.data.allowMultipleDays
          ? dates.filter((date) => date >= cursorDate)
          : [startingDate];
        if (evaluatedBranches >= GROUPED_AVAILABILITY_CALENDAR_BRANCH_LIMIT) {
          branchBudgetExhausted = true;
          truncated = true;
          return;
        }
        evaluatedBranches += 1;
        const slots = await canonicalAvailability({
          salonId: salon.id, service, dates: candidateDates, employeeId: treatment.employeeId ?? null,
          granularityMinutes: settings.slotGranularityMinutes, reservedAppointments, resourceReservations,
          resourceRequirements: requirementsByServiceId.get(treatment.serviceId),
          context: availabilityContext,
        });
        const gapEnd = appointmentEndTime(cursor, settings.maxVisitGapMinutes) ?? cursor;
        for (const slot of slots) {
          if (dayCandidates.length > GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT || branchBudgetExhausted) return;
          if (slot.date < cursorDate) continue;
          if (slot.date === cursorDate && (slot.startTime < cursor || slot.startTime > gapEnd)) continue;
          if (!body.data.allowMultipleDays && slot.date !== startingDate) continue;
          if (planned.some((entry) => entry.date === slot.date
            && entry.employeeId === slot.employeeId && entry.startTime < slot.endTime && entry.endTime > slot.startTime)) continue;
          const requirements = requirementsByServiceId.get(treatment.serviceId) ?? [];
          await extendCandidate(
            treatmentIndex + 1,
            [...planned, {
              position: treatmentIndex, serviceId: treatment.serviceId, date: slot.date,
              employeeId: slot.employeeId, startTime: slot.startTime, endTime: slot.endTime, bufferMinutes: service.bufferMinutes,
            }],
            [...reservedAppointments, {
              employeeId: slot.employeeId, date: slot.date, startTime: slot.startTime, endTime: slot.endTime,
              bufferMinutes: service.bufferMinutes, resourceIds: requirements.map((item) => item.resourceId),
            }],
            [...resourceReservations, ...requirements.map((item) => ({
              resourceId: item.resourceId, quantity: item.quantity, date: slot.date, startTime: slot.startTime,
              endTime: appointmentEndTime(slot.endTime, service.bufferMinutes)!, bufferMinutes: 0,
            }))],
            slot.date,
            slot.endTime,
          );
        }
      };

      const firstRequirements = requirementsByServiceId.get(first.serviceId) ?? [];
      for (const initial of firstSlots) {
        if (dayCandidates.length > GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT || branchBudgetExhausted) break;
        const planned = [{
          position: 0, serviceId: first.serviceId, date: initial.date,
          employeeId: initial.employeeId, startTime: initial.startTime, endTime: initial.endTime,
          bufferMinutes: initialService.bufferMinutes,
        }];
        await extendCandidate(1, planned, [{
          employeeId: initial.employeeId, date: initial.date, startTime: initial.startTime, endTime: initial.endTime,
          bufferMinutes: initialService.bufferMinutes, resourceIds: firstRequirements.map((item) => item.resourceId),
        }], firstRequirements.map((item) => ({
          resourceId: item.resourceId, quantity: item.quantity, date: initial.date, startTime: initial.startTime,
          endTime: appointmentEndTime(initial.endTime, initialService.bufferMinutes)!, bufferMinutes: 0,
        })), initial.date, initial.endTime);
      }
      calendarDays.push({
        date: startingDate,
        candidates: dayCandidates.slice(0, GROUPED_AVAILABILITY_CALENDAR_DAY_LIMIT),
        truncated,
      });
    }
    sendGroupedAvailabilityResponse(res, {
      salonId: salon.id, generatedAt: new Date().toISOString(), candidates: [], calendarDays,
    });
    return;
  }

  const firstSlots = await canonicalAvailability({
    salonId: salon.id, service: initialService, dates, employeeId: first.employeeId ?? null,
    granularityMinutes: settings.slotGranularityMinutes,
    resourceRequirements: requirementsByServiceId.get(first.serviceId),
    context: availabilityContext,
  });
  for (const initial of firstSlots) {
    const initialRequirements = requirementsByServiceId.get(initialService.id) ?? [];
    const planned = [{ position: 0, serviceId: first.serviceId, date: initial.date, employeeId: initial.employeeId, startTime: initial.startTime, endTime: initial.endTime, bufferMinutes: initialService.bufferMinutes }];
    const reservedAppointments = [{
      employeeId: initial.employeeId, date: initial.date, startTime: initial.startTime, endTime: initial.endTime,
      bufferMinutes: initialService.bufferMinutes, resourceIds: initialRequirements.map((item) => item.resourceId),
    }];
    const resourceReservations = initialRequirements.map((item) => ({
      resourceId: item.resourceId, quantity: item.quantity, date: initial.date, startTime: initial.startTime,
      endTime: appointmentEndTime(initial.endTime, initialService.bufferMinutes)!, bufferMinutes: 0,
    }));
    let cursorDate = initial.date; let cursor = initial.endTime; let valid = true;
    for (let index = 1; index < body.data.treatments.length; index++) {
      const treatment = body.data.treatments[index]!;
      const candidateDates = body.data.allowMultipleDays
        ? dates.filter((date) => date >= cursorDate)
        : [initial.date];
      const service = serviceById.get(treatment.serviceId)!;
      const slots = await canonicalAvailability({
        salonId: salon.id, service, dates: candidateDates, employeeId: treatment.employeeId ?? null,
        granularityMinutes: settings.slotGranularityMinutes, reservedAppointments, resourceReservations,
        resourceRequirements: requirementsByServiceId.get(treatment.serviceId),
        context: availabilityContext,
      });
      const gapEnd = appointmentEndTime(cursor, settings.maxVisitGapMinutes) ?? cursor;
      const next = slots.find((slot) => {
        if (slot.date < cursorDate) return false;
        if (slot.date === cursorDate && (slot.startTime < cursor || slot.startTime > gapEnd)) return false;
        if (!body.data.allowMultipleDays && slot.date !== initial.date) return false;
        return !planned.some((entry) => entry.date === slot.date
          && entry.employeeId === slot.employeeId && entry.startTime < slot.endTime && entry.endTime > slot.startTime);
      });
      if (!next) { valid = false; break; }
      planned.push({ position: index, serviceId: treatment.serviceId, date: next.date, employeeId: next.employeeId, startTime: next.startTime, endTime: next.endTime, bufferMinutes: serviceById.get(treatment.serviceId)!.bufferMinutes });
      const requirements = requirementsByServiceId.get(service.id) ?? [];
      reservedAppointments.push({
        employeeId: next.employeeId, date: next.date, startTime: next.startTime, endTime: next.endTime,
        bufferMinutes: service.bufferMinutes, resourceIds: requirements.map((item) => item.resourceId),
      });
      resourceReservations.push(...requirements.map((item) => ({
        resourceId: item.resourceId, quantity: item.quantity, date: next.date, startTime: next.startTime,
        endTime: appointmentEndTime(next.endTime, service.bufferMinutes)!, bufferMinutes: 0,
      })));
      cursorDate = next.date; cursor = next.endTime;
    }
    if (valid) candidates.push({ date: initial.date, startTime: initial.startTime, endTime: cursor, treatments: planned });
    if (candidates.length >= GROUPED_AVAILABILITY_LIST_LIMIT) break;
  }
  sendGroupedAvailabilityResponse(res, {
    salonId: salon.id, generatedAt: new Date().toISOString(), candidates,
  });
});

type StaffBookingGroupAccess = {
  user: typeof usersTable.$inferSelect;
  salon: typeof salonsTable.$inferSelect;
  employee: typeof employeesTable.$inferSelect | null;
};

async function replayCustomerBookingCommand(
  req: Request,
  res: Response,
  next: NextFunction,
  commandType: string,
): Promise<void> {
  const user = await requireCustomer(req, res); if (!user) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const salonId = typeof req.body?.salonId === "string" ? req.body.salonId : null;
  if (!salonId) { next(); return; }
  const replay = await replayBookingCommand({
    salonId, actorType: "user", actorId: user.id, idempotencyKey,
    commandType, payload: req.body,
  });
  if (replay) { sendBookingCommandResult(res, replay); return; }
  next();
}

async function replayOwnerBookingCommand(
  req: Request,
  res: Response,
  next: NextFunction,
  commandType: string,
): Promise<void> {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const replay = await replayBookingCommand({
    salonId: access.salon.id, actorType: "user", actorId: access.user.id, idempotencyKey,
    commandType, payload: req.body,
  });
  if (replay) { sendBookingCommandResult(res, replay); return; }
  next();
}

async function replayEmployeeBookingCommand(
  req: Request,
  res: Response,
  next: NextFunction,
  commandType: string,
): Promise<void> {
  const access = await requireSalonEmployee(req, res); if (!access) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const replay = await replayBookingCommand({
    salonId: access.salon.id, actorType: "user", actorId: access.user.id, idempotencyKey,
    commandType, payload: req.body,
  });
  if (replay) { sendBookingCommandResult(res, replay); return; }
  next();
}

async function createStaffBookingGroup(
  req: Request,
  res: Response,
  access: StaffBookingGroupAccess,
): Promise<void> {
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const schema = access.employee ? CreateEmployeeBookingGroupBody : CreateSalonBookingGroupBody;
  const parsed = schema.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  if (Boolean(parsed.data.salonCustomerId) === Boolean(parsed.data.guest)) {
    res.status(400).json({ error: "Izaberite CRM klijenta ili unesite podatke novog gosta." }); return;
  }
  const today = new Date().toISOString().slice(0, 10);
  const rawDates = rawTreatmentDateInputs(req.body);
  if (!rawDates) {
    res.status(400).json({ error: "Datum tretmana nije ispravan." }); return;
  }
  const treatments = parsed.data.treatments.map((item, index) => ({ ...item, date: rawDates[index]! }));
  if (treatments.some((item) => item.date < today)) {
    res.status(400).json({ error: "Datum tretmana nije ispravan." }); return;
  }
  const serviceIds = [...new Set(treatments.map((item) => item.serviceId))];
  const services = await db.select().from(servicesTable).where(and(
    eq(servicesTable.salonId, access.salon.id),
    eq(servicesTable.active, true),
    inArray(servicesTable.id, serviceIds),
  ));
  if (services.length !== serviceIds.length) {
    res.status(404).json({ error: "Jedna ili više usluga nisu pronađene u ovom salonu." }); return;
  }
  if (access.employee) {
    const assignments = await db.select().from(employeeServicesTable).where(and(
      eq(employeeServicesTable.employeeId, access.employee.id),
      inArray(employeeServicesTable.serviceId, serviceIds),
    ));
    if (assignments.length !== serviceIds.length || treatments.some((item) =>
      item.employeeId !== undefined && item.employeeId !== null && item.employeeId !== access.employee!.id)) {
      res.status(403).json({ error: "Zaposleni može grupisati samo svoje dodeljene tretmane." }); return;
    }
  }
  const byId = new Map(services.map((service) => [service.id, service]));
  try {
    const command = await executeBookingCommand({
      salonId: access.salon.id, actorType: "user", actorId: access.user.id, idempotencyKey,
      commandType: access.employee ? "employee.booking-group.create" : "salon.booking-group.create",
      payload: req.body,
    }, async (tx) => {
      await lockAppointmentResources(tx, access.salon.id, treatments.map((item) => ({ date: item.date })));
      let contact: typeof salonCustomersTable.$inferSelect;
      let newlyCreatedContact = false;
      if (parsed.data.salonCustomerId) {
        const [existing] = await tx.select().from(salonCustomersTable).where(and(
          eq(salonCustomersTable.id, parsed.data.salonCustomerId),
          eq(salonCustomersTable.salonId, access.salon.id),
        )).limit(1);
        if (!existing) throw new AppointmentSeriesError("CRM klijent ne pripada ovom salonu.", 403);
        contact = existing;
      } else {
        const phone = parsed.data.guest!.phone.trim();
        const phoneNormalized = normalizedPhone(phone);
        if (!phoneNormalized) throw new AppointmentSeriesError("Telefon gosta nije ispravan.", 400);
        const [existing] = await tx.select().from(salonCustomersTable).where(and(
          eq(salonCustomersTable.salonId, access.salon.id),
          eq(salonCustomersTable.phoneNormalized, phoneNormalized),
        )).limit(1);
        if (existing) {
          contact = existing;
        } else {
          const [registered] = await tx.select().from(usersTable)
            .where(eq(usersTable.phoneNormalized, phoneNormalized)).limit(1);
          [contact] = await tx.insert(salonCustomersTable).values({
            salonId: access.salon.id,
            firstName: parsed.data.guest!.firstName.trim(),
            lastName: parsed.data.guest!.lastName?.trim() ?? "",
            phone,
            phoneNormalized,
            email: parsed.data.guest!.email?.trim().toLowerCase() || null,
            userId: registered?.id ?? null,
          }).returning();
          newlyCreatedContact = true;
        }
      }
      if (access.employee && !newlyCreatedContact) {
        const [previous] = await tx.select({ id: appointmentsTable.id }).from(appointmentsTable).where(and(
          eq(appointmentsTable.employeeId, access.employee.id),
          eq(appointmentsTable.salonCustomerId, contact.id),
        )).limit(1);
        if (!previous) throw new AppointmentSeriesError("Možete izabrati samo klijenta kog ste već uslužili.", 403);
      }
      const requirements = await Promise.all(treatments.map((item) =>
        fetchServiceResourceRequirements(tx, item.serviceId)));
      const planned: Array<{
        item: (typeof treatments)[number];
        service: typeof servicesTable.$inferSelect;
        employeeId: string;
        endTime: string;
      }> = [];
      const reservedAppointments: Array<{ employeeId: string; date: string; startTime: string; endTime: string; bufferMinutes: number; resourceIds: string[] }> = [];
      const resourceReservations: Array<{ resourceId: string; quantity: number; date: string; startTime: string; endTime: string; bufferMinutes: number }> = [];
      for (let index = 0; index < treatments.length; index += 1) {
        const item = treatments[index]!;
        const service = byId.get(item.serviceId)!;
        const endTime = appointmentEndTime(item.startTime, service.durationMinutes);
        if (!endTime) throw new AppointmentSeriesError("Vreme tretmana nije ispravno.", 400);
        const slots = await canonicalAvailability({
          salonId: access.salon.id,
          service,
          dates: [item.date],
          employeeId: access.employee?.id ?? item.employeeId ?? null,
          store: tx,
          reservedAppointments,
          resourceReservations,
        });
        const slot = slots.find((candidate) =>
          candidate.startTime === item.startTime && candidate.endTime === endTime);
        if (!slot) throw new AppointmentSeriesError("Jedan od termina više nije slobodan.", 409);
        planned.push({ item, service, employeeId: slot.employeeId, endTime });
        reservedAppointments.push({
          employeeId: slot.employeeId, date: item.date, startTime: item.startTime, endTime,
          bufferMinutes: service.bufferMinutes, resourceIds: requirements[index]!.map((entry) => entry.resourceId),
        });
        resourceReservations.push(...requirements[index]!.map((entry) => ({
          resourceId: entry.resourceId, quantity: entry.quantity, date: item.date, startTime: item.startTime,
          endTime: appointmentEndTime(endTime, service.bufferMinutes)!, bufferMinutes: 0,
        })));
      }
      const [settings] = await tx.select({ maxVisitGapMinutes: salonBookingSettingsTable.maxVisitGapMinutes })
        .from(salonBookingSettingsTable).where(eq(salonBookingSettingsTable.salonId, access.salon.id)).for("share").limit(1);
      if (!bookingGroupLayoutValid(planned.map((entry, position) => ({
        date: entry.item.date, startTime: entry.item.startTime, endTime: entry.endTime, position,
      })), settings?.maxVisitGapMinutes ?? 0)) throw new BookingGroupLayoutConflictError();
      await lockAppointmentResources(tx, access.salon.id, planned.flatMap((entry, index) => [
        { date: entry.item.date, employeeId: entry.employeeId },
        ...requirements[index]!.map((requirement) => ({ date: entry.item.date, resourceId: requirement.resourceId })),
      ]));
      // A resolved employee may also work at another location. Re-check after
      // acquiring the global employee/resource keys so cross-location writers
      // cannot invalidate the optimistic choices made under the location lock.
      const revalidationAppointments: typeof reservedAppointments = [];
      const revalidationResources: typeof resourceReservations = [];
      for (let index = 0; index < planned.length; index += 1) {
        const entry = planned[index]!;
        const slots = await canonicalAvailability({
          salonId: access.salon.id, service: entry.service, dates: [entry.item.date],
          employeeId: entry.employeeId, store: tx,
          reservedAppointments: revalidationAppointments,
          resourceReservations: revalidationResources,
        });
        if (!slots.some((slot) => slot.startTime === entry.item.startTime
          && slot.endTime === entry.endTime && slot.employeeId === entry.employeeId)) {
          throw new AppointmentSeriesError("Jedan od termina više nije slobodan.", 409);
        }
        revalidationAppointments.push({
          employeeId: entry.employeeId, date: entry.item.date, startTime: entry.item.startTime,
          endTime: entry.endTime, bufferMinutes: entry.service.bufferMinutes,
          resourceIds: requirements[index]!.map((item) => item.resourceId),
        });
        revalidationResources.push(...requirements[index]!.map((item) => ({
          resourceId: item.resourceId, quantity: item.quantity, date: entry.item.date,
          startTime: entry.item.startTime,
          endTime: appointmentEndTime(entry.endTime, entry.service.bufferMinutes)!,
          bufferMinutes: 0,
        })));
      }
      const [group] = await tx.insert(bookingGroupsTable).values({
        salonId: access.salon.id,
        customerId: contact.userId,
        salonCustomerId: contact.id,
        createdByUserId: access.user.id,
        notes: parsed.data.notes ?? null,
      }).returning();
      const appointments = [];
      for (let position = 0; position < planned.length; position += 1) {
        const entry = planned[position]!;
        const appointment = await insertInitializedAppointmentInTx(tx, {
          salonId: access.salon.id, customerId: contact.userId, salonCustomerId: contact.id,
          employeeId: entry.employeeId, serviceId: entry.service.id, bookingGroupId: group!.id,
          date: entry.item.date, startTime: entry.item.startTime, endTime: entry.endTime,
          durationMinutes: entry.service.durationMinutes, price: entry.service.promoPrice ?? entry.service.price,
          notes: parsed.data.notes ?? null, plannedDate: entry.item.date,
          plannedStartTime: entry.item.startTime, plannedEndTime: entry.endTime,
        }, "confirmed", access.user.id);
        await tx.insert(appointmentTreatmentsTable).values({
          appointmentId: appointment!.id, serviceId: entry.service.id, employeeId: entry.employeeId,
          position, durationMinutes: entry.service.durationMinutes, bufferMinutes: entry.service.bufferMinutes,
          price: entry.service.promoPrice ?? entry.service.price,
          plannedStartTime: entry.item.startTime, plannedEndTime: entry.endTime,
        });
        const bufferedEnd = appointmentEndTime(entry.endTime, entry.service.bufferMinutes);
        if (!bufferedEnd) throw new AppointmentSeriesError("Bafer tretmana izlazi van dana.", 409);
        await allocateResourcesInTx(tx, access.salon.id, requirements[position]!, appointment!.id,
          entry.item.date, entry.item.startTime, requirements[position]!.length ? bufferedEnd : entry.endTime);
        appointments.push({ appointment: appointment!, service: entry.service, employeeId: entry.employeeId });
      }
      const employees = await tx.select().from(employeesTable).where(inArray(
        employeesTable.id, appointments.map((item) => item.employeeId)));
      const employeeById = new Map(employees.map((employee) => [employee.id, employee]));
      const views = await Promise.all(appointments.map(async (item) =>
        appointmentView(item.appointment, access.salon, item.service, contact,
          employeeById.get(item.employeeId)!, true, null,
          await getAllocationsForAppointment(tx, item.appointment.id))));
      const response = {
        id: group!.id, salonId: access.salon.id, appointments: views, createdAt: group!.createdAt,
      };
      (access.employee ? CreateEmployeeBookingGroupResponse : CreateSalonBookingGroupResponse).parse(response);
      await enqueueBookingGroupConfirmationInTx(tx, group!.id);
      return { status: 201, body: response };
    });
    if (!command.replayed && command.status === 201) {
      await publishSalonNotificationUpdate(access.salon.id);
    }
    sendBookingCommandResult(res, command);
  } catch (error) {
    if (error instanceof BookingGroupLayoutConflictError) {
      res.status(409).json({ code: error.code, error: error.message }); return;
    }
    if (error instanceof AppointmentSeriesError || error instanceof ResourceCapacityError) {
      res.status(error instanceof AppointmentSeriesError ? error.status : 409).json({ error: error.message }); return;
    }
    throw error;
  }
}

