router.post("/booking-groups", (req, res, next) =>
  replayCustomerBookingCommand(req, res, next, "customer.booking-group.create"),
admitBookingRequest, async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const parsed = CreateBookingGroupBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const rawBody = req.body && typeof req.body === "object" ? req.body as Record<string, unknown> : null;
  const date = rawDateOnlyInput(rawBody?.date);
  const rawTreatmentDates = rawTreatmentDateInputs(req.body, true);
  if (!date || !rawTreatmentDates) { res.status(400).json({ error: "Datum termina nije ispravan." }); return; }
  const treatmentDates = rawTreatmentDates.map((item) => item ?? date);
  if (treatmentDates.some((item) => item < new Date().toISOString().slice(0, 10))) { res.status(400).json({ error: "Datum termina nije ispravan." }); return; }
  const [salon] = await db.select().from(salonsTable).where(and(eq(salonsTable.id, parsed.data.salonId), eq(salonsTable.active, true))).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return; }
  const services = await db.select().from(servicesTable).where(and(eq(servicesTable.salonId, salon.id), eq(servicesTable.active, true), inArray(servicesTable.id, parsed.data.treatments.map((x) => x.serviceId))));
  if (services.length !== new Set(parsed.data.treatments.map((x) => x.serviceId)).size) { res.status(404).json({ error: "Usluga nije pronađena u ovom salonu." }); return; }
  const crm = (await db.insert(salonCustomersTable).values({ salonId: salon.id, userId: user.id, firstName: user.firstName, lastName: user.lastName, email: user.email, phone: user.phone }).onConflictDoNothing().returning())[0]
    ?? (await db.select().from(salonCustomersTable).where(and(eq(salonCustomersTable.salonId, salon.id), eq(salonCustomersTable.userId, user.id))).limit(1))[0];
  if (!crm) { res.status(409).json({ error: "Klijent nije dostupan u salonu." }); return; }
  const byId = new Map(services.map((service) => [service.id, service]));
  try {
    const command = await executeBookingCommand({
      salonId: salon.id, actorType: "user", actorId: user.id, idempotencyKey,
      commandType: "customer.booking-group.create", payload: req.body,
    }, async (tx) => {
      const requirements = await Promise.all(parsed.data.treatments.map((t) => fetchServiceResourceRequirements(tx, t.serviceId)));
      // Resolve "any employee" choices while holding the location/day lock, but
      // do not write yet. Employees are people shared by sibling locations, so
      // every resolved choice must subsequently be locked with the global key.
      await lockAppointmentResources(tx, salon.id, treatmentDates.map((item) => ({ date: item })));
      const planned: Array<{ item: (typeof parsed.data.treatments)[number]; service: typeof servicesTable.$inferSelect; date: string; endTime: string; employeeId: string }> = [];
      const reservedAppointments: Array<{ employeeId: string; date: string; startTime: string; endTime: string; bufferMinutes: number; resourceIds: string[] }> = [];
      const resourceReservations: Array<{ resourceId: string; quantity: number; date: string; startTime: string; endTime: string; bufferMinutes: number }> = [];
      for (let itemIndex = 0; itemIndex < parsed.data.treatments.length; itemIndex++) {
        const item = parsed.data.treatments[itemIndex]!;
        const itemDate = treatmentDates[itemIndex]!;
        const service = byId.get(item.serviceId)!;
        const endTime = appointmentEndTime(item.startTime, service.durationMinutes);
        if (!endTime) throw new AppointmentSeriesError("Neispravno trajanje tretmana.", 400);
        const slots = await canonicalAvailability({
          salonId: salon.id, service, dates: [itemDate], employeeId: item.employeeId ?? null, store: tx,
          reservedAppointments, resourceReservations,
        });
        const slot = slots.find((candidate) => candidate.startTime === item.startTime && candidate.endTime === endTime);
        if (!slot) throw new AppointmentSeriesError("Jedan od termina više nije slobodan.", 409);
        if (planned.some((entry) => entry.date === itemDate && entry.employeeId === slot.employeeId
          && entry.item.startTime < endTime && entry.endTime > item.startTime)) {
          throw new AppointmentSeriesError("Tretmani u grupi se preklapaju.", 409);
        }
        planned.push({ item, service, date: itemDate, endTime, employeeId: slot.employeeId });
        reservedAppointments.push({
          employeeId: slot.employeeId, date: itemDate, startTime: item.startTime, endTime,
          bufferMinutes: service.bufferMinutes, resourceIds: requirements[itemIndex]!.map((entry) => entry.resourceId),
        });
        resourceReservations.push(...requirements[itemIndex]!.map((entry) => ({
          resourceId: entry.resourceId, quantity: entry.quantity, date: itemDate, startTime: item.startTime,
          endTime: appointmentEndTime(endTime, service.bufferMinutes)!, bufferMinutes: 0,
        })));
      }
      const [groupSettings] = await tx.select({ maxVisitGapMinutes: salonBookingSettingsTable.maxVisitGapMinutes })
        .from(salonBookingSettingsTable).where(eq(salonBookingSettingsTable.salonId, salon.id)).for("share").limit(1);
      if (!bookingGroupLayoutValid(planned.map((entry) => ({
        date: entry.date, startTime: entry.item.startTime, endTime: entry.endTime,
      })), groupSettings?.maxVisitGapMinutes ?? 0)) {
        throw new BookingGroupLayoutConflictError();
      }
      await lockAppointmentResources(tx, salon.id, [
        ...planned.map((entry) => ({ date: entry.date, employeeId: entry.employeeId })),
        ...planned.flatMap((entry, index) => requirements[index]!.map((requirement) => ({ date: entry.date, resourceId: requirement.resourceId }))),
      ]);
      const revalidationAppointments: typeof reservedAppointments = [];
      const revalidationResources: typeof resourceReservations = [];
      for (let index = 0; index < planned.length; index += 1) {
        const entry = planned[index]!;
        const slots = await canonicalAvailability({
          salonId: salon.id, service: entry.service, dates: [entry.date], employeeId: entry.employeeId, store: tx,
          reservedAppointments: revalidationAppointments, resourceReservations: revalidationResources,
        });
        if (!slots.some((slot) => slot.startTime === entry.item.startTime && slot.endTime === entry.endTime && slot.employeeId === entry.employeeId)) {
          throw new AppointmentSeriesError("Jedan od termina više nije slobodan.", 409);
        }
        revalidationAppointments.push({
          employeeId: entry.employeeId, date: entry.date, startTime: entry.item.startTime, endTime: entry.endTime,
          bufferMinutes: entry.service.bufferMinutes, resourceIds: requirements[index]!.map((item) => item.resourceId),
        });
        revalidationResources.push(...requirements[index]!.map((item) => ({
          resourceId: item.resourceId, quantity: item.quantity, date: entry.date, startTime: entry.item.startTime,
          endTime: appointmentEndTime(entry.endTime, entry.service.bufferMinutes)!, bufferMinutes: 0,
        })));
      }
      const [group] = await tx.insert(bookingGroupsTable).values({ salonId: salon.id, customerId: user.id, salonCustomerId: crm.id, createdByUserId: user.id, notes: parsed.data.notes ?? null }).returning();
      const appointments: Array<{ appointment: typeof appointmentsTable.$inferSelect; employee: typeof employeesTable.$inferSelect; service: typeof servicesTable.$inferSelect }> = [];
      for (let position = 0; position < planned.length; position++) {
        const { item, service, date: itemDate, endTime, employeeId } = planned[position]!;
        const appointment = await insertInitializedAppointmentInTx(tx, {
          salonId: salon.id, customerId: user.id, salonCustomerId: crm.id, employeeId, serviceId: service.id, bookingGroupId: group!.id,
          date: itemDate, startTime: item.startTime, endTime, durationMinutes: service.durationMinutes, price: service.promoPrice ?? service.price,
          notes: parsed.data.notes ?? null, plannedDate: itemDate, plannedStartTime: item.startTime, plannedEndTime: endTime,
        }, salon.instantBooking ? "confirmed" : "pending", user.id);
        await tx.insert(appointmentTreatmentsTable).values({ appointmentId: appointment!.id, serviceId: service.id, employeeId, position, durationMinutes: service.durationMinutes, bufferMinutes: service.bufferMinutes, price: service.promoPrice ?? service.price, plannedStartTime: item.startTime, plannedEndTime: endTime });
        const bufferedEnd = appointmentEndTime(endTime, service.bufferMinutes);
        if (!bufferedEnd) throw new AppointmentSeriesError("Bafer tretmana izlazi van dana.", 409);
        await allocateResourcesInTx(tx, salon.id, requirements[position]!, appointment!.id, itemDate, item.startTime, requirements[position]!.length ? bufferedEnd : endTime);
        const [employee] = await tx.select().from(employeesTable).where(eq(employeesTable.id, employeeId)).limit(1);
        appointments.push({ appointment: appointment!, employee: employee!, service });
      }
      const views = await Promise.all(appointments.map(async ({ appointment, employee, service }) =>
        appointmentView(appointment, salon, service, user, employee, true, null,
          await getAllocationsForAppointment(tx, appointment.id))));
      await tx.insert(salonNotificationsTable).values({
        salonId: salon.id, title: "Nova grupna rezervacija",
        message: `${user.firstName} ${user.lastName} je zakazao/la ${views.length} tretmana.`,
        href: "/vlasnik/termini",
      });
      const response = CreateBookingGroupResponse.parse({
        id: group!.id, salonId: salon.id, appointments: views, createdAt: group!.createdAt,
      });
      await enqueueBookingGroupConfirmationInTx(tx, group!.id);
      return { status: 201, body: response };
    });
    if (!command.replayed && command.status === 201) {
      await publishSalonNotificationUpdate(salon.id);
    }
    sendBookingCommandResult(res, command);
  } catch (error) {
    if (error instanceof BookingGroupLayoutConflictError) {
      res.status(409).json({ code: error.code, error: error.message }); return;
    }
    if (error instanceof AppointmentSeriesError || error instanceof ResourceCapacityError) { res.status(error instanceof AppointmentSeriesError ? error.status : 409).json({ error: error.message }); return; }
    throw error;
  }
});

router.get("/booking-commands/:idempotencyKey", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const idempotencyKey = String(req.params.idempotencyKey ?? "");
  const salonId = typeof req.query.salonId === "string" ? req.query.salonId : "";
  if (!idempotencyKey || idempotencyKey.length > 200 || !salonId) {
    res.status(400).json({ error: "Idempotency-Key i salonId su obavezni." });
    return;
  }
  const receipt = await findAuthenticatedBookingCommand({ actorId: user.id, salonId, idempotencyKey });
  if (!receipt) {
    res.status(404).json({ error: "Ishod komande zakazivanja nije pronađen." });
    return;
  }
  if (receipt.commandType.startsWith("customer.")) {
    if (!await requireCustomer(req, res)) return;
  } else if (receipt.commandType.startsWith("salon.")) {
    const access = await requireSalonOwner(req, res); if (!access) return;
    if (access.salon.id !== salonId) {
      res.status(403).json({ error: "Nemate pristup ishodu ove komande." });
      return;
    }
  } else if (receipt.commandType.startsWith("employee.")) {
    const access = await requireSalonEmployee(req, res); if (!access) return;
    if (access.salon.id !== salonId) {
      res.status(403).json({ error: "Nemate pristup ishodu ove komande." });
      return;
    }
  } else {
    res.status(404).json({ error: "Ishod komande zakazivanja nije pronađen." });
    return;
  }
  res.json({
    idempotencyKey: receipt.idempotencyKey,
    commandType: receipt.commandType,
    responseStatus: receipt.responseStatus,
    responseBody: receipt.responseBody,
    createdAt: receipt.createdAt,
  });
});

async function bookingGroupView(groupId: string) {
  const [group] = await db.select().from(bookingGroupsTable).where(eq(bookingGroupsTable.id, groupId)).limit(1);
  if (!group) return null;
  const appointments = await appointmentList(eq(appointmentsTable.bookingGroupId, groupId), true);
  return { id: group.id, salonId: group.salonId, appointments, createdAt: group.createdAt };
}

async function bookingGroupAccess(req: Request, res: Response, groupId: string) {
  const user = await current(req, res); if (!user) return null;
  const [group] = await db.select().from(bookingGroupsTable).where(eq(bookingGroupsTable.id, groupId)).limit(1);
  if (!group) { res.status(404).json({ error: "Grupna rezervacija nije pronađena." }); return null; }
  const [salon] = await db.select().from(salonsTable).where(eq(salonsTable.id, group.salonId)).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return null; }
  if (user.role === "CUSTOMER" && group.customerId === user.id) return { user, group, salon, employee: null };
  if (user.role === "SALON_OWNER" && salon.ownerId === user.id) return { user, group, salon, employee: null };
  if (user.role === "SALON_EMPLOYEE") {
    const [employee] = await db.select().from(employeesTable)
      .innerJoin(employeeLocationAssignmentsTable, and(
        eq(employeeLocationAssignmentsTable.employeeId, employeesTable.id),
        eq(employeeLocationAssignmentsTable.salonId, salon.id),
        eq(employeeLocationAssignmentsTable.active, true),
      ))
      .where(and(eq(employeesTable.userId, user.id), eq(employeesTable.active, true))).limit(1);
    if (employee) return { user, group, salon, employee: employee.employees };
  }
  res.status(403).json({ error: "Nemate dozvolu za ovu grupnu rezervaciju." });
  return null;
}

export function bookingGroupLayoutValid(
  treatments: Array<{ date: string; startTime: string; endTime: string; position?: number }>,
  maxGapMinutes: number,
) {
  if (!Number.isInteger(maxGapMinutes) || maxGapMinutes < 0) return false;
  const ordered = treatments.map((treatment, index) => ({
    ...treatment,
    position: treatment.position ?? index,
  })).sort((a, b) => a.position - b.position);
  if (new Set(ordered.map((item) => item.position)).size !== ordered.length) return false;
  for (let index = 1; index < ordered.length; index++) {
    const previous = ordered[index - 1]!;
    const next = ordered[index]!;
    if (next.date < previous.date) return false;
    if (next.date !== previous.date) continue;
    const [endHour, endMinute] = previous.endTime.split(":").map(Number);
    const [startHour, startMinute] = next.startTime.split(":").map(Number);
    const gap = startHour! * 60 + startMinute! - (endHour! * 60 + endMinute!);
    if (gap < 0 || gap > maxGapMinutes) return false;
  }
  return true;
}

async function assertActiveBookingGroupLayoutInTx(
  tx: Parameters<Parameters<typeof db.transaction>[0]>[0],
  salonId: string,
  members: Array<{ id: string; date: string; startTime: string; endTime: string; status: string }>,
) {
  const active = members.filter((item) => item.status === "pending" || item.status === "confirmed");
  if (active.length < 2) return;
  const treatments = await tx.select({
    appointmentId: appointmentTreatmentsTable.appointmentId,
    position: appointmentTreatmentsTable.position,
  }).from(appointmentTreatmentsTable).where(inArray(
    appointmentTreatmentsTable.appointmentId,
    active.map((item) => item.id),
  ));
  const positionById = new Map(treatments.map((item) => [item.appointmentId, item.position]));
  if (positionById.size !== active.length) throw new BookingGroupLayoutConflictError();
  const [settings] = await tx.select({ maxVisitGapMinutes: salonBookingSettingsTable.maxVisitGapMinutes })
    .from(salonBookingSettingsTable).where(eq(salonBookingSettingsTable.salonId, salonId)).for("share").limit(1);
  if (!bookingGroupLayoutValid(active.map((item) => ({
    date: item.date,
    startTime: item.startTime,
    endTime: item.endTime,
    position: positionById.get(item.id)!,
  })), settings?.maxVisitGapMinutes ?? 0)) {
    throw new BookingGroupLayoutConflictError();
  }
}

router.patch("/booking-groups/:bookingGroupId/reschedule", admitBookingRequest, async (req, res): Promise<void> => {
  const params = RescheduleBookingGroupParams.safeParse(req.params);
  const body = RescheduleBookingGroupBody.safeParse(req.body);
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za pomeranje nisu ispravni." }); return; }
  const access = await bookingGroupAccess(req, res, params.data.bookingGroupId); if (!access) return;
  const today = new Date().toISOString().slice(0, 10);
  const rawDates = rawTreatmentDateInputs(req.body);
  if (!rawDates || rawDates.some((item) => item! < today)) {
    res.status(400).json({ error: "Novi datum termina nije ispravan." }); return;
  }
  const treatmentDatesById = new Map(body.data.treatments.map((item, index) => [item.appointmentId, rawDates[index]!]));
  try {
    const warning = await db.transaction(async (tx) => {
      await lockAppointmentResources(tx, access.salon.id);
      const members = await tx.select().from(appointmentsTable)
        .where(eq(appointmentsTable.bookingGroupId, access.group.id)).for("update");
      const active = members.filter((item) => item.status === "pending" || item.status === "confirmed");
      const affectedIds = new Set(body.data.treatments.map((item) => item.appointmentId));
      const affected = active.filter((item) => affectedIds.has(item.id));
      if (affected.length !== affectedIds.size) throw new AppointmentSeriesError("Izabrani aktivni tretman nije član ove grupe.", 404);
      if (access.employee && affected.some((item) => item.employeeId !== access.employee!.id)) {
        throw new AppointmentSeriesError("Zaposleni može pomerati samo svoje tretmane.", 403);
      }
      if (access.employee && body.data.treatments.some((item) =>
        item.employeeId !== undefined && item.employeeId !== null && item.employeeId !== access.employee!.id)) {
        throw new AppointmentSeriesError("Zaposleni ne može dodeliti tretman drugom zaposlenom.", 403);
      }
      const moveById = new Map(body.data.treatments.map((item) => [item.appointmentId, item]));
      const services = await tx.select().from(servicesTable).where(inArray(servicesTable.id, affected.map((item) => item.serviceId)));
      const serviceById = new Map(services.map((item) => [item.id, item]));
      const requirements = new Map<string, Awaited<ReturnType<typeof fetchServiceResourceRequirements>>>();
      for (const item of affected) requirements.set(item.id, await fetchServiceResourceRequirements(tx, item.serviceId));
      await lockAppointmentResources(tx, access.salon.id, affected.flatMap((item) => {
        const move = moveById.get(item.id)!; const date = treatmentDatesById.get(item.id)!;
        return [
          { date: item.date, employeeId: item.employeeId },
          { date, employeeId: move.employeeId ?? item.employeeId },
          ...requirements.get(item.id)!.map((requirement) => ({ date, resourceId: requirement.resourceId })),
        ];
      }));
      const planned: Array<{ appointment: typeof appointmentsTable.$inferSelect; service: typeof servicesTable.$inferSelect; date: string; startTime: string; endTime: string; employeeId: string }> = [];
      const reservedAppointments: Array<{ employeeId: string; date: string; startTime: string; endTime: string; bufferMinutes: number; resourceIds: string[] }> = [];
      const resourceReservations: Array<{ resourceId: string; quantity: number; date: string; startTime: string; endTime: string; bufferMinutes: number }> = [];
      for (const appointment of affected) {
        const move = moveById.get(appointment.id)!;
        const service = serviceById.get(appointment.serviceId)!;
        const date = treatmentDatesById.get(appointment.id)!;
        const endTime = appointmentEndTime(move.startTime, service.durationMinutes);
        if (!endTime) throw new AppointmentSeriesError("Novo vreme tretmana nije ispravno.", 400);
        const slots = await canonicalAvailability({
          salonId: access.salon.id, service, dates: [date], employeeId: move.employeeId ?? appointment.employeeId,
          excludeAppointmentIds: affected.map((item) => item.id), store: tx,
          reservedAppointments, resourceReservations,
        });
        const slot = slots.find((item) => item.startTime === move.startTime && item.endTime === endTime);
        if (!slot || planned.some((item) => item.date === date && item.employeeId === slot.employeeId
          && item.startTime < endTime && item.endTime > move.startTime)) {
          throw new AppointmentSeriesError("Jedan od novih termina više nije slobodan.", 409);
        }
        planned.push({ appointment, service, date, startTime: move.startTime, endTime, employeeId: slot.employeeId });
        const appointmentRequirements = requirements.get(appointment.id)!;
        reservedAppointments.push({
          employeeId: slot.employeeId, date, startTime: move.startTime, endTime,
          bufferMinutes: service.bufferMinutes, resourceIds: appointmentRequirements.map((item) => item.resourceId),
        });
        resourceReservations.push(...appointmentRequirements.map((item) => ({
          resourceId: item.resourceId, quantity: item.quantity, date, startTime: move.startTime,
          endTime: appointmentEndTime(endTime, service.bufferMinutes)!, bufferMinutes: 0,
        })));
      }
      const revalidationAppointments: typeof reservedAppointments = [];
      const revalidationResources: typeof resourceReservations = [];
      for (const item of planned) {
        const slots = await canonicalAvailability({
          salonId: access.salon.id, service: item.service, dates: [item.date], employeeId: item.employeeId,
          excludeAppointmentIds: affected.map((entry) => entry.id), store: tx,
          reservedAppointments: revalidationAppointments, resourceReservations: revalidationResources,
        });
        if (!slots.some((slot) => slot.startTime === item.startTime && slot.endTime === item.endTime
          && slot.employeeId === item.employeeId)) {
          throw new AppointmentSeriesError("Jedan od novih termina više nije slobodan.", 409);
        }
        const appointmentRequirements = requirements.get(item.appointment.id)!;
        revalidationAppointments.push({
          employeeId: item.employeeId, date: item.date, startTime: item.startTime, endTime: item.endTime,
          bufferMinutes: item.service.bufferMinutes, resourceIds: appointmentRequirements.map((entry) => entry.resourceId),
        });
        revalidationResources.push(...appointmentRequirements.map((entry) => ({
          resourceId: entry.resourceId, quantity: entry.quantity, date: item.date, startTime: item.startTime,
          endTime: appointmentEndTime(item.endTime, item.service.bufferMinutes)!, bufferMinutes: 0,
        })));
      }
      for (const item of planned) {
        await tx.delete(appointmentResourceAllocationsTable).where(eq(appointmentResourceAllocationsTable.appointmentId, item.appointment.id));
        const [updated] = await tx.update(appointmentsTable).set({
          date: item.date, startTime: item.startTime, endTime: item.endTime,
          employeeId: item.employeeId, plannedDate: item.date, plannedStartTime: item.startTime,
          plannedEndTime: item.endTime, updatedByUserId: access.user.id, updatedAt: new Date(),
        }).where(eq(appointmentsTable.id, item.appointment.id)).returning();
        await tx.update(appointmentTreatmentsTable).set({
          employeeId: item.employeeId, plannedStartTime: item.startTime, plannedEndTime: item.endTime,
        }).where(eq(appointmentTreatmentsTable.appointmentId, item.appointment.id));
        const bufferedEnd = appointmentEndTime(item.endTime, item.service.bufferMinutes);
        if (!bufferedEnd) throw new AppointmentSeriesError("Bafer tretmana izlazi van dana.", 409);
        await allocateResourcesInTx(tx, access.salon.id, requirements.get(item.appointment.id)!, item.appointment.id,
          item.date, item.startTime, requirements.get(item.appointment.id)!.length ? bufferedEnd : item.endTime);
        await tx.insert(appointmentStatusHistoryTable).values({
          appointmentId: item.appointment.id, status: updated!.status, changedByUserId: access.user.id,
        });
      }
      const finalMembers = members.map((member) => {
        const moved = planned.find((item) => item.appointment.id === member.id);
        return moved ? { ...member, date: moved.date, startTime: moved.startTime, endTime: moved.endTime } : member;
      });
      await assertActiveBookingGroupLayoutInTx(tx, access.salon.id, finalMembers);
      if (access.group.customerId) {
        await notifyCustomer(tx, {
          userId: access.group.customerId, eventKey: `booking-group:${access.group.id}:rescheduled:${Date.now()}`,
          category: "booking", title: "Grupna rezervacija je izmenjena",
          body: `Izmenjeno je ${planned.length} tretmana u salonu ${access.salon.name}.`, deepLink: "/moji-termini",
        });
      }
      await tx.insert(salonNotificationsTable).values({
        salonId: access.salon.id, title: "Izmenjena grupna rezervacija",
        message: `Izmenjeno je ${planned.length} tretmana iz grupne rezervacije.`, href: "/vlasnik/termini",
      });
      return null;
    });
    const group = await bookingGroupView(access.group.id);
    await publishSalonNotificationUpdate(access.salon.id);
    res.json(RescheduleBookingGroupResponse.parse({ group, gapWarning: warning }));
  } catch (error) {
    if (error instanceof BookingGroupLayoutConflictError) {
      res.status(409).json({ code: error.code, error: error.message }); return;
    }
    if (error instanceof AppointmentSeriesError || error instanceof ResourceCapacityError) {
      res.status(error instanceof AppointmentSeriesError ? error.status : 409).json({ error: error.message }); return;
    }
    throw error;
  }
});

router.post("/booking-groups/:bookingGroupId/cancel", async (req, res): Promise<void> => {
  const params = CancelBookingGroupParams.safeParse(req.params);
  const body = CancelBookingGroupBody.safeParse(req.body ?? {});
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za otkazivanje nisu ispravni." }); return; }
  const access = await bookingGroupAccess(req, res, params.data.bookingGroupId); if (!access) return;
  try {
    await db.transaction(async (tx) => {
      await lockAppointmentResources(tx, access.salon.id);
      const members = await tx.select().from(appointmentsTable)
        .where(eq(appointmentsTable.bookingGroupId, access.group.id)).for("update");
      const active = members.filter((item) => item.status === "pending" || item.status === "confirmed");
      const requested = body.data.appointmentIds ? new Set(body.data.appointmentIds) : null;
      const affected = requested ? active.filter((item) => requested.has(item.id)) : active;
      if (requested && affected.length !== requested.size) throw new AppointmentSeriesError("Izabrani aktivni tretman nije član ove grupe.", 404);
      if (access.employee && affected.some((item) => item.employeeId !== access.employee!.id)) {
        throw new AppointmentSeriesError("Zaposleni može otkazati samo svoje tretmane.", 403);
      }
      if (affected.some((item) => item.arrivedAt || item.actualStartedAt)) {
        throw new AppointmentSeriesError("Pristigli ili započeti tretman ne može biti otkazan.", 409);
      }
      const finalMembers = members.map((member) =>
        affected.some((item) => item.id === member.id) ? { ...member, status: "cancelled" } : member);
      await assertActiveBookingGroupLayoutInTx(tx, access.salon.id, finalMembers);
      await lockAppointmentResources(tx, access.salon.id, affected.map((item) => ({ date: item.date, employeeId: item.employeeId })));
      const cancelledAt = new Date();
      const [settings] = await tx.select().from(salonBookingSettingsTable)
        .where(eq(salonBookingSettingsTable.salonId, access.salon.id)).limit(1);
      const deadline = supportedCancellationDeadline(settings?.cancellationDeadlineMinutes);
      const lateAppointments = access.user.role === "CUSTOMER"
        ? affected.filter((item) => isLateCancellation(item.date, item.startTime, deadline, cancelledAt))
        : [];
      for (const appointment of affected) {
        const cancelled = await cancelAppointmentInTx(tx, {
          appointmentId: appointment.id, actorId: access.user.id, occurredAt: cancelledAt,
          reason: body.data.reason ?? "Otkazan tretman iz grupne rezervacije",
          allowBookingGroupMutation: true,
        });
        if (!("appointment" in cancelled)) throw new AppointmentSeriesError("Termin je u međuvremenu promenjen.", 409);
      }
      if (access.group.customerId) {
        await notifyCustomer(tx, {
          userId: access.group.customerId, eventKey: `booking-group:${access.group.id}:cancelled:${cancelledAt.toISOString()}`,
          category: "cancellation", title: "Grupna rezervacija je otkazana",
          body: lateAppointments.length
            ? `Otkazano je ${affected.length} tretmana u salonu ${access.salon.name}. Za ${lateAppointments.length} ${lateAppointments.length === 1 ? "tretman je" : "tretmana je"} prekoračen rok za besplatno otkazivanje.`
            : `Otkazano je ${affected.length} tretmana u salonu ${access.salon.name}.`,
          deepLink: "/moji-termini",
        });
      }
      await tx.insert(salonNotificationsTable).values({
        salonId: access.salon.id, title: "Otkazana grupna rezervacija",
        message: lateAppointments.length
          ? `Otkazano je ${affected.length} tretmana iz grupne rezervacije; ${lateAppointments.length} nakon roka za besplatno otkazivanje.`
          : `Otkazano je ${affected.length} tretmana iz grupne rezervacije.`,
        href: "/vlasnik/termini",
      });
    });
    const group = await bookingGroupView(access.group.id);
    await publishSalonNotificationUpdate(access.salon.id);
    res.json(CancelBookingGroupResponse.parse({ group, gapWarning: null }));
  } catch (error) {
    if (error instanceof BookingGroupLayoutConflictError) {
      res.status(409).json({ code: error.code, error: error.message }); return;
    }
    if (error instanceof AppointmentSeriesError) { res.status(error.status).json({ error: error.message }); return; }
    throw error;
  }
});

router.post("/appointments", (req, res, next) =>
  replayCustomerBookingCommand(req, res, next, "customer.appointment.create"),
admitBookingRequest, async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const parsed = CreateAppointmentBody.safeParse(req.body);
  if (!parsed.success || !isValidCalendarDate(String(req.body?.date ?? ""))) {
    res.status(400).json({ error: parsed.success ? "Datum termina nije ispravan." : parsed.error.message }); return;
  }
  const [bookingContext] = await db.select({
    service: servicesTable,
    salon: salonsTable,
    owner: usersTable,
  }).from(servicesTable)
    .innerJoin(salonsTable, eq(salonsTable.id, servicesTable.salonId))
    .innerJoin(usersTable, eq(usersTable.id, salonsTable.ownerId))
    .where(and(
      eq(servicesTable.id, parsed.data.serviceId),
      eq(servicesTable.salonId, parsed.data.salonId),
    ))
    .limit(1);
  if (!bookingContext) { res.status(404).json({ error: "Salon ili usluga nisu pronađeni." }); return; }
  const { service, salon, owner } = bookingContext;
  const treatmentLocation = parsed.data.treatmentLocation ?? "salon";
  if (treatmentLocation === "home" && !service.homeServiceAvailable) { res.status(400).json({ error: "Ova usluga trenutno nije dostupna na vašoj adresi." }); return; }
  if (treatmentLocation === "home" && (!parsed.data.treatmentAddress?.line1 || !parsed.data.treatmentAddress.city)) { res.status(400).json({ error: "Unesite adresu za dolazak." }); return; }
  if (treatmentLocation === "home" && !user.phoneNormalized) { res.status(400).json({ error: "Potvrdite broj telefona SMS kodom pre zakazivanja dolaska na adresu." }); return; }
  const basePrice = service.promoPrice ?? service.price;
  if (treatmentLocation === "home" && service.homeServiceMinimumOrder !== null && basePrice < service.homeServiceMinimumOrder) {
    res.status(400).json({ error: `Minimalna vrednost usluge za dolazak je ${service.homeServiceMinimumOrder} RSD.` }); return;
  }
  const appointmentDate = calendarDate(parsed.data.date);
  if (appointmentDate < new Date().toISOString().slice(0, 10)) {
    res.status(400).json({ error: "Termin mora biti zakazan za današnji ili budući datum." });
    return;
  }
  const endTime = appointmentEndTime(parsed.data.startTime, service.durationMinutes);
  if (!endTime) { res.status(400).json({ error: "Trajanje termina izlazi van radnog dana." }); return; }
  const [createdContact] = await db.insert(salonCustomersTable).values({
    salonId: salon.id, userId: user.id, firstName: user.firstName, lastName: user.lastName, email: user.email, phone: user.phone,
  }).onConflictDoNothing().returning();
  const crmContact = createdContact ?? (await db.select().from(salonCustomersTable).where(and(eq(salonCustomersTable.salonId, salon.id), eq(salonCustomersTable.userId, user.id))).limit(1))[0];
  const packagePurchaseId = parsed.data.packagePurchaseId ?? null;
  if (packagePurchaseId && !crmContact?.id) {
    res.status(400).json({ error: "Ne možemo povezati paket bez korisničkog profila u salonu." });
    return;
  }
  try {
    const command = await executeBookingCommand({
      salonId: salon.id, actorType: "user", actorId: user.id, idempotencyKey,
      commandType: "customer.appointment.create", payload: req.body,
    }, async (tx) => {
      const allocation = await createAllocatedAppointment({
        salonId: salon.id, customerId: user.id, salonCustomerId: crmContact?.id ?? null, serviceId: service.id,
        date: appointmentDate, startTime: parsed.data.startTime, endTime, durationMinutes: service.durationMinutes,
        price: basePrice + (treatmentLocation === "home" ? service.homeServiceFee : 0),
        status: treatmentLocation === "home" ? "pending" : salon.instantBooking ? "confirmed" : "pending", notes: parsed.data.notes ?? null,
        createdByUserId: user.id,
        preferredEmployeeId: parsed.data.employeeId,
        treatmentLocation, travelFee: treatmentLocation === "home" ? service.homeServiceFee : 0,
        treatmentAddress: treatmentLocation === "home" ? parsed.data.treatmentAddress : null,
        packagePurchaseId, tx,
        afterCreate: async (mutationTx, createdAppointment) => {
          await notifyCustomer(mutationTx, {
            userId: user.id,
            eventKey: `appointment:${createdAppointment.id}:created`,
            category: "booking",
            title: createdAppointment.status === "confirmed" ? "Termin je potvrđen" : "Zahtev za termin je primljen",
            body: `Termin u salonu ${salon.name} je zakazan za ${createdAppointment.date} u ${createdAppointment.startTime}.`,
            deepLink: "/moji-termini",
          });
          await enqueueSms(mutationTx, {
            eventKey: `appointment-created:${createdAppointment.id}`, salonId: salon.id, appointmentId: createdAppointment.id,
            type: "appointment_confirmation", phone: user.phone, smsOptOut: crmContact?.smsOptOut,
            text: createdAppointment.status === "confirmed"
              ? `LUMERA: termin u salonu ${salon.name} je potvrđen za ${calendarDate(createdAppointment.date)} u ${createdAppointment.startTime}.`
              : `LUMERA: zahtev za ${createdAppointment.treatmentLocation === "home" ? "dolazak na adresu" : "termin"} u salonu ${salon.name} je primljen za ${calendarDate(createdAppointment.date)} u ${createdAppointment.startTime}. Salon će ga potvrditi.`,
          });
          await enqueueTransactionalEmails(mutationTx, appointmentEmailInputs({
            event: "created", appointment: createdAppointment, customer: user, salon, service, owner,
          }));
        },
      });
      if (!allocation.employee || !allocation.appointment) {
        return { status: 409, body: { error: "Termin više nije slobodan. Osvežite dostupnost i izaberite drugi termin." } };
      }
      const response = appointmentView(
        allocation.appointment, salon, service, user, allocation.employee, true, null, allocation.allocatedResources,
      );
      CreateAppointmentResponse.parse(response);
      return { status: 201, body: response };
    });
    sendBookingCommandResult(res, command);
    return;
  } catch (err: unknown) {
    if (err instanceof ResourceCapacityError) {
      res.status(409).json({ error: err.message });
      return;
    }
    if (err instanceof PackageRedemptionError) {
      const messages: Record<string, string> = {
        not_found: "Izabrani paket nije pronađen.",
        wrong_salon: "Paket ne pripada ovom salonu.",
        wrong_customer: "Paket ne pripada vama.",
        already_redeemed: "Ovaj termin je već iskorišćen iz paketa.",
        no_sessions_left: "Paket nema više dostupnih tretmana.",
        expired: "Paket je istekao.",
        not_active: "Paket nije aktivan.",
        service_not_covered: "Izabrana usluga nije obuhvaćena ovim paketom.",
        appointment_not_eligible: "Termin nije prihvatljiv za iskorišćavanje paketa.",
      };
      // Stable discriminator: `code` is always PACKAGE_ERROR so clients can
      // distinguish package failures from plain availability 409s; `reason`
      // carries the specific RedeemResult reason for programmatic handling.
      res.status(409).json({
        code: "PACKAGE_ERROR",
        reason: err.reason,
        error: messages[err.reason] ?? "Iskorišćavanje paketa nije uspelo.",
      });
      return;
    }
    throw err;
  }
});

router.patch("/appointments/:appointmentId", admitBookingRequest, async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const [params, body] = [UpdateAppointmentParams.safeParse(req.params), UpdateAppointmentBody.safeParse(req.body)];
  if (!params.success || !body.success || (req.body?.date !== undefined && !isValidCalendarDate(String(req.body.date)))) {
    res.status(400).json({ error: "Podaci za izmenu termina nisu ispravni." }); return;
  }
  let result: { appointment: typeof appointmentsTable.$inferSelect; service: typeof servicesTable.$inferSelect; employee: typeof employeesTable.$inferSelect } | { error: "not-found" | "changed" | "invalid-time" | "unavailable" | "booking-group" };
  try {
    result = await db.transaction(async (tx) => {
      const [initial] = await tx.select().from(appointmentsTable).where(and(
        eq(appointmentsTable.id, params.data.appointmentId),
        eq(appointmentsTable.customerId, user.id),
      )).limit(1);
      if (!initial) return { error: "not-found" as const };
      if (initial.bookingGroupId) return { error: "booking-group" as const };

      const date = body.data.date ? calendarDate(body.data.date) : initial.date;
      const startTime = body.data.startTime ?? initial.startTime;
      const employeeId = body.data.employeeId ?? initial.employeeId;
      await lockAppointmentResources(tx, initial.salonId, [
        { date: initial.date, employeeId: initial.employeeId },
        { date, employeeId },
      ]);
      const [appointment] = await tx.select().from(appointmentsTable).where(and(
        eq(appointmentsTable.id, initial.id),
        eq(appointmentsTable.customerId, user.id),
      )).for("update").limit(1);
      if (!appointment || !["pending", "confirmed"].includes(appointment.status)) return { error: "changed" as const };
      const [service] = await tx.select().from(servicesTable).where(eq(servicesTable.id, appointment.serviceId)).limit(1);
      const endTime = service ? appointmentEndTime(startTime, service.durationMinutes) : null;
      if (!service || !endTime) return { error: "invalid-time" as const };
      const requirements = await fetchServiceResourceRequirements(tx, service.id);
      const initialSlots = await canonicalAvailability({
        salonId: appointment.salonId, service, dates: [date], employeeId,
        excludeAppointmentIds: [appointment.id], store: tx,
      });
      const initialSlot = initialSlots.find((slot) => slot.startTime === startTime && slot.endTime === endTime);
      if (!initialSlot) return { error: "unavailable" as const };
      await lockAppointmentResources(tx, appointment.salonId, [
        { date, employeeId: initialSlot.employeeId },
        ...requirements.map((requirement) => ({ date, resourceId: requirement.resourceId })),
      ]);
      const revalidated = await canonicalAvailability({
        salonId: appointment.salonId, service, dates: [date], employeeId: initialSlot.employeeId,
        excludeAppointmentIds: [appointment.id], store: tx,
      });
      if (!revalidated.some((slot) => slot.startTime === startTime && slot.endTime === endTime)) return { error: "unavailable" as const };
      const [employee] = await tx.select().from(employeesTable).where(eq(employeesTable.id, initialSlot.employeeId)).limit(1);
      if (!employee) return { error: "unavailable" as const };
      const bufferedEnd = appointmentEndTime(endTime, service.bufferMinutes);
      if (!bufferedEnd) return { error: "invalid-time" as const };
      const [updated] = await tx.update(appointmentsTable).set({
        date, startTime, endTime, employeeId: employee.id, notes: body.data.notes ?? appointment.notes,
      }).where(and(eq(appointmentsTable.id, appointment.id), inArray(appointmentsTable.status, ["pending", "confirmed"]))).returning();
      if (!updated) return { error: "changed" as const };
      await tx.delete(appointmentResourceAllocationsTable)
        .where(eq(appointmentResourceAllocationsTable.appointmentId, updated.id));
      // Throws ResourceCapacityError → rolls back transaction.
      await allocateResourcesInTx(tx, appointment.salonId, requirements, updated.id, date, startTime, requirements.length ? bufferedEnd : endTime);
      return { appointment: updated, service, employee };
    });
  } catch (err: unknown) {
    if (err instanceof ResourceCapacityError) {
      res.status(409).json({ error: err.message });
      return;
    }
    throw err;
  }
  if ("error" in result) {
    const error = result.error;
    res.status(error === "not-found" ? 404 : error === "invalid-time" ? 400 : 409).json({
      ...(error === "booking-group" ? { code: "BOOKING_GROUP_MUTATION_REQUIRED" } : {}),
      error: error === "not-found" ? "Termin nije pronađen."
        : error === "invalid-time" ? "Trajanje termina izlazi van radnog dana."
          : error === "unavailable" ? "Termin više nije slobodan kod izabranog zaposlenog."
            : error === "booking-group" ? "Tretman iz grupne rezervacije mora se menjati kroz grupni raspored."
            : "Termin je u međuvremenu promenjen. Osvežite raspored i pokušajte ponovo.",
    });
    return;
  }
  const { appointment: updated, employee } = result;
  const [salon, service, allocatedResources] = await Promise.all([
    db.select().from(salonsTable).where(eq(salonsTable.id, updated!.salonId)).limit(1),
    db.select().from(servicesTable).where(eq(servicesTable.id, updated!.serviceId)).limit(1),
    getAllocationsForAppointment(db, updated!.id),
  ]);
  await sendAppointmentEmails({ event: "updated", appointment: updated, customer: user, salon: salon[0]!, service: service[0]! });
  await notifyCustomer(db, { userId: user.id, eventKey: `appointment:${updated.id}:updated:${updated.updatedAt.toISOString()}`, category: "booking", title: "Termin je izmenjen", body: `Termin u salonu ${salon[0]!.name} je izmenjen.`, deepLink: "/moji-termini" });
  const response = appointmentView(updated, salon[0]!, service[0]!, user, employee, true, null, allocatedResources);
  UpdateAppointmentResponse.parse(response);
  res.json(response);
});

type MarketplaceTransaction = Parameters<Parameters<typeof db.transaction>[0]>[0];

/** Every completed appointment gets these durable, idempotent effects together. */
async function applyAppointmentCompletionEffectsInTx(
  tx: MarketplaceTransaction,
  appointment: typeof appointmentsTable.$inferSelect,
  occurredAt: Date,
) {
  await enqueueAftercareCompletion(tx, {
    appointmentId: appointment.id,
    transitionKey: "appointment-status:completed:v1",
  });
  const warnings = await consumeInventoryForAppointmentInTx(tx, {
    id: appointment.id, salonId: appointment.salonId, serviceId: appointment.serviceId,
  });
  if (appointment.customerId) await recordAppointmentReferralTransitionInTx(tx, {
    appointmentId: appointment.id, customerId: appointment.customerId, salonId: appointment.salonId,
    occurredAt, valid: true,
  });
  return { lowStockWarned: warnings.length > 0 };
}

/** Canonical cancellation; callers perform their own tenant/actor authorization. */
async function cancelAppointmentInTx(
  tx: MarketplaceTransaction,
  input: {
    appointmentId: string;
    actorId: string;
    occurredAt: Date;
    reason: string | null;
    allowBookingGroupMutation?: boolean;
  },
) {
  const [initial] = await tx.select().from(appointmentsTable)
    .where(eq(appointmentsTable.id, input.appointmentId)).limit(1);
  if (!initial) return { error: "not-found" as const };
  await lockAppointmentResources(tx, initial.salonId, [{ date: initial.date, employeeId: initial.employeeId }]);
  const [appointment] = await tx.select().from(appointmentsTable)
    .where(eq(appointmentsTable.id, initial.id)).for("update").limit(1);
  if (!appointment) return { error: "not-found" as const };
  if (appointment.bookingGroupId && !input.allowBookingGroupMutation) {
    return { error: "booking-group" as const };
  }
  if (!canTransitionAppointmentLifecycle(appointment, "cancel", input.occurredAt)) {
    return { error: "invalid-transition" as const };
  }
  const [cancelled] = await tx.update(appointmentsTable).set({
    status: "cancelled", cancellationReason: input.reason,
    cancelledAt: input.occurredAt, cancelledByUserId: input.actorId,
    updatedByUserId: input.actorId, updatedAt: input.occurredAt,
  }).where(and(eq(appointmentsTable.id, appointment.id), inArray(appointmentsTable.status, ["pending", "confirmed"]))).returning();
  if (!cancelled) return { error: "changed" as const };
  await tx.insert(appointmentStatusHistoryTable).values({
    appointmentId: cancelled.id, status: "cancelled", action: "cancel",
    changedByUserId: input.actorId, occurredAt: input.occurredAt,
  });
  await handleAppointmentCancellationReversalsInTx(tx, cancelled.id, cancelled.salonId, input.occurredAt);
  if (cancelled.customerId) {
    await recordAppointmentReferralTransitionInTx(tx, {
      appointmentId: cancelled.id, customerId: cancelled.customerId, salonId: cancelled.salonId,
      occurredAt: input.occurredAt, valid: false, reason: "appointment_cancelled",
    });
    await notifyCustomer(tx, {
      userId: cancelled.customerId,
      eventKey: `appointment:${cancelled.id}:lifecycle:cancel:${input.occurredAt.toISOString()}`,
      category: "cancellation", title: "Termin je otkazan",
      body: "Termin je otkazan.", deepLink: "/moji-termini",
      metadata: { appointmentId: cancelled.id, bookingGroupId: cancelled.bookingGroupId, action: "cancel", occurredAt: input.occurredAt.toISOString() },
    });
  }
  return { appointment: cancelled };
}

router.post("/appointments/:appointmentId/lifecycle", async (req, res): Promise<void> => {
  const actor = await current(req, res); if (!actor) return;
  const [params, body] = [TransitionAppointmentLifecycleParams.safeParse(req.params), TransitionAppointmentLifecycleBody.safeParse(req.body)];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci o promeni statusa nisu ispravni." }); return; }
  let allowedSalonId: string | null = null; let employeeId: string | null = null;
  if (actor.role === "SALON_OWNER") allowedSalonId = (await ownedSalon(actor.id))?.id ?? null;
  else if (actor.role === "SALON_EMPLOYEE") {
    const access = await requireSalonEmployee(req, res); if (!access) return;
    allowedSalonId = access.salon.id; employeeId = access.employee.id;
  } else { res.status(403).json({ error: "Niste ovlašćeni da menjate status termina." }); return; }
  if (!allowedSalonId) { res.status(403).json({ error: "Nalog nije povezan sa salonom." }); return; }
  const serverNow = new Date();
  // `occurredAt` supports a small clock-correction only; it is never a way to
  // backdate a start around the useful-treatment policy.
  if (body.data.occurredAt && !isAllowedLifecycleOccurredAt(body.data.occurredAt, serverNow)) {
    res.status(400).json({ error: "Vreme događaja može odstupati najviše pet minuta od vremena servera.", code: "OCCURRED_AT_OUT_OF_RANGE" });
    return;
  }
  const result = await db.transaction(async (tx) => {
    const [initial] = await tx.select().from(appointmentsTable).where(and(eq(appointmentsTable.id, params.data.appointmentId), eq(appointmentsTable.salonId, allowedSalonId!))).limit(1);
    if (!initial || (employeeId && initial.employeeId !== employeeId)) return null;
    await lockAppointmentResources(tx, initial.salonId, [{ date: initial.date, employeeId: initial.employeeId }]);
    const [appointment] = await tx.select().from(appointmentsTable).where(eq(appointmentsTable.id, initial.id)).for("update").limit(1);
    if (!appointment) return null;
    const occurredAt = body.data.occurredAt ?? serverNow;
    const action = body.data.action;
    if (action === "cancel") {
      const cancelled = await cancelAppointmentInTx(tx, {
        appointmentId: appointment.id, actorId: actor.id, occurredAt, reason: body.data.reason ?? null,
      });
      if ("error" in cancelled && cancelled.error === "booking-group") {
        return { changed: "booking-group" as const };
      }
      return "appointment" in cancelled
        ? { changed: "ok" as const, appointment: cancelled.appointment, lowStockWarned: false }
        : { changed: "invalid" as const };
    }
    if (!canTransitionAppointmentLifecycle(appointment, action, occurredAt)) return { changed: "invalid" as const };
    const fields: Partial<typeof appointmentsTable.$inferInsert> = { updatedByUserId: actor.id, updatedAt: new Date() };
    if (action === "confirm" && appointment.status === "pending") { fields.status = "confirmed"; fields.confirmedAt = occurredAt; }
    else if (action === "arrive" && appointment.status === "confirmed" && !appointment.arrivedAt && !appointment.actualStartedAt) {
      fields.arrivedAt = occurredAt; fields.arrivedByUserId = actor.id;
    } else if (action === "start" && appointment.status === "confirmed" && appointment.arrivedAt && !appointment.actualStartedAt) {
      const plannedEnd = appointment.plannedEndTime ?? appointment.endTime;
      const plannedEndAt = zonedAppointmentInstant(appointment.plannedDate ?? appointment.date, plannedEnd);
      const remaining = Math.floor((plannedEndAt.getTime() - occurredAt.getTime()) / 60_000);
      const [settings] = await tx.select().from(salonBookingSettingsTable).where(eq(salonBookingSettingsTable.salonId, appointment.salonId)).limit(1);
      const minimumUsefulMinutes = settings?.minimumUsefulLateTreatmentMinutes ?? 0;
      if (remaining < minimumUsefulMinutes) return { changed: "late" as const, remainingMinutes: remaining, minimumUsefulMinutes, plannedEndAt };
      fields.actualStartedAt = occurredAt; fields.startedByUserId = actor.id;
    } else if (action === "complete" && appointment.status === "confirmed" && appointment.actualStartedAt) {
      fields.status = "completed"; fields.actualCompletedAt = occurredAt; fields.completedAt = occurredAt; fields.completedByUserId = actor.id;
    } else if (action === "no-show" && ["pending", "confirmed"].includes(appointment.status) && !appointment.arrivedAt && !appointment.actualStartedAt) {
      fields.status = "no-show"; fields.noShowAt = occurredAt; fields.noShowByUserId = actor.id;
    } else return { changed: "invalid" as const };
    const [updated] = await tx.update(appointmentsTable).set(fields).where(eq(appointmentsTable.id, appointment.id)).returning();
    await tx.insert(appointmentStatusHistoryTable).values({
      appointmentId: appointment.id, status: updated!.status, action,
      changedByUserId: actor.id, occurredAt,
    });
    if (action === "no-show" && updated!.customerId) await recordAppointmentReferralTransitionInTx(tx, {
      appointmentId: updated!.id, customerId: updated!.customerId, salonId: updated!.salonId,
      occurredAt, valid: false, reason: "salon_marked_no_show",
    });
    const completionEffects = action === "complete"
      ? await applyAppointmentCompletionEffectsInTx(tx, updated!, occurredAt)
      : { lowStockWarned: false };
    if (updated!.customerId) await notifyCustomer(tx, {
      userId: updated!.customerId,
      eventKey: `appointment:${updated!.id}:lifecycle:${action}:${occurredAt.toISOString()}`,
      category: "booking",
      title: "Status termina je promenjen", body: `Termin je označen kao ${action}.`,
      deepLink: "/moji-termini",
      metadata: { appointmentId: updated!.id, bookingGroupId: updated!.bookingGroupId, action, occurredAt: occurredAt.toISOString() },
    });
    if (action === "complete") await createAppointmentReviewInvitationInTx(tx, updated!);
    return { changed: "ok" as const, appointment: updated!, ...completionEffects };
  });
  if (!result) { res.status(404).json({ error: "Termin nije pronađen." }); return; }
  if (result.changed !== "ok") {
    res.status(409).json(result.changed === "late"
      ? { error: "Preostalo vreme nije dovoljno za tretman.", code: "INSUFFICIENT_USEFUL_TIME", remainingMinutes: result.remainingMinutes, minimumUsefulMinutes: result.minimumUsefulMinutes, plannedEndAt: result.plannedEndAt }
      : result.changed === "booking-group"
        ? { error: "Tretman iz grupne rezervacije mora se otkazati kroz grupni raspored.", code: "BOOKING_GROUP_MUTATION_REQUIRED" }
      : { error: "Ova promena statusa nije dozvoljena.", code: "INVALID_TRANSITION" });
    return;
  }
  const lifecycleAppointment = result.appointment!;
  const [salon, service, employee, allocations] = await Promise.all([
    db.select().from(salonsTable).where(eq(salonsTable.id, lifecycleAppointment.salonId)).limit(1),
    db.select().from(servicesTable).where(eq(servicesTable.id, lifecycleAppointment.serviceId)).limit(1),
    lifecycleAppointment.employeeId ? db.select().from(employeesTable).where(eq(employeesTable.id, lifecycleAppointment.employeeId)).limit(1) : Promise.resolve([]),
    getAllocationsForAppointment(db, lifecycleAppointment.id),
  ]);
  if (result.lowStockWarned) await publishSalonNotificationUpdate(lifecycleAppointment.salonId);
  res.json(TransitionAppointmentLifecycleResponse.parse(appointmentView(lifecycleAppointment, salon[0]!, service[0]!, actor, employee[0], true, null, allocations)));
});

router.post("/appointments/:appointmentId/cancel", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const [params, body] = [CancelAppointmentParams.safeParse(req.params), CancelAppointmentBody.safeParse(req.body ?? {})];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za otkazivanje nisu ispravni." }); return; }
  const result = await db.transaction(async (tx) => {
    const [initial] = await tx.select().from(appointmentsTable).where(and(
      eq(appointmentsTable.id, params.data.appointmentId),
      eq(appointmentsTable.customerId, user.id),
    )).limit(1);
    if (!initial) return { error: "not-found" as const };
    await lockAppointmentResources(tx, initial.salonId, [{ date: initial.date, employeeId: initial.employeeId }]);
    const [settings] = await tx.select().from(salonBookingSettingsTable)
      .where(eq(salonBookingSettingsTable.salonId, initial.salonId)).limit(1);
    const cancelledAt = new Date();
    const deadline = supportedCancellationDeadline(settings?.cancellationDeadlineMinutes);
    const lateCancellation = isLateCancellation(initial.date, initial.startTime, deadline, cancelledAt);
    const cancelled = await cancelAppointmentInTx(tx, {
      appointmentId: initial.id, actorId: user.id, occurredAt: cancelledAt, reason: body.data.reason ?? null,
    });
    if ("error" in cancelled && cancelled.error === "booking-group") return { error: "booking-group" as const };
    if (!("appointment" in cancelled)) return { error: "changed" as const };
    const appointment = cancelled.appointment!;
    if (lateCancellation) {
      await tx.insert(salonNotificationsTable).values({
        salonId: appointment.salonId,
        title: "Kasno otkazivanje termina",
        message: `${user.firstName} ${user.lastName} je otkazao/la termin ${appointment.date} u ${appointment.startTime} nakon roka za otkazivanje.`,
        href: "/vlasnik/termini",
      });
    }
    return { appointment, lateCancellation };
  });
  if ("error" in result) {
    res.status(result.error === "not-found" ? 404 : 409).json({
      ...(result.error === "booking-group" ? { code: "BOOKING_GROUP_MUTATION_REQUIRED" } : {}),
      error: result.error === "not-found" ? "Termin nije pronađen."
        : result.error === "booking-group" ? "Tretman iz grupne rezervacije mora se otkazati kroz grupni raspored."
          : "Termin je u međuvremenu promenjen ili otkazan.",
    });
    return;
  }
  const appointment = result.appointment!;
  const { lateCancellation } = result;
  const [salon, service, employee, allocatedResources] = await Promise.all([
    db.select().from(salonsTable).where(eq(salonsTable.id, appointment.salonId)).limit(1),
    db.select().from(servicesTable).where(eq(servicesTable.id, appointment.serviceId)).limit(1),
    appointment.employeeId ? db.select().from(employeesTable).where(eq(employeesTable.id, appointment.employeeId)).limit(1) : Promise.resolve([]),
    getAllocationsForAppointment(db, appointment.id),
  ]);
  await sendAppointmentEmails({ event: "cancelled", appointment, customer: user, salon: salon[0]!, service: service[0]! });
  if (lateCancellation) await publishSalonNotificationUpdate(appointment.salonId);
  const response = appointmentView(appointment, salon[0]!, service[0]!, user, employee[0], true, null, allocatedResources);
  CancelAppointmentResponse.parse(response);
  res.json(response);
});

router.get("/customer/dashboard", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  // Bound every read to what the dashboard renders instead of loading the
  // customer's entire appointment history:
  //   - `upcoming` is the earliest 3 non-cancelled appointments (SQL order + limit).
  //   - visit/favorite counts and booked/preference sets are SQL aggregates.
  //   - recommendation candidates are ranked and limited in SQL before card assembly.
  const [upcoming, visitCountRows, favoriteCountRows, bookedSalonRows, preferredCategoryRows] = await Promise.all([
    appointmentList(
      and(eq(appointmentsTable.customerId, user.id), ne(appointmentsTable.status, "cancelled")),
      true,
      { limit: 3, offset: 0 },
    ),
    db.select({ value: count() }).from(appointmentsTable)
      .where(and(eq(appointmentsTable.customerId, user.id), eq(appointmentsTable.status, "completed"))),
    db.select({ value: count() }).from(favoritesTable).where(eq(favoritesTable.userId, user.id)),
    db.selectDistinct({ salonId: appointmentsTable.salonId }).from(appointmentsTable)
      .where(and(eq(appointmentsTable.customerId, user.id), ne(appointmentsTable.status, "cancelled"))),
    db.selectDistinct({ categoryName: servicesTable.categoryName })
      .from(appointmentsTable)
      .innerJoin(servicesTable, eq(servicesTable.id, appointmentsTable.serviceId))
      .where(and(eq(appointmentsTable.customerId, user.id), ne(appointmentsTable.status, "cancelled"))),
  ]);
  const bookedSalonIds = bookedSalonRows.map((row) => row.salonId);
  const preferredCategories = preferredCategoryRows.map((row) => row.categoryName);
  // Rank recommendation candidates in SQL (active salons with an active service
  // in a preferred category, excluding already-booked salons) and cap at 15 so
  // card assembly only ever sees a bounded set.
  const recommendedSalonIdRows = preferredCategories.length
    ? await db.selectDistinct({
        id: salonsTable.id,
        topSalon: salonsTable.topSalon,
        featured: salonsTable.featured,
        rating: salonsTable.rating,
      })
      .from(salonsTable)
      .innerJoin(servicesTable, eq(servicesTable.salonId, salonsTable.id))
      .where(and(
        eq(salonsTable.active, true),
        eq(servicesTable.active, true),
        inArray(servicesTable.categoryName, preferredCategories),
        ...(bookedSalonIds.length ? [notInArray(salonsTable.id, bookedSalonIds)] : []),
      ))
      .orderBy(desc(salonsTable.topSalon), desc(salonsTable.featured), desc(salonsTable.rating), asc(salonsTable.id))
      .limit(15)
    : [];
  const recommendedIds = recommendedSalonIdRows.map((row) => row.id);
  const [recommendedSalons, recentSalons] = await Promise.all([
    recommendedIds.length
      ? db.select().from(salonsTable).where(inArray(salonsTable.id, recommendedIds))
      : Promise.resolve([] as (typeof salonsTable.$inferSelect)[]),
    db.select().from(salonsTable).where(eq(salonsTable.active, true)).limit(3),
  ]);
  // Preserve the SQL ranking order when reloading full salon rows for cards.
  const recommendedRank = new Map(recommendedIds.map((id, index) => [id, index]));
  recommendedSalons.sort((left, right) => (recommendedRank.get(left.id) ?? 0) - (recommendedRank.get(right.id) ?? 0));
  res.json(GetCustomerDashboardResponse.parse({
    upcoming,
    recentSalons: await salonCards(recentSalons),
    recommendations: await salonCards(recommendedSalons),
    favoriteCount: favoriteCountRows[0]?.value ?? 0,
    visitCount: visitCountRows[0]?.value ?? 0,
  }));
});

router.get("/customer/favorites", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const favorites = await db.select().from(favoritesTable).where(eq(favoritesTable.userId, user.id));
  const salons = favorites.length ? await db.select().from(salonsTable).where(inArray(salonsTable.id, favorites.map((item) => item.salonId))) : [];
  res.json(ListFavoritesResponse.parse(await salonCards(salons)));
});

router.post("/customer/favorites", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const parsed = ToggleFavoriteBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const [favorite] = await db.select().from(favoritesTable).where(and(eq(favoritesTable.userId, user.id), eq(favoritesTable.salonId, parsed.data.salonId))).limit(1);
  if (favorite) await db.delete(favoritesTable).where(eq(favoritesTable.id, favorite.id));
  else await db.insert(favoritesTable).values({ userId: user.id, salonId: parsed.data.salonId });
  res.json(ToggleFavoriteResponse.parse({ salonId: parsed.data.salonId, favorited: !favorite }));
});

async function customerReviewContext(customerId: string, salonId: string) {
  const [completedAppointments, existingReview] = await Promise.all([
    db.select().from(appointmentsTable).where(and(
      eq(appointmentsTable.customerId, customerId),
      eq(appointmentsTable.salonId, salonId),
      eq(appointmentsTable.status, "completed"),
    )),
    db.select().from(reviewsTable).where(and(
      eq(reviewsTable.customerId, customerId),
      eq(reviewsTable.salonId, salonId),
    )).orderBy(desc(reviewsTable.createdAt)).limit(1),
  ]);
  const completedServiceIds = [...new Set(completedAppointments.map((appointment) => appointment.serviceId))];
  const completedServices = completedServiceIds.length
    ? await db.select().from(servicesTable).where(inArray(servicesTable.id, completedServiceIds))
    : [];
  return {
    review: existingReview[0] ?? null,
    eligibleServices: [...new Set(completedServices.map((service) => service.name))],
  };
}

function customerReviewView(review: typeof reviewsTable.$inferSelect) {
  return {
    id: review.id,
    salonId: review.salonId,
    serviceName: review.serviceName,
    rating: review.rating,
    text: review.text,
    showProfilePhoto: review.showProfilePhoto,
  };
}

router.get("/customer/reviews/:salonId", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const parsed = GetCustomerSalonReviewParams.safeParse(req.params);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const [salon] = await db.select({ id: salonsTable.id }).from(salonsTable).where(eq(salonsTable.id, parsed.data.salonId)).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return; }
  const context = await customerReviewContext(user.id, salon.id);
  res.json(GetCustomerSalonReviewResponse.parse({
    review: context.review ? customerReviewView(context.review) : null,
    eligibleServices: context.eligibleServices,
  }));
});

router.put("/customer/reviews/:salonId", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const [params, body] = [UpsertCustomerSalonReviewParams.safeParse(req.params), UpsertCustomerSalonReviewBody.safeParse(req.body)];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za recenziju nisu ispravni." }); return; }
  const [salon] = await db.select({ id: salonsTable.id }).from(salonsTable).where(eq(salonsTable.id, params.data.salonId)).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return; }
  const context = await customerReviewContext(user.id, salon.id);
  const keepsExistingService = context.review?.serviceName === body.data.serviceName;
  if (!keepsExistingService && !context.eligibleServices.includes(body.data.serviceName)) {
    res.status(400).json({ error: "Recenziju možete ostaviti samo za završenu uslugu u ovom salonu." });
    return;
  }
  // Derive the employeeId from the customer's most recent completed appointment at this salon
  const [custRec] = await db
    .select({ id: salonCustomersTable.id })
    .from(salonCustomersTable)
    .where(and(eq(salonCustomersTable.userId, user.id), eq(salonCustomersTable.salonId, salon.id)))
    .limit(1);
  let latestEmployeeId: string | null = null;
  if (custRec) {
    const [latestAppt] = await db
      .select({ employeeId: appointmentsTable.employeeId })
      .from(appointmentsTable)
      .where(and(
        eq(appointmentsTable.salonId, salon.id),
        eq(appointmentsTable.salonCustomerId, custRec.id),
        eq(appointmentsTable.status, "completed"),
      ))
      .orderBy(desc(appointmentsTable.date))
      .limit(1);
    latestEmployeeId = latestAppt?.employeeId ?? null;
  }
  const reviewInput = {
    serviceName: body.data.serviceName,
    rating: body.data.rating,
    text: body.data.text.trim(),
    showProfilePhoto: body.data.showProfilePhoto,
    employeeId: latestEmployeeId,
  };
  const saved = await db.transaction(async (tx) => {
    // Serializing writes per salon keeps the stored public aggregate in sync
    // when several customers submit reviews at the same time.
    await tx.select({ id: salonsTable.id }).from(salonsTable)
      .where(eq(salonsTable.id, salon.id))
      .for("update");
    const [review] = await tx.insert(reviewsTable)
      .values({ salonId: salon.id, customerId: user.id, ...reviewInput })
      .onConflictDoUpdate({
        target: [reviewsTable.customerId, reviewsTable.salonId],
        set: reviewInput,
      })
      .returning();
    const visibleReviews = await tx.select().from(reviewsTable).where(and(
      eq(reviewsTable.salonId, salon.id),
      eq(reviewsTable.visible, true),
    ));
    const reviewCount = visibleReviews.length;
    const rating = reviewCount
      ? Math.round(visibleReviews.reduce((total, item) => total + item.rating, 0) / reviewCount * 10)
      : 0;
    await tx.update(salonsTable).set({ reviewCount, rating }).where(eq(salonsTable.id, salon.id));
    return review!;
  });
  res.json(UpsertCustomerSalonReviewResponse.parse(customerReviewView(saved!)));
});

router.delete("/customer/reviews/:salonId", async (req, res): Promise<void> => {
  const user = await requireCustomer(req, res); if (!user) return;
  const params = DeleteCustomerSalonReviewParams.safeParse(req.params);
  if (!params.success) { res.status(400).json({ error: params.error.message }); return; }
  const [salon] = await db.select({ id: salonsTable.id }).from(salonsTable).where(eq(salonsTable.id, params.data.salonId)).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return; }

  const deleted = await db.transaction(async (tx) => {
    // Serialize review writes per salon so the stored public aggregate stays
    // correct when a review is deleted while another is created or updated.
    await tx.select({ id: salonsTable.id }).from(salonsTable)
      .where(eq(salonsTable.id, salon.id))
      .for("update");
    const [review] = await tx.delete(reviewsTable).where(and(
      eq(reviewsTable.salonId, salon.id),
      eq(reviewsTable.customerId, user.id),
    )).returning();
    if (!review) return false;

    const visibleReviews = await tx.select().from(reviewsTable).where(and(
      eq(reviewsTable.salonId, salon.id),
      eq(reviewsTable.visible, true),
    ));
    const reviewCount = visibleReviews.length;
    const rating = reviewCount
      ? Math.round(visibleReviews.reduce((total, item) => total + item.rating, 0) / reviewCount * 10)
      : 0;
    await tx.update(salonsTable).set({ reviewCount, rating }).where(eq(salonsTable.id, salon.id));
    return true;
  });
  if (!deleted) { res.status(404).json({ error: "Vaša recenzija nije pronađena." }); return; }

  DeleteCustomerSalonReviewResponse.parse(undefined);
  res.sendStatus(204);
});

