const BOOKING_CANCELLATION_DEADLINES = new Set([720, 1440, 2880]);
const BOOKING_REMINDER_OFFSETS = new Set([120, 720, 1440]);

function supportedCancellationDeadline(value: number | null | undefined) {
  return value != null && BOOKING_CANCELLATION_DEADLINES.has(value) ? value : 1440;
}

function supportedReminderOffsets(values: number[] | null | undefined) {
  return [...new Set((values ?? []).filter((value) => BOOKING_REMINDER_OFFSETS.has(value)))];
}

async function bookingSettingsView(salonId: string) {
  const [settings, dateHours, downtime] = await Promise.all([
    db.select().from(salonBookingSettingsTable).where(eq(salonBookingSettingsTable.salonId, salonId)).limit(1),
    db.select().from(salonDateHoursTable).where(eq(salonDateHoursTable.salonId, salonId)).orderBy(asc(salonDateHoursTable.date)),
    db.select({ downtime: salonResourceDowntimeTable }).from(salonResourceDowntimeTable)
      .innerJoin(salonResourcesTable, eq(salonResourcesTable.id, salonResourceDowntimeTable.resourceId))
      .where(eq(salonResourcesTable.salonId, salonId)),
  ]);
  const row = settings[0];
  return {
    salonId, updatedAt: row?.updatedAt ?? new Date(),
    slotGranularityMinutes: row?.slotGranularityMinutes ?? 15,
    minimumLeadTimeMinutes: row?.minimumLeadTimeMinutes ?? 0,
    cancellationDeadlineMinutes: supportedCancellationDeadline(row?.cancellationDeadlineMinutes),
    reminderOffsetsMinutes: supportedReminderOffsets(row?.reminderOffsetsMinutes),
    reminderChannels: row?.reminderChannels ?? [],
    maxVisitGapMinutes: row?.maxVisitGapMinutes ?? 0,
    minimumUsefulLateTreatmentMinutes: row?.minimumUsefulLateTreatmentMinutes ?? 0,
    dateHours: dateHours.map((item) => ({ id: item.id, date: new Date(`${item.date}T00:00:00Z`), closed: item.closed, openTime: item.openTime, closeTime: item.closeTime, reason: item.reason })),
    resourceDowntime: downtime.map(({ downtime: item }) => ({ id: item.id, resourceId: item.resourceId, startsAt: item.startsAt, endsAt: item.endsAt, reason: item.reason })),
  };
}

router.get("/salon/booking-settings", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  res.json(GetSalonBookingSettingsResponse.parse(await bookingSettingsView(access.salon.id)));
});

router.put("/salon/booking-settings", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = ReplaceSalonBookingSettingsBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const rawDateHours = rawTreatmentDateInputs({ treatments: req.body?.dateHours });
  if (!rawDateHours) { res.status(400).json({ error: "Izuzeci radnog vremena nisu ispravni." }); return; }
  const dateHours = parsed.data.dateHours.map((item, index) => ({ ...item, date: rawDateHours[index]! }));
  const invalidHours = dateHours.some((item) =>
    item.closed ? item.openTime !== null || item.closeTime !== null : !item.openTime || !item.closeTime || item.openTime >= item.closeTime);
  if (invalidHours) { res.status(400).json({ error: "Izuzeci radnog vremena nisu ispravni." }); return; }
  const resourceIds = [...new Set(parsed.data.resourceDowntime.map((item) => item.resourceId))];
  if (resourceIds.length) {
    const resources = await db.select({ id: salonResourcesTable.id }).from(salonResourcesTable)
      .where(and(eq(salonResourcesTable.salonId, access.salon.id), inArray(salonResourcesTable.id, resourceIds)));
    if (resources.length !== resourceIds.length) { res.status(404).json({ error: "Resurs ne pripada aktivnom salonu." }); return; }
  }
  await db.transaction(async (tx) => {
    await tx.insert(salonBookingSettingsTable).values({ salonId: access.salon.id, ...parsed.data, updatedByUserId: access.user.id, updatedAt: new Date() })
      .onConflictDoUpdate({ target: salonBookingSettingsTable.salonId, set: { ...parsed.data, updatedByUserId: access.user.id, updatedAt: new Date() } });
    await tx.delete(salonDateHoursTable).where(eq(salonDateHoursTable.salonId, access.salon.id));
    if (dateHours.length) await tx.insert(salonDateHoursTable).values(dateHours.map((item) => ({
      salonId: access.salon.id, date: item.date, closed: item.closed, openTime: item.openTime, closeTime: item.closeTime, reason: item.reason,
    })));
    const allResourceIds = (await tx.select({ id: salonResourcesTable.id }).from(salonResourcesTable)
      .where(eq(salonResourcesTable.salonId, access.salon.id))).map((resource) => resource.id);
    if (allResourceIds.length) await tx.delete(salonResourceDowntimeTable)
      .where(inArray(salonResourceDowntimeTable.resourceId, allResourceIds));
    if (parsed.data.resourceDowntime.length) await tx.insert(salonResourceDowntimeTable).values(parsed.data.resourceDowntime.map((item) => ({
      resourceId: item.resourceId, startsAt: item.startsAt, endsAt: item.endsAt, reason: item.reason, createdByUserId: access.user.id,
    })));
  });
  res.json(ReplaceSalonBookingSettingsResponse.parse(await bookingSettingsView(access.salon.id)));
});

router.get("/salon/appointments", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const { salon } = access;
  const parseQueryDate = (value: unknown) => typeof value === "string" ? new Date(`${value}T12:00:00.000Z`) : value;
  const parsed = ListSalonAppointmentsQueryParams.safeParse({ ...req.query, from: parseQueryDate(req.query.from), to: parseQueryDate(req.query.to) });
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  // Push status/date-range predicates into SQL so they filter before the stable
  // page. Query count stays constant regardless of page size or applied filters.
  const predicates = [eq(appointmentsTable.salonId, salon.id)];
  if (parsed.data.status) predicates.push(sql`${appointmentsTable.status}::text = ${parsed.data.status}`);
  if (parsed.data.from) predicates.push(gte(appointmentsTable.date, calendarDate(parsed.data.from)));
  if (parsed.data.to) predicates.push(lte(appointmentsTable.date, calendarDate(parsed.data.to)));
  if (parsed.data.employeeId) {
    if (!(await employeeInSalon(parsed.data.employeeId, salon.id))) {
      res.status(404).json({ error: "Zaposleni nije pronađen u ovom salonu." });
      return;
    }
    predicates.push(eq(appointmentsTable.employeeId, parsed.data.employeeId));
  }
  if (parsed.data.serviceId) {
    const [service] = await db.select({ id: servicesTable.id }).from(servicesTable).where(and(
      eq(servicesTable.id, parsed.data.serviceId),
      eq(servicesTable.salonId, salon.id),
    )).limit(1);
    if (!service) {
      res.status(404).json({ error: "Usluga nije pronađena u ovom salonu." });
      return;
    }
    predicates.push(eq(appointmentsTable.serviceId, service.id));
  }
  const { limit, offset } = parsePagination(req.query, 100);
  const items = await appointmentList(and(...predicates), true, { limit, offset });
  res.json(ListSalonAppointmentsResponse.parse(items));
});

router.get("/salon/time-blocks", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = ListSalonTimeBlocksQueryParams.safeParse(req.query);
  if (!parsed.success || !isValidCalendarDate(parsed.data.date)) {
    res.status(400).json({ error: parsed.success ? "Datum nije ispravan." : parsed.error.message }); return;
  }
  if (parsed.data.employeeId && !(await employeeInSalon(parsed.data.employeeId, access.salon.id))) {
    res.status(404).json({ error: "Zaposleni nije pronađen u ovom salonu." }); return;
  }
  const employeeIds = parsed.data.employeeId
    ? [parsed.data.employeeId]
    : (await db.select({ id: employeesTable.id }).from(employeesTable)
      .innerJoin(employeeLocationAssignmentsTable, and(
        eq(employeeLocationAssignmentsTable.employeeId, employeesTable.id),
        eq(employeeLocationAssignmentsTable.salonId, access.salon.id),
        eq(employeeLocationAssignmentsTable.active, true),
      )).where(eq(employeesTable.active, true))).map((employee) => employee.id);
  const blocks = employeeIds.length ? await db.select().from(employeeTimeOffTable).where(and(
    inArray(employeeTimeOffTable.employeeId, employeeIds),
    eq(employeeTimeOffTable.startDate, parsed.data.date),
    eq(employeeTimeOffTable.endDate, parsed.data.date),
    or(isNull(employeeTimeOffTable.salonId), eq(employeeTimeOffTable.salonId, access.salon.id)),
    isNotNull(employeeTimeOffTable.startTime),
    isNotNull(employeeTimeOffTable.endTime),
  )).orderBy(asc(employeeTimeOffTable.startTime), asc(employeeTimeOffTable.id)) : [];
  const response = blocks.map((block) => ({
    id: block.id, employeeId: block.employeeId, date: block.startDate,
    startTime: block.startTime!, endTime: block.endTime!, reason: block.reason,
  }));
  res.json(ListSalonTimeBlocksResponse.parse(response));
});

router.post("/salon/time-blocks", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = CreateSalonTimeBlockBody.safeParse(req.body);
  if (!parsed.success || !isValidCalendarDate(parsed.data.date) || parsed.data.startTime >= parsed.data.endTime) {
    res.status(400).json({
      error: !parsed.success
        ? parsed.error.message
        : !isValidCalendarDate(parsed.data.date)
          ? "Datum nije ispravan."
          : "Vreme početka mora biti pre vremena završetka.",
    });
    return;
  }
  const employee = await employeeInSalon(parsed.data.employeeId, access.salon.id);
  if (!employee || !employee.active) { res.status(404).json({ error: "Aktivni zaposleni nije pronađen u ovom salonu." }); return; }
  const result = await db.transaction(async (tx) => {
    await lockAppointmentResources(tx, access.salon.id, [{ date: parsed.data.date, employeeId: employee.id }]);
    const appointments = await tx.select().from(appointmentsTable).where(and(
      eq(appointmentsTable.salonId, access.salon.id),
      eq(appointmentsTable.employeeId, employee.id),
      eq(appointmentsTable.date, parsed.data.date),
    ));
    if (appointments.some((appointment) => overlapsAppointment(parsed.data.startTime, parsed.data.endTime, appointment))) return null;
    const [block] = await tx.insert(employeeTimeOffTable).values({
      employeeId: employee.id, startDate: parsed.data.date, endDate: parsed.data.date,
      salonId: access.salon.id, startTime: parsed.data.startTime, endTime: parsed.data.endTime, reason: parsed.data.reason.trim(),
    }).returning();
    return block!;
  });
  if (!result) { res.status(409).json({ error: "Blok se preklapa sa aktivnim terminom." }); return; }
  res.status(201).json(CreateSalonTimeBlockResponse.parse({
    id: result.id, employeeId: result.employeeId, date: result.startDate,
    startTime: result.startTime!, endTime: result.endTime!, reason: result.reason,
  }));
});

router.delete("/salon/time-blocks/:timeBlockId", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const params = DeleteSalonTimeBlockParams.safeParse(req.params);
  if (!params.success) { res.status(400).json({ error: params.error.message }); return; }
  const deleted = await db.delete(employeeTimeOffTable).where(and(
    eq(employeeTimeOffTable.id, params.data.timeBlockId),
    isNotNull(employeeTimeOffTable.startTime),
    isNotNull(employeeTimeOffTable.endTime),
    or(isNull(employeeTimeOffTable.salonId), eq(employeeTimeOffTable.salonId, access.salon.id)),
    exists(db.select({ id: employeeLocationAssignmentsTable.id }).from(employeeLocationAssignmentsTable).where(and(
      eq(employeeLocationAssignmentsTable.employeeId, employeeTimeOffTable.employeeId),
      eq(employeeLocationAssignmentsTable.salonId, access.salon.id),
      eq(employeeLocationAssignmentsTable.active, true),
    ))),
  )).returning({ id: employeeTimeOffTable.id });
  if (!deleted.length) { res.status(404).json({ error: "Blok nije pronađen." }); return; }
  res.status(204).send();
});

router.get("/salon/availability/search", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = SearchSalonAvailabilityQueryParams.safeParse(req.query);
  if (!parsed.success || !isValidCalendarDate(parsed.data.startDate)) {
    res.status(400).json({ error: parsed.success ? "Početni datum nije ispravan." : parsed.error.message }); return;
  }
  const [service] = await db.select().from(servicesTable).where(and(
    eq(servicesTable.id, parsed.data.serviceId),
    eq(servicesTable.salonId, access.salon.id),
    eq(servicesTable.active, true),
  )).limit(1);
  if (!service) { res.status(404).json({ error: "Usluga nije pronađena u ovom salonu." }); return; }
  if (parsed.data.employeeId && !(await employeeInSalon(parsed.data.employeeId, access.salon.id))) {
    res.status(404).json({ error: "Zaposleni nije pronađen u ovom salonu." }); return;
  }

  const dates = Array.from({ length: 7 }, (_, offset) =>
    dateAtOffset(new Date(`${parsed.data.startDate}T12:00:00.000Z`), offset));
  const granularity = parsed.data.granularityMinutes ?? 30;
  const slots = await canonicalAvailability({
    salonId: access.salon.id, service, dates, employeeId: parsed.data.employeeId,
    granularityMinutes: granularity, limit: parsed.data.limit,
  });
  res.json(SearchSalonAvailabilityResponse.parse(slots));
});

