router.get("/salon/calendar-day", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = GetSalonCalendarDayQueryParams.safeParse(req.query);
  if (!parsed.success || !isValidCalendarDate(parsed.data.date)) {
    res.status(400).json({ error: parsed.success ? "Datum nije ispravan." : parsed.error.message }); return;
  }
  const employees = await db.select({ employee: employeesTable }).from(employeesTable)
    .innerJoin(employeeLocationAssignmentsTable, and(
      eq(employeeLocationAssignmentsTable.employeeId, employeesTable.id),
      eq(employeeLocationAssignmentsTable.salonId, access.salon.id),
      eq(employeeLocationAssignmentsTable.active, true),
    ))
    .where(eq(employeesTable.active, true))
    .orderBy(asc(employeesTable.name), asc(employeesTable.id)).then((rows) => rows.map((row) => row.employee));
  const employeeIds = employees.map((employee) => employee.id);
  const weekday = ((new Date(`${parsed.data.date}T12:00:00.000Z`).getUTCDay() + 6) % 7) + 1;
  const [schedules, allDayLeave] = await Promise.all([
    employeeIds.length ? db.select().from(employeeLocationSchedulesTable).where(and(
      inArray(employeeLocationSchedulesTable.employeeId, employeeIds),
      eq(employeeLocationSchedulesTable.salonId, access.salon.id),
      eq(employeeLocationSchedulesTable.weekday, weekday),
    )) : Promise.resolve([] as (typeof employeeLocationSchedulesTable.$inferSelect)[]),
    employeeIds.length ? db.select().from(employeeTimeOffTable).where(and(
      inArray(employeeTimeOffTable.employeeId, employeeIds),
      lte(employeeTimeOffTable.startDate, parsed.data.date),
      gte(employeeTimeOffTable.endDate, parsed.data.date),
      isNull(employeeTimeOffTable.startTime),
      isNull(employeeTimeOffTable.endTime),
      or(isNull(employeeTimeOffTable.salonId), eq(employeeTimeOffTable.salonId, access.salon.id)),
    )) : Promise.resolve([] as (typeof employeeTimeOffTable.$inferSelect)[]),
  ]);
  const response = employees.map((employee) => {
    const windows = schedules.filter((schedule) => schedule.employeeId === employee.id)
      .map((schedule) => ({
        startTime: schedule.startTime, endTime: schedule.endTime,
        breakStart: schedule.breakStart, breakEnd: schedule.breakEnd,
      }));
    const leave = allDayLeave.filter((item) => item.employeeId === employee.id);
    return {
      employeeId: employee.id,
      name: employee.name,
      role: employee.role,
      // This explicitly mirrors employeeWorksAt(): no row means unrestricted,
      // not closed. The UI can distinguish that from an explicit schedule.
      hasExplicitSchedule: windows.length > 0,
      scheduleWindows: windows,
      unavailable: leave.length > 0,
      unavailableReason: leave.length ? leave.map((item) => item.reason).join("; ") : null,
    };
  });
  res.json(GetSalonCalendarDayResponse.parse(response));
});

router.get("/salon/customers", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const today = new Date().toISOString().slice(0, 10);
  // Page the CRM contacts first with a stable order (lastName, firstName, id) so
  // that every downstream read is scoped to the page's contact IDs instead of the
  // full salon appointment/series tables. Query count is constant per page.
  const { limit, offset } = parsePagination(req.query, 50);
  const contacts = await db.select().from(salonCustomersTable)
    .where(eq(salonCustomersTable.salonId, access.salon.id))
    .orderBy(asc(salonCustomersTable.lastName), asc(salonCustomersTable.firstName), asc(salonCustomersTable.id))
    .limit(limit).offset(offset);
  if (!contacts.length) { res.json(ListSalonCustomersResponse.parse([])); return; }
  const contactIds = contacts.map((contact) => contact.id);

  // Grouped aggregate counts restricted to the page contacts (no full table read).
  const [visitCounts, noShowCounts, series] = await Promise.all([
    db.select({ salonCustomerId: appointmentsTable.salonCustomerId, value: count() }).from(appointmentsTable)
      .where(and(
        eq(appointmentsTable.salonId, access.salon.id),
        inArray(appointmentsTable.salonCustomerId, contactIds),
      ))
      .groupBy(appointmentsTable.salonCustomerId),
    db.select({ salonCustomerId: appointmentsTable.salonCustomerId, value: count() }).from(appointmentsTable)
      .where(and(
        eq(appointmentsTable.salonId, access.salon.id),
        inArray(appointmentsTable.salonCustomerId, contactIds),
        eq(appointmentsTable.status, "no-show"),
      ))
      .groupBy(appointmentsTable.salonCustomerId),
    db.select().from(appointmentSeriesTable)
      .where(and(eq(appointmentSeriesTable.salonId, access.salon.id), inArray(appointmentSeriesTable.salonCustomerId, contactIds))),
  ]);
  const visitCountByContactId = new Map(visitCounts.flatMap((row) => row.salonCustomerId ? [[row.salonCustomerId, Number(row.value)] as const] : []));
  const noShowCountByContactId = new Map(noShowCounts.flatMap((row) => row.salonCustomerId ? [[row.salonCustomerId, Number(row.value)] as const] : []));

  // Batch reads for series membership + service names restricted to the page's
  // series/service IDs only.
  const seriesIds = [...new Set(series.map((item) => item.id))];
  const serviceIds = [...new Set(series.map((item) => item.serviceId))];
  const [seriesAppointments, services] = await Promise.all([
    seriesIds.length
      ? db.select({ seriesId: appointmentsTable.seriesId, status: appointmentsTable.status, date: appointmentsTable.date })
          .from(appointmentsTable).where(and(
            eq(appointmentsTable.salonId, access.salon.id),
            inArray(appointmentsTable.seriesId, seriesIds),
          ))
      : Promise.resolve([] as { seriesId: string | null; status: string; date: string }[]),
    serviceIds.length
      ? db.select({ id: servicesTable.id, name: servicesTable.name }).from(servicesTable).where(and(
          eq(servicesTable.salonId, access.salon.id),
          inArray(servicesTable.id, serviceIds),
        ))
      : Promise.resolve([] as { id: string; name: string }[]),
  ]);
  const serviceNameById = new Map(services.map((s) => [s.id, s.name]));
  const appointmentsBySeriesId = new Map<string, { status: string; date: string }[]>();
  for (const appt of seriesAppointments) {
    if (!appt.seriesId) continue;
    const arr = appointmentsBySeriesId.get(appt.seriesId) ?? [];
    arr.push({ status: appt.status, date: appt.date });
    appointmentsBySeriesId.set(appt.seriesId, arr);
  }
  const seriesByContactId = new Map<string, (typeof appointmentSeriesTable.$inferSelect)[]>();
  for (const s of series) {
    if (!s.salonCustomerId) continue;
    const arr = seriesByContactId.get(s.salonCustomerId) ?? [];
    arr.push(s);
    seriesByContactId.set(s.salonCustomerId, arr);
  }
  res.json(ListSalonCustomersResponse.parse(contacts.map((contact) => ({
    id: contact.id, firstName: contact.firstName, lastName: contact.lastName, email: contact.email, phone: contact.phone,
    smsOptOut: contact.smsOptOut,
    visitCount: visitCountByContactId.get(contact.id) ?? 0,
    noShowCount: noShowCountByContactId.get(contact.id) ?? 0,
    isRegistered: Boolean(contact.userId),
    series: (seriesByContactId.get(contact.id) ?? []).map((item) => {
      const members = appointmentsBySeriesId.get(item.id) ?? [];
      return {
        id: item.id, serviceName: serviceNameById.get(item.serviceId) ?? "Usluga",
        totalAppointments: item.totalAppointments,
        completedAppointments: members.filter((a) => a.status === "completed").length,
        upcomingAppointments: members.filter((a) => a.date >= today && ["pending", "confirmed"].includes(a.status)).length,
      };
    }),
  }))));
});

router.patch("/salon/customers/:customerId", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const [params, body] = [UpdateSalonCustomerParams.safeParse(req.params), UpdateSalonCustomerBody.safeParse(req.body)];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za CRM klijenta nisu ispravni." }); return; }
  // Partial update: only touch columns the client explicitly sent.
  //  - smsOptOut omitted → preserve the stored value (never reset to false).
  //  - birthDate present → set YYYY-MM-DD (Date → date string); null clears it.
  const updateFields: Partial<typeof salonCustomersTable.$inferInsert> = { updatedAt: new Date() };
  if (body.data.smsOptOut !== undefined) updateFields.smsOptOut = body.data.smsOptOut;
  if ("birthDate" in body.data) {
    const bd = body.data.birthDate;
    updateFields.birthDate = bd instanceof Date ? bd.toISOString().slice(0, 10) : null;
  }
  const [contact] = await db.update(salonCustomersTable).set(updateFields)
    .where(and(eq(salonCustomersTable.id, params.data.customerId), eq(salonCustomersTable.salonId, access.salon.id))).returning();
  if (!contact) { res.status(404).json({ error: "CRM klijent nije pronađen." }); return; }
  const appointments = await db.select({ id: appointmentsTable.id }).from(appointmentsTable).where(and(
    eq(appointmentsTable.salonId, access.salon.id),
    eq(appointmentsTable.salonCustomerId, contact.id),
  ));
  const noShowCount = (await db.select({ id: appointmentsTable.id }).from(appointmentsTable).where(and(
    eq(appointmentsTable.salonId, access.salon.id),
    eq(appointmentsTable.salonCustomerId, contact.id),
    eq(appointmentsTable.status, "no-show"),
  ))).length;
  // birthDate is a `date` column (mode:"string") → already YYYY-MM-DD or null.
  const payload = {
    id: contact.id, firstName: contact.firstName, lastName: contact.lastName, email: contact.email, phone: contact.phone,
    smsOptOut: contact.smsOptOut, birthDate: contact.birthDate, visitCount: appointments.length,
    noShowCount, isRegistered: Boolean(contact.userId),
  };
  // Validate the shape, but respond with the raw YYYY-MM-DD string so the UI
  // rehydrates the date input (zod.coerce.date() would turn it into a full ISO
  // timestamp, which the date field cannot consume).
  UpdateSalonCustomerResponse.parse(payload);
  res.json(payload);
});

router.post("/salon/appointments", (req, res, next) =>
  replayOwnerBookingCommand(req, res, next, "salon.appointment.create"),
admitBookingRequest, async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const parsed = CreateSalonAppointmentBody.safeParse(req.body);
  const rawDate = rawDateOnlyInput(req.body?.date);
  if (!parsed.success || !rawDate) {
    res.status(400).json({ error: parsed.success ? "Datum termina nije ispravan." : parsed.error.message }); return;
  }
  const { salon } = access;
  if (Boolean(parsed.data.salonCustomerId) === Boolean(parsed.data.guest)) {
    res.status(400).json({ error: "Izaberite CRM klijenta ili unesite podatke novog gosta." }); return;
  }
  if (parsed.data.packagePurchaseId && !parsed.data.salonCustomerId) {
    res.status(400).json({ error: "Paket se može iskoristiti samo za postojećeg CRM klijenta." }); return;
  }
  const [service] = await db.select().from(servicesTable).where(and(eq(servicesTable.id, parsed.data.serviceId), eq(servicesTable.salonId, salon.id), eq(servicesTable.active, true))).limit(1);
  if (!service) { res.status(404).json({ error: "Usluga nije pronađena u ovom salonu." }); return; }
  const date = rawDate;
  const endTime = appointmentEndTime(parsed.data.startTime, service.durationMinutes);
  if (!endTime) { res.status(400).json({ error: "Trajanje termina izlazi van radnog dana." }); return; }
  let contact: typeof salonCustomersTable.$inferSelect | undefined;
  if (parsed.data.salonCustomerId) {
    contact = (await db.select().from(salonCustomersTable).where(and(eq(salonCustomersTable.id, parsed.data.salonCustomerId), eq(salonCustomersTable.salonId, salon.id))).limit(1))[0];
    if (!contact) { res.status(404).json({ error: "CRM klijent ne pripada ovom salonu." }); return; }
  } else {
    const submittedPhone = normalizedPhone(parsed.data.guest!.phone);
    const contacts = await db.select().from(salonCustomersTable).where(eq(salonCustomersTable.salonId, salon.id));
    const [registeredUser] = await db.select().from(usersTable).where(eq(usersTable.phoneNormalized, submittedPhone)).limit(1);
    contact = contacts.find((item) => item.phoneNormalized === submittedPhone || (item.phone && normalizedPhone(item.phone) === submittedPhone));
    if (!contact) {
      [contact] = await db.insert(salonCustomersTable).values({
        salonId: salon.id, firstName: parsed.data.guest!.firstName.trim(), lastName: parsed.data.guest!.lastName.trim(),
        phone: parsed.data.guest!.phone.trim(), phoneNormalized: submittedPhone, userId: registeredUser?.id ?? null, email: parsed.data.guest!.email?.trim().toLowerCase() || null,
      }).returning();
    } else if (registeredUser && contact.userId !== registeredUser.id) {
      [contact] = await db.update(salonCustomersTable).set({ userId: registeredUser.id, phoneNormalized: submittedPhone, updatedAt: new Date() }).where(eq(salonCustomersTable.id, contact.id)).returning();
      await db.update(appointmentsTable).set({ customerId: registeredUser.id }).where(eq(appointmentsTable.salonCustomerId, contact!.id));
    }
  }
  try {
    const command = await executeBookingCommand({
      salonId: salon.id, actorType: "user", actorId: access.user.id, idempotencyKey,
      commandType: "salon.appointment.create", payload: req.body,
    }, async (tx) => {
      const allocation = await createAllocatedAppointment({
        salonId: salon.id,
        customerId: contact!.userId,
        salonCustomerId: contact!.id,
        serviceId: service.id,
        date,
        startTime: parsed.data.startTime,
        endTime,
        durationMinutes: service.durationMinutes,
        price: service.promoPrice ?? service.price,
        status: "confirmed",
        createdByUserId: access.user.id,
        notes: parsed.data.notes ?? null,
        preferredEmployeeId: parsed.data.employeeId,
        packagePurchaseId: parsed.data.packagePurchaseId,
        tx,
        afterCreate: async (mutationTx, createdAppointment) => {
          await enqueueSms(mutationTx, {
            eventKey: `appointment-confirmation:${createdAppointment.id}`,
            salonId: salon.id,
            appointmentId: createdAppointment.id,
            type: "appointment_confirmation",
            phone: contact!.phone,
            smsOptOut: contact!.smsOptOut,
            text: `LUMERA: termin u salonu ${salon.name} je zakazan za ${date} u ${createdAppointment.startTime}.`,
          });
        },
      });
      if (!allocation.appointment || !allocation.employee) {
        return { status: 409, body: { error: "Termin više nije slobodan. Osvežite dostupnost i izaberite drugi termin." } };
      }
      const response = appointmentView(
        allocation.appointment, salon, service, contact!, allocation.employee, true, null, allocation.allocatedResources,
      );
      CreateSalonAppointmentResponse.parse(response);
      return { status: 201, body: response };
    });
    sendBookingCommandResult(res, command);
    return;
  } catch (err: unknown) {
    if (err instanceof ResourceCapacityError) {
      res.status(409).json({ error: err.message });
      return;
    }
    if (err instanceof PackageRedemptionError) {
      res.status(409).json({ error: err.message, code: "PACKAGE_ERROR", reason: err.reason }); return;
    }
    throw err;
  }
});

router.post("/salon/appointment-series/preview", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = PreviewSalonAppointmentSeriesBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: "Podaci za pregled serije nisu ispravni." }); return; }
  const [service] = await db.select().from(servicesTable).where(and(eq(servicesTable.id, parsed.data.serviceId), eq(servicesTable.salonId, access.salon.id), eq(servicesTable.active, true))).limit(1);
  if (!service) { res.status(404).json({ error: "Usluga nije pronađena u ovom salonu." }); return; }
  if (parsed.data.employeeId && !(await employeeInSalon(parsed.data.employeeId, access.salon.id))) {
    res.status(403).json({ error: "Zaposleni pripada drugom salonu." }); return;
  }
  try {
    const slots = prepareSeriesSlots(parsed.data.slots, service.durationMinutes);
    let entitlement: { ok: boolean; reason?: string } = { ok: true };
    if (parsed.data.packagePurchaseId) {
      if (!parsed.data.salonCustomerId) {
        res.status(400).json({ error: "Za pregled paketa izaberite CRM klijenta." }); return;
      }
      entitlement = await packageEntitlementForServices(db, {
        purchaseId: parsed.data.packagePurchaseId, salonId: access.salon.id,
        salonCustomerId: parsed.data.salonCustomerId,
        requiredByService: new Map([[service.id, slots.length]]),
      });
    }
    const response = PreviewSalonAppointmentSeriesResponse.parse(
      { ...(await previewSeriesSlots(access.salon.id, service, slots, parsed.data.employeeId)),
        packageEligible: parsed.data.packagePurchaseId ? entitlement.ok : null,
        packageReason: parsed.data.packagePurchaseId && !entitlement.ok ? entitlement.reason : null },
    );
    res.json({
      ...response,
      slots: response.slots.map((slot) => ({ ...slot, date: calendarDate(slot.date) })),
    });
  } catch (error) {
    const message = error instanceof AppointmentSeriesError ? error.message : "Pregled serije nije uspeo.";
    res.status(error instanceof AppointmentSeriesError ? error.status : 500).json({ error: message });
  }
});

async function packageBookingInput(
  store: typeof db | any,
  input: {
    salonId: string;
    purchaseId: string;
    slots: Array<{ serviceId: string; date: string | Date; startTime: string; employeeId?: string | null }>;
    lockEntitlement?: boolean;
  },
) {
  const [purchase] = await store.select().from(customerPackagePurchasesTable).where(eq(customerPackagePurchasesTable.id, input.purchaseId)).limit(1);
  if (!purchase || purchase.salonId !== input.salonId) throw new PackageRedemptionError(purchase ? "wrong_salon" : "not_found");
  const [contact] = await store.select().from(salonCustomersTable).where(and(eq(salonCustomersTable.id, purchase.salonCustomerId), eq(salonCustomersTable.salonId, input.salonId))).limit(1);
  if (!contact) throw new PackageRedemptionError("wrong_customer");
  const required = new Map<string, number>();
  for (const slot of input.slots) required.set(slot.serviceId, (required.get(slot.serviceId) ?? 0) + 1);
  const entitlement = input.lockEntitlement
    ? await lockPackageEntitlementForServicesInTx(store, {
        purchaseId: purchase.id,
        salonId: input.salonId,
        salonCustomerId: contact.id,
        requiredByService: required,
      })
    : await packageEntitlementForServices(store, {
        purchaseId: purchase.id,
        salonId: input.salonId,
        salonCustomerId: contact.id,
        requiredByService: required,
      });
  if (!entitlement.ok) throw new PackageRedemptionError(entitlement.reason);
  const currentPurchase = "purchase" in entitlement ? entitlement.purchase : purchase;
  const links = "links" in entitlement
    ? entitlement.links
    : await store.select().from(packagePurchaseServiceLinksTable).where(eq(packagePurchaseServiceLinksTable.purchaseId, purchase.id));
  if (currentPurchase.quotaPolicy === "per_service") {
    if (required.size !== links.filter((link: typeof packagePurchaseServiceLinksTable.$inferSelect) => link.remainingQuota > 0).length ||
      links.some((link: typeof packagePurchaseServiceLinksTable.$inferSelect) => link.remainingQuota > 0 && required.get(link.serviceId) !== link.remainingQuota)) throw new AppointmentSeriesError("Morate zakazati tačno sve preostale termine paketa.", 400);
  } else if ([...required.values()].reduce((sum, value) => sum + value, 0) !== currentPurchase.remainingSessions) {
    throw new AppointmentSeriesError("Morate zakazati tačno sve preostale termine paketa.", 400);
  }
  const services = await store.select().from(servicesTable).where(and(eq(servicesTable.salonId, input.salonId), inArray(servicesTable.id, [...required.keys()])));
  if (services.length !== required.size || services.some((service: typeof servicesTable.$inferSelect) => !service.active)) throw new PackageRedemptionError("service_not_covered");
  return { purchase: currentPurchase, contact, services, required };
}

async function previewPackageSlots(salonId: string, services: (typeof servicesTable.$inferSelect)[], slots: Array<{ serviceId: string; date: string | Date; startTime: string; employeeId?: string | null }>) {
  const reservedAppointments: Array<{
    employeeId: string; date: string; startTime: string; endTime: string;
    bufferMinutes: number; resourceIds: string[];
  }> = [];
  const reservations: Array<{
    resourceId: string; quantity: number; date: string; startTime: string; endTime: string; bufferMinutes: number;
  }> = [];
  const result: Array<{ serviceId: string; date: string; startTime: string; employeeId?: string | null; available: boolean; reason: string | null }> = [];
  for (const slot of slots) {
    const service = services.find((item) => item.id === slot.serviceId)!;
    const prepared = prepareSeriesSlots([slot], service.durationMinutes)[0]!;
    const requirements = await fetchServiceResourceRequirements(db, service.id);
    const candidates = await canonicalAvailability({
      salonId,
      service,
      dates: [prepared.date],
      employeeId: slot.employeeId,
      reservedAppointments,
      resourceReservations: reservations,
    });
    const employee = candidates.find((candidate) =>
      candidate.startTime === prepared.startTime && candidate.endTime === prepared.endTime);
    const available = Boolean(employee);
    result.push({ ...slot, date: prepared.date, available, reason: available ? null : "Nema slobodnog zaposlenog, termin izlazi van radnog vremena, ili nema dostupnih resursa." });
    if (employee) {
      reservedAppointments.push({
        employeeId: employee.employeeId, date: prepared.date, startTime: prepared.startTime, endTime: prepared.endTime,
        bufferMinutes: service.bufferMinutes, resourceIds: requirements.map((item) => item.resourceId),
      });
      for (const requirement of requirements) reservations.push({
        resourceId: requirement.resourceId, quantity: requirement.quantity, date: prepared.date,
        startTime: prepared.startTime, endTime: prepared.endTime, bufferMinutes: service.bufferMinutes,
      });
    }
  }
  return result;
}

router.post("/salon/package-appointments/preview", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = PreviewSalonPackageAppointmentsBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: "Podaci paketa nisu ispravni." }); return; }
  try {
    const prepared = await packageBookingInput(db, { salonId: access.salon.id, purchaseId: parsed.data.packagePurchaseId, slots: parsed.data.slots });
    const slots = await previewPackageSlots(access.salon.id, prepared.services, parsed.data.slots);
    res.json(PreviewSalonPackageAppointmentsResponse.parse({ slots, allAvailable: slots.every((slot) => slot.available), packageEligible: true, packageReason: null, remainingSessions: prepared.purchase.remainingSessions }));
  } catch (error) {
    const reason = error instanceof PackageRedemptionError ? error.reason : null;
    res.status(error instanceof AppointmentSeriesError ? error.status : 409).json({ error: error instanceof Error ? error.message : "Pregled paketa nije uspeo.", ...(reason ? { code: "PACKAGE_ERROR", reason } : {}) });
  }
});

router.post("/salon/package-appointments", (req, res, next) =>
  replayOwnerBookingCommand(req, res, next, "salon.package-appointments.create"),
admitBookingRequest, async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const parsed = CreateSalonPackageAppointmentsBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: "Podaci paketa nisu ispravni." }); return; }
  try {
    let prepared!: Awaited<ReturnType<typeof packageBookingInput>>;
    const command = await executeBookingCommand({
      salonId: access.salon.id, actorType: "user", actorId: access.user.id, idempotencyKey,
      commandType: "salon.package-appointments.create", payload: req.body,
    }, async (tx) => {
      await lockAppointmentResources(tx, access.salon.id, parsed.data.slots.map((slot) => ({
        date: calendarDate(slot.date),
        employeeId: slot.employeeId ?? null,
      })));
      prepared = await packageBookingInput(tx, {
        salonId: access.salon.id,
        purchaseId: parsed.data.packagePurchaseId,
        slots: parsed.data.slots,
        lockEntitlement: true,
      });
      const groups = new Map<string, typeof parsed.data.slots>();
      for (const slot of parsed.data.slots) groups.set(slot.serviceId, [...(groups.get(slot.serviceId) ?? []), slot]);
      const result = [];
      for (const [serviceId, slots] of groups) {
        const service = prepared.services.find((item: typeof servicesTable.$inferSelect) => item.id === serviceId)!;
        const preferredEmployeeBySlot = new Map(
          slots.map((slot) => [`${calendarDate(slot.date)}:${slot.startTime}`, slot.employeeId ?? null]),
        );
        const preparedSlots = prepareSeriesSlots(slots, service.durationMinutes).map((slot) => ({
          ...slot,
          preferredEmployeeId: preferredEmployeeBySlot.get(`${slot.date}:${slot.startTime}`) ?? null,
        }));
        result.push(await createAppointmentSeries({
          salonId: access.salon.id,
          customerId: prepared.contact.userId,
          salonCustomerId: prepared.contact.id,
          service,
          slots: preparedSlots,
          createdByUserId: access.user.id,
          packagePurchaseId: prepared.purchase.id,
          tx,
        }));
      }
      for (const item of result) {
        await enqueueSeriesConfirmationsInTx(tx, {
          appointments: item.appointments, contact: prepared.contact, salon: access.salon,
        });
      }
      const [updated] = await tx.select().from(customerPackagePurchasesTable).where(eq(customerPackagePurchasesTable.id, prepared.purchase.id));
      const series = [];
      for (const item of result) {
        const service = prepared.services.find((candidate: typeof servicesTable.$inferSelect) =>
          candidate.id === item.series.serviceId)!;
        const employees = await tx.select().from(employeesTable).where(inArray(
          employeesTable.id, [...new Set(item.appointments.flatMap((appointment) =>
            appointment.employeeId ? [appointment.employeeId] : []))],
        ));
        const appointments = await Promise.all(item.appointments.map(async (appointment) =>
          appointmentView(appointment, access.salon, service, prepared.contact,
            employees.find((employee) => employee.id === appointment.employeeId), true, null,
            await getAllocationsForAppointment(tx, appointment.id))));
        series.push({ id: item.series.id, totalAppointments: item.appointments.length, appointments });
      }
      return {
        status: 201,
        body: CreateSalonPackageAppointmentsResponse.parse({
          series, remainingSessions: updated!.remainingSessions,
        }),
      };
    });
    sendBookingCommandResult(res, command);
  } catch (error) {
    const reason = error instanceof PackageRedemptionError ? error.reason : null;
    res.status(error instanceof AppointmentSeriesError ? error.status : 409).json({ error: error instanceof Error ? error.message : "Paket nije sačuvan.", ...(reason ? { code: "PACKAGE_ERROR", reason } : {}) });
  }
});

router.post("/salon/appointment-series", (req, res, next) =>
  replayOwnerBookingCommand(req, res, next, "salon.appointment-series.create"),
admitBookingRequest, async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const idempotencyKey = bookingIdempotencyKey(req, res); if (!idempotencyKey) return;
  const parsed = CreateSalonAppointmentSeriesBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: "Podaci za seriju termina nisu ispravni." }); return; }
  if (Boolean(parsed.data.salonCustomerId) === Boolean(parsed.data.guest)) {
    res.status(400).json({ error: "Izaberite CRM klijenta ili unesite podatke novog gosta." }); return;
  }
  if (parsed.data.packagePurchaseId && !parsed.data.salonCustomerId) {
    res.status(400).json({ error: "Paket se može iskoristiti samo za postojećeg CRM klijenta." }); return;
  }
  const [service] = await db.select().from(servicesTable).where(and(eq(servicesTable.id, parsed.data.serviceId), eq(servicesTable.salonId, access.salon.id), eq(servicesTable.active, true))).limit(1);
  if (!service) { res.status(404).json({ error: "Usluga nije pronađena u ovom salonu." }); return; }
  if (parsed.data.employeeId && !(await employeeInSalon(parsed.data.employeeId, access.salon.id))) {
    res.status(403).json({ error: "Zaposleni pripada drugom salonu." }); return;
  }
  let contact: typeof salonCustomersTable.$inferSelect | undefined;
  if (parsed.data.salonCustomerId) {
    contact = (await db.select().from(salonCustomersTable).where(and(eq(salonCustomersTable.id, parsed.data.salonCustomerId), eq(salonCustomersTable.salonId, access.salon.id))).limit(1))[0];
    if (!contact) { res.status(404).json({ error: "CRM klijent ne pripada ovom salonu." }); return; }
  } else {
    const phone = normalizedPhone(parsed.data.guest!.phone);
    if (!phone) { res.status(400).json({ error: "Unesite ispravan broj telefona klijenta." }); return; }
    const [registered] = await db.select().from(usersTable).where(eq(usersTable.phoneNormalized, phone)).limit(1);
    const contacts = await db.select().from(salonCustomersTable).where(eq(salonCustomersTable.salonId, access.salon.id));
    contact = contacts.find((item) => item.phoneNormalized === phone || (item.phone && normalizedPhone(item.phone) === phone));
    if (!contact) {
      [contact] = await db.insert(salonCustomersTable).values({
        salonId: access.salon.id, firstName: parsed.data.guest!.firstName.trim(), lastName: parsed.data.guest!.lastName.trim(),
        phone: parsed.data.guest!.phone.trim(), phoneNormalized: phone, userId: registered?.id ?? null, email: parsed.data.guest!.email?.trim().toLowerCase() || null,
      }).returning();
    }
  }
  try {
    const slots = prepareSeriesSlots(parsed.data.slots, service.durationMinutes);
    const command = await executeBookingCommand({
      salonId: access.salon.id, actorType: "user", actorId: access.user.id, idempotencyKey,
      commandType: "salon.appointment-series.create", payload: req.body,
    }, async (tx) => {
      const created = await createAppointmentSeries({
        salonId: access.salon.id, customerId: contact!.userId, salonCustomerId: contact!.id, service, slots,
        createdByUserId: access.user.id, notes: parsed.data.notes ?? null, preferredEmployeeId: parsed.data.employeeId,
        packagePurchaseId: parsed.data.packagePurchaseId, tx,
      });
      const employees = await tx.select().from(employeesTable).where(inArray(
        employeesTable.id, [...new Set(created.appointments.flatMap((item) =>
          item.employeeId ? [item.employeeId] : []))],
      ));
      const views = await Promise.all(created.appointments.map(async (appointment) =>
        appointmentView(appointment, access.salon, service, contact!,
          employees.find((employee) => employee.id === appointment.employeeId), true, null,
          await getAllocationsForAppointment(tx, appointment.id))));
      const response = {
        id: created.series.id, totalAppointments: created.appointments.length, appointments: views,
      };
      CreateSalonAppointmentSeriesResponse.parse(response);
      await enqueueSeriesConfirmationsInTx(tx, {
        appointments: created.appointments, contact: contact!, salon: access.salon,
      });
      return { status: 201, body: response };
    });
    sendBookingCommandResult(res, command);
  } catch (error) {
    const message = error instanceof PackageRedemptionError ? error.message
      : error instanceof ResourceCapacityError ? error.message
      : error instanceof AppointmentSeriesError ? error.message
        : "Serija termina nije sačuvana.";
    res.status(error instanceof PackageRedemptionError ? 409 : error instanceof ResourceCapacityError ? 409 : error instanceof AppointmentSeriesError ? error.status : 500).json(error instanceof PackageRedemptionError ? { error: message, code: "PACKAGE_ERROR", reason: error.reason } : { error: message });
  }
});

router.delete("/salon/appointment-series/:seriesId", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const params = CancelSalonAppointmentSeriesParams.safeParse(req.params);
  if (!params.success) { res.status(400).json({ error: "Serija termina nije ispravna." }); return; }
  const result = await db.transaction(async (tx) => {
    await lockAppointmentResources(tx, access.salon.id);
    const [series] = await tx.select().from(appointmentSeriesTable).where(and(
      eq(appointmentSeriesTable.id, params.data.seriesId),
      eq(appointmentSeriesTable.salonId, access.salon.id),
    )).limit(1);
    if (!series) return { error: "not-found" as const };
    const today = new Date().toISOString().slice(0, 10);
    const upcoming = await tx.select().from(appointmentsTable).where(and(
      eq(appointmentsTable.seriesId, series.id),
      sql`${appointmentsTable.date} >= ${today}`,
      inArray(appointmentsTable.status, ["pending", "confirmed"]),
    )).for("update");
    if (upcoming.some((appointment) => appointment.arrivedAt || appointment.actualStartedAt)) {
      return { error: "invalid-transition" as const };
    }
    await lockAppointmentResources(tx, access.salon.id, upcoming);
    const cancelled = [];
    const occurredAt = new Date();
    for (const appointment of upcoming) {
      const result = await cancelAppointmentInTx(tx, {
        appointmentId: appointment.id, actorId: access.user.id, occurredAt,
        reason: "Otkazana preostala serija termina.",
      });
      if (!("appointment" in result)) return { error: "invalid-transition" as const };
      cancelled.push(result.appointment);
    }
    return { series, cancelled };
  });
  if ("error" in result) { res.status(result.error === "not-found" ? 404 : 409).json({ error: result.error === "not-found" ? "Serija termina nije pronađena." : "Pristigli ili započeti termin ne može biti otkazan." }); return; }
  const { series, cancelled } = result;
  res.json(CancelSalonAppointmentSeriesResponse.parse({ id: series.id, cancelledAppointments: cancelled.length }));
});

router.post("/salon/appointment-series/:seriesId/move/preview", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const [params, body] = [PreviewSalonAppointmentSeriesMoveParams.safeParse(req.params), PreviewSalonAppointmentSeriesMoveBody.safeParse(req.body)];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za pomeranje serije nisu ispravni." }); return; }
  const [series] = await db.select().from(appointmentSeriesTable).where(and(
    eq(appointmentSeriesTable.id, params.data.seriesId),
    eq(appointmentSeriesTable.salonId, access.salon.id),
  )).limit(1);
  if (!series) { res.status(404).json({ error: "Serija termina nije pronađena." }); return; }
  const appointments = futureUnfinishedSeriesAppointments(await db.select().from(appointmentsTable).where(and(
    eq(appointmentsTable.salonId, access.salon.id),
    eq(appointmentsTable.seriesId, series.id),
  )));
  if (!appointments.length) { res.status(409).json({ error: "U ovoj seriji nema budućih nezavršenih termina za pomeranje." }); return; }
  try {
    const slots = prepareSeriesMoveSlots(appointments, body.data);
    const response = PreviewSalonAppointmentSeriesMoveResponse.parse(
      await previewSeriesMove(db, access.salon.id, slots),
    );
    res.json({
      ...response,
      slots: response.slots.map((slot) => ({
        ...slot,
        currentDate: calendarDate(slot.currentDate),
        date: calendarDate(slot.date),
      })),
    });
  } catch (error) {
    const message = error instanceof AppointmentSeriesError ? error.message : "Pregled pomeranja serije nije uspeo.";
    res.status(error instanceof AppointmentSeriesError ? error.status : 500).json({ error: message });
  }
});

router.post("/salon/appointment-series/:seriesId/move", admitBookingRequest, async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const [params, body] = [MoveSalonAppointmentSeriesParams.safeParse(req.params), MoveSalonAppointmentSeriesBody.safeParse(req.body)];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za pomeranje serije nisu ispravni." }); return; }
  const [series] = await db.select().from(appointmentSeriesTable).where(and(
    eq(appointmentSeriesTable.id, params.data.seriesId),
    eq(appointmentSeriesTable.salonId, access.salon.id),
  )).limit(1);
  if (!series) { res.status(404).json({ error: "Serija termina nije pronađena." }); return; }
  try {
    const [contact] = series.salonCustomerId
      ? await db.select().from(salonCustomersTable).where(and(eq(salonCustomersTable.id, series.salonCustomerId), eq(salonCustomersTable.salonId, access.salon.id))).limit(1)
      : [];
    const moveEventId = randomUUID();
    const moved = await moveAppointmentSeries({ salonId: access.salon.id, seriesId: series.id, move: body.data, contact: contact ?? null, salon: access.salon, moveEventId });
    if (contact) {
      await sendSeriesUpdates({ appointments: moved, contact, salon: access.salon, moveEventId });
      await runRescheduledConfirmationRetries();
    }
    const views = await appointmentList(and(eq(appointmentsTable.salonId, access.salon.id), inArray(appointmentsTable.id, moved.map((appointment) => appointment.id))), true);
    const viewById = new Map(views.map((appointment) => [appointment.id, appointment]));
    const response = {
      id: series.id,
      movedAppointments: moved.length,
      appointments: moved.map((appointment) => viewById.get(appointment.id)!),
    };
    MoveSalonAppointmentSeriesResponse.parse(response);
    res.json(response);
  } catch (error) {
    const message = error instanceof ResourceCapacityError ? error.message
      : error instanceof AppointmentSeriesError ? error.message
        : "Pomeranje serije nije uspelo.";
    res.status(error instanceof AppointmentSeriesError ? error.status : 409).json({ error: message });
  }
});

router.patch("/salon/appointments/:appointmentId", admitBookingRequest, async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const { salon } = access;
  const [params, body] = [UpdateSalonAppointmentParams.safeParse(req.params), UpdateSalonAppointmentBody.safeParse(req.body)];
  if (!params.success || !body.success) { res.status(400).json({ error: "Podaci za izmenu nisu ispravni." }); return; }
  if (body.data.status !== undefined) {
    res.status(400).json({ error: "Status termina menjajte isključivo preko lifecycle endpointa." });
    return;
  }
  const result = await db.transaction(async (tx) => {
    await lockAppointmentResources(tx, salon.id);
    if (body.data.employeeId) {
      const [requestedEmployee] = await tx.select({ id: employeesTable.id }).from(employeesTable)
        .innerJoin(employeeLocationAssignmentsTable, and(
          eq(employeeLocationAssignmentsTable.employeeId, employeesTable.id),
          eq(employeeLocationAssignmentsTable.salonId, salon.id),
          eq(employeeLocationAssignmentsTable.active, true),
        ))
        .where(and(eq(employeesTable.id, body.data.employeeId), eq(employeesTable.active, true))).limit(1);
      if (!requestedEmployee) return { error: "foreign-employee" as const };
    }
    const [target] = await tx.select().from(appointmentsTable).where(and(
      eq(appointmentsTable.id, params.data.appointmentId),
      eq(appointmentsTable.salonId, salon.id),
    )).for("update").limit(1);
    if (!target) return { error: "not-found" as const };
    const employeeId = body.data.employeeId ?? target.employeeId;
    const status = body.data.status ?? target.status;
    await lockAppointmentResources(tx, salon.id, [
      { date: target.date, employeeId: target.employeeId },
      { date: target.date, employeeId },
    ]);
    if (employeeId && status !== "cancelled") {
      const [service] = await tx.select().from(servicesTable).where(eq(servicesTable.id, target.serviceId)).limit(1);
      if (!service) return { error: "unavailable" as const };
      const requirements = await fetchServiceResourceRequirements(tx, service.id);
      await lockAppointmentResources(tx, salon.id, [
        { date: target.date, employeeId },
        ...requirements.map((requirement) => ({ date: target.date, resourceId: requirement.resourceId })),
      ]);
      const slots = await canonicalAvailability({
        salonId: salon.id, service, dates: [target.date], employeeId,
        excludeAppointmentIds: [target.id], store: tx,
      });
      if (!slots.some((slot) => slot.startTime === target.startTime && slot.endTime === target.endTime)) {
        return { error: "unavailable" as const };
      }
    }
    if (target.status === "cancelled" && status !== "cancelled") {
      const existingAllocations = await fetchAppointmentResourceRequirements(tx, target.id);
      const requirements = existingAllocations.length
        ? existingAllocations
        : await fetchServiceResourceRequirements(tx, target.serviceId);
      const [service] = await tx.select().from(servicesTable).where(eq(servicesTable.id, target.serviceId)).limit(1);
      const bufferedEnd = service ? appointmentEndTime(target.endTime, service.bufferMinutes) : null;
      if (!bufferedEnd) return { error: "unavailable" as const };
      await allocateResourcesInTx(
        tx,
        salon.id,
        requirements,
        target.id,
        target.date,
        target.startTime,
        requirements.length ? bufferedEnd : target.endTime,
        [target.id],
      );
    }
    const [updated] = await tx.update(appointmentsTable).set({
      employeeId: body.data.employeeId,
      notes: body.data.notes === "" ? null : body.data.notes,
      updatedByUserId: access.user.id,
      updatedAt: new Date(),
    }).where(and(
      eq(appointmentsTable.id, target.id),
      eq(appointmentsTable.salonId, salon.id),
    )).returning();
    if (!updated) return { error: "changed" as const };
    // On transition INTO cancelled, reverse active package redemptions atomically.
    if (updated.status === "cancelled" && target.status !== "cancelled") {
      await handleAppointmentCancellationReversalsInTx(tx, updated.id, salon.id);
    }
    if (target.status === "completed" && updated.status !== "completed" && updated.customerId) {
      await recordAppointmentReferralTransitionInTx(tx, {
        appointmentId: updated.id, customerId: updated.customerId, salonId: updated.salonId,
        occurredAt: new Date(), valid: false, reason: `owner_changed_status_to_${updated.status}`,
      });
    }
    // On transition INTO completed, auto-decrement mapped salon inventory
    // (idempotent per appointment/product via the consumption ledger).
    let lowStockWarned = false;
    if (updated.status === "completed" && target.status !== "completed") {
      await enqueueAftercareCompletion(tx, {
        appointmentId: updated.id,
        transitionKey: "appointment-status:completed:v1",
      });
      const warnings = await consumeInventoryForAppointmentInTx(tx, { id: updated.id, salonId: salon.id, serviceId: updated.serviceId });
      if (updated.customerId) await recordAppointmentReferralTransitionInTx(tx, {
        appointmentId: updated.id, customerId: updated.customerId, salonId: updated.salonId,
        occurredAt: new Date(), valid: true,
      });
      lowStockWarned = warnings.length > 0;
    }
    return { updated, lowStockWarned };
  }).catch((error: unknown) => {
    if (error instanceof ResourceCapacityError) return { error: "resource-unavailable" as const };
    throw error;
  });
  if ("error" in result) {
    res.status(result.error === "not-found" ? 404 : result.error === "foreign-employee" ? 403 : 409).json({
      error: result.error === "not-found" ? "Termin nije pronađen."
        : result.error === "foreign-employee" ? "Zaposleni pripada drugom salonu."
          : result.error === "unavailable" ? "Izabrani zaposleni nije slobodan za ovaj termin."
            : result.error === "resource-unavailable" ? "Potrebni resursi nisu slobodni za ovaj termin."
            : "Termin je u međuvremenu promenjen.",
    });
    return;
  }
  const { updated } = result;
  if ("lowStockWarned" in result && result.lowStockWarned) await publishSalonNotificationUpdate(salon.id);
  const view = (await appointmentList(and(eq(appointmentsTable.id, updated.id), eq(appointmentsTable.salonId, salon.id)), true))[0];
  UpdateSalonAppointmentResponse.parse(view);
  res.json(view);
});

