router.post("/retail/cart/saved-items/:savedItemId/restore", async (req, res): Promise<void> => {
  const cart = await retailCartForRequest(req, res);
  const result = await db.transaction(async (tx) => {
    await tx.execute(sql`select id from retail_carts where id = ${cart.id} for update`);
    const [saved] = await tx.select().from(savedRetailCartItemsTable).where(and(eq(savedRetailCartItemsTable.id, req.params.savedItemId), eq(savedRetailCartItemsTable.cartId, cart.id))).limit(1);
    if (!saved) return "missing";
    if (saved.bundleId) {
      const target = await bundleForCartInTx(tx, saved.bundleId, "B2C");
      const [existing] = target ? await tx.select().from(retailCartItemsTable).where(and(eq(retailCartItemsTable.cartId, cart.id), eq(retailCartItemsTable.bundleId, saved.bundleId))).limit(1) : [];
      const quantity = (existing?.quantity ?? 0) + saved.quantity;
      if (!target || target.bundle.b2cPrice == null || quantity > target.derivedStock) return "unavailable";
      if (existing) await tx.update(retailCartItemsTable).set({ quantity, unitPrice: target.bundle.b2cPrice, updatedAt: new Date() }).where(eq(retailCartItemsTable.id, existing.id));
      else await tx.insert(retailCartItemsTable).values({ cartId: cart.id, bundleId: saved.bundleId, productName: target.bundle.name, productImageUrl: target.bundle.imageUrl ?? "", unitPrice: target.bundle.b2cPrice, quantity, weightGrams: 0 });
    } else if (saved.productId) {
      await tx.execute(sql`select id from products where id = ${saved.productId} for update`);
      const [product] = await tx.select().from(productsTable).where(and(eq(productsTable.id, saved.productId), eq(productsTable.active, true), eq(productsTable.retailEnabled, true), isNotNull(productsTable.publicDescription), isNotNull(productsTable.publicPrice), retailVariantCompatibleCondition(), activeCategoryCondition(), activeSupplierCondition("B2C"))).limit(1);
      const productCartItems = product ? await tx.select().from(retailCartItemsTable).where(and(
        eq(retailCartItemsTable.cartId, cart.id), eq(retailCartItemsTable.productId, saved.productId),
      )) : [];
      const existing = productCartItems.find((item) => item.variantValue === saved.variantValue);
      const selection = product ? retailVariantSelection(product, saved.variantValue) : null;
      const quantity = (existing?.quantity ?? 0) + saved.quantity;
      const reserved = selection?.variant?.stock == null
        ? productCartItems.reduce((sum, item) => sum + item.quantity, 0) - (existing?.quantity ?? 0) + quantity
        : quantity;
      if (!product || !selection || reserved > selection.available || quantity < product.minimumOrderQuantity) return "unavailable";
      const unitPrice = retailProductPrice(product, quantity).unitPrice;
      if (existing) await tx.update(retailCartItemsTable).set({ quantity, unitPrice, updatedAt: new Date() }).where(eq(retailCartItemsTable.id, existing.id));
      else await tx.insert(retailCartItemsTable).values({
        cartId: cart.id, productId: product.id, productName: product.name,
        productImageUrl: selection.variant?.mainImageUrl ?? product.imageUrl,
        productCatalogReference: product.catalogReference, variantValue: saved.variantValue,
        unitPrice, quantity, weightGrams: product.weightGrams ?? 0,
      });
    } else return "unavailable";
    await tx.delete(savedRetailCartItemsTable).where(eq(savedRetailCartItemsTable.id, saved.id));
    await tx.update(retailCartsTable).set({ updatedAt: new Date(), activityVersion: sql`${retailCartsTable.activityVersion} + 1` }).where(eq(retailCartsTable.id, cart.id));
    return "ok";
  });
  if (result !== "ok") { res.status(result === "missing" ? 404 : 409).json({ error: result === "missing" ? "Sačuvana stavka nije pronađena." : "Stavka više nije dostupna u traženoj količini." }); return; }
  res.json(await retailCartDto(cart.id));
});

router.post("/retail/orders/repeat-last", async (req, res): Promise<void> => {
  const user = await getCurrentUser(req);
  if (!isRetailAccount(user)) { res.status(401).json({ error: "Prijavite se da biste ponovili porudžbinu." }); return; }
  const key = req.get("Idempotency-Key")?.trim() ?? "";
  if (key.length < 8 || key.length > 200) { res.status(400).json({ error: "Idempotency-Key zaglavlje je obavezno." }); return; }
  const cart = await retailCartForRequest(req, res);
  const result = await db.transaction(async (tx) => {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`b2c:${user.id}:${key}`}))`);
    const [prior] = await tx.select().from(reorderActionsTable).where(and(eq(reorderActionsTable.userId, user.id), eq(reorderActionsTable.idempotencyKey, key))).limit(1);
    if (prior) return prior.result;
    await tx.execute(sql`select id from retail_carts where id = ${cart.id} for update`);
    const [order] = await tx.select().from(retailOrdersTable).where(eq(retailOrdersTable.userId, user.id)).orderBy(desc(retailOrdersTable.createdAt)).limit(1);
    const outcome: { added: unknown[]; skipped: unknown[]; adjusted: unknown[] } = { added: [], skipped: [], adjusted: [] };
    if (order) for (const source of await tx.select().from(retailOrderItemsTable).where(eq(retailOrderItemsTable.orderId, order.id))) {
      if (source.bundleId) {
        const target = await bundleForCartInTx(tx, source.bundleId, "B2C");
        const [existing] = target ? await tx.select().from(retailCartItemsTable).where(and(eq(retailCartItemsTable.cartId, cart.id), eq(retailCartItemsTable.bundleId, source.bundleId))).limit(1) : [];
        const requested = source.quantity; const quantity = Math.min(requested, Math.max(0, (target?.derivedStock ?? 0) - (existing?.quantity ?? 0)));
        if (!target || target.bundle.b2cPrice == null || quantity < 1) { outcome.skipped.push({ id: source.bundleId, reason: "unavailable" }); continue; }
        if (existing) await tx.update(retailCartItemsTable).set({ quantity: existing.quantity + quantity, unitPrice: target.bundle.b2cPrice, updatedAt: new Date() }).where(eq(retailCartItemsTable.id, existing.id));
        else await tx.insert(retailCartItemsTable).values({ cartId: cart.id, bundleId: source.bundleId, productName: target.bundle.name, productImageUrl: target.bundle.imageUrl ?? "", unitPrice: target.bundle.b2cPrice, quantity, weightGrams: 0 });
        (quantity === requested ? outcome.added : outcome.adjusted).push({ id: source.bundleId, requestedQuantity: requested, quantity });
      } else if (source.productId) {
        await tx.execute(sql`select id from products where id = ${source.productId} for update`);
        const [product] = await tx.select().from(productsTable).where(and(eq(productsTable.id, source.productId), eq(productsTable.active, true), eq(productsTable.retailEnabled, true), isNotNull(productsTable.publicDescription), isNotNull(productsTable.publicPrice), retailVariantCompatibleCondition(), activeCategoryCondition(), activeSupplierCondition("B2C"))).limit(1);
        const productCartItems = product ? await tx.select().from(retailCartItemsTable).where(and(
          eq(retailCartItemsTable.cartId, cart.id), eq(retailCartItemsTable.productId, source.productId),
        )) : [];
        const existing = productCartItems.find((item) => item.variantValue === source.variantValue);
        const selection = product ? retailVariantSelection(product, source.variantValue) : null;
        const alreadyReserved = selection?.variant?.stock == null
          ? productCartItems.reduce((sum, item) => sum + item.quantity, 0)
          : existing?.quantity ?? 0;
        const requested = source.quantity;
        const quantity = Math.min(requested, Math.max(0, (selection?.available ?? 0) - alreadyReserved));
        if (!product || !selection || quantity < product.minimumOrderQuantity) { outcome.skipped.push({ id: source.productId, variantValue: source.variantValue, reason: "unavailable" }); continue; }
        const unitPrice = retailProductPrice(product, (existing?.quantity ?? 0) + quantity).unitPrice;
        if (existing) await tx.update(retailCartItemsTable).set({ quantity: existing.quantity + quantity, unitPrice, updatedAt: new Date() }).where(eq(retailCartItemsTable.id, existing.id));
        else await tx.insert(retailCartItemsTable).values({
          cartId: cart.id, productId: product.id, productName: product.name,
          productImageUrl: selection.variant?.mainImageUrl ?? product.imageUrl,
          productCatalogReference: product.catalogReference, variantValue: source.variantValue,
          unitPrice, quantity, weightGrams: product.weightGrams ?? 0,
        });
        (quantity === requested ? outcome.added : outcome.adjusted).push({ id: source.productId, variantValue: source.variantValue, requestedQuantity: requested, quantity });
      }
    }
    await tx.update(retailCartsTable).set({ updatedAt: new Date(), activityVersion: sql`${retailCartsTable.activityVersion} + 1` }).where(eq(retailCartsTable.id, cart.id));
    await tx.insert(reorderActionsTable).values({ audience: "B2C", userId: user.id, idempotencyKey: key, result: outcome });
    return outcome;
  });
  res.json({ ...result, cart: await retailCartDto(cart.id) });
});

router.get("/retail/checkout-preview", async (req, res): Promise<void> => {
  const cart = await retailCartForRequest(req, res);
  const user = await getCurrentUser(req);
  const aftercareRecommendationId = typeof req.query.aftercareRecommendationId === "string"
    && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(req.query.aftercareRecommendationId)
    ? req.query.aftercareRecommendationId : null;
  if (req.query.aftercareRecommendationId !== undefined && !aftercareRecommendationId) {
    res.status(409).json({ error: "Preporuka za negu nije dostupna.", code: "AFTERCARE_RECOMMENDATION_UNAVAILABLE" }); return;
  }
  const aftercare = await lockedAftercareDiscounts(db, isRetailAccount(user) ? user.id : null, aftercareRecommendationId);
  if (!aftercare) {
    res.status(409).json({ error: "Preporuka za negu nije dostupna.", code: "AFTERCARE_RECOMMENDATION_UNAVAILABLE" }); return;
  }
  const quote = await retailCheckoutCartQuote(cart.id, isRetailAccount(user) ? user.id : null);
  if (!quote.view) {
    res.status(409).json({
      error: "Dostupnost ili cena proizvoda u korpi se promenila. Osvežite korpu i pokušajte ponovo.",
      code: "CHECKOUT_QUOTE_CHANGED",
      unavailableItems: quote.unavailableItems,
    });
    return;
  }
  const view = quote.view;
  if (aftercare.recommendationId && !view.items.some((line) =>
    line.kind === "product" ? aftercare.eligibleProductIds.has(line.productId)
      : aftercare.eligibleBundleIds.has(line.bundleId))) {
    res.status(409).json({ error: "Preporuka za negu nije dostupna.", code: "AFTERCARE_RECOMMENDATION_UNAVAILABLE" }); return;
  }
  const prepared = await prepareRetailCommerceQuote(db, view.items, quote.rules, "B2C", aftercare.discounts);
  const couponCode = typeof req.query.couponCode === "string" ? req.query.couponCode : null;
  const appliedCoupon = await quoteCouponFromDb(db, {
    code: couponCode, audience: "B2C",
    lines: prepared.couponLines.map((line) => ({ ...line, categoryIds: [...line.categoryIds] })),
    customer: isRetailAccount(user) ? { userId: user.id } : {},
  });
  if (appliedCoupon && "reason" in appliedCoupon) { couponErrorResponse(res, appliedCoupon.reason); return; }
  const config = await getShippingConfig();
  const deliveryMethod = req.query.deliveryMethod === "personal_belgrade" ? "personal_belgrade" : "courier";
  const city = typeof req.query.city === "string" ? req.query.city : "";
  if (deliveryMethod === "personal_belgrade" && (!config.personalDeliveryEnabled || !/beograd/i.test(city))) {
    res.status(400).json({ error: "Lična dostava je dostupna samo u Beogradu." }); return;
  }
  const calculatedShipping = calculateShipping(config, view.totalWeightGrams, view.subtotal, deliveryMethod, city);
  const desired = typeof req.query.desiredReferralCreditRsd === "string" && /^\d+$/.test(req.query.desiredReferralCreditRsd)
    ? Number(req.query.desiredReferralCreditRsd) : 0;
  const available = user?.role === "CUSTOMER"
    ? await db.transaction((tx) => referralCreditBalanceInTx(tx, { ownerUserId: user.id, walletKind: "B2C" }))
    : 0;
  const totals = finalizeCommerceQuote({
    prepared,
    lockedCouponQuote: appliedCoupon?.quote ?? quoteCoupon({
      coupon: null,
      audience: "B2C",
      lines: prepared.couponLines.map((line) => ({ ...line, categoryIds: [...line.categoryIds] })),
      now: new Date(),
      customerUsageCount: 0,
    }),
    thresholdRewards: quote.rules.thresholdRewards,
    requestedReferralCreditRsd: desired || available,
    availableReferralCreditRsd: available,
    shippingRsd: calculatedShipping.shippingCost,
  });
  const rewardGifts = await thresholdGiftDescriptors(db, totals.rewardGifts, quote.rules, "B2C");
  if (!rewardGifts) {
    res.status(409).json({
      error: "Nagradni proizvod više nije dostupan. Osvežite pregled i pokušajte ponovo.",
      code: "CHECKOUT_REWARD_UNAVAILABLE",
    });
    return;
  }
  const crossedThresholdRewards = quote.rules.thresholdRewards.filter((rule) => rule.active
    && rule.thresholdRsd <= totals.thresholdQualificationSubtotalRsd);
  const nextThresholdReward = quote.rules.thresholdRewards
    .filter((rule) => rule.active && rule.thresholdRsd > totals.thresholdQualificationSubtotalRsd)
    .sort((left, right) => left.thresholdRsd - right.thresholdRsd || left.id.localeCompare(right.id))[0];
  const thresholdFreeShipping = crossedThresholdRewards.some((rule) => rule.kind === "FREE_SHIPPING");
  const couponDiscountRsd = totals.couponDiscountRsd;
  const shipping = totals.shippingRsd === calculatedShipping.shippingCost
    ? calculatedShipping : { ...calculatedShipping, shippingCost: totals.shippingRsd, isFreeShipping: true };
  const commerce = await cartCommerceFields("B2C", view.items.map((line) => ({
    productId: line.kind === "product" ? line.productId : undefined, bundleId: line.kind === "bundle" ? line.bundleId : undefined,
    quantity: line.quantity, lineTotal: line.lineTotal, availableStock: 0,
  })), user?.role === "CUSTOMER" ? { userId: user.id } : null);
  const { lineLowStock, ...commerceDto } = commerce;
  res.json({
    cart: { ...view, ...commerceDto, items: view.items.map((line) => ({
      ...line, lowStock: lineLowStock.get(line.kind === "product" ? line.productId : `bundle:${line.bundleId}`) ?? false,
    })) }, shipping, total: totals.payableTotalRsd, paymentMethods: checkoutPaymentMethods,
    referralCreditAvailableRsd: available, referralCreditAppliedRsd: totals.referralAppliedRsd,
    merchandiseSubtotalRsd: totals.referralBaseRsd, shippingRsd: totals.shippingRsd,
    payableTotalRsd: totals.payableTotalRsd,
    coupon: appliedCoupon ? {
      code: appliedCoupon.quote.code, discountRsd: couponDiscountRsd,
      freeShipping: appliedCoupon.quote.freeShipping, allocations: appliedCoupon.quote.allocations,
    } : null,
    couponDiscountRsd,
    personalizedTreatmentBundleDiscountRsd: totals.personalizedTreatmentBundleDiscountRsd,
    postTreatmentRecommendationDiscountRsd: totals.postTreatmentRecommendationDiscountRsd,
    automaticPromotionDiscountRsd: totals.automaticPromotionDiscountRsd,
    thresholdRewardDiscountRsd: totals.thresholdRewardDiscountRsd,
    thresholdFreeShipping,
    thresholdReached: crossedThresholdRewards.map((rule) => ({ id: rule.id, thresholdRsd: rule.thresholdRsd, kind: rule.kind })),
    thresholdNext: nextThresholdReward ? {
      id: nextThresholdReward.id, thresholdRsd: nextThresholdReward.thresholdRsd,
      remainingRsd: nextThresholdReward.thresholdRsd - totals.thresholdQualificationSubtotalRsd,
      kind: nextThresholdReward.kind,
    } : null,
    thresholdQualificationSubtotalRsd: totals.thresholdQualificationSubtotalRsd,
    rewardGifts: rewardGifts.map(({ product, rewardSnapshot, ...gift }) => gift),
  });
});

router.post("/retail/checkout", async (req, res): Promise<void> => {
  const couponCode = typeof req.body?.couponCode === "string" ? req.body.couponCode.trim().toUpperCase() || null : null;
  if (req.body?.aftercareRecommendationId !== undefined
    && (typeof req.body.aftercareRecommendationId !== "string"
      || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(req.body.aftercareRecommendationId))) {
    res.status(409).json({ error: "Preporuka za negu nije dostupna.", code: "AFTERCARE_RECOMMENDATION_UNAVAILABLE" }); return;
  }
  const parsed = retailCheckoutInput(req.body);
  if (!parsed) { res.status(400).json({ error: "Unesite kompletne i ispravne podatke za dostavu." }); return; }
  const cart = await retailCartForRequest(req, res);
  const currentUser = await getCurrentUser(req);
  const userId = isRetailAccount(currentUser) ? currentUser.id : null;
  if (parsed.paymentMethod === "CARD") {
    res.status(400).json({ error: "Plaćanje karticom biće dostupno čim se uključi siguran payment handoff." }); return;
  }
  const config = await getShippingConfig();
  if (parsed.deliveryMethod === "personal_belgrade" && (!config.personalDeliveryEnabled || !/beograd/i.test(parsed.city))) {
    res.status(400).json({ error: "Lična dostava je trenutno dostupna samo u Beogradu." }); return;
  }
  let stockError: string | null = null;
  let unavailableItems: Array<{ productId: string; name: string }> = [];
  let trackingToken: string | null = null;
  let stockConflict = false;
  let idempotencyConflict = false;
  let quoteConflict = false;
  let couponFailure: string | null = null;
  let aftercareFailure = false;
  let rewardUnavailable = false;
  let minimumOrderConflict: { name: string; minimumOrderQuantity: number } | null = null;
  const created = await db.transaction(async (tx) => {
    await tx.execute(sql`select id from retail_carts where id = ${cart.id} for update`);
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${parsed.idempotencyKey}))`);
    const [previous] = await tx.select().from(retailOrdersTable)
      .where(and(eq(retailOrdersTable.cartId, cart.id), eq(retailOrdersTable.idempotencyKey, parsed.idempotencyKey))).limit(1);
    if (previous) return { order: previous, repeat: true };
    const [collision] = await tx.select({ id: retailOrdersTable.id }).from(retailOrdersTable)
      .where(eq(retailOrdersTable.idempotencyKey, parsed.idempotencyKey)).limit(1);
    if (collision) throw new Error("retail_idempotency_collision");
    const cartItems = await tx.select().from(retailCartItemsTable).where(eq(retailCartItemsTable.cartId, cart.id));
    if (!cartItems.length) throw new Error("retail_cart_empty");
    const productItems = cartItems.filter((item): item is typeof item & { productId: string; bundleId: null } => item.productId !== null);
    const bundleItems = cartItems.filter((item): item is typeof item & { bundleId: string; productId: null } => item.bundleId !== null);
    const bundleIds = [...new Set(bundleItems.map((item) => item.bundleId))].sort();
    // Lock every mutable catalog record in a global order before revalidating
    // the quote.  A bundle consumes its component inventory, never its own.
    for (const id of bundleIds) await tx.execute(sql`select id from product_bundles where id = ${id} for update`);
    const bundles = bundleIds.length ? await tx.select().from(productBundlesTable).where(inArray(productBundlesTable.id, bundleIds)) : [];
    const bundlesById = new Map(bundles.map((bundle) => [bundle.id, bundle]));
    const components = bundleIds.length ? await tx.select().from(productBundleComponentsTable)
      .where(inArray(productBundleComponentsTable.bundleId, bundleIds))
      .orderBy(asc(productBundleComponentsTable.bundleId), asc(productBundleComponentsTable.productId)) : [];
    const componentsByBundle = new Map<string, typeof components>();
    for (const component of components) componentsByBundle.set(component.bundleId, [...(componentsByBundle.get(component.bundleId) ?? []), component]);
    for (const component of components) await tx.execute(sql`select id from product_bundle_components where id = ${component.id} for update`);
    const productIds = [...new Set([...productItems.map((item) => item.productId), ...components.map((component) => component.productId)])].sort();
    for (const id of productIds) await tx.execute(sql`select id from products where id = ${id} for update`);
    const rawProducts = await tx.select().from(productsTable).where(inArray(productsTable.id, productIds));
    const supplierIds = [...new Set([...rawProducts.map((product) => product.supplierId), ...bundles.map((bundle) => bundle.supplierId)])].sort();
    for (const supplierId of supplierIds) {
      await tx.execute(sql`select id from suppliers where id = ${supplierId} for update`);
      await tx.execute(sql`select id from product_categories where supplier_id = ${supplierId} order by id for update`);
    }
    const products = await tx.select().from(productsTable).where(and(inArray(productsTable.id, productIds), activeCategoryCondition(), activeSupplierCondition("B2C")));
    // Reload rule facts within the same checkout transaction as product and
    // inventory locks. A changed campaign/tier therefore changes the expected
    // quote rather than silently charging a stale preview.
    const deoRules = await loadDeoG2RuleSnapshot(tx, {
      market: "B2C", now: new Date(), productIds, userId,
    });
    const byId = new Map(products.map((product) => [product.id, product]));
    const supplierRows = await tx.select().from(suppliersTable)
      .where(and(inArray(suppliersTable.id, [...new Set([...products.map((product) => product.supplierId), ...bundles.map((bundle) => bundle.supplierId)])]),
        eq(suppliersTable.active, true), inArray(suppliersTable.scope, ["B2C", "BOTH"])));
    const suppliersById = new Map(supplierRows.map((supplier) => [supplier.id, supplier]));
    const quantityByProduct = new Map<string, number>();
    const quantityByVariant = new Map<string, number>();
    for (const item of productItems) {
      quantityByProduct.set(item.productId, (quantityByProduct.get(item.productId) ?? 0) + item.quantity);
      if (item.variantValue) {
        const key = `${item.productId}\u0000${item.variantValue}`;
        quantityByVariant.set(key, (quantityByVariant.get(key) ?? 0) + item.quantity);
      }
    }
    for (const item of bundleItems) {
      const bundle = bundlesById.get(item.bundleId);
      const bundleComponents = componentsByBundle.get(item.bundleId) ?? [];
      if (!bundle || !suppliersById.has(bundle.supplierId) || !bundle.active || !["B2C", "BOTH"].includes(bundle.market) || bundle.b2cPrice == null || bundleComponents.length < 2) {
        unavailableItems.push({ productId: item.bundleId, name: item.productName }); continue;
      }
      for (const component of bundleComponents) {
        quantityByProduct.set(component.productId, (quantityByProduct.get(component.productId) ?? 0) + component.quantity * item.quantity);
      }
    }
    for (const [productId, quantity] of quantityByProduct) {
      const product = byId.get(productId);
      if (!product || product.stock < quantity) {
        unavailableItems.push({
          productId,
          name: product?.name ?? productItems.find((item) => item.productId === productId)?.productName ?? "Proizvod",
        });
      }
    }
    if (unavailableItems.length) {
      stockError = unavailableItems[0]!.name;
      throw new Error("retail_stock_conflict");
    }
    let subtotal = 0;
    let weight = 0;
    const lines = productItems.map((item) => {
      const product = byId.get(item.productId);
      const selection = product ? retailVariantSelection(product, item.variantValue) : null;
      const requiredStock = selection?.variant?.stock != null
        ? quantityByVariant.get(`${item.productId}\u0000${item.variantValue}`) ?? 0
        : quantityByProduct.get(item.productId) ?? 0;
       if (!product || !product.active || !product.retailEnabled || !product.publicDescription || product.publicPrice == null
         || !selection || selection.available < requiredStock) {
        const name = product?.name ?? item.productName;
        if (!unavailableItems.some((unavailable) => unavailable.productId === item.productId)) {
          unavailableItems.push({ productId: item.productId, name });
        }
        stockError ??= name;
        return null;
      }
      if (item.quantity < product.minimumOrderQuantity) {
        minimumOrderConflict = {
          name: product.name,
          minimumOrderQuantity: product.minimumOrderQuantity,
        };
        throw new Error("retail_moq_conflict");
      }
      const pricing = retailProductPrice(product, item.quantity, deoRules);
      const unitPrice = pricing.unitPrice;
      subtotal += unitPrice * item.quantity;
      weight += (product.weightGrams ?? 0) * item.quantity;
       return { product, item, variant: selection.variant, unitPrice, pricing };
    });
    const bundleLines = bundleItems.map((item) => {
      const bundle = bundlesById.get(item.bundleId);
      const bundleComponents = (componentsByBundle.get(item.bundleId) ?? []).map((component) => ({ component, product: byId.get(component.productId) }));
      if (!bundle || bundle.b2cPrice == null || bundleComponents.length < 2 || bundleComponents.some(({ product }) => !product)) {
        stockError ??= item.productName; return null;
      }
      subtotal += bundle.b2cPrice * item.quantity;
      weight += bundleComponents.reduce((sum, { component, product }) => sum + (product!.weightGrams ?? 0) * component.quantity * item.quantity, 0);
      return { bundle, item, unitPrice: bundle.b2cPrice, components: bundleComponents.map(({ component, product }) => ({ component, product: product! })) };
    });
    if (stockError || unavailableItems.length || lines.some((line) => !line) || bundleLines.some((line) => !line)) throw new Error("retail_stock_conflict");
    const defaultDeliveryDays = (await tx.select().from(shopSettingsTable).limit(1))[0]?.defaultDeliveryBusinessDays ?? 3;
    const deliveryDays = Math.max(defaultDeliveryDays, ...[
      ...lines.filter((line): line is NonNullable<typeof line> => line !== null).map(({ product }) => product.deliveryBusinessDaysOverride ?? defaultDeliveryDays),
      ...bundleLines.filter((line): line is NonNullable<typeof line> => line !== null).flatMap(({ components }) => components.map(({ product }) => product.deliveryBusinessDaysOverride ?? defaultDeliveryDays)),
    ]);
    const estimatedDeliveryDate = belgradeBusinessDate(deliveryDays);
    const quoteItems = [
      ...lines.filter((line): line is NonNullable<typeof line> => line !== null).map((line) => ({
        id: line.item.id, kind: "product" as const, productId: line.product.id, quantity: line.item.quantity,
        unitPrice: line.unitPrice, baseUnitPrice: line.pricing.baseUnitPrice, priceSource: line.pricing.priceSource,
      })),
      ...bundleLines.filter((line): line is NonNullable<typeof line> => line !== null).map((line) => ({
        id: line.item.id, kind: "bundle" as const, bundleId: line.bundle.id, quantity: line.item.quantity,
        unitPrice: line.unitPrice, priceSource: "BUNDLE" as const,
      })),
    ];
    // Re-load under the same cart/catalog checkout transaction. Preview is
    // advisory only; a consumed, revoked or expired recommendation can never
    // survive to the final quote.
    const aftercare = await lockedAftercareDiscounts(tx, userId, parsed.aftercareRecommendationId, true);
    if (!aftercare) { aftercareFailure = true; throw new Error("retail_aftercare_conflict"); }
    if (aftercare.recommendationId && !quoteItems.some((line) =>
      line.kind === "product" ? aftercare.eligibleProductIds.has(line.productId)
        : aftercare.eligibleBundleIds.has(line.bundleId))) {
      aftercareFailure = true; throw new Error("retail_aftercare_conflict");
    }
    const prepared = await prepareRetailCommerceQuote(tx, quoteItems, deoRules, "B2C", aftercare.discounts);
    subtotal = prepared.subtotalRsd;
    const couponResult = await quoteCouponFromDb(tx, {
      code: couponCode, audience: "B2C", lock: true,
      customer: userId ? { userId } : { guestEmailNormalized: parsed.email.trim().toLowerCase() },
      lines: prepared.couponLines.map((line) => ({ ...line, categoryIds: [...line.categoryIds] })),
    });
    if (couponResult && "reason" in couponResult) {
      couponFailure = couponResult.reason;
      throw new Error("retail_coupon_conflict");
    }
    const appliedCoupon = couponResult && "quote" in couponResult ? couponResult : null;
    const calculatedShipping = calculateShipping(config, weight, subtotal, parsed.deliveryMethod, parsed.city);
    const lockedCouponQuote = appliedCoupon?.quote ?? quoteCoupon({
      coupon: null,
      audience: "B2C",
      lines: prepared.couponLines.map((line) => ({ ...line, categoryIds: [...line.categoryIds] })),
      now: deoRules.now,
      customerUsageCount: 0,
    });
    const preReferralTotals = finalizeCommerceQuote({
      prepared, lockedCouponQuote, thresholdRewards: deoRules.thresholdRewards,
      requestedReferralCreditRsd: parsed.desiredReferralCreditRsd, availableReferralCreditRsd: 0,
      shippingRsd: calculatedShipping.shippingCost,
    });
    const referral = userId
      ? await allocateReferralCreditInTx(tx, { ownerUserId: userId, walletKind: "B2C" }, parsed.desiredReferralCreditRsd,
        preReferralTotals.referralBaseRsd)
      : { availableRsd: 0, appliedRsd: 0, allocations: [] };
    const totals = finalizeCommerceQuote({
      prepared, lockedCouponQuote, thresholdRewards: deoRules.thresholdRewards,
      requestedReferralCreditRsd: referral.appliedRsd, availableReferralCreditRsd: referral.appliedRsd,
      shippingRsd: calculatedShipping.shippingCost,
    });
    // Gift products are locked and checked after the finalized threshold
    // calculation; aggregate same-SKU levels before any inventory mutation.
    const rewardGifts = await thresholdGiftDescriptors(tx, totals.rewardGifts, deoRules, "B2C", true);
    if (!rewardGifts) { rewardUnavailable = true; stockError = "nagradni proizvod"; throw new Error("retail_stock_conflict"); }
    const giftSupplierIds = [...new Set(rewardGifts.map((gift) => gift.product.supplierId))];
    if (giftSupplierIds.length) for (const supplier of await tx.select().from(suppliersTable)
      .where(inArray(suppliersTable.id, giftSupplierIds))) suppliersById.set(supplier.id, supplier);
    for (const gift of rewardGifts) {
      const combined = (quantityByProduct.get(gift.productId) ?? 0) + gift.quantity;
      if (gift.product.stock < combined) { rewardUnavailable = true; stockError = gift.product.name; throw new Error("retail_stock_conflict"); }
      quantityByProduct.set(gift.productId, combined);
      byId.set(gift.productId, gift.product);
    }
    const couponDiscountRsd = totals.couponDiscountRsd;
    const shipping = totals.shippingRsd === calculatedShipping.shippingCost
      ? calculatedShipping : { ...calculatedShipping, shippingCost: totals.shippingRsd, isFreeShipping: true };
    const payableTotal = totals.payableTotalRsd;
    if ((parsed.expectedSubtotal !== undefined && parsed.expectedSubtotal !== subtotal)
      || (parsed.expectedShippingCost !== undefined && parsed.expectedShippingCost !== shipping.shippingCost)
      || (parsed.expectedTotal !== undefined && parsed.expectedTotal !== payableTotal)) {
      quoteConflict = true;
      return null;
    }
    trackingToken = randomBytes(32).toString("base64url");
    const orderNumber = `LR-${randomUUID().replace(/-/g, "").slice(0, 10).toUpperCase()}`;
    const [order] = await tx.insert(retailOrdersTable).values({
      orderNumber, cartId: cart.id, userId, trackingTokenHash: hashRetailToken(trackingToken),
      trackingTokenExpiresAt: new Date(deoRules.now.getTime() + 180 * 24 * 60 * 60 * 1000),
      idempotencyKey: parsed.idempotencyKey,
      status: "pending", paymentMethod: parsed.paymentMethod,
      paymentStatus: parsed.paymentMethod === "CASH_ON_DELIVERY" ? "unpaid" : "pending",
      deliveryMethod: parsed.deliveryMethod, subtotal, shippingCost: shipping.shippingCost, total: payableTotal,
      couponCodeSnapshot: appliedCoupon?.quote.code ?? null, couponDiscountRsd,
      couponFreeShipping: appliedCoupon?.quote.freeShipping ?? false,
      promotionSnapshot: {
        campaigns: deoRules.campaigns.map((rule) => ({
          id: rule.id, version: rule.version, market: rule.market, status: rule.status,
          discountType: rule.discountType, discountValue: rule.discountValue,
          startsAt: rule.startsAt, endsAt: rule.endsAt,
          productIds: rule.productIds, categoryIds: rule.categoryIds,
        })),
        loyaltyTier: deoRules.loyaltyTier,
        loyaltyExcludedProductIds: [...deoRules.loyaltyExcludedProductIds],
        automaticPromotions: deoRules.automaticPromotions.map((rule) => ({
          id: rule.id, version: rule.version, name: rule.name, market: rule.market, startsAt: rule.startsAt,
          endsAt: rule.endsAt, buyQuantity: rule.buyQuantity, rewardQuantity: rule.rewardQuantity,
          rewardPercent: rule.rewardPercent, perOrderRewardUnitCap: rule.perOrderRewardUnitCap,
          buyProductIds: rule.buyProductIds, buyCategoryIds: rule.buyCategoryIds,
          rewardProductIds: rule.rewardProductIds, rewardCategoryIds: rule.rewardCategoryIds,
        })),
        thresholdRewards: deoRules.thresholdRewards.map((rule) => ({
          id: rule.id, version: rule.version, name: rule.name, market: rule.market, thresholdRsd: rule.thresholdRsd,
          kind: rule.kind, percent: rule.percent, giftProductId: rule.giftProductId, giftQuantity: rule.giftQuantity,
        })),
        automaticApplications: totals.automaticPromotionSnapshots,
        thresholdQualificationSubtotalRsd: totals.thresholdQualificationSubtotalRsd,
        automaticPromotionDiscountRsd: totals.automaticPromotionDiscountRsd,
        thresholdRewardDiscountRsd: totals.thresholdRewardDiscountRsd,
        personalizedTreatmentBundleDiscountRsd: totals.personalizedTreatmentBundleDiscountRsd,
        postTreatmentRecommendationDiscountRsd: totals.postTreatmentRecommendationDiscountRsd,
        aftercareRecommendationId: aftercare.recommendationId,
        thresholdFreeShipping: deoRules.thresholdRewards.some((rule) => rule.active
          && rule.kind === "FREE_SHIPPING" && rule.thresholdRsd <= totals.thresholdQualificationSubtotalRsd),
      },
      referralCreditMerchandiseSubtotalRsd: totals.referralBaseRsd,
      referralCreditPreCreditPayableTotalRsd: payableTotal + referral.appliedRsd,
      referralCreditAppliedRsd: referral.appliedRsd,
      shippingName: `${parsed.firstName} ${parsed.lastName}`, shippingAddress: parsed.street, shippingCity: parsed.city,
      shippingPostalCode: parsed.postalCode, shippingPhone: parsed.phone, shippingEmail: parsed.email.toLowerCase(), shippingNote: parsed.note ?? null, estimatedDeliveryDate,
    }).returning();
    if (appliedCoupon) {
      await tx.insert(couponRedemptionsTable).values({
        couponId: appliedCoupon.coupon.id, audience: "B2C", retailOrderId: order!.id,
        ...(userId ? { userId } : { guestEmailNormalized: parsed.email.trim().toLowerCase() }),
        codeSnapshot: appliedCoupon.quote.code, discountRsd: couponDiscountRsd,
        freeShipping: appliedCoupon.quote.freeShipping,
      });
      await tx.update(couponsTable).set({ usageCount: sql`${couponsTable.usageCount} + 1`, updatedAt: new Date() })
        .where(eq(couponsTable.id, appliedCoupon.coupon.id));
    }
    if (referral.appliedRsd) await recordReferralRedemptionInTx(tx, {
      scope: { ownerUserId: userId!, walletKind: "B2C" }, retailOrderId: order!.id,
      allocations: referral.allocations, idempotencyKey: parsed.idempotencyKey, actorUserId: userId,
    });
    const referralAllocations = allocateFinalReferralDiscount(totals.lines, totals.referralAppliedRsd);
    const orderItems = [
       ...lines.filter((line): line is NonNullable<typeof line> => line !== null).map(({ product, item, variant, unitPrice, pricing }) => {
      const supplier = suppliersById.get(product.supplierId);
      if (!supplier) throw new Error("retail_stock_conflict");
       const finalizedLine = totals.lines.find((candidate) => candidate.id === item.id)!;
       const lineCouponDiscount = finalizedLine.couponAllocationRsd;
       const referralDiscountRsd = referralAllocations.get(item.id) ?? 0;
       const unitCostPriceRsd = product.costPriceRsd ?? 0;
      return {
        orderId: order!.id, productId: product.id, productName: product.name, productImageUrl: product.imageUrl,
        productCatalogReference: item.productCatalogReference ?? product.catalogReference,
         variantValue: item.variantValue, variantLabel: variant?.label ?? null, unitPrice, quantity: item.quantity,
        supplierId: supplier.id, supplierName: supplier.name, supplierSlug: supplier.slug,
         productSkuSnapshot: variant?.sku ?? product.sku, market: "B2C" as const, currency: "RSD",
         categoryIdSnapshot: product.categoryId, categoryNameSnapshot: product.categoryName, brandSnapshot: product.brand,
        discountSnapshot: pricing.baseUnitPrice > unitPrice ? pricing.baseUnitPrice - unitPrice : null,
        baseUnitPrice: pricing.baseUnitPrice, effectiveUnitPrice: unitPrice,
        priceSource: pricing.priceSource, lineDiscount: (pricing.baseUnitPrice - unitPrice) * item.quantity,
        couponDiscountRsd: lineCouponDiscount,
         automaticPromotionDiscountRsd: finalizedLine.automaticPromotionAllocationRsd,
         thresholdRewardDiscountRsd: finalizedLine.thresholdRewardAllocationRsd,
         unitCostPriceRsd, lineCogsRsd: unitCostPriceRsd * item.quantity,
         referralDiscountRsd, realizedRevenueRsd: finalizedLine.lineTotalRsd - referralDiscountRsd,
         personalizedTreatmentBundleDiscountRsd: finalizedLine.personalizedTreatmentBundleDiscountRsd,
         postTreatmentRecommendationDiscountRsd: finalizedLine.postTreatmentRecommendationDiscountRsd,
         aftercareRecommendationId: aftercare.eligibleProductIds.has(product.id) ? aftercare.recommendationId : null,
         estimatedDeliveryDate, lineSubtotal: finalizedLine.lineSubtotalRsd, lineTotal: finalizedLine.lineTotalRsd,
      };
      }),
      ...bundleLines.filter((line): line is NonNullable<typeof line> => line !== null).map(({ bundle, item, unitPrice, components }) => {
        const supplier = suppliersById.get(bundle.supplierId);
        if (!supplier) throw new Error("retail_stock_conflict");
         const finalizedLine = totals.lines.find((candidate) => candidate.id === item.id)!;
         const lineCouponDiscount = finalizedLine.couponAllocationRsd;
         const referralDiscountRsd = referralAllocations.get(item.id) ?? 0;
         const unitCostPriceRsd = components.reduce(
           (sum, { component, product }) => sum + (product.costPriceRsd ?? 0) * component.quantity,
           0,
         );
        return {
          orderId: order!.id, productId: null, bundleId: bundle.id, productName: bundle.name, productImageUrl: bundle.imageUrl ?? "",
          productCatalogReference: null, variantValue: null, variantLabel: null, unitPrice, quantity: item.quantity,
          supplierId: supplier.id, supplierName: supplier.name, supplierSlug: supplier.slug, productSkuSnapshot: null,
           categoryIdSnapshot: null, categoryNameSnapshot: null, brandSnapshot: null,
          market: "B2C" as const, currency: "RSD", discountSnapshot: null, baseUnitPrice: unitPrice,
          effectiveUnitPrice: unitPrice, priceSource: "BUNDLE" as const, lineDiscount: 0, bundleNameSnapshot: bundle.name,
          couponDiscountRsd: lineCouponDiscount,
           automaticPromotionDiscountRsd: finalizedLine.automaticPromotionAllocationRsd,
           thresholdRewardDiscountRsd: finalizedLine.thresholdRewardAllocationRsd,
           unitCostPriceRsd, lineCogsRsd: unitCostPriceRsd * item.quantity,
           referralDiscountRsd, realizedRevenueRsd: finalizedLine.lineTotalRsd - referralDiscountRsd,
          personalizedTreatmentBundleDiscountRsd: finalizedLine.personalizedTreatmentBundleDiscountRsd,
          postTreatmentRecommendationDiscountRsd: finalizedLine.postTreatmentRecommendationDiscountRsd,
          aftercareRecommendationId: aftercare.eligibleBundleIds.has(bundle.id) ? aftercare.recommendationId : null,
          bundleComponentsSnapshot: components.map(({ component, product }) => ({
            productId: product.id, name: product.name, catalogReference: product.catalogReference, quantity: component.quantity,
          })),
           estimatedDeliveryDate, lineSubtotal: finalizedLine.lineSubtotalRsd, lineTotal: finalizedLine.lineTotalRsd,
        };
      }),
      ...rewardGifts.map((gift) => {
        const supplier = suppliersById.get(gift.product.supplierId);
        if (!supplier) throw new Error("retail_stock_conflict");
        return {
          orderId: order!.id, productId: gift.product.id, productName: gift.product.name,
          productImageUrl: gift.product.imageUrl, productCatalogReference: gift.product.catalogReference,
          variantValue: null, variantLabel: null, unitPrice: 0, quantity: gift.quantity,
          supplierId: supplier.id, supplierName: supplier.name, supplierSlug: supplier.slug,
          productSkuSnapshot: gift.product.sku, market: "B2C" as const, currency: "RSD",
           categoryIdSnapshot: gift.product.categoryId, categoryNameSnapshot: gift.product.categoryName, brandSnapshot: gift.product.brand,
          discountSnapshot: null, baseUnitPrice: 0, effectiveUnitPrice: 0, priceSource: "FULL_PRICE" as const,
          lineDiscount: 0, couponDiscountRsd: 0, automaticPromotionDiscountRsd: 0,
          personalizedTreatmentBundleDiscountRsd: 0, postTreatmentRecommendationDiscountRsd: 0,
          aftercareRecommendationId: null,
          thresholdRewardDiscountRsd: 0, lineSubtotal: 0, lineTotal: 0, estimatedDeliveryDate,
           unitCostPriceRsd: gift.product.costPriceRsd ?? 0,
           lineCogsRsd: (gift.product.costPriceRsd ?? 0) * gift.quantity,
           referralDiscountRsd: 0, realizedRevenueRsd: 0,
          isRewardGift: true, rewardSnapshot: gift.rewardSnapshot,
        };
      }),
    ];
    await tx.insert(retailOrderItemsTable).values(orderItems);
    const [pointSettings] = await tx.select().from(shopSettingsTable).limit(1);
    const awarded = userId
      ? await awardLoyaltyPointsInTx(tx, { audience: "B2C", userId, retailOrderId: order!.id },
        orderItems.filter((item) => item.priceSource === "FULL_PRICE")
          .reduce((sum, item) => sum + item.lineTotal, 0), pointSettings)
      : 0;
    if (awarded) await tx.update(retailOrdersTable).set({ loyaltyPointsAwarded: awarded }).where(eq(retailOrdersTable.id, order!.id));
    for (const [productId, quantity] of quantityByProduct) {
      const product = byId.get(productId)!;
      const updatedVariants = (product.variants ?? []).map((variant) => {
        const used = quantityByVariant.get(`${productId}\u0000${variant.value}`) ?? 0;
        return used > 0 && variant.stock !== undefined ? { ...variant, stock: variant.stock - used } : variant;
      });
      const [updated] = await tx.update(productsTable).set({ stock: sql`${productsTable.stock} - ${quantity}`, variants: updatedVariants })
        .where(and(eq(productsTable.id, productId), gte(productsTable.stock, quantity))).returning({ id: productsTable.id });
       if (!updated) { stockError = byId.get(productId)?.name ?? "Proizvod"; throw new Error("retail_stock_conflict"); }
    }
    await tx.delete(retailCartItemsTable).where(eq(retailCartItemsTable.cartId, cart.id));
    // Preserve the completed activity marker before the cart becomes empty.
    // A subsequent item/contact mutation advances activityVersion and can then
    // qualify independently for a future reminder.
    await tx.update(retailCartsTable).set({
      userId,
      completedActivityVersion: retailCartsTable.activityVersion,
      activityVersion: sql`${retailCartsTable.activityVersion} + 1`,
      updatedAt: new Date(),
    }).where(eq(retailCartsTable.id, cart.id));
    await notifyCustomer(tx, {
      userId,
      eventKey: `retail-order:${order!.id}:created`,
      category: "commerce",
      title: "Porudžbina je primljena",
      body: `Porudžbina ${order!.orderNumber} je uspešno kreirana.`,
      deepLink: `/moj-nalog?tab=orders`,
      metadata: { retailOrderId: order!.id, orderNumber: order!.orderNumber, status: order!.status },
    });
    return { order: order!, repeat: false };
  }).catch((error: unknown) => {
    if (error instanceof Error && error.message === "retail_cart_empty") return "empty" as const;
    if (error instanceof Error && error.message === "retail_stock_conflict") { stockConflict = true; return null; }
    if (error instanceof Error && error.message === "retail_idempotency_collision") { idempotencyConflict = true; return null; }
    if (error instanceof Error && error.message === "retail_moq_conflict") return null;
    if (error instanceof Error && error.message === "retail_coupon_conflict") return null;
    if (error instanceof Error && error.message === "retail_aftercare_conflict") return null;
    throw error;
  });
  if (created === "empty") { res.status(400).json({ error: "Korpa je prazna." }); return; }
  if (couponFailure) { couponErrorResponse(res, couponFailure); return; }
  if (aftercareFailure) {
    res.status(409).json({ error: "Preporuka za negu nije dostupna.", code: "AFTERCARE_RECOMMENDATION_UNAVAILABLE" }); return;
  }
  if (idempotencyConflict) { res.status(409).json({ error: "Ovaj ključ potvrde je već iskorišćen za drugu korpu. Osvežite stranicu i pokušajte ponovo." }); return; }
  const checkoutMinimumOrderConflict = minimumOrderConflict as {
    name: string;
    minimumOrderQuantity: number;
  } | null;
  if (checkoutMinimumOrderConflict) {
    res.status(409).json({
      error: `Minimalna količina za proizvod "${checkoutMinimumOrderConflict.name}" je ${checkoutMinimumOrderConflict.minimumOrderQuantity}.`,
      code: "MINIMUM_ORDER_QUANTITY",
      minimumOrderQuantity: checkoutMinimumOrderConflict.minimumOrderQuantity,
    });
    return;
  }
  if (quoteConflict) {
    res.status(409).json({
      error: "Iznos porudžbine se promenio. Osvežite pregled i pokušajte ponovo.",
      code: rewardUnavailable ? "CHECKOUT_REWARD_UNAVAILABLE" : "CHECKOUT_QUOTE_CHANGED",
    });
    return;
  }
  if (stockConflict || !created || stockError) {
    res.status(409).json({
      error: `Dostupnost proizvoda${stockError ? ` "${stockError}"` : ""} se promenila. Osvežite korpu i pokušajte ponovo.`,
      code: "CHECKOUT_QUOTE_CHANGED",
      unavailableItems,
    });
    return;
  }
  const detail = await retailOrderWithItems(created.order);
  if (!created.repeat && trackingToken) {
    const origin = configuredAppOrigin();
    if (origin && (new URL(origin).protocol === "https:" || process.env.NODE_ENV !== "production")) {
      const trackingUrl = `${origin}/porudzbina/pracenje?token=${encodeURIComponent(trackingToken)}`;
      void sendTransactionalEmail({
        eventKey: `retail-order:${created.order.id}:confirmation`, emailType: "retail_order_confirmation",
        to: { email: created.order.shippingEmail, name: created.order.shippingName },
        subject: `LUMERA — porudžbina ${created.order.orderNumber} je primljena`,
        htmlContent: lumeraEmailHtml("Porudžbina je primljena", `<p>Hvala! Primili smo vašu porudžbinu <strong>${emailSafe(created.order.orderNumber)}</strong>.</p><p>Praćenje: <a href="${emailSafe(trackingUrl)}">otvorite status porudžbine</a>.</p>`),
        metadata: { retailOrderId: created.order.id },
      });
    }
    const phone = normalizedPhone(created.order.shippingPhone);
    if (phone) void sendSms({
      eventKey: `retail-order:${created.order.id}:confirmation`, salonId: null, appointmentId: null,
      type: "retail_order", phone, text: `LUMERA: porudžbina ${created.order.orderNumber} je primljena.`,
    });
  }
  res.status(created.repeat ? 200 : 201).json({ ...detail, trackingToken: created.repeat ? null : trackingToken, alreadySubmitted: created.repeat });
});

router.get("/retail/orders/track", async (req, res): Promise<void> => {
  const token = typeof req.query.token === "string" ? req.query.token : "";
  if (token.length < 32) { res.status(404).json({ error: "Porudžbina nije pronađena." }); return; }
  const [order] = await db.select().from(retailOrdersTable).where(and(
    eq(retailOrdersTable.trackingTokenHash, hashRetailToken(token)),
    isNull(retailOrdersTable.trackingTokenRevokedAt),
    gt(retailOrdersTable.trackingTokenExpiresAt, new Date()),
  )).limit(1);
  if (!order) { res.status(404).json({ error: "Porudžbina nije pronađena." }); return; }
  res.json(publicTrackingDto(order));
});

router.post("/retail/orders/track/lookup", async (req, res): Promise<void> => {
  const generic = { error: "Porudžbina nije pronađena." };
  if (await retailLookupRateLimited(req)) { res.status(429).json(generic); return; }
  const orderNumber = typeof req.body?.orderNumber === "string" ? req.body.orderNumber.trim() : "";
  const email = typeof req.body?.email === "string" ? req.body.email.trim().toLowerCase() : "";
  if (!orderNumber || orderNumber.length > 80 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    res.status(404).json(generic); return;
  }
  const token = randomBytes(32).toString("base64url");
  const now = new Date();
  const [order] = await db.update(retailOrdersTable).set({
    trackingTokenHash: hashRetailToken(token),
    trackingTokenExpiresAt: new Date(now.getTime() + 180 * 24 * 60 * 60 * 1000),
    trackingTokenRotatedAt: now,
    trackingTokenRevokedAt: null,
  }).where(and(
    eq(retailOrdersTable.orderNumber, orderNumber),
    sql`lower(btrim(${retailOrdersTable.shippingEmail})) = ${email}`,
  )).returning();
  if (!order) { res.status(404).json(generic); return; }
  const origin = configuredAppOrigin();
  if (origin && (new URL(origin).protocol === "https:" || process.env.NODE_ENV !== "production")) {
    const trackingUrl = `${origin}/porudzbina/pracenje?token=${encodeURIComponent(token)}`;
    void sendTransactionalEmail({
      eventKey: `retail-order:${order.id}:tracking-rotation:${now.toISOString()}`,
      emailType: "retail_order_tracking",
      to: { email: order.shippingEmail, name: order.shippingName },
      subject: `LUMERA — praćenje porudžbine ${order.orderNumber}`,
      htmlContent: lumeraEmailHtml("Praćenje porudžbine", `<p><a href="${emailSafe(trackingUrl)}">Otvorite status porudžbine</a>.</p>`),
      metadata: { retailOrderId: order.id },
    });
  }
  res.json(publicTrackingDto(order));
});

