async function restockRetailBundleComponentsForCancelledOrderInTx(tx: BundleTransaction, orderId: string) {
  const items = await tx.select({
    productId: retailOrderItemsTable.productId,
    bundleId: retailOrderItemsTable.bundleId,
    quantity: retailOrderItemsTable.quantity,
    components: retailOrderItemsTable.bundleComponentsSnapshot,
  }).from(retailOrderItemsTable).where(eq(retailOrderItemsTable.orderId, orderId));
  const quantities = new Map<string, number>();
  for (const item of items) {
    if (item.bundleId && item.components) for (const component of item.components) {
      quantities.set(component.productId, (quantities.get(component.productId) ?? 0) + component.quantity * item.quantity);
    } else if (item.productId) {
      quantities.set(item.productId, (quantities.get(item.productId) ?? 0) + item.quantity);
    }
  }
  for (const productId of [...quantities.keys()].sort()) await tx.execute(sql`select id from products where id = ${productId} for update`);
  for (const [productId, quantity] of quantities) {
    await tx.update(productsTable).set({ stock: sql`${productsTable.stock} + ${quantity}` }).where(eq(productsTable.id, productId));
  }
}

async function releaseCouponRedemptionInTx(
  tx: BundleTransaction,
  target: { orderId?: string; retailOrderId?: string },
) {
  const condition = target.orderId
    ? eq(couponRedemptionsTable.orderId, target.orderId)
    : eq(couponRedemptionsTable.retailOrderId, target.retailOrderId!);
  const [redemption] = await tx.select().from(couponRedemptionsTable)
    .where(and(condition, isNull(couponRedemptionsTable.cancelledAt))).limit(1).for("update");
  if (!redemption) return;
  const [released] = await tx.update(couponRedemptionsTable).set({ cancelledAt: new Date() })
    .where(and(eq(couponRedemptionsTable.id, redemption.id), isNull(couponRedemptionsTable.cancelledAt)))
    .returning({ id: couponRedemptionsTable.id });
  if (released) {
    await tx.update(couponsTable).set({
      usageCount: sql`greatest(0, ${couponsTable.usageCount} - 1)`,
      updatedAt: new Date(),
    }).where(eq(couponsTable.id, redemption.couponId));
  }
}

router.patch("/admin/retail-orders/:orderId/status", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const legacyFulfillment = {
    pending: "RECEIVED", confirmed: "PREPARING", paid: "PREPARING", processing: "PACKING",
    shipped: "SHIPPED", delivered: "COMPLETED", cancelled: "CANCELLED",
  } as const;
  const next = req.body?.fulfillmentStatus
    ?? (typeof req.body?.status === "string" ? legacyFulfillment[req.body.status as keyof typeof legacyFulfillment] : undefined);
  const trackingNumber = req.body?.trackingNumber === null ? null
    : typeof req.body?.trackingNumber === "string" ? req.body.trackingNumber.trim() || null : undefined;
  const trackingUrl = req.body?.trackingUrl === null ? null
    : typeof req.body?.trackingUrl === "string" ? req.body.trackingUrl.trim() || null : undefined;
  if (typeof next !== "string" || !Object.hasOwn(fulfillmentTransitions, next)
    || (trackingUrl !== undefined && !validProviderUrl(trackingUrl))) {
    res.status(400).json({ error: "Neispravan status ili URL za praćenje." }); return;
  }
  let transitionError = false;
  const order = await db.transaction(async (tx) => {
    const [locked] = await tx.select().from(retailOrdersTable).where(eq(retailOrdersTable.id, req.params.orderId)).for("update");
    if (!locked) return null;
    if (next !== locked.fulfillmentStatus && !fulfillmentTransitions[locked.fulfillmentStatus]?.includes(next)) {
      transitionError = true; return null;
    }
    const effectiveTrackingNumber = trackingNumber === undefined ? locked.trackingNumber : trackingNumber;
    if (next === "SHIPPED" && !effectiveTrackingNumber) { transitionError = true; return null; }
    const now = new Date();
    const cancellationTransition = next === "CANCELLED" && locked.fulfillmentStatus !== "CANCELLED";
    if (cancellationTransition && locked.referralCreditAppliedRsd > 0 && !locked.referralCreditRestoredAt && locked.userId) {
      await restoreReferralCreditForOrderInTx(tx, {
        scope: { ownerUserId: locked.userId, walletKind: "B2C" }, retailOrderId: locked.id,
        eventKey: `retail-cancel:${locked.id}`, actorUserId: user.id, now,
      });
    }
    if (cancellationTransition) {
      await restockRetailBundleComponentsForCancelledOrderInTx(tx, locked.id);
      await releaseCouponRedemptionInTx(tx, { retailOrderId: locked.id });
    }
    const reversedPoints = cancellationTransition && !locked.loyaltyPointsReversedAt && locked.userId
      ? await reverseLoyaltyPointsInTx(tx, { audience: "B2C", userId: locked.userId, retailOrderId: locked.id, points: locked.loyaltyPointsAwarded })
      : false;
    const [saved] = await tx.update(retailOrdersTable).set({
      fulfillmentStatus: next as typeof retailOrdersTable.$inferInsert.fulfillmentStatus,
      status: legacyStatusForFulfillment(next), updatedAt: now,
      ...(trackingNumber !== undefined ? { trackingNumber } : {}),
      ...(trackingUrl !== undefined ? { trackingUrl } : {}),
      ...(cancellationTransition && locked.referralCreditAppliedRsd > 0 && !locked.referralCreditRestoredAt ? { referralCreditRestoredAt: now } : {}),
      ...(reversedPoints ? { loyaltyPointsReversedAt: now } : {}),
    }).where(eq(retailOrdersTable.id, locked.id)).returning();
    if (locked.fulfillmentStatus !== next) {
      const copy = next === "SHIPPED"
        ? ["Porudžbina je poslata", `Porudžbina ${locked.orderNumber} je predata dostavi.`]
        : next === "COMPLETED"
          ? ["Porudžbina je isporučena", `Porudžbina ${locked.orderNumber} je isporučena.`]
          : next === "CANCELLED"
            ? ["Porudžbina je otkazana", `Porudžbina ${locked.orderNumber} je otkazana.`]
            : ["Status porudžbine je promenjen", `Porudžbina ${locked.orderNumber} sada ima status ${next}.`];
      await notifyCustomer(tx, {
        userId: locked.userId,
        eventKey: `retail-order:${locked.id}:fulfillment:${next}`,
        category: "commerce",
        title: copy[0]!,
        body: copy[1]!,
        deepLink: "/moj-nalog?tab=orders",
        metadata: { retailOrderId: locked.id, fulfillmentStatus: next, trackingUrl: trackingUrl ?? locked.trackingUrl },
      });
    }
    for (const [field, previousValue, nextValue] of [
      ["fulfillmentStatus", locked.fulfillmentStatus, next],
      ["trackingNumber", locked.trackingNumber, trackingNumber],
      ["trackingUrl", locked.trackingUrl, trackingUrl],
    ] as const) if (nextValue !== undefined && previousValue !== nextValue) {
      await tx.insert(retailOrderStatusHistoryTable).values({
        retailOrderId: locked.id, actorUserId: user.id,
        actorName: `${user.firstName} ${user.lastName}`.trim() || "Administrator",
        field, previousValue, nextValue,
      });
    }
    return saved!;
  });
  if (transitionError) { res.status(409).json({ error: next === "SHIPPED" ? "Broj za praćenje je obavezan, a promena mora pratiti tok isporuke." : "Promena statusa nije dozvoljena." }); return; }
  if (!order) { res.status(404).json({ error: "Retail porudžbina nije pronađena." }); return; }
  res.json(await adminRetailOrderDetail(order));
});

router.patch("/admin/retail-orders/:orderId/payment-status", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const next = req.body?.paymentStatus;
  if (typeof next !== "string" || !["unpaid", "pending", "paid", "refunded", "failed"].includes(next)) {
    res.status(400).json({ error: "Neispravan status plaćanja." }); return;
  }
  const order = await db.transaction(async (tx) => {
    const [locked] = await tx.select().from(retailOrdersTable).where(eq(retailOrdersTable.id, req.params.orderId)).for("update");
    if (!locked) return null;
    const now = new Date();
    if (next === "refunded" && locked.referralCreditAppliedRsd > 0 && !locked.referralCreditRestoredAt && locked.userId) {
      await restoreReferralCreditForOrderInTx(tx, {
        scope: { ownerUserId: locked.userId, walletKind: "B2C" }, retailOrderId: locked.id,
        eventKey: `retail-refund:${locked.id}`, actorUserId: user.id, now,
      });
    }
    const [saved] = await tx.update(retailOrdersTable).set({
      paymentStatus: next as typeof retailOrdersTable.$inferInsert.paymentStatus, updatedAt: now,
      ...(next === "refunded" && locked.referralCreditAppliedRsd > 0 && !locked.referralCreditRestoredAt ? { referralCreditRestoredAt: now } : {}),
    }).where(eq(retailOrdersTable.id, locked.id)).returning();
    if (next !== locked.paymentStatus) await tx.insert(retailOrderStatusHistoryTable).values({
      retailOrderId: locked.id, actorUserId: user.id,
      actorName: `${user.firstName} ${user.lastName}`.trim() || "Administrator",
      field: "paymentStatus", previousValue: locked.paymentStatus, nextValue: next,
    });
    return saved!;
  });
  if (!order) { res.status(404).json({ error: "Retail porudžbina nije pronađena." }); return; }
  res.json(await adminRetailOrderDetail(order));
});

router.get("/retail/products/:productId/reviews", async (req, res): Promise<void> => {
  const [candidate] = await db.select({ supplierId: productsTable.supplierId })
    .from(productsTable)
    .innerJoin(suppliersTable, and(
      eq(productsTable.supplierId, suppliersTable.id),
      eq(suppliersTable.active, true),
      inArray(suppliersTable.scope, ["B2C", "BOTH"]),
    ))
    .where(eq(productsTable.id, req.params.productId))
    .limit(1);
  if (!candidate) { res.status(404).json({ error: "Proizvod nije pronađen." }); return; }
  const [publicProduct] = await db.select({ id: productsTable.id }).from(productsTable)
    .where(and(eq(productsTable.id, req.params.productId), canonicalPublicProductCondition(candidate.supplierId)))
    .limit(1);
  if (!publicProduct) { res.status(404).json({ error: "Proizvod nije pronađen." }); return; }
  const rows = await db.select({
    review: retailProductReviewsTable, firstName: usersTable.firstName, lastName: usersTable.lastName,
  }).from(retailProductReviewsTable).innerJoin(usersTable, eq(retailProductReviewsTable.userId, usersTable.id))
    .where(and(eq(retailProductReviewsTable.productId, req.params.productId), eq(retailProductReviewsTable.moderationStatus, "PUBLISHED")))
    .orderBy(desc(retailProductReviewsTable.updatedAt), desc(retailProductReviewsTable.id));
  // Deliberately only return the platform's privacy-safe display form, never
  // account identity, email, order or delivery data.
  res.json(rows.map(({ review, firstName, lastName }) => ({
    id: review.id, rating: review.rating, comment: review.comment, verifiedPurchase: true,
    reviewerName: `${firstName} ${lastName.slice(0, 1)}.`.trim(),
    createdAt: safeIsoTimestamp(review.createdAt), updatedAt: safeIsoTimestamp(review.updatedAt),
  })));
});

const retailReviewStatuses = ["PUBLISHED", "REPORTED", "AUTO_FLAGGED", "REMOVED"] as const;
const retailReportReasons = ["SPAM", "ABUSE", "HATE", "PERSONAL_INFORMATION", "MISLEADING", "OTHER"] as const;
const RETAIL_REVIEW_AUTO_FLAG_REPORT_COUNT = 3;

function retailReviewInput(body: unknown) {
  const value = body as { rating?: unknown; comment?: unknown; photoUrls?: unknown };
  if (!Number.isInteger(value?.rating) || Number(value.rating) < 1 || Number(value.rating) > 5) throw new Error("Ocena mora biti između 1 i 5.");
  if (typeof value.comment !== "string" || !value.comment.trim() || value.comment.trim().length > 2_000) throw new Error("Tekst recenzije je obavezan i može imati najviše 2000 karaktera.");
  // Explicit deterministic safety rule: contact details or an URL are held for
  // moderation rather than automatically made public.
  const comment = value.comment.trim();
  const autoFlagged = /(?:https?:\/\/|www\.|[\w.+-]+@[\w.-]+\.[a-z]{2,}|\+?\d[\d\s().-]{7,}\d)/i.test(comment);
  if (value.photoUrls !== undefined && (!Array.isArray(value.photoUrls) || value.photoUrls.length > 6 || value.photoUrls.some((url) => typeof url !== "string" || !mediaAssetIdFromUrl(url)))) throw new Error("Fotografije recenzije moraju biti najviše šest upravljanih slika.");
  return { rating: Number(value.rating), comment, autoFlagged, photoUrls: value.photoUrls === undefined ? undefined : value.photoUrls as string[] };
}

async function retailReviewAccess(req: Request, res: Response) {
  const user = await getCurrentUser(req);
  if (!user) { res.status(401).json({ error: "Prijava je obavezna." }); return null; }
  if (!user.active || !["CUSTOMER", "JOBSEEKER"].includes(user.role)) { res.status(403).json({ error: "Aktivan CUSTOMER ili JOBSEEKER nalog je obavezan." }); return null; }
  return user;
}

async function verifiedRetailItem(userId: string, productId: string) {
  const delivered = await db.select({ item: retailOrderItemsTable }).from(retailOrderItemsTable)
    .innerJoin(retailOrdersTable, eq(retailOrderItemsTable.orderId, retailOrdersTable.id))
    .where(and(eq(retailOrderItemsTable.productId, productId), eq(retailOrdersTable.userId, userId), eq(retailOrdersTable.status, "delivered")))
    .orderBy(desc(retailOrdersTable.updatedAt), desc(retailOrderItemsTable.id)).limit(1);
  return delivered[0]?.item ?? null;
}

async function refreshRetailProductReviewAggregate(tx: any, productId: string) {
  // Caller owns the product row lock, so the review-state transition and its
  // externally visible aggregate commit together.
  const [aggregate] = await tx.select({
    count: count(), average: sql<number>`coalesce(round(avg(${retailProductReviewsTable.rating})::numeric), 0)`,
  }).from(retailProductReviewsTable).where(and(
    eq(retailProductReviewsTable.productId, productId),
    eq(retailProductReviewsTable.moderationStatus, "PUBLISHED"),
  ));
  await tx.update(productsTable).set({
    averageRating: Number(aggregate?.average ?? 0), reviewCount: Number(aggregate?.count ?? 0),
  }).where(eq(productsTable.id, productId));
}

async function lockRetailReviewProduct(tx: any, productId: string) {
  const [product] = await tx.select({ id: productsTable.id }).from(productsTable)
    .where(eq(productsTable.id, productId)).for("update");
  return product;
}

router.get("/customer/retail-products/:productId/review-context", async (req, res): Promise<void> => {
  const user = await retailReviewAccess(req, res); if (!user) return;
  const item = await verifiedRetailItem(user.id, req.params.productId);
  const [review] = await db.select().from(retailProductReviewsTable).where(and(
    eq(retailProductReviewsTable.productId, req.params.productId), eq(retailProductReviewsTable.userId, user.id),
  )).limit(1);
  res.json({ eligible: Boolean(item), verifiedPurchase: Boolean(item), review: review ? {
    id: review.id, rating: review.rating, comment: review.comment, moderationStatus: review.moderationStatus,
  } : null });
});

router.post("/customer/retail-products/:productId/reviews", async (req, res): Promise<void> => {
  const user = await retailReviewAccess(req, res); if (!user) return;
  let input: ReturnType<typeof retailReviewInput>;
  try { input = retailReviewInput(req.body); } catch (error) { res.status(400).json({ error: (error as Error).message }); return; }
  const item = await verifiedRetailItem(user.id, req.params.productId);
  if (!item) { res.status(403).json({ error: "Recenziju može ostaviti samo korisnik sa dostavljenom porudžbinom tog proizvoda." }); return; }
  try {
    const saved = await db.transaction(async (tx) => {
      if (!await lockRetailReviewProduct(tx, req.params.productId)) throw new Error("PRODUCT_NOT_FOUND");
      const [active] = await tx.select().from(retailProductReviewsTable).where(and(
        eq(retailProductReviewsTable.productId, req.params.productId), eq(retailProductReviewsTable.userId, user.id),
        sql`${retailProductReviewsTable.moderationStatus} <> 'REMOVED'`,
      )).for("update");
      if (active) throw new Error("DUPLICATE_REVIEW");
      // Reuse a prior self-removed row when it has the same immutable order
      // item. This also remains compatible with the legacy item/user unique
      // index retained during the additive rollout.
      const [removed] = await tx.select().from(retailProductReviewsTable).where(and(
        eq(retailProductReviewsTable.productId, req.params.productId), eq(retailProductReviewsTable.userId, user.id),
        eq(retailProductReviewsTable.moderationStatus, "REMOVED"),
      )).for("update");
      const values = {
        orderItemId: item.id, rating: input.rating, comment: input.comment,
        moderationStatus: input.autoFlagged ? "AUTO_FLAGGED" as const : "PUBLISHED" as const,
        moderationReason: input.autoFlagged ? "Deterministic contact-or-link safety rule." : null,
        removedAt: null, updatedAt: new Date(),
      };
      const [created] = removed
        ? await tx.update(retailProductReviewsTable).set(values).where(eq(retailProductReviewsTable.id, removed.id)).returning()
        : await tx.insert(retailProductReviewsTable).values({ productId: req.params.productId, userId: user.id, ...values }).returning();
      for (const url of input.photoUrls ?? []) {
        if (!await claimMediaReference({ userId: user.id, url, scope: "retail-review-photo", resourceId: created!.id, visibility: "private" }, tx)) throw new Error("REVIEW_MEDIA_CLAIM");
        await tx.insert(retailProductReviewAttachmentsTable).values({ reviewId: created!.id, mediaAssetId: mediaAssetIdFromUrl(url)! });
      }
      await refreshRetailProductReviewAggregate(tx, req.params.productId);
      // Product remains the first lock, preserving the established
      // product->review order. The delivered order is the cross-product
      // concurrency fence for the one reward allowed per order.
      await tx.select({ id: retailOrdersTable.id }).from(retailOrdersTable)
        .where(eq(retailOrdersTable.id, item.orderId)).for("update");
      const [settings] = await tx.select().from(shopSettingsTable).limit(1);
      let reward: { issued: boolean; percent?: number; expiresAt?: Date } = { issued: false };
      if (settings?.reviewRewardsEnabled) {
        const [existingReward] = await tx.select({ id: reviewRewardIssuancesTable.id }).from(reviewRewardIssuancesTable)
          .where(eq(reviewRewardIssuancesTable.orderId, item.orderId)).limit(1);
        if (!existingReward) {
          const expiresAt = new Date(Date.now() + settings.reviewRewardValidityDays * 86_400_000);
          const [coupon] = await tx.insert(couponsTable).values({
            code: `REC-${randomBytes(12).toString("base64url").toUpperCase()}`,
            audience: "B2C", discountType: "PERCENTAGE", discountValue: settings.reviewRewardPercent,
            startsAt: new Date(), endsAt: expiresAt, usageLimit: 1, perCustomerUsageLimit: 1,
          }).returning();
          await tx.insert(reviewRewardIssuancesTable).values({
            orderId: item.orderId, reviewId: created!.id, couponId: coupon!.id,
            percentSnapshot: settings.reviewRewardPercent, expiresAt,
          });
          await tx.insert(emailDeliveriesTable).values({
            eventKey: `retail-review-reward:${item.orderId}`,
            emailType: "retail_review_reward",
            recipientEmail: user.email,
            recipientName: user.firstName,
            subject: "LUMERA — vaš kupon za recenziju",
            htmlContent: lumeraEmailHtml(
              "Hvala na recenziji",
              `<p>Vaš jednokratni kupon za ${settings.reviewRewardPercent}% popusta je <strong>${emailSafe(coupon!.code)}</strong>.</p><p>Kupon važi do ${expiresAt.toLocaleDateString("sr-RS")} i vezan je za vaš nalog.</p>`,
            ),
            status: "queued",
            scheduledAt: new Date(),
            metadata: { retailOrderId: item.orderId, reviewId: created!.id, couponId: coupon!.id },
          }).onConflictDoNothing();
          reward = { issued: true, percent: settings.reviewRewardPercent, expiresAt };
        }
      }
      return { created: created!, reward };
    });
    res.status(201).json({ id: saved.created.id, rating: saved.created.rating, comment: saved.created.comment, verifiedPurchase: true, moderationStatus: saved.created.moderationStatus, reward: saved.reward });
  } catch (error) {
    res.status((error as Error).message === "DUPLICATE_REVIEW" || (error as Error).message === "REVIEW_MEDIA_CLAIM" ? 409 : 400).json({ error: (error as Error).message === "DUPLICATE_REVIEW" ? "Već imate aktivnu recenziju za ovaj proizvod." : "Recenzija nije sačuvana." });
  }
});

router.patch("/customer/retail-products/:productId/reviews/:reviewId", async (req, res): Promise<void> => {
  const user = await retailReviewAccess(req, res); if (!user) return;
  let input: ReturnType<typeof retailReviewInput>;
  try { input = retailReviewInput(req.body); } catch (error) { res.status(400).json({ error: (error as Error).message }); return; }
  const item = await verifiedRetailItem(user.id, req.params.productId);
  if (!item) { res.status(403).json({ error: "Nije potvrđena kupovina tog proizvoda." }); return; }
  const saved = await db.transaction(async (tx) => {
    if (!await lockRetailReviewProduct(tx, req.params.productId)) return null;
    const [review] = await tx.select().from(retailProductReviewsTable).where(and(
      eq(retailProductReviewsTable.id, req.params.reviewId), eq(retailProductReviewsTable.productId, req.params.productId),
      eq(retailProductReviewsTable.userId, user.id),
    )).for("update");
    if (!review || review.moderationStatus === "REMOVED") return null;
    const nextStatus = input.autoFlagged ? "AUTO_FLAGGED" : review.moderationStatus === "PUBLISHED" ? "PUBLISHED" : "REPORTED";
    const [updated] = await tx.update(retailProductReviewsTable).set({
      rating: input.rating, comment: input.comment, orderItemId: item.id, moderationStatus: nextStatus,
      moderationReason: input.autoFlagged ? "Deterministic contact-or-link safety rule." : review.moderationReason,
      updatedAt: new Date(),
    }).where(eq(retailProductReviewsTable.id, review.id)).returning();
    if (input.photoUrls !== undefined) {
      const previous = await tx.select({ mediaAssetId: retailProductReviewAttachmentsTable.mediaAssetId })
        .from(retailProductReviewAttachmentsTable).where(eq(retailProductReviewAttachmentsTable.reviewId, review.id));
      await tx.delete(retailProductReviewAttachmentsTable).where(eq(retailProductReviewAttachmentsTable.reviewId, review.id));
      await releaseMediaReferenceClaims({ urls: previous.map((attachment) => `/api/media/${attachment.mediaAssetId}`), resourceId: review.id, visibility: "private" }, tx);
      for (const url of input.photoUrls) {
        if (!await claimMediaReference({ userId: user.id, url, scope: "retail-review-photo", resourceId: review.id, visibility: "private" }, tx)) throw new Error("REVIEW_MEDIA_CLAIM");
        await tx.insert(retailProductReviewAttachmentsTable).values({ reviewId: review.id, mediaAssetId: mediaAssetIdFromUrl(url)! });
      }
    }
    await refreshRetailProductReviewAggregate(tx, req.params.productId);
    return updated!;
  });
  if (!saved) { res.status(404).json({ error: "Recenzija nije pronađena." }); return; }
  res.json({ id: saved.id, rating: saved.rating, comment: saved.comment, verifiedPurchase: true, moderationStatus: saved.moderationStatus });
});

router.delete("/customer/retail-products/:productId/reviews/:reviewId", async (req, res): Promise<void> => {
  const user = await retailReviewAccess(req, res); if (!user) return;
  const deleted = await db.transaction(async (tx) => {
    if (!await lockRetailReviewProduct(tx, req.params.productId)) return false;
    const [review] = await tx.select().from(retailProductReviewsTable).where(and(
      eq(retailProductReviewsTable.id, req.params.reviewId), eq(retailProductReviewsTable.productId, req.params.productId),
      eq(retailProductReviewsTable.userId, user.id),
    )).for("update");
    if (!review || review.moderationStatus === "REMOVED") return false;
    await tx.update(retailProductReviewsTable).set({ moderationStatus: "REMOVED", removedAt: new Date(), updatedAt: new Date() })
      .where(eq(retailProductReviewsTable.id, review.id));
    await refreshRetailProductReviewAggregate(tx, req.params.productId);
    return true;
  });
  if (!deleted) { res.status(404).json({ error: "Recenzija nije pronađena." }); return; }
  res.status(204).end();
});

router.post("/retail-product-reviews/:reviewId/reports", async (req, res): Promise<void> => {
  const user = await getCurrentUser(req);
  if (!user || !user.active) { res.status(401).json({ error: "Prijava je obavezna." }); return; }
  const reason = String(req.body?.reason ?? "");
  const explanation = req.body?.explanation == null ? null : String(req.body.explanation).trim();
  if (!retailReportReasons.includes(reason as typeof retailReportReasons[number]) || (explanation?.length ?? 0) > 2_000) {
    res.status(400).json({ error: "Neispravan razlog prijave." }); return;
  }
  const [candidate] = await db.select({ productId: retailProductReviewsTable.productId })
    .from(retailProductReviewsTable).where(eq(retailProductReviewsTable.id, req.params.reviewId)).limit(1);
  if (!candidate) { res.status(404).json({ error: "Recenzija nije pronađena ili je uklonjena." }); return; }
  const result = await db.transaction(async (tx) => {
    // Lock order is always product -> review (the same order as create/edit/
    // delete/moderation) so concurrent reports cannot deadlock a review write.
    if (!await lockRetailReviewProduct(tx, candidate.productId)) return null;
    const [review] = await tx.select().from(retailProductReviewsTable).where(and(
      eq(retailProductReviewsTable.id, req.params.reviewId),
      eq(retailProductReviewsTable.productId, candidate.productId),
    )).for("update");
    if (!review || review.moderationStatus === "REMOVED") return null;
    const [report] = await tx.insert(retailProductReviewReportsTable).values({
      reviewId: review.id, reporterUserId: user.id, reason: reason as "SPAM", explanation,
    }).onConflictDoUpdate({
      target: [retailProductReviewReportsTable.reviewId, retailProductReviewReportsTable.reporterUserId],
      set: { reason: reason as "SPAM", explanation, updatedAt: new Date() },
    }).returning();
    const [reportCount] = await tx.select({ value: count() }).from(retailProductReviewReportsTable)
      .where(eq(retailProductReviewReportsTable.reviewId, review.id));
    const next = Number(reportCount?.value ?? 0) >= RETAIL_REVIEW_AUTO_FLAG_REPORT_COUNT ? "AUTO_FLAGGED" : "REPORTED";
    if (review.moderationStatus === "PUBLISHED" || review.moderationStatus === "REPORTED") {
      await tx.update(retailProductReviewsTable).set({ moderationStatus: next, updatedAt: new Date() }).where(eq(retailProductReviewsTable.id, review.id));
      await refreshRetailProductReviewAggregate(tx, review.productId);
    }
    return { report, moderationStatus: next, reportCount: Number(reportCount?.value ?? 0) };
  });
  if (!result) { res.status(404).json({ error: "Recenzija nije pronađena ili je uklonjena." }); return; }
  res.status(201).json({ id: result.report!.id, reportCount: result.reportCount, moderationStatus: result.moderationStatus });
});

router.get("/admin/retail-product-reviews", async (req, res): Promise<void> => {
  if (!await requireAdmin(req, res)) return;
  const status = String(req.query.status ?? "ALL");
  if (status !== "ALL" && !retailReviewStatuses.includes(status as typeof retailReviewStatuses[number])) { res.status(400).json({ error: "Neispravan status." }); return; }
  const page = Math.max(1, Number(req.query.page) || 1); const pageSize = Math.min(100, Math.max(1, Number(req.query.pageSize) || 25));
  const conditions = [
    status === "ALL" ? undefined : eq(retailProductReviewsTable.moderationStatus, status as "PUBLISHED"),
    typeof req.query.productId === "string" ? eq(retailProductReviewsTable.productId, req.query.productId) : undefined,
    typeof req.query.supplierId === "string" ? eq(productsTable.supplierId, req.query.supplierId) : undefined,
    req.query.from ? gte(retailProductReviewsTable.createdAt, new Date(String(req.query.from))) : undefined,
    req.query.to ? lte(retailProductReviewsTable.createdAt, new Date(String(req.query.to))) : undefined,
  ].filter(Boolean);
  const where = and(...conditions as [SQL, ...SQL[]]);
  const rows = await db.select({
    review: retailProductReviewsTable, productName: productsTable.name, supplierId: productsTable.supplierId,
    reportCount: sql<number>`count(${retailProductReviewReportsTable.id})`,
  }).from(retailProductReviewsTable).innerJoin(productsTable, eq(retailProductReviewsTable.productId, productsTable.id))
    .leftJoin(retailProductReviewReportsTable, eq(retailProductReviewReportsTable.reviewId, retailProductReviewsTable.id))
    .where(where).groupBy(retailProductReviewsTable.id, productsTable.id)
    .orderBy(desc(retailProductReviewsTable.updatedAt), desc(retailProductReviewsTable.id)).limit(pageSize).offset((page - 1) * pageSize);
  const [total] = await db.select({ value: count() }).from(retailProductReviewsTable).innerJoin(productsTable, eq(retailProductReviewsTable.productId, productsTable.id)).where(where);
  res.json({
    items: rows.map(({ review, productName, supplierId, reportCount }) => ({
      id: review.id,
      productId: review.productId,
      productName,
      supplierId,
      rating: review.rating,
      comment: review.comment,
      moderationStatus: review.moderationStatus,
      moderationReason: review.moderationReason,
      removedAt: review.removedAt,
      createdAt: review.createdAt,
      updatedAt: review.updatedAt,
      verifiedPurchase: true,
      reportCount: Number(reportCount),
    })),
    page,
    pageSize,
    total: Number(total?.value ?? 0),
  });
});

router.get("/admin/retail-product-reviews/:reviewId", async (req, res): Promise<void> => {
  if (!await requireAdmin(req, res)) return;
  const [row] = await db.select({ review: retailProductReviewsTable, productName: productsTable.name, supplierId: productsTable.supplierId })
    .from(retailProductReviewsTable).innerJoin(productsTable, eq(retailProductReviewsTable.productId, productsTable.id))
    .where(eq(retailProductReviewsTable.id, req.params.reviewId)).limit(1);
  if (!row) { res.status(404).json({ error: "Recenzija nije pronađena." }); return; }
  const [reports, audits, rewardRows] = await Promise.all([
    db.select({ reason: retailProductReviewReportsTable.reason, explanation: retailProductReviewReportsTable.explanation, createdAt: retailProductReviewReportsTable.createdAt })
      .from(retailProductReviewReportsTable).where(eq(retailProductReviewReportsTable.reviewId, row.review.id)).orderBy(desc(retailProductReviewReportsTable.createdAt)),
    db.select().from(retailProductReviewModerationAuditsTable).where(eq(retailProductReviewModerationAuditsTable.reviewId, row.review.id))
      .orderBy(desc(retailProductReviewModerationAuditsTable.createdAt)),
    db.select({ issuance: reviewRewardIssuancesTable, coupon: couponsTable, redeemedAt: couponRedemptionsTable.createdAt })
      .from(reviewRewardIssuancesTable).innerJoin(couponsTable, eq(reviewRewardIssuancesTable.couponId, couponsTable.id))
      .leftJoin(couponRedemptionsTable, and(eq(couponRedemptionsTable.couponId, couponsTable.id), sql`${couponRedemptionsTable.cancelledAt} IS NULL`))
      .where(eq(reviewRewardIssuancesTable.reviewId, row.review.id)).limit(1),
  ]);
  const reward = rewardRows[0];
  // Admin has no need for purchaser PII either; reports are presented as
  // reason records, not as a reporter directory.
  res.json({
    id: row.review.id,
    productId: row.review.productId,
    productName: row.productName,
    supplierId: row.supplierId,
    rating: row.review.rating,
    comment: row.review.comment,
    moderationStatus: row.review.moderationStatus,
    moderationReason: row.review.moderationReason,
    removedAt: row.review.removedAt,
    createdAt: row.review.createdAt,
    updatedAt: row.review.updatedAt,
    verifiedPurchase: true,
    reportCount: reports.length,
    reports,
    audits,
    reward: reward ? {
      issued: true,
      // Admins only need correlation, never the redeemable raw code.
      maskedCode: `${reward.coupon.code.slice(0, 4)}…${reward.coupon.code.slice(-4)}`,
      issuedAt: reward.issuance.createdAt,
      expiresAt: reward.issuance.expiresAt,
      redeemed: Boolean(reward.redeemedAt),
      redeemedAt: reward.redeemedAt ?? null,
    } : { issued: false, maskedCode: null, issuedAt: null, expiresAt: null, redeemed: false, redeemedAt: null },
  });
});

router.post("/admin/retail-product-reviews/:reviewId/moderation", async (req, res): Promise<void> => {
  const moderator = await requireAdmin(req, res); if (!moderator) return;
  const action = String(req.body?.action ?? "");
  const reason = req.body?.reason == null ? null : String(req.body.reason).trim().slice(0, 2_000);
  const internalNote = req.body?.internalNote == null ? null : String(req.body.internalNote).trim().slice(0, 4_000);
  if (!["KEEP", "DISMISS_REPORTS", "REMOVE", "RESTORE"].includes(action)) { res.status(400).json({ error: "Neispravna moderatorska akcija." }); return; }
  const [candidate] = await db.select({ productId: retailProductReviewsTable.productId })
    .from(retailProductReviewsTable).where(eq(retailProductReviewsTable.id, req.params.reviewId)).limit(1);
  if (!candidate) { res.status(404).json({ error: "Recenzija nije pronađena." }); return; }
  const updated = await db.transaction(async (tx) => {
    if (!await lockRetailReviewProduct(tx, candidate.productId)) return null;
    const [review] = await tx.select().from(retailProductReviewsTable).where(and(
      eq(retailProductReviewsTable.id, req.params.reviewId),
      eq(retailProductReviewsTable.productId, candidate.productId),
    )).for("update");
    if (!review) return null;
    const nextStatus = action === "REMOVE" ? "REMOVED" : "PUBLISHED";
    // Identical retries are idempotent: retain state but record no duplicate
    // action/audit row. Dismiss reports intentionally clears their queue.
    const stateAlreadyApplied = review.moderationStatus === nextStatus
      && !(action === "DISMISS_REPORTS" && review.moderationStatus !== "REMOVED");
    if (!stateAlreadyApplied) {
      await tx.update(retailProductReviewsTable).set({
        moderationStatus: nextStatus,
        removedAt: nextStatus === "REMOVED" ? new Date() : null,
        moderationReason: reason,
        updatedAt: new Date(),
      }).where(eq(retailProductReviewsTable.id, review.id));
      await tx.insert(retailProductReviewModerationAuditsTable).values({
        reviewId: review.id, moderatorUserId: moderator.id, action: action as "KEEP",
        previousStatus: review.moderationStatus, nextStatus, reason, internalNote,
      });
    }
    if (action === "DISMISS_REPORTS") await tx.delete(retailProductReviewReportsTable).where(eq(retailProductReviewReportsTable.reviewId, review.id));
    await refreshRetailProductReviewAggregate(tx, review.productId);
    const [saved] = await tx.select().from(retailProductReviewsTable).where(eq(retailProductReviewsTable.id, review.id));
    return saved!;
  });
  if (!updated) { res.status(404).json({ error: "Recenzija nije pronađena." }); return; }
  res.json({ id: updated.id, moderationStatus: updated.moderationStatus, verifiedPurchase: true });
});

router.get("/shop/products", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const normalized = normalizeBooleanQuery(req.query, ["onSale", "isNew", "isBestseller"]);
  if (!normalized) { res.status(400).json({ error: "Invalid boolean filter" }); return; }
  const parsed = ListProductsQueryParams.safeParse(normalized);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const q = parsed.data;
  const productFilters: Parameters<typeof and>[0][] = [
    eq(productsTable.active, true),
    eq(productsTable.professionalEnabled, true),
  ];
  if (q.category) productFilters.push(eq(productsTable.categoryName, q.category));
  if (q.subcategory) productFilters.push(eq(productsTable.subcategoryName, q.subcategory));
  if (q.brand) productFilters.push(sql`lower(${productsTable.brand}) = ${q.brand.toLowerCase()}`);
  if (q.onSale) productFilters.push(activeProductSaleConditionSql("B2B"));
  if (q.isNew) productFilters.push(eq(productsTable.isNew, true));
  if (q.isBestseller) productFilters.push(eq(productsTable.isBestseller, true));
  if (q.search) productFilters.push(sql`(
    lower(${productsTable.name} || ' ' || ${productsTable.description} || ' ' || coalesce(${productsTable.brand}, '')) like ${`%${q.search.toLowerCase()}%`}
    or similarity(lower(${productsTable.name}), ${q.search.toLowerCase()}) >= 0.25
    or exists (select 1 from jsonb_array_elements_text(${productsTable.searchSynonyms}) synonym
      where lower(synonym) like ${`%${q.search.toLowerCase()}%`} or similarity(lower(synonym), ${q.search.toLowerCase()}) >= 0.25)
  )`);
  // Category availability is enforced in SQL so counting and paging stay stable
  // and every matching product remains reachable across pages.
  productFilters.push(activeCategoryCondition(), activeSupplierCondition("B2B"));
  const whereClause = and(...productFilters);
  const page = q.page ?? 1;
  const pageSize = q.pageSize ?? 24;
  // Count the full matching set, then fetch only the requested page ordered
  // deterministically (name asc, id asc) so page boundaries never shift.
  const [[totals], pageProducts] = await Promise.all([
    db.select({ total: count(productsTable.id) }).from(productsTable).where(whereClause),
    db
      .select()
      .from(productsTable)
      .where(whereClause)
      .orderBy(...(q.search ? [
        desc(sql`CASE WHEN lower(${productsTable.name}) = ${q.search.toLowerCase()} THEN 3
          WHEN lower(${productsTable.name}) LIKE ${`%${q.search.toLowerCase()}%`} THEN 2 ELSE 1 END`),
        desc(sql`similarity(lower(${productsTable.name}), ${q.search.toLowerCase()})`),
        asc(productsTable.id),
      ] : [asc(productsTable.name), asc(productsTable.id)]))
      .limit(pageSize)
      .offset((page - 1) * pageSize),
  ]);
  const total = Number(totals?.total ?? 0);
  // Review aggregates are grouped and scoped to only the products on this page.
  const aggregates = await productReviewAggregates(pageProducts.map((item) => item.id));
  res.json(ListProductsResponse.parse({
    items: pageProducts.map((item) => productDtoWithAggregate(item, aggregates.get(item.id))),
    total,
    page,
    pageSize,
    totalPages: Math.max(1, Math.ceil(total / pageSize)),
  }));
});

router.get("/shop/products/:productId", async (req, res): Promise<void> => {
  const access = await requireSalonOwner(req, res); if (!access) return;
  const parsed = GetShopProductParams.safeParse(req.params);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  // Availability (active + active category) is enforced in SQL; a miss is a 404.
  const [product] = await db
    .select()
    .from(productsTable)
    .where(and(eq(productsTable.id, parsed.data.productId), eq(productsTable.active, true), eq(productsTable.professionalEnabled, true), activeCategoryCondition(), activeSupplierCondition("B2B")))
    .limit(1);
  if (!product) {
    res.status(404).json({ error: "Proizvod nije pronađen ili nije dostupan." }); return;
  }
  const item = product;
  // Fetch up to 4 related candidates in SQL, already excluding the current
  // product and enforcing category availability, so the full same-category set
  // is never loaded into memory.
  const [reviewRows, relatedProducts] = await Promise.all([
    productReviewViews(item.id, access.salon.id),
    similarProductCards(item, "B2B"),
  ]);
  // Review aggregates are queried only for the current product plus the related
  // ones and read from grouped maps instead of repeated array filters.
  const aggregates = await productReviewAggregates([item.id]);
  res.json(GetShopProductResponse.parse({
    ...productDtoWithAggregate(item, aggregates.get(item.id)),
    reviews: reviewRows,
    relatedProducts,
  }));
});

/**
 * Product availability waitlist.  The identity is derived exclusively from the
 * authenticated session: callers can never subscribe another salon/customer.
 * A notified entry is deliberately not revived by a duplicate subscribe; an
 * explicit new subscribe creates the next availability episode.
 */
async function productWaitlistProduct(productId: string, audience: "B2B" | "B2C") {
  const [product] = await db.select().from(productsTable).where(and(
    eq(productsTable.id, productId),
    eq(productsTable.active, true),
    audience === "B2B" ? eq(productsTable.professionalEnabled, true) : eq(productsTable.retailEnabled, true),
  )).limit(1);
  return product ?? null;
}

async function subscribeProductWaitlist(
  req: Request,
  res: Response,
  audience: "B2B" | "B2C",
): Promise<void> {
  const productId = String(req.params.productId);
  const access = audience === "B2B"
    ? await requireSalonOwner(req, res).then((value) => value ? { salonId: value.salon.id, userId: null } : null)
    : await requireCustomer(req, res).then((value) => value ? { salonId: null, userId: value.id } : null);
  if (!access) return;
  const product = await productWaitlistProduct(productId, audience);
  if (!product) { res.status(404).json({ error: "Proizvod nije dostupan u ovom kanalu." }); return; }
  if (product.stock !== 0) { res.status(409).json({ error: "Obaveštenje je moguće uključiti samo kada proizvod nije na stanju." }); return; }
  const { salonId, userId } = access;
  const ownerWhere = audience === "B2B"
    ? and(eq(productWaitlistTable.productId, product.id), eq(productWaitlistTable.salonId, salonId!))
    : and(eq(productWaitlistTable.productId, product.id), eq(productWaitlistTable.userId, userId!));
  const [active] = await db.select().from(productWaitlistTable).where(and(ownerWhere, eq(productWaitlistTable.status, "ACTIVE"))).limit(1);
  if (active) { res.json({ id: active.id, status: active.status, subscribed: true }); return; }
  let created: typeof productWaitlistTable.$inferSelect;
  try {
    [created] = await db.insert(productWaitlistTable).values({
      productId: product.id, audience, salonId, userId, status: "ACTIVE",
    }).returning();
    await notifyCustomer(db, {
      userId,
      eventKey: `product-waitlist:${created!.id}:joined`,
      category: "commerce",
      title: "Pratite dostupnost proizvoda",
      body: `Obavestićemo vas kada „${product.name}“ ponovo bude na stanju.`,
      deepLink: `/shop/public/products/${product.id}`,
      metadata: { productId: product.id, waitlistId: created!.id },
    });
  } catch (error: unknown) {
    // The partial unique indexes are the authoritative race-safe invariant.
    // A concurrent identical subscribe therefore has the same idempotent
    // result instead of becoming a server error.
    if ((error as { code?: string }).code !== "23505") throw error;
    const [concurrent] = await db.select().from(productWaitlistTable)
      .where(and(ownerWhere, eq(productWaitlistTable.status, "ACTIVE"))).limit(1);
    if (!concurrent) throw error;
    res.json({ id: concurrent.id, status: concurrent.status, subscribed: true });
    return;
  }
  res.status(201).json({ id: created!.id, status: created!.status, subscribed: true });
}

async function productWaitlistStatus(req: Request, res: Response, audience: "B2B" | "B2C"): Promise<void> {
  const productId = String(req.params.productId);
  const access = audience === "B2B"
    ? await requireSalonOwner(req, res).then((value) => value ? { salonId: value.salon.id, userId: null } : null)
    : await requireCustomer(req, res).then((value) => value ? { salonId: null, userId: value.id } : null);
  if (!access) return;
  const rowWhere = audience === "B2B"
    ? and(eq(productWaitlistTable.productId, productId), eq(productWaitlistTable.salonId, access.salonId!))
    : and(eq(productWaitlistTable.productId, productId), eq(productWaitlistTable.userId, access.userId!));
  const [entry] = await db.select().from(productWaitlistTable).where(rowWhere).orderBy(desc(productWaitlistTable.updatedAt)).limit(1);
  res.json({ subscribed: entry?.status === "ACTIVE", status: entry?.status ?? null, notifiedAt: entry?.notifiedAt?.toISOString() ?? null });
}

async function unsubscribeProductWaitlist(req: Request, res: Response, audience: "B2B" | "B2C"): Promise<void> {
  const productId = String(req.params.productId);
  const access = audience === "B2B"
    ? await requireSalonOwner(req, res).then((value) => value ? { salonId: value.salon.id, userId: null } : null)
    : await requireCustomer(req, res).then((value) => value ? { salonId: null, userId: value.id } : null);
  if (!access) return;
  const rowWhere = audience === "B2B"
    ? and(eq(productWaitlistTable.productId, productId), eq(productWaitlistTable.salonId, access.salonId!), eq(productWaitlistTable.status, "ACTIVE"))
    : and(eq(productWaitlistTable.productId, productId), eq(productWaitlistTable.userId, access.userId!), eq(productWaitlistTable.status, "ACTIVE"));
  await db.update(productWaitlistTable).set({ status: "UNSUBSCRIBED", updatedAt: new Date() }).where(rowWhere);
  // DELETE is idempotent and never changes a terminal NOTIFIED record.
  res.status(204).end();
}

