function giftVoucherCodeHash(code: string) {
  return createHash("sha256").update(code.normalize("NFKC").trim().toUpperCase()).digest("hex");
}

function educationGiftVoucherView(row: typeof educationGiftVouchersTable.$inferSelect) {
  return {
    id: row.id, courseId: row.courseId, centerId: row.centerId, purchaserId: row.purchaserId,
    recipientUserId: row.recipientUserId, recipientEmail: row.recipientEmail,
    recipientName: row.recipientNameSnapshot, giftMessage: row.giftMessageSnapshot,
    courseTitle: row.courseTitleSnapshot, courseImageUrl: row.courseImageUrlSnapshot,
    amount: row.amountSnapshot, currency: row.currencySnapshot, codeLast4: row.codeLast4,
    status: row.status, paymentReference: row.paymentReference,
    redeemedEnrollmentId: row.redeemedEnrollmentId, createdAt: safeIsoTimestamp(row.createdAt),
  };
}

function adminEducationGiftVoucherView(row: typeof educationGiftVouchersTable.$inferSelect) {
  return {
    ...educationGiftVoucherView(row),
    maskedCode: `••••${row.codeLast4}`,
    settledByUserId: row.settledByUserId, settledAt: safeIsoTimestamp(row.settledAt),
    redeemedByUserId: row.redeemedByUserId, redeemedAt: safeIsoTimestamp(row.redeemedAt),
    refundedByUserId: row.refundedByUserId, refundedAt: safeIsoTimestamp(row.refundedAt),
    refundNote: row.refundNote, disputeId: row.disputeId, updatedAt: safeIsoTimestamp(row.updatedAt),
  };
}

/** The only course representation permitted outside publisher/enrolled APIs. */
function publicEducationCourseView<T extends { modules?: unknown }>(view: T): Omit<T, "modules"> {
  const { modules: _privateModules, ...publicView } = view;
  return publicView;
}

router.get("/education/gift-vouchers", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const { page, pageSize, limit, offset } = parsePagination(req.query, 20);
  // Recipient identity is conjunctive when both fields were captured; this
  // exactly mirrors redemption and prevents an email-only partial match.
  const predicate = or(
    eq(educationGiftVouchersTable.purchaserId, user.id),
    and(
      or(isNull(educationGiftVouchersTable.recipientUserId), eq(educationGiftVouchersTable.recipientUserId, user.id)),
      or(isNull(educationGiftVouchersTable.recipientEmail), eq(sql`lower(${educationGiftVouchersTable.recipientEmail})`, user.email.toLowerCase())),
    ),
  );
  const [rows, totals] = await Promise.all([
    db.select().from(educationGiftVouchersTable).where(predicate)
      .orderBy(desc(educationGiftVouchersTable.createdAt), desc(educationGiftVouchersTable.id)).limit(limit).offset(offset),
    db.select({ value: count() }).from(educationGiftVouchersTable).where(predicate),
  ]);
  res.json({ items: rows.map(educationGiftVoucherView), page, pageSize, total: Number(totals[0]?.value ?? 0) });
});

router.post("/education/gift-vouchers", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const parsed = PurchaseEducationGiftVoucherBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const idempotencyKey = String(req.header("Idempotency-Key") ?? "").trim();
  if (!idempotencyKey || idempotencyKey.length > 200) { res.status(400).json({ error: "Idempotency-Key je obavezan." }); return; }
  const recipientEmail = parsed.data.recipientEmail?.normalize("NFKC").trim().toLowerCase() ?? null;
  const recipientUserId = parsed.data.recipientUserId ?? null;
  const recipientName = parsed.data.recipientName?.normalize("NFKC").trim() || null;
  const giftMessage = parsed.data.giftMessage?.normalize("NFKC").trim() || null;
  if (!recipientEmail && !recipientUserId) { res.status(400).json({ error: "Primalac vaučera je obavezan." }); return; }
  if (recipientEmail && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(recipientEmail)) {
    res.status(400).json({ error: "Email primaoca nije ispravan." }); return;
  }
  if (recipientUserId) {
    const [recipient] = await db.select({ id: usersTable.id, email: usersTable.email }).from(usersTable).where(eq(usersTable.id, recipientUserId)).limit(1);
    if (!recipient) { res.status(400).json({ error: "Nalog primaoca nije pronađen." }); return; }
    if (recipientEmail && recipient.email.toLowerCase() !== recipientEmail) {
      res.status(400).json({ error: "ID i email primaoca ne pripadaju istom nalogu." }); return;
    }
  }
  const [course] = await db.select().from(coursesTable).where(eq(coursesTable.id, parsed.data.courseId)).limit(1);
  if (!course?.centerId || !course.giftVoucherEligible || !(await isPublicEducationCourse(course))) {
    res.status(404).json({ error: "Poklon vaučer nije dostupan za ovu edukaciju." }); return;
  }
  const existing = (await db.select().from(educationGiftVouchersTable).where(and(
    eq(educationGiftVouchersTable.purchaserId, user.id), eq(educationGiftVouchersTable.idempotencyKey, idempotencyKey),
  )).limit(1))[0];
  if (existing) {
    if (existing.courseId !== course.id || existing.recipientUserId !== recipientUserId || existing.recipientEmail !== recipientEmail
      || existing.recipientNameSnapshot !== recipientName || existing.giftMessageSnapshot !== giftMessage) {
      res.status(409).json({ error: "Idempotency-Key je već korišćen za drugi zahtev." }); return;
    }
    res.json({ ...educationGiftVoucherView(existing), redemptionCode: "" }); return;
  }
  const rawCode = `EDU-${randomBytes(18).toString("base64url").toUpperCase()}`;
  try {
    const [created] = await db.insert(educationGiftVouchersTable).values({
      courseId: course.id, centerId: course.centerId, purchaserId: user.id,
      recipientUserId, recipientEmail, recipientNameSnapshot: recipientName, giftMessageSnapshot: giftMessage, courseTitleSnapshot: course.title,
      courseImageUrlSnapshot: course.imageUrl, amountSnapshot: course.price,
      codeHash: giftVoucherCodeHash(rawCode), codeLast4: rawCode.slice(-4),
      paymentReference: `EDU-GIFT-${randomUUID()}`, idempotencyKey,
    }).returning();
    res.status(201).json({ ...educationGiftVoucherView(created!), redemptionCode: rawCode });
  } catch (error: any) {
    if (error?.code === "23505") {
      const replay = (await db.select().from(educationGiftVouchersTable).where(and(
        eq(educationGiftVouchersTable.purchaserId, user.id), eq(educationGiftVouchersTable.idempotencyKey, idempotencyKey),
      )).limit(1))[0];
      if (replay) {
        if (replay.courseId !== course.id || replay.recipientUserId !== recipientUserId || replay.recipientEmail !== recipientEmail
          || replay.recipientNameSnapshot !== recipientName || replay.giftMessageSnapshot !== giftMessage) {
          res.status(409).json({ error: "Idempotency-Key je već korišćen za drugi zahtev." }); return;
        }
        res.json({ ...educationGiftVoucherView(replay), redemptionCode: "" }); return;
      }
    }
    throw error;
  }
});

router.get("/admin/education/gift-vouchers", async (req, res): Promise<void> => {
  const admin = await requireAdmin(req, res); if (!admin) return;
  const status = typeof req.query.status === "string" ? req.query.status : "all";
  if (!["all", "pending_payment", "active", "redeemed", "refunded", "cancelled"].includes(status)) {
    res.status(400).json({ error: "Status vaučera nije ispravan." }); return;
  }
  const { page, pageSize, limit, offset } = parsePagination(req.query, 20);
  const predicate = status === "all" ? undefined
    : eq(educationGiftVouchersTable.status, status as "pending_payment" | "active" | "redeemed" | "refunded" | "cancelled");
  const [rows, totals] = await Promise.all([
    db.select().from(educationGiftVouchersTable).where(predicate)
      .orderBy(desc(educationGiftVouchersTable.createdAt), desc(educationGiftVouchersTable.id)).limit(limit).offset(offset),
    db.select({ value: count() }).from(educationGiftVouchersTable).where(predicate),
  ]);
  res.json({
    items: rows.map(adminEducationGiftVoucherView), page, pageSize, total: Number(totals[0]?.value ?? 0),
  });
});

router.post("/admin/education/gift-vouchers/:voucherId/settle", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const voucherId = String(req.params.voucherId ?? "");
  const updated = await db.transaction(async (tx) => {
    const [voucher] = await tx.select().from(educationGiftVouchersTable)
      .where(eq(educationGiftVouchersTable.id, voucherId)).for("update").limit(1);
    if (!voucher || voucher.status !== "pending_payment") return null;
    const now = new Date();
    const [settled] = await tx.update(educationGiftVouchersTable).set({
      status: "active", settledByUserId: admin.id, settledAt: now, updatedAt: now,
    }).where(and(
      eq(educationGiftVouchersTable.id, voucher.id),
      eq(educationGiftVouchersTable.status, "pending_payment"),
    )).returning();
    if (!settled) throw new Error("Vaučer je izmenjen u drugoj operaciji.");
    await recordEducationFinancialAudit(tx, {
      actorUserId: admin.id, action: "education_gift_voucher_settled",
      entityType: "education_gift_voucher", entityId: voucher.id,
      oldValue: { status: voucher.status, amount: voucher.amountSnapshot, centerId: voucher.centerId },
      newValue: { status: settled.status, amount: settled.amountSnapshot, centerId: settled.centerId },
      reason: "Ručna potvrda uplate poklon vaučera.",
    });
    return settled;
  });
  if (updated) { res.json(educationGiftVoucherView(updated)); return; }
  // A retry after a successful manual settlement is intentionally a no-op.
  // The conditional update above is still the state transition and remains atomic.
  const [alreadySettled] = await db.select().from(educationGiftVouchersTable)
    .where(and(eq(educationGiftVouchersTable.id, voucherId), eq(educationGiftVouchersTable.status, "active")))
    .limit(1);
  if (alreadySettled) { res.json(educationGiftVoucherView(alreadySettled)); return; }
  res.status(409).json({ error: "Vaučer nije u statusu za potvrdu ručne uplate." });
});

router.post("/education/gift-vouchers/redeem", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const parsed = RedeemEducationGiftVoucherBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  try {
    const enrollment = await db.transaction(async (tx) => {
      const [voucher] = await tx.select().from(educationGiftVouchersTable)
        .where(eq(educationGiftVouchersTable.codeHash, giftVoucherCodeHash(parsed.data.code))).for("update").limit(1);
      if (!voucher || voucher.status !== "active" || voucher.redeemedEnrollmentId) throw new Error("Vaučer nije aktivan ili je već iskorišćen.");
      if (!educationGiftVoucherRecipientMatches(voucher, user)) throw new Error("Vaučer je namenjen drugom korisniku.");
      await lockEducationCenterFinancials(tx, voucher.centerId);
      const [course] = await tx.select().from(coursesTable).where(eq(coursesTable.id, voucher.courseId)).for("update").limit(1);
      if (!course || !course.published || course.archived || !course.centerId || course.centerId !== voucher.centerId) {
        throw new Error("Edukacija sa vaučera više nije dostupna.");
      }
      assertOnlineEnrollmentRequest(course, parsed.data.digitalContentConsent);
      const [duplicate] = await tx.select({ id: courseEnrollmentsTable.id }).from(courseEnrollmentsTable).where(and(
        eq(courseEnrollmentsTable.courseId, course.id), eq(courseEnrollmentsTable.purchaserId, user.id),
        ne(courseEnrollmentsTable.status, "cancelled"),
      )).limit(1);
      if (duplicate) throw new Error("Već imate aktivan upis za ovu edukaciju.");
      let session: typeof courseSessionsTable.$inferSelect | undefined;
      if (course.format !== "online") {
        [session] = await tx.select().from(courseSessionsTable).where(and(
          eq(courseSessionsTable.courseId, course.id), isNull(courseSessionsTable.cancelledAt),
          gt(courseSessionsTable.startsAt, new Date()), lt(courseSessionsTable.reservedSeats, courseSessionsTable.capacity),
        )).orderBy(asc(courseSessionsTable.startsAt)).for("update").limit(1);
        if (!session) throw new Error("Nema slobodnog termina za ovaj vaučer.");
        await tx.update(courseSessionsTable).set({ reservedSeats: sql`${courseSessionsTable.reservedSeats} + 1` })
          .where(eq(courseSessionsTable.id, session.id));
      }
      const now = new Date();
      const [created] = await tx.insert(courseEnrollmentsTable).values({
        courseId: course.id, userId: user.id, purchaserId: user.id, sessionId: session?.id ?? null,
        status: "active", paymentStatus: "paid", chargedAmount: voucher.amountSnapshot,
        accessGrantedAt: now, idempotencyKey: `gift:${voucher.id}`,
        ...(course.format === "online" ? issueOnlineEnrollmentFields(course, { userId: user.id, acceptedAt: now }, now) : {}),
        auditData: { giftVoucherId: voucher.id, ...(session ? { seatReserved: true } : {}) },
      }).returning();
      const settings = await resolveEducationBillingSettingsForChargeInTx(voucher.centerId, tx);
      const gross = voucher.amountSnapshot;
      const platformFee = Math.round(gross * settings.effective.commissionPercent / 100);
      const reserveAmount = Math.round((gross - platformFee) * settings.effective.reservePercent / 100);
      const netAmount = gross - platformFee - reserveAmount;
      const releaseAt = await releaseAtForEducationCourse(course, settings.effective, session);
      const [escrow] = await tx.insert(educationEscrowsTable).values({
        enrollmentId: created!.id, centerId: voucher.centerId, grossAmount: gross,
        platformFee, reserveAmount, netAmount, releaseAt, status: "held",
        paymentReference: voucher.paymentReference,
      }).returning();
      await tx.insert(educationLedgerEntriesTable).values([
        { escrowId: escrow!.id, enrollmentId: created!.id, centerId: voucher.centerId, type: "charge", amount: gross, idempotencyKey: `gift:${voucher.id}:charge`, metadata: { giftVoucherId: voucher.id } },
        { escrowId: escrow!.id, enrollmentId: created!.id, centerId: voucher.centerId, type: "platform_fee", amount: platformFee, idempotencyKey: `gift:${voucher.id}:fee`, metadata: { giftVoucherId: voucher.id } },
        { escrowId: escrow!.id, enrollmentId: created!.id, centerId: voucher.centerId, type: "reserve_hold", amount: reserveAmount, idempotencyKey: `gift:${voucher.id}:reserve`, metadata: { giftVoucherId: voucher.id } },
      ]);
      await tx.insert(educationFinancialEventsTable).values({
        escrowId: escrow!.id, enrollmentId: created!.id, actorUserId: user.id,
        eventType: "gift_voucher_redeemed", previousStatus: "active", nextStatus: "redeemed",
        amount: gross, metadata: { giftVoucherId: voucher.id },
      });
      await tx.update(educationGiftVouchersTable).set({
        status: "redeemed", redeemedByUserId: user.id, redeemedEnrollmentId: created!.id,
        redeemedAt: now, updatedAt: now,
      }).where(eq(educationGiftVouchersTable.id, voucher.id));
      return created!;
    });
    res.status(201).json(await educationEnrollmentView(enrollment));
  } catch (error) {
    const message = error instanceof Error ? error.message : "Vaučer nije moguće iskoristiti.";
    if (message === "ONLINE_CONTENT_CONSENT_REQUIRED") {
      res.status(409).json({ error: "Za online kurs potrebna je izričita saglasnost za digitalni sadržaj." }); return;
    }
    if (message === "ONLINE_ACCESS_POLICY_MISSING") {
      res.status(409).json({ error: "Online kurs nema kompletno podešene uslove pristupa." }); return;
    }
    res.status(409).json({ error: message });
  }
});

router.post("/admin/education/gift-vouchers/:voucherId/refund", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsed = AdminRefundEducationGiftVoucherBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  try {
    const result = await db.transaction(async (tx) => {
      const [row] = await tx.select().from(educationGiftVouchersTable)
        .where(eq(educationGiftVouchersTable.id, String(req.params.voucherId ?? ""))).for("update").limit(1);
      if (!row || !["active", "redeemed"].includes(row.status)) throw new Error("Vaučer nije u statusu za refundaciju.");
      await lockEducationCenterFinancials(tx, row.centerId);
      if (parsed.data.disputeId) {
        const [dispute] = await tx.select({
          id: educationDisputesTable.id,
          enrollmentId: educationDisputesTable.enrollmentId,
        }).from(educationDisputesTable)
          .where(eq(educationDisputesTable.id, parsed.data.disputeId)).limit(1);
        if (!dispute) throw new Error("Spor nije pronađen.");
        if (!row.redeemedEnrollmentId || dispute.enrollmentId !== row.redeemedEnrollmentId) {
          throw new Error("Spor nije vezan za upis nastao korišćenjem ovog vaučera.");
        }
      }
      let promoted: typeof educationWaitlistTable.$inferSelect | null = null;
      let promotedCourse: typeof coursesTable.$inferSelect | null = null;
      if (row.redeemedEnrollmentId) {
        const [enrollment] = await tx.select().from(courseEnrollmentsTable)
          .where(eq(courseEnrollmentsTable.id, row.redeemedEnrollmentId)).for("update").limit(1);
        if (!enrollment) throw new Error("Upis nastao korišćenjem vaučera nije pronađen.");
        const [escrow] = await tx.select().from(educationEscrowsTable)
          .where(eq(educationEscrowsTable.enrollmentId, row.redeemedEnrollmentId)).for("update").limit(1);
        // This is deliberately the same pre-payout eligibility boundary as the
        // canonical enrollment cancellation path. Post-payout reconciliation
        // is a separate accounting workflow and must not partially cancel.
        if (!escrow || !["held", "ready_for_payout", "frozen"].includes(escrow.status)
          || escrow.netPaidAt !== null || escrow.reservePaidAt !== null) {
          throw new Error("Vaučer je već ušao u isplatu centra; potrebna je posebna post-isplatna korekcija.");
        }
        const [refundedEscrow] = await tx.update(educationEscrowsTable)
          .set({ status: "refunded", updatedAt: new Date() })
          .where(and(
            eq(educationEscrowsTable.id, escrow.id),
            inArray(educationEscrowsTable.status, ["held", "ready_for_payout", "frozen"]),
            isNull(educationEscrowsTable.netPaidAt),
            isNull(educationEscrowsTable.reservePaidAt),
          )).returning();
        if (!refundedEscrow) throw new Error("Vaučer je već ušao u isplatu centra; potrebna je posebna post-isplatna korekcija.");
        await tx.insert(educationLedgerEntriesTable).values({
          escrowId: escrow.id, enrollmentId: row.redeemedEnrollmentId, centerId: row.centerId,
          type: "refund", amount: -row.amountSnapshot, actorUserId: admin.id,
          idempotencyKey: `gift:${row.id}:refund`, note: parsed.data.note, metadata: { giftVoucherId: row.id, disputeId: parsed.data.disputeId ?? null },
        });
        await tx.insert(educationFinancialEventsTable).values({
          escrowId: escrow.id, enrollmentId: row.redeemedEnrollmentId, actorUserId: admin.id,
          eventType: "enrollment_cancelled_refund", previousStatus: escrow.status, nextStatus: "refunded",
          amount: -row.amountSnapshot, note: parsed.data.note,
          metadata: { giftVoucherId: row.id, disputeId: parsed.data.disputeId ?? null },
        });
        await tx.update(courseEnrollmentsTable).set({ status: "cancelled", paymentStatus: "refunded", updatedAt: new Date() })
          .where(eq(courseEnrollmentsTable.id, row.redeemedEnrollmentId));
        const holdsSeat = Boolean((enrollment.auditData as { seatReserved?: boolean } | null)?.seatReserved);
        if (enrollment.sessionId && holdsSeat) {
          const [course] = await tx.select().from(coursesTable)
            .where(eq(coursesTable.id, enrollment.courseId)).limit(1);
          if (!course) throw new Error("Kurs za upis nije pronađen.");
          promoted = await releaseSeatAndPromoteWaiter(tx, enrollment.sessionId, course);
          promotedCourse = course;
        }
      }
      const [updated] = await tx.update(educationGiftVouchersTable).set({
        status: "refunded", refundedByUserId: admin.id, refundedAt: new Date(),
        refundNote: parsed.data.note, disputeId: parsed.data.disputeId ?? null, updatedAt: new Date(),
      }).where(eq(educationGiftVouchersTable.id, row.id)).returning();
      await recordEducationFinancialAudit(tx, {
        actorUserId: admin.id, action: "education_gift_voucher_refunded",
        entityType: "education_gift_voucher", entityId: row.id,
        oldValue: { status: row.status, amount: row.amountSnapshot, redeemedEnrollmentId: row.redeemedEnrollmentId },
        newValue: {
          status: updated!.status, amount: updated!.amountSnapshot,
          escrowRefunded: Boolean(row.redeemedEnrollmentId), disputeId: parsed.data.disputeId ?? null,
        },
        reason: parsed.data.note,
      });
      return { voucher: updated!, promoted, promotedCourse };
    });
    if (result.promoted && result.promotedCourse) {
      await notifyPromotedWaiter(result.promoted, result.promotedCourse);
    }
    res.json(educationGiftVoucherView(result.voucher));
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Vaučer nije refundiran." });
  }
});

router.get("/education/public/featured", async (_req, res): Promise<void> => {
  const courses = await db.select().from(coursesTable)
    .where(and(
      eq(coursesTable.published, true), eq(coursesTable.archived, false), isNotNull(coursesTable.centerId),
      eq(coursesTable.isFeatured, true), or(sql`${coursesTable.featuredUntil} is null`, gte(coursesTable.featuredUntil, new Date())),
    ))
    .orderBy(desc(coursesTable.featuredActivatedAt));
  if (!courses.length) { res.json([]); return; }
  // Batch eligibility check — replaces N×2 per-course queries.
  const centerIds = [...new Set(courses.map((c) => c.centerId) as string[])];
  const eligibilityMap = await batchCenterEligibility(centerIds);
  // Batch paid-charge check — one query for all candidates.
  const paidCharges = await db.select().from(educationFeaturedChargesTable)
    .where(and(
      inArray(educationFeaturedChargesTable.courseId, courses.map((c) => c.id)),
      eq(educationFeaturedChargesTable.status, "paid"),
    ))
    .orderBy(desc(educationFeaturedChargesTable.createdAt));
  const paidCourseIds = new Set(paidCharges.map((ch) => ch.courseId));
  const visible = courses.filter((course) =>
    course.centerId && eligibilityMap.get(course.centerId) === true && paidCourseIds.has(course.id),
  );
  res.json((await batchEducationCourseViews(visible)).map(publicEducationCourseView));
});

router.get("/education/instructors", async (req, res): Promise<void> => {
  const access = await requireEducationAccess(req, res); if (!access) return;
  const centerId = access.centers[0]?.id;
  if (!centerId || access.admin) { res.status(403).json({ error: "Profilima instruktora upravlja njihov edukativni centar." }); return; }
  const instructors = await db.select().from(educationInstructorsTable).where(eq(educationInstructorsTable.centerId, centerId)).orderBy(desc(educationInstructorsTable.createdAt));
  res.json(instructors.map(instructorProfileView));
});

function instructorBodyFields(body: Record<string, unknown>) {
  const strings = (value: unknown) => Array.isArray(value) ? value.filter((item): item is string => typeof item === "string").map((item) => item.trim()).filter(Boolean).slice(0, 20) : [];
  const portfolioMedia = Array.isArray(body.portfolioMedia) ? body.portfolioMedia : [];
  if (portfolioMedia.length > 12 || portfolioMedia.some((value) => typeof value !== "string" || value.length > 2000 || !/^https:\/\//i.test(value))
    || new Set(portfolioMedia).size !== portfolioMedia.length) throw new Error("Portfolio mora sadržati najviše 12 jedinstvenih HTTPS URL adresa.");
  return {
    photoUrl: typeof body.photoUrl === "string" ? body.photoUrl : null,
    biography: typeof body.biography === "string" ? body.biography.slice(0, 4000) : "",
    industryYears: typeof body.industryYears === "number" && body.industryYears >= 0 ? Math.floor(body.industryYears) : 0,
    experienceYears: typeof body.experienceYears === "number" && body.experienceYears >= 0 ? Math.floor(body.experienceYears) : 0,
    specializations: strings(body.specializations), qualifications: strings(body.qualifications), portfolioMedia,
  };
}

function instructorProfileView(instructor: typeof educationInstructorsTable.$inferSelect) {
  return {
    id: instructor.id, centerId: instructor.centerId, userId: instructor.userId ?? null,
    fullName: instructor.fullName, photoUrl: instructor.photoUrl ?? null, biography: instructor.biography,
    industryYears: instructor.industryYears, experienceYears: instructor.experienceYears,
    specializations: instructor.specializations, qualifications: instructor.qualifications, portfolioMedia: instructor.portfolioMedia,
    createdAt: safeIsoTimestamp(instructor.createdAt), updatedAt: safeIsoTimestamp(instructor.updatedAt),
  };
}

function instructorProfileSummary(instructor: typeof educationInstructorsTable.$inferSelect) {
  return {
    id: instructor.id,
    fullName: instructor.fullName,
    photoUrl: instructor.photoUrl ?? null,
    biography: instructor.biography,
    industryYears: instructor.industryYears,
    experienceYears: instructor.experienceYears,
    specializations: instructor.specializations,
    qualifications: instructor.qualifications, portfolioMedia: instructor.portfolioMedia,
  };
}

router.post("/education/instructors", async (req, res): Promise<void> => {
  const access = await requireEducationAccess(req, res); if (!access) return;
  const centerId = access.centers[0]?.id;
  if (!centerId || access.admin) { res.status(403).json({ error: "Profilima instruktora upravlja njihov edukativni centar." }); return; }
  const body = req.body as Record<string, unknown>;
  const fullName = typeof body.fullName === "string" ? body.fullName.trim() : "";
  if (!fullName || fullName.length > 120) { res.status(400).json({ error: "Unesite ime instruktora." }); return; }
  const userId = typeof body.userId === "string" && /^[0-9a-f-]{36}$/i.test(body.userId) ? body.userId : null;
  if (userId) {
    const [linkedUser] = await db.select().from(usersTable).where(eq(usersTable.id, userId)).limit(1);
    if (!linkedUser || !["INSTRUCTOR", "EDUKATIVNI_CENTAR"].includes(linkedUser.role)) {
      res.status(400).json({ error: "Izaberite važeći nalog instruktora." }); return;
    }
  }
  let fields;
  try { fields = instructorBodyFields(body); } catch (error) {
    res.status(400).json({ error: error instanceof Error ? error.message : "Portfolio nije ispravan." }); return;
  }
  const [created] = await db.insert(educationInstructorsTable).values({ centerId, userId, fullName, ...fields }).returning();
  res.status(201).json(instructorProfileView(created!));
});

router.patch("/education/instructors/:instructorId", async (req, res): Promise<void> => {
  const access = await requireEducationAccess(req, res); if (!access) return;
  const centerId = access.centers[0]?.id;
  if (!centerId || access.admin) { res.status(403).json({ error: "Profilima instruktora upravlja njihov edukativni centar." }); return; }
  const instructorId = String(req.params.instructorId ?? "");
  const [instructor] = await db.select().from(educationInstructorsTable).where(and(eq(educationInstructorsTable.id, instructorId), eq(educationInstructorsTable.centerId, centerId))).limit(1);
  if (!instructor) { res.status(404).json({ error: "Instruktor nije pronađen." }); return; }
  const body = req.body as Record<string, unknown>;
  const fullName = typeof body.fullName === "string" ? body.fullName.trim() : instructor.fullName;
  if (!fullName || fullName.length > 120) { res.status(400).json({ error: "Unesite ime instruktora." }); return; }
  const userId = typeof body.userId === "string" && /^[0-9a-f-]{36}$/i.test(body.userId) ? body.userId : ("userId" in body ? null : instructor.userId);
  if (userId && userId !== instructor.userId) {
    const [linkedUser] = await db.select().from(usersTable).where(eq(usersTable.id, userId)).limit(1);
    if (!linkedUser || !["INSTRUCTOR", "EDUKATIVNI_CENTAR"].includes(linkedUser.role)) {
      res.status(400).json({ error: "Izaberite važeći nalog instruktora." }); return;
    }
  }
  let fields;
  try { fields = instructorBodyFields({ ...instructor, ...body }); } catch (error) {
    res.status(400).json({ error: error instanceof Error ? error.message : "Portfolio nije ispravan." }); return;
  }
  const [updated] = await db.update(educationInstructorsTable).set({
    fullName, userId, ...fields, updatedAt: new Date(),
  }).where(eq(educationInstructorsTable.id, instructor.id)).returning();
  res.json(instructorProfileView(updated!));
});

router.delete("/education/instructors/:instructorId", async (req, res): Promise<void> => {
  const access = await requireEducationAccess(req, res); if (!access) return;
  const centerId = access.centers[0]?.id;
  if (!centerId || access.admin) { res.status(403).json({ error: "Profilima instruktora upravlja njihov edukativni centar." }); return; }
  const instructorId = String(req.params.instructorId ?? "");
  const [instructor] = await db.select().from(educationInstructorsTable).where(and(eq(educationInstructorsTable.id, instructorId), eq(educationInstructorsTable.centerId, centerId))).limit(1);
  if (!instructor) { res.status(404).json({ error: "Instruktor nije pronađen." }); return; }
  await db.delete(educationInstructorsTable).where(eq(educationInstructorsTable.id, instructor.id));
  res.sendStatus(204);
});

router.get("/education/instructors/:instructorId/public", async (req, res): Promise<void> => {
  const instructorId = String(req.params.instructorId ?? "");
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(instructorId)) {
    res.status(404).json({ error: "Instruktor nije pronađen." });
    return;
  }
  const [instructor] = await db.select().from(educationInstructorsTable).where(eq(educationInstructorsTable.id, instructorId)).limit(1);
  if (!instructor) { res.status(404).json({ error: "Instruktor nije pronađen." }); return; }
  const allCourses = await db.select().from(coursesTable).where(eq(coursesTable.centerId, instructor.centerId));
  // Courses are linked to the instructor PROFILE (instructorProfileId). Older
  // records may only carry the legacy userId link, so fall back to that when
  // the profile is backed by a user account.
  const courses = allCourses.filter((course) =>
    course.instructorProfileId === instructor.id
    || (instructor.userId != null && course.instructorProfileId == null && course.instructorId === instructor.userId));
  // Batch eligibility check — one pair of queries for all center IDs.
  const uniqueCenterIds = [...new Set(courses.flatMap((c) => (c.centerId ? [c.centerId] : [])))];
  const eligibilityMap = await batchCenterEligibility(uniqueCenterIds);
  const publicCourses = courses.filter((course) =>
    course.published && !course.archived && course.centerId && eligibilityMap.get(course.centerId) === true,
  );
  const publicCourseIds = publicCourses.map((course) => course.id);
  const [enrollments, publicCourseViews] = await Promise.all([
    publicCourseIds.length
      ? db.select().from(courseEnrollmentsTable).where(and(inArray(courseEnrollmentsTable.courseId, publicCourseIds), eq(courseEnrollmentsTable.paymentStatus, "paid")))
      : [],
    batchEducationCourseViews(publicCourses).then((views) => views.map(publicEducationCourseView)),
  ]);
  const [publishedReviewAggregate] = publicCourseIds.length
    ? await db.select({
      reviewCount: count(),
      rating: sql<string>`coalesce(avg(${courseReviewsTable.rating}), 0)`,
    }).from(courseReviewsTable)
      .where(and(inArray(courseReviewsTable.courseId, publicCourseIds), eq(courseReviewsTable.status, "published")))
    : [{ reviewCount: 0, rating: "0" }];
  const reviewCount = Number(publishedReviewAggregate?.reviewCount ?? 0);
  const rating = Math.round(Number(publishedReviewAggregate?.rating ?? 0) * 10) / 10;
  res.json({
    id: instructor.id, name: instructor.fullName, photoUrl: instructor.photoUrl ?? null, biography: instructor.biography,
    industryYears: instructor.industryYears, experienceYears: instructor.experienceYears, specializations: instructor.specializations,
    qualifications: instructor.qualifications, portfolioMedia: instructor.portfolioMedia,
    rating, reviewCount, ratingSource: "published_course_reviews", participantCount: enrollments.length,
    courses: publicCourseViews,
  });
});

router.get("/education/center/status", async (req, res): Promise<void> => {
  const access = await requireEducationAccess(req, res); if (!access) return;
  if (access.admin) { res.status(403).json({ error: "Ovaj status je rezervisan za vlasnika edukativnog centra." }); return; }
  // Batch-fetch subscriptions for all centers in one query.
  const centerIds = access.centers.map((c) => c.id);
  const subscriptions = centerIds.length
    ? await db.select().from(educationCenterSubscriptionsTable).where(inArray(educationCenterSubscriptionsTable.centerId, centerIds))
    : [];
  const subByCenterId = new Map(subscriptions.map((s) => [s.centerId, s]));
  const ninetyDays = new Date(Date.now() - 90 * 86400_000);
  const [inquiries, completed, learners, courseReviews, centerReviews] = await Promise.all([
    db.select({ centerId: educationInquiriesTable.centerId, value: count() }).from(educationInquiriesTable).where(and(inArray(educationInquiriesTable.centerId, centerIds), gte(educationInquiriesTable.createdAt, ninetyDays))).groupBy(educationInquiriesTable.centerId),
    db.select({ centerId: coursesTable.centerId, value: count() }).from(courseEnrollmentsTable).innerJoin(coursesTable, eq(courseEnrollmentsTable.courseId, coursesTable.id)).where(and(inArray(coursesTable.centerId, centerIds), eq(courseEnrollmentsTable.status, "completed"), gte(courseEnrollmentsTable.completedAt, ninetyDays))).groupBy(coursesTable.centerId),
    db.select({ centerId: coursesTable.centerId, value: count() }).from(courseEnrollmentsTable).innerJoin(coursesTable, eq(courseEnrollmentsTable.courseId, coursesTable.id)).where(and(inArray(coursesTable.centerId, centerIds), eq(courseEnrollmentsTable.status, "completed"))).groupBy(coursesTable.centerId),
    db.select({ centerId: coursesTable.centerId, rating: courseReviewsTable.rating }).from(courseReviewsTable).innerJoin(coursesTable, eq(courseReviewsTable.courseId, coursesTable.id)).where(and(inArray(coursesTable.centerId, centerIds), eq(courseReviewsTable.status, "published"))),
    db.select({ centerId: educationCenterReviewsTable.centerId, rating: educationCenterReviewsTable.rating }).from(educationCenterReviewsTable).where(and(inArray(educationCenterReviewsTable.centerId, centerIds), eq(educationCenterReviewsTable.status, "published"))),
  ]);
  const requestCounts = new Map<string, number>();
  for (const row of [...inquiries, ...completed]) if (row.centerId) requestCounts.set(row.centerId, (requestCounts.get(row.centerId) ?? 0) + Number(row.value));
  const learnerCounts = new Map(learners.flatMap((row) => row.centerId ? [[row.centerId, Number(row.value)] as const] : []));
  const ratings = new Map<string, number[]>();
  for (const row of [...courseReviews, ...centerReviews]) if (row.centerId) ratings.set(row.centerId, [...(ratings.get(row.centerId) ?? []), row.rating]);
  const centers = access.centers.map((center) => {
    const subscription = subByCenterId.get(center.id);
    const eligible = center.verificationStatus === "verified" && hasActiveEducationSubscription(subscription);
    return {
      id: center.id, name: center.name, verificationStatus: center.verificationStatus, verificationNote: center.verificationNote,
      subscriptionStatus: subscription?.status ?? null, currentPeriodEnd: safeIsoTimestamp(subscription?.currentPeriodEnd), eligible,
      organicInquiriesAndCompletedEnrollments90d: requestCounts.get(center.id) ?? 0,
      completedLearnerCount: learnerCounts.get(center.id) ?? 0,
      publishedReviewCount: ratings.get(center.id)?.length ?? 0,
      publishedRating: ratings.get(center.id)?.length ? Math.round((ratings.get(center.id)!.reduce((sum, rating) => sum + rating, 0) / ratings.get(center.id)!.length) * 10) / 10 : 0,
      qualifiesMostRequested: qualifiesAsMostRequestedEducationCenter(requestCounts.get(center.id) ?? 0),
      qualifiesTopRated: qualifiesAsTopRatedEducationCenter(ratings.get(center.id)?.length ?? 0),
      metricsExplanation: "Organski upiti i završeni upisi u poslednjih 90 dana; objavljene recenzije kursa i centra. Plaćeni plasmani se ne računaju.",
    };
  });
  res.json(centers);
});

router.get("/education/purchases", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  if (!["JOBSEEKER", "STUDENT"].includes(user.role)) { res.status(403).json({ error: "Edukacije za polaznike su dostupne samo polazničkim nalozima." }); return; }
  // Bounded, stably ordered purchaser list — never full-scans course_enrollments.
  const { limit, offset } = parsePagination(req.query, 50);
  const enrollments = await db.select().from(courseEnrollmentsTable)
    .where(eq(courseEnrollmentsTable.purchaserId, user.id))
    .orderBy(desc(courseEnrollmentsTable.purchasedAt), desc(courseEnrollmentsTable.id))
    .limit(limit)
    .offset(offset);
  res.json(await batchEducationEnrollmentViews(enrollments));
});

// ─── Certificate PDF ────────────────────────────────────────────────────────
// Generates (once) and serves a plain-PDF certificate for a completed online
// enrollment.  The path is persisted in certificatePath so rerequests are free.

function buildCertificatePdf(learnerName: string, courseTitle: string, issuedAt: Date, certificateNumber: string): Buffer {
  const iso = issuedAt.toISOString().slice(0, 10);
  const escaped = (s: string) => s.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");

  // Simple single-page PDF built by hand (no external libraries).
  // Content stream draws text in two fonts: Helvetica (body) and Helvetica-Bold
  // (title).  Coordinates are in points (72 pt = 1 inch).  Page: A4 landscape.
  const W = 841, H = 595;

  const contentLines = [
    "BT",
    `/F2 36 Tf`,
    `${W / 2} ${H / 2 + 90} Td`,
    `(${escaped("LUMERA Edukacije")}) Tj`,
    "ET",
    "BT",
    `/F2 24 Tf`,
    `${W / 2} ${H / 2 + 40} Td`,
    `(${escaped("Sertifikat o završenoj edukaciji")}) Tj`,
    "ET",
    "BT",
    `/F1 16 Tf`,
    `${W / 2} ${H / 2} Td`,
    `(${escaped(learnerName)}) Tj`,
    "ET",
    "BT",
    `/F1 13 Tf`,
    `${W / 2} ${H / 2 - 36} Td`,
    `(${escaped("uspešno je završio/la kurs:")}) Tj`,
    "ET",
    "BT",
    `/F2 15 Tf`,
    `${W / 2} ${H / 2 - 64} Td`,
    `(${escaped(courseTitle.length > 70 ? courseTitle.slice(0, 67) + "..." : courseTitle)}) Tj`,
    "ET",
    "BT",
    `/F1 11 Tf`,
    `${W / 2} ${H / 2 - 108} Td`,
    `(${escaped(`Datum: ${iso}   |   Broj: ${certificateNumber}`)}) Tj`,
    "ET",
  ];

  const contentStream = [
    "q",
    // Decorative border rectangle
    `0.8 0.6 0.8 RG`,
    `2 w`,
    `30 30 ${W - 60} ${H - 60} re S`,
    // Center all text via TextMatrix offsets (simple negative-half-width centering is not
    // supported without font metrics in raw PDF; we use approximate centering).
    // Text matrix: positioned relative to page origin with TextMatrix.
    "BT",
    `/F2 36 Tf`,
    `1 0 0 1 ${W / 2 - 130} ${H / 2 + 90} Tm`,
    `(${escaped("LUMERA Edukacije")}) Tj`,
    "ET",
    "BT",
    `/F2 22 Tf`,
    `1 0 0 1 ${W / 2 - 185} ${H / 2 + 44} Tm`,
    `(${escaped("Sertifikat o završenoj edukaciji")}) Tj`,
    "ET",
    "BT",
    `/F1 16 Tf`,
    `1 0 0 1 ${W / 2 - Math.min(learnerName.length * 4.5, 200)} ${H / 2} Tm`,
    `(${escaped(learnerName)}) Tj`,
    "ET",
    "BT",
    `/F1 13 Tf`,
    `1 0 0 1 ${W / 2 - 130} ${H / 2 - 36} Tm`,
    `(${escaped("uspešno je završio/la kurs:")}) Tj`,
    "ET",
    "BT",
    `/F2 14 Tf`,
    `1 0 0 1 ${W / 2 - Math.min(courseTitle.length * 4, 240)} ${H / 2 - 62} Tm`,
    `(${escaped(courseTitle.length > 70 ? courseTitle.slice(0, 67) + "..." : courseTitle)}) Tj`,
    "ET",
    "BT",
    `/F1 10 Tf`,
    `1 0 0 1 ${W / 2 - 165} ${H / 2 - 108} Tm`,
    `(${escaped(`Datum: ${iso}   |   Broj sertifikata: ${certificateNumber}`)}) Tj`,
    "ET",
    "Q",
  ].join("\n");

  const encoder = new TextEncoder();
  const streamBytes = encoder.encode(contentStream);
  const streamLength = streamBytes.length;

  // Build PDF objects
  const objects: string[] = [];
  const offsets: number[] = [];
  let body = "%PDF-1.4\n";

  function addObj(n: number, content: string) {
    offsets[n] = body.length;
    objects.push(content);
    body += `${n} 0 obj\n${content}\nendobj\n`;
  }

  // 1: Catalog
  addObj(1, "<< /Type /Catalog /Pages 2 0 R >>");
  // 2: Pages
  addObj(2, `<< /Type /Pages /Kids [3 0 R] /Count 1 >>`);
  // 3: Page (A4 landscape)
  addObj(3, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Contents 4 0 R /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> >>`);
  // 4: Content stream
  addObj(4, `<< /Length ${streamLength} >>\nstream\n${contentStream}\nendstream`);
  // 5: Font Helvetica
  addObj(5, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
  // 6: Font Helvetica-Bold
  addObj(6, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");

  const xrefOffset = body.length;
  body += "xref\n";
  body += `0 ${offsets.length + 1}\n`;
  body += "0000000000 65535 f \n";
  for (let i = 1; i <= offsets.length; i++) {
    body += `${String(offsets[i]!).padStart(10, "0")} 00000 n \n`;
  }
  body += `trailer\n<< /Size ${offsets.length + 1} /Root 1 0 R >>\n`;
  body += `startxref\n${xrefOffset}\n%%EOF\n`;

  return Buffer.from(body, "latin1");
}

router.get("/education/enrollments/:enrollmentId/certificate", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  if (user.role === "CUSTOMER") { res.status(403).json({ error: "Edukacije nisu dostupne CUSTOMER nalozima." }); return; }
  const enrollmentId = String(req.params.enrollmentId ?? "");
  let result: {
    enrollment: typeof courseEnrollmentsTable.$inferSelect;
    course: typeof coursesTable.$inferSelect;
  };
  try {
    result = await db.transaction(async (tx) => {
      const [enrollment] = await tx.select().from(courseEnrollmentsTable)
        .where(eq(courseEnrollmentsTable.id, enrollmentId)).for("update").limit(1);
      if (!enrollment) throw new Error("NOT_FOUND");
      // Operational named-seat certificates belong only to the linked learner.
      if (enrollment.participantId && enrollment.userId !== user.id) throw new Error("FORBIDDEN");
      if (!enrollment.participantId && enrollment.purchaserId !== user.id && !isAdmin(user)) {
        const [employee] = enrollment.employeeId
          ? await tx.select().from(employeesTable).where(eq(employeesTable.id, enrollment.employeeId)).limit(1)
          : [];
        if (!employee || employee.userId !== user.id) throw new Error("FORBIDDEN");
      }
      const [courseClock] = await tx.select({
        course: coursesTable,
        databaseNow: sql<string>`current_timestamp`,
      }).from(coursesTable).where(eq(coursesTable.id, enrollment.courseId)).limit(1);
      if (!courseClock) throw new Error("COURSE_NOT_FOUND");
      const databaseNow = new Date(courseClock.databaseNow);
      // Completion remains on the learner's record, but private online
      // artifacts are no longer issuable or downloadable after entitlement.
      if (isOnlineEnrollmentSnapshot(enrollment)
        && (!enrollment.accessExpiresAt || enrollment.accessExpiresAt <= databaseNow)) {
        throw new Error("ONLINE_ACCESS_EXPIRED");
      }
      const eligibility = await educationCertificateEligibility(enrollment, tx);
      if (enrollment.status !== "completed" || enrollment.paymentStatus !== "paid" || !eligibility.certificateEligible) {
        throw new Error("NOT_ELIGIBLE");
      }
      if (!courseClock.course.certification) throw new Error("NO_CERTIFICATION");
      if (enrollment.certificateNumber) return { enrollment, course: courseClock.course };
      const certificateNumber = `LUMERA-${Date.now().toString(36).toUpperCase()}-${randomBytes(3).toString("hex").toUpperCase()}`;
      const [issued] = await tx.update(courseEnrollmentsTable).set({
        certificateNumber,
        certificateIssuedAt: databaseNow,
        updatedAt: databaseNow,
      }).where(eq(courseEnrollmentsTable.id, enrollment.id)).returning();
      return { enrollment: issued!, course: courseClock.course };
    });
  } catch (error) {
    const code = error instanceof Error ? error.message : "";
    if (code === "NOT_FOUND") { res.status(404).json({ error: "Prijava nije pronađena." }); return; }
    if (code === "COURSE_NOT_FOUND") { res.status(404).json({ error: "Kurs nije pronađen." }); return; }
    if (code === "FORBIDDEN") { res.status(403).json({ error: "Nemate pristup ovom sertifikatu." }); return; }
    if (code === "ONLINE_ACCESS_EXPIRED") { res.status(403).json({ error: "Pristup online kursu je istekao." }); return; }
    if (code === "NOT_ELIGIBLE") { res.status(409).json({ error: "Sertifikat je dostupan tek nakon što završite kurs i platite." }); return; }
    if (code === "NO_CERTIFICATION") { res.status(409).json({ error: "Ovaj kurs ne nudi zvanični sertifikat." }); return; }
    throw error;
  }
  const { enrollment, course } = result;
  const certNumber = enrollment.certificateNumber!;

  const [purchaser, employee, participant] = await Promise.all([
    db.select().from(usersTable).where(eq(usersTable.id, enrollment.purchaserId)).limit(1),
    enrollment.employeeId ? db.select().from(employeesTable).where(eq(employeesTable.id, enrollment.employeeId)).limit(1) : Promise.resolve([]),
    enrollment.participantId
      ? db.select({ fullName: educationBookingParticipantsTable.fullName })
          .from(educationBookingParticipantsTable)
          .where(eq(educationBookingParticipantsTable.id, enrollment.participantId))
          .limit(1)
      : Promise.resolve([]),
  ]);
  const learnerName = participant[0]?.fullName
    ?? employee[0]?.name
    ?? `${purchaser[0]?.firstName ?? "Polaznik"} ${purchaser[0]?.lastName ?? ""}`.trim();
  const issuedAt = enrollment.certificateIssuedAt ?? new Date();

  const pdfBuffer = buildCertificatePdf(learnerName, course.title, issuedAt, certNumber);
  const filename = `sertifikat-${certNumber}.pdf`;
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
  res.setHeader("Content-Length", pdfBuffer.length);
  res.end(pdfBuffer);
});

// ─── ICS Calendar Export ─────────────────────────────────────────────────────
// Generates an RFC 5545 .ics file for a purchased live session enrollment.

function buildIcs(params: {
  uid: string;
  summary: string;
  description: string;
  location: string | null;
  dtstart: Date;
  dtend: Date;
  organizerName: string;
  organizerEmail: string;
}): string {
  function icsDate(d: Date) {
    return d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
  }
  // RFC 5545 §3.1 content-line folding: lines longer than 75 octets are split
  // and each continuation line begins with a single space. Folding must count
  // UTF-8 octets (not JS characters) and must never split a multi-byte
  // character across a fold boundary, otherwise the value cannot be decoded.
  function fold(line: string): string {
    const encoder = new TextEncoder();
    if (encoder.encode(line).length <= 75) return line;
    const result: string[] = [];
    // First line may use all 75 octets; continuation lines reserve 1 octet for
    // the leading space, leaving 74 octets of content per continuation.
    let cur = "";
    let curBytes = 0;
    let limit = 75;
    for (const ch of line) {
      const chBytes = encoder.encode(ch).length;
      if (curBytes + chBytes > limit) {
        result.push(cur);
        cur = " " + ch;
        curBytes = 1 + chBytes;
        limit = 75;
      } else {
        cur += ch;
        curBytes += chBytes;
      }
    }
    if (cur) result.push(cur);
    return result.join("\r\n");
  }
  const esc = (s: string) => s.replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\n/g, "\\n");
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//LUMERA//Education//SR",
    "CALSCALE:GREGORIAN",
    "METHOD:PUBLISH",
    "BEGIN:VEVENT",
    `UID:${params.uid}`,
    `DTSTAMP:${icsDate(new Date())}`,
    `DTSTART:${icsDate(params.dtstart)}`,
    `DTEND:${icsDate(params.dtend)}`,
    fold(`SUMMARY:${esc(params.summary)}`),
    fold(`DESCRIPTION:${esc(params.description)}`),
    ...(params.location ? [fold(`LOCATION:${esc(params.location)}`)] : []),
    fold(`ORGANIZER;CN="${esc(params.organizerName)}":mailto:${params.organizerEmail}`),
    "END:VEVENT",
    "END:VCALENDAR",
  ];
  return lines.join("\r\n") + "\r\n";
}

router.get("/education/enrollments/:enrollmentId/session.ics", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  if (user.role === "CUSTOMER") { res.status(403).json({ error: "Edukacije nisu dostupne CUSTOMER nalozima." }); return; }
  const enrollmentId = String(req.params.enrollmentId ?? "");
  const [enrollment] = await db.select().from(courseEnrollmentsTable).where(eq(courseEnrollmentsTable.id, enrollmentId)).limit(1);
  if (!enrollment) { res.status(404).json({ error: "Prijava nije pronađena." }); return; }
  if (enrollment.participantId && enrollment.userId !== user.id) {
    res.status(403).json({ error: "Nemate pristup ovom terminu." }); return;
  }
  if (!enrollment.participantId && enrollment.purchaserId !== user.id && !isAdmin(user)) {
    const [emp] = enrollment.employeeId
      ? await db.select().from(employeesTable).where(eq(employeesTable.id, enrollment.employeeId)).limit(1)
      : [];
    if (!emp || emp.userId !== user.id) {
      res.status(403).json({ error: "Nemate pristup ovom terminu." }); return;
    }
  }
  if (enrollment.paymentStatus !== "paid") {
    res.status(409).json({ error: "Detalji termina su dostupni tek nakon potvrđene uplate." }); return;
  }
  if (!enrollment.sessionId) {
    res.status(409).json({ error: "Ova prijava nema dodeljen termin." }); return;
  }
  const [session, course] = await Promise.all([
    db.select().from(courseSessionsTable).where(eq(courseSessionsTable.id, enrollment.sessionId)).limit(1),
    db.select().from(coursesTable).where(eq(coursesTable.id, enrollment.courseId)).limit(1),
  ]);
  if (!session[0] || !course[0]) { res.status(404).json({ error: "Termin ili kurs nisu pronađeni." }); return; }
  const [purchaser] = await db.select().from(usersTable).where(eq(usersTable.id, enrollment.purchaserId)).limit(1);
  const uid = `lumera-session-${session[0].id}@lumera.app`;
  const description = `Edukacija: ${course[0].title}\nOrganizator: LUMERA Edukacije\nBroj prijave: ${enrollment.id}`;
  const icsContent = buildIcs({
    uid,
    summary: `LUMERA Edukacije: ${course[0].title}`,
    description,
    location: session[0].location,
    dtstart: session[0].startsAt,
    dtend: session[0].endsAt,
    organizerName: "LUMERA Edukacije",
    organizerEmail: purchaser?.email ?? "edukacije@lumera.app",
  });
  res.setHeader("Content-Type", "text/calendar; charset=utf-8");
  res.setHeader("Content-Disposition", `attachment; filename="termin-${session[0].id}.ics"`);
  res.end(icsContent);
});

// ─── Group Enrollment ────────────────────────────────────────────────────────
// Salon owner enrolls multiple employees at once. The server validates:
//  - all employeeIds belong to the caller's salon
//  - group size ≥ course.groupDiscountMinimum
//  - applies configured groupDiscountPercent to each seat
//  - inserts one enrollment per seat in a single transaction

router.post("/education/courses/:courseId/group-enrollments", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  if (user.role !== "SALON_OWNER") {
    res.status(403).json({ error: "Grupna prijava je dostupna samo vlasnicima salona." }); return;
  }
  const [params, body] = [
    CreateEducationGroupEnrollmentsParams.safeParse(req.params),
    CreateEducationGroupEnrollmentsBody.safeParse(req.body ?? {}),
  ];
  if (!params.success || !body.success) {
    res.status(400).json({ error: "Podaci grupne prijave nisu ispravni." }); return;
  }
  const courseId = params.data.courseId;
  const access = await requireEducationAccess(req, res); if (!access) return;
  const salon = access.salon;
  if (!salon) { res.status(403).json({ error: "Nalog nije povezan sa salonom." }); return; }

  const employeeIds = body.data.employeeIds;
  const sessionId = body.data.sessionId ?? null;

  const [course] = await db.select().from(coursesTable).where(eq(coursesTable.id, courseId)).limit(1);
  if (!course || !(await isPublicEducationCourse(course)) && !(course.salonId === salon.id && course.published && !course.archived)) {
    res.status(404).json({ error: "Kurs nije dostupan za grupnu prijavu." }); return;
  }
  if (course.format === "online" && body.data.digitalContentConsent !== true) {
    res.status(400).json({ error: "Za online kurs potrebna je izričita saglasnost za digitalni sadržaj." }); return;
  }
  if (course.format === "online" && sessionId) {
    res.status(409).json({ error: "Online kurs ne može koristiti termin uživo." }); return;
  }
  if (course.format === "online" && (!course.onlineAccessDays || course.onlineAccessDays < 1
    || !course.extensionPrice1Month || !course.extensionPrice3Months || !course.extensionPrice6Months)) {
    res.status(409).json({ error: "Online kurs nema kompletno podešene pozitivne uslove pristupa." }); return;
  }

  // Validate all employees belong to caller's salon
  const employees = employeeIds.length
    ? await db.select({ employee: employeesTable }).from(employeesTable)
        .innerJoin(employeeLocationAssignmentsTable, and(
          eq(employeeLocationAssignmentsTable.employeeId, employeesTable.id),
          eq(employeeLocationAssignmentsTable.salonId, salon.id),
          eq(employeeLocationAssignmentsTable.active, true),
        ))
        .where(and(inArray(employeesTable.id, employeeIds), eq(employeesTable.active, true)))
        .then((rows) => rows.map((row) => row.employee))
    : [];
  if (employees.length !== employeeIds.length) {
    res.status(403).json({ error: "Jedan ili više zaposlenih ne pripada vašem salonu ili nisu aktivni." }); return;
  }

  // Validate group discount eligibility
  const minGroup = course.groupDiscountMinimum ?? null;
  const discountPercent = course.groupDiscountPercent ?? 0;
  if (minGroup !== null && employeeIds.length < minGroup) {
    res.status(400).json({
      error: `Grupni popust zahteva najmanje ${minGroup} polaznika. Prijavili ste ${employeeIds.length}.`,
      minimumRequired: minGroup,
      submitted: employeeIds.length,
    }); return;
  }
  const effectiveDiscountPercent = (minGroup !== null && employeeIds.length >= minGroup) ? discountPercent : 0;
  const unitPrice = Math.max(0, Math.round(course.price * (1 - effectiveDiscountPercent / 100)));
  const idempotencyKey = req.get("idempotency-key")?.trim() || null;
  if (idempotencyKey && idempotencyKey.length > 200) {
    res.status(400).json({ error: "Idempotency ključ je predugačak." }); return;
  }

  let enrollments: (typeof courseEnrollmentsTable.$inferSelect)[];
  try {
    const isSalonInternal = course.salonId === salon.id && !course.centerId;
    const paymentSettings = !isSalonInternal && unitPrice > 0 ? await getEducationPlatformSettings() : null;
    const enrollmentIds = new Map(employees.map((employee) => [employee.id, randomUUID()]));
    const paymentInstructions = new Map(employees.map((employee) => {
      const enrollmentId = enrollmentIds.get(employee.id)!;
      return [employee.id, paymentSettings ? educationIpsQrPayload({
        recipientName: paymentSettings.ipsRecipientName,
        recipientAccount: paymentSettings.ipsRecipientAccount,
        purpose: paymentSettings.ipsPurpose,
        amount: unitPrice,
        reference: educationEnrollmentPaymentReference(enrollmentId),
        recipientType: "platform",
        transactionType: "course_enrollment",
        accountEnvironment: paymentSettings.ipsAccountEnvironment as "production" | "test",
        runtimeEnvironment: educationIpsRuntimeEnvironment(),
      }) : null] as const;
    }));
    enrollments = await db.transaction(async (tx) => {
      if (course.centerId) {
        await lockEducationCenterFinancials(tx, course.centerId);
        const [currentCenter] = await tx.select().from(educationCentersTable)
          .where(eq(educationCentersTable.id, course.centerId)).for("update").limit(1);
        const [subscription] = await tx.select().from(educationCenterSubscriptionsTable)
          .where(eq(educationCenterSubscriptionsTable.centerId, course.centerId)).for("update").limit(1);
        if (currentCenter?.verificationStatus !== "verified" || !hasActiveEducationSubscription(subscription)) {
          throw new Error("Centar više nije verifikovan ili nema aktivnu pretplatu.");
        }
      }
      const [lockedCourse] = await tx.select().from(coursesTable)
        .where(eq(coursesTable.id, course.id)).for("update").limit(1);
      if (!lockedCourse) throw new Error("Kurs više nije dostupan.");
      assertOnlineEnrollmentRequest(lockedCourse, body.data.digitalContentConsent);
      if (sessionId && lockedCourse.format === "online") {
        throw new Error("Online kurs ne može koristiti termin uživo.");
      }
      const isSalonInternal = lockedCourse.salonId === salon.id && !lockedCourse.centerId;
      if (sessionId) {
        const [reqSession] = await tx.select().from(courseSessionsTable)
          .where(and(eq(courseSessionsTable.id, sessionId), eq(courseSessionsTable.courseId, course.id)))
          .for("update").limit(1);
        if (!reqSession || reqSession.startsAt <= new Date() || reqSession.cancelledAt) {
          throw new Error("Izabrani termin nije dostupan.");
        }
        const remaining = reqSession.capacity - reqSession.reservedSeats;
        if (remaining < employeeIds.length) {
          throw new Error(`Na izabranom terminu ima samo ${remaining} slobodnih mesta.`);
        }
        // Only reserve seats now for enrollments that become active immediately
        // (salon-internal). Center-marketplace group seats stay pending and are
        // reserved atomically at settlement, exactly like single enrollments —
        // this prevents a group from double-reserving (once here, once again on
        // settle) and from leaking capacity when a pending request is abandoned.
        if (isSalonInternal) {
          await tx.update(courseSessionsTable)
            .set({ reservedSeats: reqSession.reservedSeats + employeeIds.length })
            .where(eq(courseSessionsTable.id, reqSession.id));
        }
      }
      const accessGrantedAt = new Date();
      const values = employees.map((emp) => ({
        id: enrollmentIds.get(emp.id)!,
        courseId: course.id,
        userId: emp.userId ?? user.id,
        salonId: salon.id,
        employeeId: emp.id,
        purchaserId: user.id,
        status: isSalonInternal ? ("active" as const) : ("pending" as const),
        paymentStatus: isSalonInternal ? ("paid" as const) : ("pending" as const),
        chargedAmount: unitPrice,
        ...(isSalonInternal ? { accessGrantedAt } : {}),
        ...(lockedCourse.format === "online" ? issueOnlineEnrollmentFields(
          lockedCourse, { userId: user.id, acceptedAt: accessGrantedAt }, isSalonInternal ? accessGrantedAt : undefined,
        ) : {}),
        sessionId: sessionId,
        auditData: {
          source: "group-enrollment",
          groupSize: employeeIds.length,
          effectiveDiscountPercent,
          unitPrice,
          idempotencyKey,
        },
        idempotencyKey: idempotencyKey ? `${idempotencyKey}:${emp.id}` : null,
        idempotencyFingerprint: `${course.id}:${emp.id}:group:${sessionId ?? "auto"}`,
        paymentInstructionsSnapshot: paymentInstructions.get(emp.id),
      }));
      const created = await tx.insert(courseEnrollmentsTable).values(values).returning();
      return created;
    });
  } catch (error) {
    const errorCode = typeof error === "object" && error
      ? (error as { code?: string; cause?: { code?: string } }).code ?? (error as { cause?: { code?: string } }).cause?.code
      : undefined;
    if (isEducationPaymentConfigurationError(error)) {
      res.status(503).json(EDUCATION_PAYMENT_UNAVAILABLE_ERROR); return;
    }
    if (errorCode === "23505") {
      res.status(409).json({ error: "Jedan ili više zaposlenih je već prijavljen na ovaj kurs." }); return;
    }
    if (error instanceof Error && error.message === "ONLINE_CONTENT_CONSENT_REQUIRED") {
      res.status(409).json({ error: "Za online kurs potrebna je izričita saglasnost za digitalni sadržaj." }); return;
    }
    if (error instanceof Error && error.message === "ONLINE_ACCESS_POLICY_MISSING") {
      res.status(409).json({ error: "Online kurs nema kompletno podešene uslove pristupa." }); return;
    }
    res.status(409).json({ error: error instanceof Error ? error.message : "Grupna prijava nije uspela." }); return;
  }

  // Send notification email to the purchaser
  await sendTransactionalEmail({
    eventKey: `group-enrollment:${salon.id}:${course.id}:${idempotencyKey ?? Date.now()}`,
    emailType: "course_enrollment_requested",
    to: { email: user.email, name: `${user.firstName} ${user.lastName}` },
    subject: "LUMERA Edukacije — grupna prijava je primljena",
    htmlContent: lumeraEmailHtml(
      "Grupna prijava na edukaciju",
      `<p>Uspešno ste prijavili ${enrollments.length} zaposlenih na kurs <strong>${emailSafe(course.title)}</strong>.</p>`
        + (effectiveDiscountPercent > 0 ? `<p>Primenjen je grupni popust od <strong>${effectiveDiscountPercent}%</strong>. Cena po polazniku: <strong>${unitPrice} RSD</strong>.</p>` : "")
        + `<p>Pristup se aktivira nakon ručne potvrde uplate za svaku prijavu.</p>`,
    ),
    metadata: { courseId: course.id, salonId: salon.id, groupSize: enrollments.length },
  });

  res.status(201).json(CreateEducationGroupEnrollmentsResponse.parse({
    enrollments: await batchEducationEnrollmentViews(enrollments),
    paymentInstructions: enrollments.flatMap((enrollment) => {
      const instructions = enrollment.paymentInstructionsSnapshot as Record<string, unknown> | null;
      return instructions
        ? [publicEducationEnrollmentPaymentInstructions(enrollment.id, instructions)]
        : [];
    }),
    discountPercent: effectiveDiscountPercent,
    unitPrice,
    totalPrice: unitPrice * enrollments.length,
  }));
});

async function enrollmentAccessForUser(user: typeof usersTable.$inferSelect, enrollmentId: string) {
  if (user.role === "CUSTOMER") {
    return { enrollment: null, course: null, center: null, canParticipate: false, admin: false };
  }
  const [enrollment] = await db.select().from(courseEnrollmentsTable).where(eq(courseEnrollmentsTable.id, enrollmentId)).limit(1);
  if (!enrollment) return { enrollment: null, course: null, center: null, canParticipate: false, admin: false };
  const [course] = await db.select().from(coursesTable).where(eq(coursesTable.id, enrollment.courseId)).limit(1);
  const [center] = course?.centerId
    ? await db.select().from(educationCentersTable).where(eq(educationCentersTable.id, course.centerId)).limit(1)
    : [];
  const admin = isAdmin(user);
  return {
    enrollment,
    course: course ?? null,
    center: center ?? null,
    canParticipate: admin || enrollment.purchaserId === user.id || (Boolean(center) && center!.ownerId === user.id),
    admin,
  };
}

router.get("/education/purchases/:enrollmentId/messages", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const access = await enrollmentAccessForUser(user, String(req.params.enrollmentId));
  if (!access.enrollment || !access.canParticipate) { res.status(403).json({ error: "Nemate pristup porukama ove kupovine." }); return; }
  if (access.enrollment.paymentStatus !== "paid") { res.status(409).json({ error: "Poruke postaju dostupne nakon potvrđene uplate." }); return; }
  const [thread] = await db.select().from(educationThreadsTable).where(eq(educationThreadsTable.enrollmentId, access.enrollment.id)).limit(1);
  if (!thread) { res.json({ thread: null, messages: [] }); return; }
  const messages = await db.select().from(educationMessagesTable).where(eq(educationMessagesTable.threadId, thread.id)).orderBy(asc(educationMessagesTable.createdAt));
  const senderIds = [...new Set(messages.map((message) => message.senderId))];
  const senders = senderIds.length ? await db.select({ id: usersTable.id, firstName: usersTable.firstName, lastName: usersTable.lastName }).from(usersTable).where(inArray(usersTable.id, senderIds)) : [];
  if (!access.admin) {
    await db.update(educationMessagesTable).set({ readAt: new Date() })
      .where(and(eq(educationMessagesTable.threadId, thread.id), ne(educationMessagesTable.senderId, user.id), sql`${educationMessagesTable.readAt} is null`));
  }
  res.json({
    thread: { id: thread.id, status: thread.status, enrollmentId: thread.enrollmentId },
    messages: messages.map((message) => {
      const sender = senders.find((item) => item.id === message.senderId);
      return { id: message.id, body: message.body, senderId: message.senderId, senderName: sender ? `${sender.firstName} ${sender.lastName}` : "LUMERA korisnik", createdAt: safeIsoTimestamp(message.createdAt), readAt: safeIsoTimestamp(message.readAt) };
    }),
  });
});

router.post("/education/purchases/:enrollmentId/messages", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const body = typeof req.body?.body === "string" ? req.body.body.trim() : "";
  if (!body || body.length > 4000) { res.status(400).json({ error: "Poruka mora imati između 1 i 4000 karaktera." }); return; }
  const access = await enrollmentAccessForUser(user, String(req.params.enrollmentId));
  if (!access.enrollment || !access.canParticipate || access.admin || !access.center) { res.status(403).json({ error: "Samo kupac i vlasnik centra mogu slati poruke u ovoj kupovini." }); return; }
  if (access.enrollment.paymentStatus !== "paid") { res.status(409).json({ error: "Poruke postaju dostupne nakon potvrđene uplate." }); return; }
  let [thread] = await db.select().from(educationThreadsTable).where(eq(educationThreadsTable.enrollmentId, access.enrollment.id)).limit(1);
  if (!thread) {
    [thread] = await db.insert(educationThreadsTable).values({
      enrollmentId: access.enrollment.id,
      purchaserId: access.enrollment.purchaserId,
      centerId: access.center.id,
    }).returning();
  }
  if (thread!.status !== "open") { res.status(409).json({ error: "Ova konverzacija je zatvorena." }); return; }
  const [message] = await db.insert(educationMessagesTable).values({ threadId: thread!.id, senderId: user.id, body }).returning();
  await db.update(educationThreadsTable).set({ updatedAt: new Date() }).where(eq(educationThreadsTable.id, thread!.id));
  res.status(201).json({ id: message!.id, body: message!.body, senderId: message!.senderId, senderName: `${user.firstName} ${user.lastName}`, createdAt: message!.createdAt.toISOString(), readAt: null });
});

router.post("/education/purchases/:enrollmentId/disputes", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const reason = typeof req.body?.reason === "string" ? req.body.reason.trim() : "";
  const details = typeof req.body?.details === "string" ? req.body.details.trim() : "";
  if (!reason || !details || reason.length > 160 || details.length > 4000) { res.status(400).json({ error: "Unesite razlog i opis problema." }); return; }
  const access = await enrollmentAccessForUser(user, String(req.params.enrollmentId));
  if (!access.enrollment || access.enrollment.purchaserId !== user.id) { res.status(403).json({ error: "Samo kupac može prijaviti problem za svoju kupovinu." }); return; }
  if (access.enrollment.paymentStatus !== "paid") { res.status(409).json({ error: "Spor se može otvoriti tek nakon potvrđene uplate." }); return; }
  const [escrowPreview] = await db.select().from(educationEscrowsTable).where(eq(educationEscrowsTable.enrollmentId, access.enrollment.id)).limit(1);
  if (!escrowPreview) { res.status(409).json({ error: "Kupovina nema escrow zaštitu koju možemo zamrznuti." }); return; }
  let result: { dispute: typeof educationDisputesTable.$inferSelect; duplicate: boolean };
  try {
    result = await db.transaction(async (tx) => {
    await lockEducationCenterFinancials(tx, escrowPreview.centerId);
    const [existing] = await tx.select().from(educationDisputesTable)
      .where(and(eq(educationDisputesTable.enrollmentId, access.enrollment!.id), inArray(educationDisputesTable.status, ["open", "under_review"]))).for("update").limit(1);
    if (existing) return { dispute: existing, duplicate: true };
    const [escrow] = await tx.select().from(educationEscrowsTable).where(eq(educationEscrowsTable.id, escrowPreview.id)).for("update").limit(1);
    if (!escrow || !["held", "ready_for_payout"].includes(escrow.status) || escrow.netPaidAt || escrow.reservePaidAt) {
      throw new Error("Ova kupovina više nije podobna za otvaranje spora.");
    }
    if (escrow.releaseAt <= new Date()) throw new Error("Rok za prijavu problema je istekao.");
    const [created] = await tx.insert(educationDisputesTable).values({ enrollmentId: access.enrollment!.id, openedByUserId: user.id, reason, details }).returning();
      const [frozen] = await tx.update(educationEscrowsTable).set({ status: "frozen", frozenAt: new Date(), updatedAt: new Date() })
        .where(and(eq(educationEscrowsTable.id, escrow.id), inArray(educationEscrowsTable.status, ["held", "ready_for_payout"]), sql`${educationEscrowsTable.releaseAt} > now()`, sql`${educationEscrowsTable.netPaidAt} is null`, sql`${educationEscrowsTable.reservePaidAt} is null`)).returning();
      if (!frozen) throw new Error("Escrow je izmenjen u drugoj finansijskoj operaciji.");
      await tx.insert(educationFinancialEventsTable).values({
        escrowId: escrow.id, enrollmentId: access.enrollment!.id, actorUserId: user.id,
        eventType: "dispute_opened", previousStatus: escrow.status, nextStatus: "frozen", note: reason,
      });
    return { dispute: created!, duplicate: false };
    });
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Spor nije mogao biti otvoren." });
    return;
  }
  const dispute = {
    id: result.dispute.id,
    enrollmentId: result.dispute.enrollmentId,
    reason: result.dispute.reason,
    details: result.dispute.details,
    status: result.dispute.status,
    createdAt: result.dispute.createdAt.toISOString(),
  };
  if (result.duplicate) {
    res.status(409).json({ error: "Za ovu kupovinu već postoji otvoren spor.", dispute });
    return;
  }
  res.status(201).json(dispute);
});

router.get("/education/disputes", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  const disputes = await db.select().from(educationDisputesTable).orderBy(desc(educationDisputesTable.createdAt));
  const visible = [];
  for (const dispute of disputes) {
    const access = await enrollmentAccessForUser(user, dispute.enrollmentId);
    if (!access.enrollment || !access.canParticipate) continue;
    visible.push({
      id: dispute.id, enrollmentId: dispute.enrollmentId, courseTitle: access.course?.title ?? "Edukacija",
      reason: dispute.reason, details: dispute.details, status: dispute.status, resolutionNote: dispute.resolutionNote,
      createdAt: safeIsoTimestamp(dispute.createdAt), resolvedAt: safeIsoTimestamp(dispute.resolvedAt),
    });
  }
  res.json(visible);
});

router.get("/admin/summary", async (req, res): Promise<void> => {
  const user = await current(req, res); if (!user) return;
  if (!isAdmin(user)) { res.status(403).json({ error: "Samo administratori mogu da vide ovaj pregled." }); return; }

  const now = new Date();
  const thisMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const lastMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);

  const {
    topCategories,
    deliveryReports,
    aggregateSummary,
  } = await db.transaction(async (tx) => {
    // PostgreSQL's default READ COMMITTED level gives each aggregate query a
    // different snapshot. Keep every database-backed summary field, including
    // helper-derived alerts and the category ranking, on one repeatable read.
    // A Drizzle transaction owns one pg client, so these must not be fired in
    // parallel. Sequential reads still share this transaction's snapshot.
    // Keep each growing relation to one aggregate scan. Combining scalar
    // subqueries would reduce round trips but make PostgreSQL rescan a table
    // for every dashboard metric derived from it.
    const aggregateResult = await tx.execute(sql<AdminSummaryAggregateRow>`
      WITH
        user_summary AS (
          SELECT
            count(*)::int AS "totalUsers",
            count(*) FILTER (
              WHERE ${usersTable.active}
                AND ${usersTable.role} IN ('ADMIN', 'SUPER_ADMIN')
                AND ${usersTable.phone} IS NOT NULL
                AND btrim(${usersTable.phone}) <> ''
            )::int AS "smsFallbackReachableAdminCount"
          FROM ${usersTable}
        ),
        salon_summary AS (
          SELECT
            count(*)::int AS "totalSalons",
            count(*) FILTER (WHERE ${salonsTable.active})::int AS "activeSalons",
            count(*) FILTER (WHERE ${salonsTable.createdAt} >= ${thisMonthStart})::int AS "newSalonsThisMonth"
          FROM ${salonsTable}
        ),
        appointment_summary AS (
          SELECT
            count(*) FILTER (WHERE ${appointmentsTable.createdAt} >= ${thisMonthStart})::int AS "bookingsThisMonth",
            count(*) FILTER (
              WHERE ${appointmentsTable.createdAt} >= ${lastMonthStart}
                AND ${appointmentsTable.createdAt} < ${thisMonthStart}
            )::int AS "bookingsLastMonth"
          FROM ${appointmentsTable}
        ),
        order_summary AS (
          SELECT coalesce(sum(${ordersTable.total}), 0)::double precision AS "grossMerchandiseValue"
          FROM ${ordersTable}
        ),
        review_summary AS (
          SELECT
            count(*)::int AS "totalReviews",
            count(*) FILTER (WHERE NOT ${reviewsTable.visible})::int AS "hiddenReviews"
          FROM ${reviewsTable}
        ),
        subscription_summary AS (
          SELECT count(*) FILTER (
            WHERE ${subscriptionsTable.status} IN ('active', 'free_via_loyalty')
          )::int AS "activeSubscriptions"
          FROM ${subscriptionsTable}
        ),
        gallery_summary AS (
          SELECT
            count(*) FILTER (
              WHERE (
                ${educationMediaUploadsTable.attachedAt} IS NOT NULL
                OR (
                  ${educationMediaUploadsTable.attachedAt} IS NULL
                  AND ${educationMediaUploadsTable.expiresAt} < ${now}
                )
              )
              AND ${educationMediaUploadsTable.cleanupFailureCount} > 0
            )::int AS "galleryCleanupFailedTickets",
            coalesce(sum(${educationMediaUploadsTable.cleanupFailureCount}) FILTER (
              WHERE (
                ${educationMediaUploadsTable.attachedAt} IS NOT NULL
                OR (
                  ${educationMediaUploadsTable.attachedAt} IS NULL
                  AND ${educationMediaUploadsTable.expiresAt} < ${now}
                )
              )
              AND ${educationMediaUploadsTable.cleanupFailureCount} > 0
            ), 0)::int AS "galleryCleanupFailureAttempts",
            min(${educationMediaUploadsTable.createdAt}) FILTER (
              WHERE (
                ${educationMediaUploadsTable.attachedAt} IS NOT NULL
                OR (
                  ${educationMediaUploadsTable.attachedAt} IS NULL
                  AND ${educationMediaUploadsTable.expiresAt} < ${now}
                )
              )
              AND ${educationMediaUploadsTable.cleanupFailureCount} > 0
            ) AS "galleryCleanupOldestEligibleAt",
            coalesce(bool_or(${educationMediaUploadsTable.cleanupFailureCount} >= ${EDUCATION_GALLERY_CLEANUP_ALERT_FAILURE_COUNT}) FILTER (
              WHERE (
                ${educationMediaUploadsTable.attachedAt} IS NOT NULL
                OR (
                  ${educationMediaUploadsTable.attachedAt} IS NULL
                  AND ${educationMediaUploadsTable.expiresAt} < ${now}
                )
              )
              AND ${educationMediaUploadsTable.cleanupFailureCount} > 0
            ), false) AS "galleryCleanupHasRepeatedFailures"
          FROM ${educationMediaUploadsTable}
        )
      SELECT *
      FROM user_summary
      CROSS JOIN salon_summary
      CROSS JOIN appointment_summary
      CROSS JOIN order_summary
      CROSS JOIN review_summary
      CROSS JOIN subscription_summary
      CROSS JOIN gallery_summary
    `);
    const aggregateSummary = aggregateResult.rows[0] as AdminSummaryAggregateRow | undefined;
    if (!aggregateSummary) throw new Error("Admin summary aggregate query returned no row.");
    await adminSummaryAfterFirstReadForTest?.();
    const topCategories = await tx.select({
      name: servicesTable.categoryName,
      count: count(),
    })
      .from(appointmentsTable)
      .innerJoin(servicesTable, eq(servicesTable.id, appointmentsTable.serviceId))
      .where(ne(servicesTable.categoryName, ""))
      .groupBy(servicesTable.categoryName)
      .orderBy(desc(count()), asc(servicesTable.categoryName))
      .limit(5);
    const deliveryReports = await deliveryReportStatuses(now, tx);
    return {
      topCategories,
      deliveryReports,
      aggregateSummary,
    };
  }, {
    isolationLevel: "repeatable read",
    accessMode: "read only",
  });

  const bookingsThisMonth = Number(aggregateSummary.bookingsThisMonth ?? 0);
  const bookingsLastMonth = Number(aggregateSummary.bookingsLastMonth ?? 0);
  const bookingsTrend = bookingsLastMonth > 0 ? Math.round(((bookingsThisMonth - bookingsLastMonth) / bookingsLastMonth) * 100) : 0;
  const newSalonsThisMonth = Number(aggregateSummary.newSalonsThisMonth ?? 0);
  const hiddenReviews = Number(aggregateSummary.hiddenReviews ?? 0);
  const activeSubscriptions = Number(aggregateSummary.activeSubscriptions ?? 0);
  const galleryCleanupOldestEligibleTicketAgeMinutes = timestampAgeMinutes(
    aggregateSummary.galleryCleanupOldestEligibleAt,
    now,
  );
  const schedulerJobs = schedulerHealthSnapshot();
  const schedulerDatabaseCapacity = schedulerDatabaseCapacitySnapshot();

  res.json(GetAdminSummaryResponse.parse({
    totalUsers: Number(aggregateSummary.totalUsers ?? 0),
    totalSalons: Number(aggregateSummary.totalSalons ?? 0),
    activeSalons: Number(aggregateSummary.activeSalons ?? 0),
    bookingsThisMonth,
    bookingsLastMonth,
    bookingsTrend,
    grossMerchandiseValue: Number(aggregateSummary.grossMerchandiseValue ?? 0),
    newSalonsThisMonth,
    totalReviews: Number(aggregateSummary.totalReviews ?? 0),
    hiddenReviews,
    activeSubscriptions,
    galleryCleanupFailedTickets: Number(aggregateSummary.galleryCleanupFailedTickets ?? 0),
    galleryCleanupFailureAttempts: Number(aggregateSummary.galleryCleanupFailureAttempts ?? 0),
    galleryCleanupOldestEligibleTicketAgeMinutes,
    galleryCleanupHasRepeatedFailures: aggregateSummary.galleryCleanupHasRepeatedFailures,
    // Same staleness signal as the integrations page — surfaces the
    // "Potrebna je intervencija" alert on the dashboard proactively.
    deliveryReportStaleProviders: staleDeliveryReportProviders(deliveryReports),
    // Same audience + phone predicate as the emergency-SMS send path (shared
    // helper) — zero means a total email outage would reach no administrator,
    // so the dashboard shows the same standing warning as the integrations page.
    smsFallbackReachableAdminCount: Number(aggregateSummary.smsFallbackReachableAdminCount ?? 0),
    schedulerJobs,
    schedulerDatabaseCapacity,
    topCategories,
  }));
});

// ── Admin helper ──────────────────────────────────────────────────────────────

async function requireAdmin(req: Request, res: Response) {
  const user = await current(req, res);
  if (!user) return null;
  if (!isAdmin(user)) { res.status(403).json({ error: "Pristup dozvoljen samo administratorima." }); return null; }
  return user;
}

async function requireSuperAdmin(req: Request, res: Response) {
  const user = await requireAdmin(req, res);
  if (!user) return null;
  if (user.role !== "SUPER_ADMIN") {
    res.status(403).json({ error: "Ova promena je dozvoljena samo super administratorima." });
    return null;
  }
  return user;
}

type AdminSummaryAggregateRow = {
  totalUsers: number;
  totalSalons: number;
  activeSalons: number;
  newSalonsThisMonth: number;
  bookingsThisMonth: number;
  bookingsLastMonth: number;
  grossMerchandiseValue: number;
  totalReviews: number;
  hiddenReviews: number;
  activeSubscriptions: number;
  galleryCleanupFailedTickets: number;
  galleryCleanupFailureAttempts: number;
  galleryCleanupOldestEligibleAt: Date | string | null;
  galleryCleanupHasRepeatedFailures: boolean;
  smsFallbackReachableAdminCount: number;
};

function educationSettingsView(settings: typeof educationPlatformSettingsTable.$inferSelect) {
  return {
    id: settings.id,
    commissionPercent: settings.commissionPercent,
    reservePercent: settings.reservePercent,
    onlineRefundDays: settings.onlineRefundDays,
    liveAppealDays: settings.liveAppealDays,
    featuredCoursePrice: settings.featuredCoursePrice,
    ipsRecipientName: settings.ipsRecipientName,
    ipsRecipientAccount: settings.ipsRecipientAccount,
    ipsAccountEnvironment: settings.ipsAccountEnvironment,
    ipsPurpose: settings.ipsPurpose,
    updatedAt: settings.updatedAt.toISOString(),
  };
}

