router.post("/admin/education/placements/:paymentReference/settle", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const paymentReference = decodeURIComponent(String(req.params.paymentReference));
  const [preview] = await db.select().from(educationPlacementsTable).where(eq(educationPlacementsTable.paymentReference, paymentReference)).limit(1);
  if (!preview) { res.status(404).json({ error: "Plasman nije pronađen." }); return; }
  const [previewCourse] = preview.courseId ? await db.select().from(coursesTable).where(eq(coursesTable.id, preview.courseId)).limit(1) : [];
  const centerId = preview.centerId ?? previewCourse?.centerId;
  if (!centerId) { res.status(409).json({ error: "Plasman nema važećeg vlasnika." }); return; }
  try {
    const settlement = await db.transaction(async (tx) => {
      await lockEducationCenterFinancials(tx, centerId);
      const [row] = await tx.select().from(educationPlacementsTable)
        .where(eq(educationPlacementsTable.paymentReference, paymentReference)).for("update").limit(1);
      if (!row) throw new Error("Plasman nije pronađen.");
      if (row.status === "active") return { placement: row, expired: false };
      if (row.status !== "pending_payment") throw new Error("Plasman nije u stanju za potvrdu uplate.");
      const now = new Date();
      if (row.createdAt.getTime() + EDUCATION_PLACEMENT_PAYMENT_WINDOW_MS <= now.getTime()) {
        const expired = await expireFeaturedPlacementPaymentInTx(tx, row, now);
        if (!expired.placement) throw new Error("Plasman je istovremeno izmenjen.");
        await recordEducationFinancialAudit(tx, {
          actorUserId: admin.id, action: "education_placement_payment_expired",
          entityType: "education_placement", entityId: row.id,
          oldValue: { status: row.status, priceSnapshot: row.priceSnapshot },
          newValue: { status: expired.placement.status, priceSnapshot: expired.placement.priceSnapshot },
          reason: "Rok za ručnu uplatu plasmana je istekao.",
        });
        return { placement: expired.placement, expired: true };
      }
      await lockEducationPlacementResource(tx, row.kind, row.scope, row.scopeCategoryId ?? row.scopeSubcategoryId);
      const scopeValid = row.scope === "home"
        ? !row.scopeCategoryId && !row.scopeSubcategoryId
        : row.scope === "category" ? Boolean(row.scopeCategoryId && !row.scopeSubcategoryId) : Boolean(row.scopeSubcategoryId && !row.scopeCategoryId);
      if (!scopeValid) throw new Error("Opseg plasmana nije važeći.");
      if (row.scope === "category") {
        const [category] = await tx.select({ id: courseCategoriesTable.id }).from(courseCategoriesTable)
          .where(and(eq(courseCategoriesTable.id, row.scopeCategoryId!), eq(courseCategoriesTable.active, true))).limit(1);
        if (!category) throw new Error("Kategorija plasmana više nije aktivna.");
      } else if (row.scope === "subcategory") {
        const [subcategory] = await tx.select({ id: educationSubcategoriesTable.id }).from(educationSubcategoriesTable)
          .where(and(eq(educationSubcategoriesTable.id, row.scopeSubcategoryId!), eq(educationSubcategoriesTable.active, true))).limit(1);
        if (!subcategory) throw new Error("Potkategorija plasmana više nije aktivna.");
      }
      if (row.kind === "special_offer") {
        const [targetCourse] = await tx.select().from(coursesTable).where(eq(coursesTable.id, row.courseId!)).limit(1);
        if (!targetCourse || !targetCourse.published || targetCourse.archived || !(await isPublicEducationCourse(targetCourse))) {
          throw new Error("Kurs specijalne ponude više nije javno dostupan.");
        }
        if ((row.scope === "category" && targetCourse.categoryId !== row.scopeCategoryId)
          || (row.scope === "subcategory" && targetCourse.subcategoryId !== row.scopeSubcategoryId)) {
          throw new Error("Kurs specijalne ponude više ne pripada izabranom opsegu.");
        }
      }
      const [conflict] = await tx.select({ id: educationPlacementsTable.id }).from(educationPlacementsTable).where(and(
        ne(educationPlacementsTable.id, row.id), eq(educationPlacementsTable.kind, row.kind), eq(educationPlacementsTable.scope, row.scope),
        eq(educationPlacementsTable.slotNumber, row.slotNumber), eq(educationPlacementsTable.status, "active"),
        row.scope === "category" ? eq(educationPlacementsTable.scopeCategoryId, row.scopeCategoryId!) : row.scope === "subcategory" ? eq(educationPlacementsTable.scopeSubcategoryId, row.scopeSubcategoryId!) : undefined,
        gt(educationPlacementsTable.endsAt, new Date()),
      )).limit(1);
      if (conflict) throw new Error("Slot je u međuvremenu zauzet.");
      const startsAt = now;
      const endsAt = addEducationBelgradeCalendarDays(startsAt, row.durationDaysSnapshot);
      const [updated] = await tx.update(educationPlacementsTable).set({
        status: "active", startsAt, endsAt, settledAt: startsAt, settledByUserId: admin.id, updatedAt: startsAt,
      }).where(and(eq(educationPlacementsTable.id, row.id), eq(educationPlacementsTable.status, "pending_payment"))).returning();
      if (!updated) throw new Error("Plasman je istovremeno izmenjen.");
      await recordEducationFinancialAudit(tx, {
        actorUserId: admin.id, action: "education_placement_settled",
        entityType: "education_placement", entityId: row.id,
        oldValue: { status: row.status, priceSnapshot: row.priceSnapshot, paymentReference: row.paymentReference },
        newValue: { status: updated.status, priceSnapshot: updated.priceSnapshot, startsAt, endsAt },
        reason: "Ručna potvrda uplate plasmana.",
      });
      return { placement: updated!, expired: false };
    });
    if (settlement.expired) {
      res.status(409).json({ error: "Rok za uplatu plasmana je istekao. Kreirajte novi zahtev." });
      return;
    }
    res.json(educationPlacementView(settlement.placement));
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Potvrda uplate nije uspela." });
  }
});

router.get("/admin/featured-placements", async (req, res): Promise<void> => {
  const admin = await requireAdmin(req, res); if (!admin) return;
  const parsed = ListAdminFeaturedPlacementsQueryParams.safeParse(req.query);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const page = parsed.data.page ?? 1;
  const pageSize = parsed.data.pageSize ?? 20;
  const statusPredicate = parsed.data.status ? eq(educationPlacementsTable.status, parsed.data.status) : undefined;
  const predicate = parsed.data.status === "pending_payment"
    ? and(
      statusPredicate,
      gt(educationPlacementsTable.createdAt, new Date(Date.now() - EDUCATION_PLACEMENT_PAYMENT_WINDOW_MS)),
    )
    : statusPredicate;
  const [[total], rows] = await Promise.all([
    db.select({ value: count() }).from(educationPlacementsTable).where(predicate),
    db.select().from(educationPlacementsTable).where(predicate)
      .orderBy(desc(educationPlacementsTable.createdAt), desc(educationPlacementsTable.id))
      .limit(pageSize).offset((page - 1) * pageSize),
  ]);
  res.json(ListAdminFeaturedPlacementsResponse.parse({
    items: await Promise.all(rows.map(featuredPlacementView)),
    page, pageSize, total: Number(total?.value ?? 0),
  }));
});

router.post("/admin/featured-placements/:placementId/confirm", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsed = ConfirmAdminFeaturedPlacementParams.safeParse(req.params);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  try {
    const settlement = await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`featured-placement:${parsed.data.placementId}`}))`);
      const [row] = await tx.select().from(educationPlacementsTable)
        .where(eq(educationPlacementsTable.id, parsed.data.placementId)).for("update").limit(1);
      if (!row) throw new Error("NOT_FOUND");
      // Returning the persisted row makes retries idempotent: dates and audit
      // actor are never recalculated after the first successful confirmation.
      if (row.status === "active") return { placement: row, activated: false, expired: false };
      if (row.status !== "pending_payment") throw new Error("Plasman nije u stanju za potvrdu uplate.");
      await lockEducationPlacementResource(tx, row.kind, row.scope, row.scopeCategoryId ?? row.scopeSubcategoryId);
      const now = new Date();
      if (row.createdAt.getTime() + EDUCATION_PLACEMENT_PAYMENT_WINDOW_MS <= now.getTime()) {
        const expired = await expireFeaturedPlacementPaymentInTx(tx, row, now);
        if (!expired.placement) throw new Error("Plasman je istovremeno izmenjen.");
        await recordEducationFinancialAudit(tx, {
          actorUserId: admin.id, action: "education_placement_payment_expired",
          entityType: "education_placement", entityId: row.id,
          oldValue: { status: row.status, priceSnapshot: row.priceSnapshot },
          newValue: { status: expired.placement.status, priceSnapshot: expired.placement.priceSnapshot },
          reason: "Rok za ručnu uplatu plasmana je istekao.",
        });
        return { placement: expired.placement, activated: false, expired: true };
      }
      await validateSharedPlacementScope(row.kind, row.scope, row.scopeCategoryId ?? row.scopeSubcategoryId, row.courseId);
      if (row.kind === "featured_center" && (!row.centerId || !(await educationCenterEligibility(row.centerId)).eligible)) {
        throw new Error("Edukativni centar više ne ispunjava uslove za javni marketplace.");
      }
      if (row.kind === "special_offer") {
        const [course] = await tx.select().from(coursesTable).where(eq(coursesTable.id, row.courseId!)).limit(1);
        if (!course || !course.published || course.archived || !(await isPublicEducationCourse(course))) {
          throw new Error("Kurs specijalne ponude više nije javno dostupan.");
        }
      }
      const endsAt = addEducationBelgradeCalendarDays(now, row.durationDaysSnapshot);
      const [updated] = await tx.update(educationPlacementsTable).set({
        status: "active", startsAt: now, endsAt, settledAt: now,
        settledByUserId: admin.id, updatedAt: now,
      }).where(and(
        eq(educationPlacementsTable.id, row.id),
        eq(educationPlacementsTable.status, "pending_payment"),
      )).returning();
      if (!updated) throw new Error("Plasman je istovremeno izmenjen.");
      await recordEducationFinancialAudit(tx, {
        actorUserId: admin.id, action: "education_placement_settled",
        entityType: "education_placement", entityId: row.id,
        oldValue: { status: row.status, priceSnapshot: row.priceSnapshot, paymentReference: row.paymentReference },
        newValue: { status: updated.status, priceSnapshot: updated.priceSnapshot, startsAt: now, endsAt },
        reason: "Ručna potvrda uplate plasmana.",
      });
      return { placement: updated, activated: true, expired: false };
    });
    if (settlement.expired) {
      res.status(409).json({ error: "Rok za uplatu plasmana je istekao. Kreirajte novi zahtev." });
      return;
    }
    if (settlement.activated && settlement.placement.kind === "featured_salon") {
      await publishCatalogInvalidation(["salons"]);
    }
    res.json(ConfirmAdminFeaturedPlacementResponse.parse({
      ...(await featuredPlacementView(settlement.placement)),
      activated: settlement.activated,
    }));
  } catch (error) {
    if (error instanceof Error && error.message === "NOT_FOUND") {
      res.status(404).json({ error: "Plasman nije pronađen." }); return;
    }
    res.status(409).json({ error: error instanceof Error ? error.message : "Potvrda uplate nije uspela." });
  }
});

