router.patch("/admin/education/settings", async (req, res): Promise<void> => {
  const user = await requireSuperAdmin(req, res); if (!user) return;
  const parseNumericInput = (value: unknown) =>
    typeof value === "string" && !value.trim() ? Number.NaN : Number(value);
  const featuredCoursePriceRaw = parseNumericInput(req.body?.featuredCoursePrice);
  const candidate = {
    commissionPercent: parseNumericInput(req.body?.commissionPercent),
    reservePercent: parseNumericInput(req.body?.reservePercent),
    onlineRefundDays: parseNumericInput(req.body?.onlineRefundDays),
    liveAppealDays: parseNumericInput(req.body?.liveAppealDays),
    featuredCoursePrice: Number.isInteger(featuredCoursePriceRaw) && featuredCoursePriceRaw >= 0 ? featuredCoursePriceRaw : 0,
    ipsRecipientName: typeof req.body?.ipsRecipientName === "string" && req.body.ipsRecipientName.trim() ? req.body.ipsRecipientName.trim() : null,
    ipsRecipientAccount: typeof req.body?.ipsRecipientAccount === "string" && req.body.ipsRecipientAccount.trim() ? req.body.ipsRecipientAccount.replace(/[\s-]/g, "") : null,
    ipsAccountEnvironment: req.body?.ipsAccountEnvironment === "test" ? "test" as const : "production" as const,
    ipsPurpose: typeof req.body?.ipsPurpose === "string" && req.body.ipsPurpose.trim() ? req.body.ipsPurpose.trim() : null,
  };
  if (![candidate.commissionPercent, candidate.reservePercent, candidate.onlineRefundDays, candidate.liveAppealDays, candidate.featuredCoursePrice].every((value) => Number.isInteger(value) && value >= 0)
    || candidate.commissionPercent + candidate.reservePercent > 100
    || candidate.onlineRefundDays > 365 || candidate.liveAppealDays > 365
    || (candidate.ipsRecipientAccount !== null && !/^\d{18}$/.test(candidate.ipsRecipientAccount))
    || [candidate.ipsRecipientName, candidate.ipsRecipientAccount, candidate.ipsPurpose].some((value) => value !== null && value.length > 140)) {
    res.status(400).json({ error: "Proverite procente i rokove. Zbir provizije i rezerve ne može preći 100%." });
    return;
  }
  try {
    const settings = await db.transaction(async (tx) => {
      await lockEducationBillingRules(tx, "exclusive");
      const currentSettings = await getEducationPlatformSettings(tx);
      const [invalidCenter] = await tx.select({ id: educationCentersTable.id })
        .from(educationCentersTable)
        .where(sql`
          coalesce(${educationCentersTable.commissionPercentOverride}, ${candidate.commissionPercent})
          + coalesce(${educationCentersTable.reservePercentOverride}, ${candidate.reservePercent}) > 100
        `)
        .limit(1);
      if (invalidCenter) {
        throw new Error("Globalna pravila bi za najmanje jedan centar dala zbir provizije i rezerve veći od 100%.");
      }
      const [saved] = await tx.update(educationPlatformSettingsTable).set({
        ...candidate, updatedByUserId: user.id, updatedAt: new Date(),
      }).where(eq(educationPlatformSettingsTable.id, currentSettings.id)).returning();
      await recordEducationFinancialAudit(tx, {
        actorUserId: user.id, action: "admin_education_platform_settings_changed",
        entityType: "education_platform_settings", entityId: currentSettings.id,
        oldValue: currentSettings,
        newValue: saved!,
        reason: "Administratorska promena globalnih Education finansijskih pravila.",
      });
      return saved!;
    });
    res.json(educationSettingsView(settings));
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Globalna pravila nisu sačuvana." });
  }
});

router.get("/admin/education/centers", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const [centers, subscriptions, plans, escrows] = await Promise.all([
    db.select().from(educationCentersTable).orderBy(desc(educationCentersTable.createdAt)),
    db.select().from(educationCenterSubscriptionsTable),
    db.select().from(subscriptionPlansTable),
    db.select().from(educationEscrowsTable),
  ]);
  const status = typeof req.query.status === "string" ? req.query.status : null;
  res.json(centers.filter((center) => !status || center.verificationStatus === status).map((center) => {
    const subscription = subscriptions.find((item) => item.centerId === center.id);
    const plan = plans.find((item) => item.id === subscription?.planId);
    const held = escrows.filter((item) => item.centerId === center.id && ["held", "frozen"].includes(item.status)).reduce((sum, item) => sum + item.netAmount, 0);
    return {
      id: center.id, name: center.name, city: center.city, description: center.description, imageUrl: center.imageUrl,
      pib: center.pib,
      verificationStatus: center.verificationStatus, verificationNote: center.verificationNote,
      verifiedAt: safeIsoTimestamp(center.verifiedAt), subscriptionStatus: subscription?.status ?? null,
      subscriptionPlanId: subscription?.planId ?? null, subscriptionPlan: plan?.name ?? null, heldAmount: held,
      createdAt: safeIsoTimestamp(center.createdAt),
    };
  }));
});

async function adminEducationCenterDetail(centerId: string) {
  const [center] = await db.select().from(educationCentersTable)
    .where(eq(educationCentersTable.id, centerId))
    .limit(1);
  if (!center) return null;
  const [subscriptions, plans, escrows, resolved, courses] = await Promise.all([
    db.select().from(educationCenterSubscriptionsTable).where(eq(educationCenterSubscriptionsTable.centerId, center.id)).limit(1),
    db.select().from(subscriptionPlansTable),
    db.select().from(educationEscrowsTable).where(eq(educationEscrowsTable.centerId, center.id)),
    resolveEducationBillingSettings(center.id, db, center),
    db.select({
      id: coursesTable.id,
      title: coursesTable.title,
      published: coursesTable.published,
      subscriptionSuspended: coursesTable.subscriptionSuspended,
    }).from(coursesTable)
      .where(and(eq(coursesTable.centerId, center.id), eq(coursesTable.archived, false)))
      .orderBy(asc(coursesTable.createdAt)),
  ]);
  const subscription = subscriptions[0];
  const plan = plans.find((item) => item.id === subscription?.planId);
  const reactivation = subscription && plan
    ? educationReactivationState({ subscription, plan, courses, now: new Date() })
    : null;
  const heldAmount = escrows
    .filter((item) => ["held", "frozen"].includes(item.status))
    .reduce((sum, item) => sum + item.netAmount, 0);
  return {
    id: center.id,
    name: center.name,
    city: center.city,
    description: center.description,
    pib: center.pib,
    contactEmail: center.contactEmail,
    contactPhone: center.contactPhone,
    verificationStatus: center.verificationStatus,
    verificationNote: center.verificationNote,
    verifiedAt: center.verifiedAt?.toISOString() ?? null,
    subscriptionStatus: subscription?.status ?? null,
    subscriptionPlanId: subscription?.planId ?? null,
    subscriptionPlan: plan?.name ?? null,
    deactivatedAt: subscription?.deactivatedAt?.toISOString() ?? null,
    reactivation,
    heldAmount,
    billingSettings: resolved.billingSettings,
  };
}

router.get("/admin/education/centers/:centerId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const detail = await adminEducationCenterDetail(String(req.params.centerId));
  if (!detail) { res.status(404).json({ error: "Edukativni centar nije pronađen." }); return; }
  res.json(detail);
});

router.patch("/admin/education/centers/:centerId", async (req, res): Promise<void> => {
  const user = await requireSuperAdmin(req, res); if (!user) return;
  const centerId = String(req.params.centerId);
  const [center] = await db.select().from(educationCentersTable).where(eq(educationCentersTable.id, centerId)).limit(1);
  if (!center) { res.status(404).json({ error: "Edukativni centar nije pronađen." }); return; }
  const verificationStatus = typeof req.body?.verificationStatus === "string" ? req.body.verificationStatus : center.verificationStatus;
  const allowedVerification = ["pending", "verified", "rejected", "suspended"];
  const subscriptionStatus = typeof req.body?.subscriptionStatus === "string" ? req.body.subscriptionStatus : undefined;
  const planId = typeof req.body?.planId === "string" ? req.body.planId : null;
  const allowedSubscription = ["trial", "active", "past_due", "cancelled", "suspended", "free_via_loyalty"];
  if (!allowedVerification.includes(verificationStatus) || (subscriptionStatus && !allowedSubscription.includes(subscriptionStatus))) {
    res.status(400).json({ error: "Status nije ispravan." }); return;
  }
  if (subscriptionStatus !== undefined) {
    res.status(409).json({ error: "Finansijski status pretplate nije moguće menjati kroz verifikaciju centra." }); return;
  }
  if ((subscriptionStatus || planId) && user.role !== "SUPER_ADMIN") {
    res.status(403).json({ error: "Samo super administrator može menjati finansijski status ili plan centra." }); return;
  }
  if (planId) {
    const [selectedPlan] = await db.select({ id: subscriptionPlansTable.id }).from(subscriptionPlansTable)
      .where(and(eq(subscriptionPlansTable.id, planId), eq(subscriptionPlansTable.active, true), eq(subscriptionPlansTable.audience, "education"))).limit(1);
    if (!selectedPlan) { res.status(400).json({ error: "Izabrani plan nije aktivan." }); return; }
  }
  const hasOwn = (key: string) => Object.prototype.hasOwnProperty.call(req.body ?? {}, key);
  const pib = hasOwn("pib")
    ? typeof req.body.pib === "string"
      ? req.body.pib.trim().slice(0, 50) || null
      : req.body.pib === null
        ? null
        : undefined
    : center.pib;
  if (hasOwn("pib") && pib === undefined) {
    res.status(400).json({ error: "PIB mora biti tekstualna vrednost ili null." }); return;
  }
  if (hasOwn("pib") && pib === null) {
    res.status(400).json({ error: "PIB aktivnog pravnog lica ne može biti uklonjen." }); return;
  }
  const billingOverrides = req.body?.billingOverrides;
  if (billingOverrides !== undefined && (!billingOverrides || typeof billingOverrides !== "object" || Array.isArray(billingOverrides))) {
    res.status(400).json({ error: "Pravila obračuna nisu ispravna." }); return;
  }
  const overrideLimits: Record<EducationBillingKey, number> = {
    commissionPercent: 100,
    reservePercent: 100,
    onlineRefundDays: 365,
    liveAppealDays: 365,
    featuredCoursePrice: 100_000_000,
  };
  const overrideUpdates: Partial<Record<(typeof educationBillingOverrideColumns)[EducationBillingKey], number | null>> = {};
  if (billingOverrides) {
    const unknownKeys = Object.keys(billingOverrides).filter((key) => !(key in educationBillingOverrideColumns));
    if (unknownKeys.length) {
      res.status(400).json({ error: "Nepoznato pravilo obračuna." }); return;
    }
    for (const key of Object.keys(educationBillingOverrideColumns) as EducationBillingKey[]) {
      if (!Object.prototype.hasOwnProperty.call(billingOverrides, key)) continue;
      const value = billingOverrides[key];
      if (value !== null && (!Number.isInteger(value) || value < 0 || value > overrideLimits[key])) {
        res.status(400).json({ error: "Vrednost pravila obračuna nije ispravna." }); return;
      }
      overrideUpdates[educationBillingOverrideColumns[key]] = value;
    }
  }
  let updated: typeof center | undefined;
  try {
    await db.transaction(async (tx) => {
      await lockEducationBillingRules(tx, "shared");
      // Verification changes and settlements must share the same center lock.
      // Otherwise a settlement can pass its eligibility check while a revocation
      // is waiting to commit, then create access and financial records anyway.
      await lockEducationCenterFinancials(tx, center.id);
      const [currentCenter] = await tx.select().from(educationCentersTable)
        .where(eq(educationCentersTable.id, center.id))
        .for("update")
        .limit(1);
      if (!currentCenter) throw new Error("Edukativni centar nije pronađen.");
      const currentVerificationStatus = verificationStatus as typeof currentCenter.verificationStatus;
      let normalizedPib = pib;
      if (pib) {
        const legalBinding = await bindLegalEntityBusinessInTx(tx, {
          pib, legalName: currentCenter.name, ownerUserId: currentCenter.ownerId,
          educationCenterId: currentCenter.id,
        });
        normalizedPib = legalBinding.normalizedPib;
      }
      const globalSettings = await getEducationPlatformSettings(tx);
      const effectiveCommissionOverride = Object.prototype.hasOwnProperty.call(overrideUpdates, "commissionPercentOverride")
        ? overrideUpdates.commissionPercentOverride!
        : currentCenter.commissionPercentOverride;
      const effectiveReserveOverride = Object.prototype.hasOwnProperty.call(overrideUpdates, "reservePercentOverride")
        ? overrideUpdates.reservePercentOverride!
        : currentCenter.reservePercentOverride;
      const effectiveCommission = effectiveCommissionOverride
        ?? globalSettings.commissionPercent;
      const effectiveReserve = effectiveReserveOverride
        ?? globalSettings.reservePercent;
      if (effectiveCommission + effectiveReserve > 100) {
        throw new Error("Zbir efektivne provizije i rezerve ne može preći 100%.");
      }
      [updated] = await tx.update(educationCentersTable).set({
        verificationStatus: currentVerificationStatus,
        verificationNote: typeof req.body?.verificationNote === "string" ? req.body.verificationNote.trim().slice(0, 1000) || null : currentCenter.verificationNote,
        verifiedAt: currentVerificationStatus === "verified" ? currentCenter.verifiedAt ?? new Date() : null,
        verifiedByUserId: currentVerificationStatus === "verified" ? currentCenter.verifiedByUserId ?? user.id : null,
        pib: normalizedPib,
        ...overrideUpdates,
        updatedAt: new Date(),
      }).where(eq(educationCentersTable.id, currentCenter.id)).returning();
      await recordEducationFinancialAudit(tx, {
        actorUserId: user.id, action: "admin_education_center_financial_settings_changed",
        entityType: "education_center", entityId: currentCenter.id,
        oldValue: {
          verificationStatus: currentCenter.verificationStatus,
          commissionPercentOverride: currentCenter.commissionPercentOverride,
          reservePercentOverride: currentCenter.reservePercentOverride,
          onlineRefundDaysOverride: currentCenter.onlineRefundDaysOverride,
          liveAppealDaysOverride: currentCenter.liveAppealDaysOverride,
          featuredCoursePriceOverride: currentCenter.featuredCoursePriceOverride,
        },
        newValue: {
          verificationStatus: updated!.verificationStatus,
          commissionPercentOverride: updated!.commissionPercentOverride,
          reservePercentOverride: updated!.reservePercentOverride,
          onlineRefundDaysOverride: updated!.onlineRefundDaysOverride,
          liveAppealDaysOverride: updated!.liveAppealDaysOverride,
          featuredCoursePriceOverride: updated!.featuredCoursePriceOverride,
        },
        reason: typeof req.body?.reason === "string" ? req.body.reason.trim().slice(0, 1000) : "Administratorska promena centra i njegovih finansijskih pravila.",
      });
      if (subscriptionStatus) {
        const [existing] = await tx.select().from(educationCenterSubscriptionsTable)
          .where(eq(educationCenterSubscriptionsTable.centerId, currentCenter.id))
          .for("update")
          .limit(1);
        if (existing) {
          await tx.update(educationCenterSubscriptionsTable).set({
            status: subscriptionStatus as typeof existing.status,
            ...(planId ? { planId } : {}),
            currentPeriodEnd: subscriptionStatus === "active" ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) : existing.currentPeriodEnd,
            updatedAt: new Date(),
          }).where(eq(educationCenterSubscriptionsTable.id, existing.id));
          await recordEducationFinancialAudit(tx, {
            actorUserId: user.id, action: "admin_education_subscription_status_changed",
            entityType: "education_center_subscription", entityId: existing.id,
            oldValue: { status: existing.status, planId: existing.planId, currentPeriodEnd: existing.currentPeriodEnd },
            newValue: { status: subscriptionStatus, planId: planId ?? existing.planId },
            reason: typeof req.body?.reason === "string" ? req.body.reason.trim().slice(0, 1000) : "Administratorska promena subscription statusa",
          });
        } else {
          const [fallbackPlan] = planId
            ? await tx.select().from(subscriptionPlansTable).where(eq(subscriptionPlansTable.id, planId)).limit(1)
            : await tx.select().from(subscriptionPlansTable).where(and(eq(subscriptionPlansTable.active, true), eq(subscriptionPlansTable.audience, "education"))).limit(1);
          if (!fallbackPlan) throw new Error("Pre aktivacije pretplate mora postojati aktivan plan.");
          await tx.insert(educationCenterSubscriptionsTable).values({
            centerId: currentCenter.id, planId: fallbackPlan.id, status: subscriptionStatus as "trial" | "active" | "past_due" | "cancelled" | "suspended" | "free_via_loyalty",
            dueAmount: fallbackPlan.price, currentPeriodEnd: subscriptionStatus === "active" ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) : null,
          });
        }
      }
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Izmena centra nije uspela.";
    res.status(message === "Edukativni centar nije pronađen." ? 404 : 409).json(error instanceof LegalEntityOwnerConflictError
      ? { error: message, code: error.code, normalizedPib: error.normalizedPib, outcome: "cross_account_conflict", conflictingOwnerCount: error.existingOwnerUserIds.length }
      : { error: message });
    return;
  }
  void publishCatalogInvalidation(["education-categories"]);
  const detail = await adminEducationCenterDetail(updated!.id);
  res.json(detail);
});

router.get("/admin/education/finance", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  await refreshMatureEducationEscrows();
  const centerId = typeof req.query.centerId === "string" ? req.query.centerId : null;
  const status = typeof req.query.status === "string" ? req.query.status : null;
  const [escrows, centers, enrollments, courses, disputes, payouts, featuredCharges] = await Promise.all([
    db.select().from(educationEscrowsTable).orderBy(desc(educationEscrowsTable.createdAt)),
    db.select().from(educationCentersTable),
    db.select().from(courseEnrollmentsTable),
    db.select().from(coursesTable),
    db.select().from(educationDisputesTable),
    db.select().from(educationPayoutsTable).orderBy(desc(educationPayoutsTable.createdAt)),
    db.select().from(educationFeaturedChargesTable).orderBy(desc(educationFeaturedChargesTable.createdAt)),
  ]);
  const filtered = escrows.filter((escrow) => (!centerId || escrow.centerId === centerId) && (!status || escrow.status === status));
  const rows = filtered.map((escrow) => {
    const enrollment = enrollments.find((item) => item.id === escrow.enrollmentId);
    const course = courses.find((item) => item.id === enrollment?.courseId);
    const center = centers.find((item) => item.id === escrow.centerId);
    const dispute = disputes.find((item) => item.enrollmentId === escrow.enrollmentId && ["open", "under_review"].includes(item.status));
    return {
      id: escrow.id, enrollmentId: escrow.enrollmentId, centerId: escrow.centerId, centerName: center?.name ?? "Obrisan centar",
      courseTitle: course?.title ?? "Arhivirana edukacija", grossAmount: escrow.grossAmount, platformFee: escrow.platformFee,
      reserveAmount: escrow.reserveAmount, netAmount: escrow.netAmount, status: escrow.status,
      releaseAt: safeIsoTimestamp(escrow.releaseAt), netPaidAt: safeIsoTimestamp(escrow.netPaidAt),
      reservePaidAt: safeIsoTimestamp(escrow.reservePaidAt), disputeOpen: Boolean(dispute), createdAt: safeIsoTimestamp(escrow.createdAt),
    };
  });
  res.json({
    summary: {
      held: rows.filter((row) => row.status === "held").reduce((sum, row) => sum + row.netAmount, 0),
      ready: rows.filter((row) => row.status === "ready_for_payout").reduce((sum, row) => sum + row.netAmount, 0),
      frozen: rows.filter((row) => row.status === "frozen").reduce((sum, row) => sum + row.netAmount, 0),
      paidOut: rows.filter((row) => row.status === "paid_out").reduce((sum, row) => sum + row.netAmount, 0),
    },
    escrows: rows,
    pendingEnrollments: enrollments.filter((enrollment) => enrollment.status === "pending" && enrollment.paymentStatus === "pending").map((enrollment) => {
      const course = courses.find((item) => item.id === enrollment.courseId);
      return { id: enrollment.id, courseTitle: course?.title ?? "Arhivirana edukacija", purchaserId: enrollment.purchaserId, amount: course?.price ?? 0, createdAt: safeIsoTimestamp(enrollment.purchasedAt) };
    }),
    payouts: payouts.map((payout) => ({ ...payout, paidAt: safeIsoTimestamp(payout.paidAt), createdAt: safeIsoTimestamp(payout.createdAt) })),
    featuredCharges: featuredCharges
      .filter((charge) => !centerId || charge.centerId === centerId)
      .map((charge) => {
        const course = courses.find((item) => item.id === charge.courseId);
        const center = centers.find((item) => item.id === charge.centerId);
        return {
          id: charge.id, courseId: charge.courseId, courseTitle: course?.title ?? "Arhivirana edukacija",
          centerName: center?.name ?? null, amount: charge.amount, status: charge.status,
          paymentReference: charge.paymentReference, activatedAt: safeIsoTimestamp(charge.activatedAt),
          settledAt: safeIsoTimestamp(charge.settledAt),
        };
      }),
  });
});

router.post("/admin/education/featured-charges/:chargeId/settle", async (req, res): Promise<void> => {
  const user = await requireSuperAdmin(req, res); if (!user) return;
  const chargeId = String(req.params.chargeId ?? "");
  const paymentReference = typeof req.body?.paymentReference === "string" && req.body.paymentReference.trim().length > 0
    ? req.body.paymentReference.trim().slice(0, 200)
    : null;
  const [charge] = await db.select().from(educationFeaturedChargesTable).where(eq(educationFeaturedChargesTable.id, chargeId)).limit(1);
  if (!charge) { res.status(404).json({ error: "Naplata isticanja nije pronađena." }); return; }
  if (charge.status !== "pending") { res.status(409).json({ error: "Ova naplata isticanja je već obrađena." }); return; }
  const updated = await db.transaction(async (tx) => {
    const [lockedCharge] = await tx.select().from(educationFeaturedChargesTable)
      .where(eq(educationFeaturedChargesTable.id, charge.id)).for("update").limit(1);
    if (!lockedCharge || lockedCharge.status !== "pending") return null;
    const now = new Date();
    const [settled] = await tx.update(educationFeaturedChargesTable).set({
      status: "paid", settledByUserId: user.id, settledAt: now,
      paymentReference: paymentReference ?? lockedCharge.paymentReference, updatedAt: now,
    }).where(and(eq(educationFeaturedChargesTable.id, lockedCharge.id), eq(educationFeaturedChargesTable.status, "pending"))).returning();
    if (!settled) throw new Error("Ova naplata isticanja je već obrađena.");
    await recordEducationFinancialAudit(tx, {
      actorUserId: user.id, action: "education_featured_charge_settled",
      entityType: "education_featured_charge", entityId: lockedCharge.id,
      oldValue: { status: lockedCharge.status, amount: lockedCharge.amount, centerId: lockedCharge.centerId },
      newValue: { status: settled.status, amount: settled.amount, centerId: settled.centerId },
      reason: "Ručna potvrda naplate isticanja.",
    });
    return settled;
  });
  if (!updated) { res.status(409).json({ error: "Ova naplata isticanja je već obrađena." }); return; }
  res.json({
    id: updated.id, courseId: updated.courseId, amount: updated.amount, status: updated.status,
    paymentReference: updated.paymentReference, activatedAt: updated.activatedAt.toISOString(),
    settledAt: updated.settledAt?.toISOString() ?? null,
  });
});

router.post("/admin/education/payouts", async (req, res): Promise<void> => {
  const user = await requireSuperAdmin(req, res); if (!user) return;
  await refreshMatureEducationEscrows();
  const centerId = typeof req.body?.centerId === "string" ? req.body.centerId : "";
  const includeReserve = req.body?.includeReserve === true;
  if (!centerId) { res.status(400).json({ error: "Izaberite edukativni centar." }); return; }
  if (includeReserve && (new Date().getUTCMonth() + 1) % 3 !== 0) {
    res.status(409).json({ error: "Rezerva se može evidentirati samo tokom poslednjeg meseca kvartala." }); return;
  }
  const today = new Date().toISOString().slice(0, 10);
  let payout: typeof educationPayoutsTable.$inferSelect;
  try {
    payout = await db.transaction(async (tx) => {
      // All financial operations for a center acquire this advisory lock before reading escrow rows.
      // It serializes payout and dispute-resolution decisions even when they target different enrollments.
      await lockEducationCenterFinancials(tx, centerId);
      const openDisputes = await tx.select({ id: educationDisputesTable.id }).from(educationDisputesTable)
        .innerJoin(courseEnrollmentsTable, eq(educationDisputesTable.enrollmentId, courseEnrollmentsTable.id))
        .innerJoin(coursesTable, eq(courseEnrollmentsTable.courseId, coursesTable.id))
        .where(and(eq(coursesTable.centerId, centerId), inArray(educationDisputesTable.status, ["open", "under_review"])));
      if (openDisputes.length) throw new Error("Isplata nije moguća dok centar ima otvoren spor.");
      const ready = await tx.select().from(educationEscrowsTable)
        .where(and(eq(educationEscrowsTable.centerId, centerId), eq(educationEscrowsTable.status, "ready_for_payout"), sql`${educationEscrowsTable.releaseAt} <= now()`))
        .for("update");
      const netEscrows = ready.filter((escrow) => !escrow.netPaidAt);
      const reserveEscrows = includeReserve ? ready.filter((escrow) => !escrow.reservePaidAt) : [];
      const amount = netEscrows.reduce((sum, escrow) => sum + escrow.netAmount, 0) + reserveEscrows.reduce((sum, escrow) => sum + escrow.reserveAmount, 0);
      if (!amount) throw new Error("Nema sredstava podobnih za isplatu.");
    const [created] = await tx.insert(educationPayoutsTable).values({
      centerId, amount, periodStart: today, periodEnd: today, status: "paid",
      reference: typeof req.body?.reference === "string" ? req.body.reference.trim().slice(0, 120) || null : null,
      note: typeof req.body?.note === "string" ? req.body.note.trim().slice(0, 2000) || null : null,
      createdByUserId: user.id, paidAt: new Date(),
    }).returning();
    for (const escrow of netEscrows) {
      const payReserve = reserveEscrows.some((item) => item.id === escrow.id);
      const [claimed] = await tx.update(educationEscrowsTable).set({
        netPaidAt: new Date(), ...(payReserve ? { reservePaidAt: new Date(), status: "paid_out" as const } : { status: "ready_for_payout" as const }), updatedAt: new Date(),
      }).where(and(eq(educationEscrowsTable.id, escrow.id), eq(educationEscrowsTable.status, "ready_for_payout"), sql`${educationEscrowsTable.netPaidAt} is null`, ...(payReserve ? [sql`${educationEscrowsTable.reservePaidAt} is null`] : []))).returning();
      if (!claimed) throw new Error("Escrow više nije podoban za isplatu.");
      await tx.insert(educationLedgerEntriesTable).values({ escrowId: escrow.id, enrollmentId: escrow.enrollmentId, centerId, type: "payout", amount: -escrow.netAmount, note: "Ručna isplata neto iznosa.", actorUserId: user.id, metadata: { payoutId: created!.id } });
      if (payReserve) await tx.insert(educationLedgerEntriesTable).values({ escrowId: escrow.id, enrollmentId: escrow.enrollmentId, centerId, type: "payout", amount: -escrow.reserveAmount, note: "Kvartalna isplata rezerve.", actorUserId: user.id, metadata: { payoutId: created!.id, reserve: true } });
    }
    for (const escrow of reserveEscrows.filter((item) => item.netPaidAt)) {
      const [claimed] = await tx.update(educationEscrowsTable).set({ reservePaidAt: new Date(), status: "paid_out", updatedAt: new Date() })
        .where(and(eq(educationEscrowsTable.id, escrow.id), eq(educationEscrowsTable.status, "ready_for_payout"), sql`${educationEscrowsTable.netPaidAt} is not null`, sql`${educationEscrowsTable.reservePaidAt} is null`)).returning();
      if (!claimed) throw new Error("Rezerva više nije podobna za isplatu.");
      await tx.insert(educationLedgerEntriesTable).values({ escrowId: escrow.id, enrollmentId: escrow.enrollmentId, centerId, type: "payout", amount: -escrow.reserveAmount, note: "Kvartalna isplata rezerve.", actorUserId: user.id, metadata: { payoutId: created!.id, reserve: true } });
    }
    await recordEducationFinancialAudit(tx, {
      actorUserId: user.id, action: "education_payout_created",
      entityType: "education_payout", entityId: created!.id,
      newValue: {
        centerId, amount: created!.amount, includeReserve,
        netEscrowCount: netEscrows.length, reserveEscrowCount: reserveEscrows.length,
      },
      reason: created!.note ?? "Ručna isplata Education sredstava.",
    });
    return created!;
    });
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Isplata nije moguća." });
    return;
  }
  res.status(201).json({ id: payout.id, centerId: payout.centerId, amount: payout.amount, status: payout.status, paidAt: payout.paidAt?.toISOString() ?? null });
});

router.patch("/admin/education/disputes/:disputeId", async (req, res): Promise<void> => {
  const user = await requireSuperAdmin(req, res); if (!user) return;
  const action = typeof req.body?.action === "string" ? req.body.action : "";
  const resolutionNote = typeof req.body?.resolutionNote === "string" ? req.body.resolutionNote.trim().slice(0, 4000) : "";
  if (!["refund", "release", "reject"].includes(action) || !resolutionNote) { res.status(400).json({ error: "Izaberite odluku i unesite obrazloženje." }); return; }
  const [disputePreview] = await db.select().from(educationDisputesTable).where(eq(educationDisputesTable.id, String(req.params.disputeId))).limit(1);
  if (!disputePreview) { res.status(404).json({ error: "Spor nije pronađen." }); return; }
  const [escrowPreview] = await db.select().from(educationEscrowsTable).where(eq(educationEscrowsTable.enrollmentId, disputePreview.enrollmentId)).limit(1);
  if (!escrowPreview) { res.status(409).json({ error: "Spor nema escrow zapis za rešavanje." }); return; }
  let resolution: { result: typeof educationDisputesTable.$inferSelect; enrollment: typeof courseEnrollmentsTable.$inferSelect };
  let promotedWaiter: typeof educationWaitlistTable.$inferSelect | null = null;
  try {
    resolution = await db.transaction(async (tx) => {
    await lockEducationCenterFinancials(tx, escrowPreview.centerId);
    const [dispute] = await tx.select().from(educationDisputesTable).where(eq(educationDisputesTable.id, disputePreview.id)).for("update").limit(1);
    const [enrollment] = await tx.select().from(courseEnrollmentsTable).where(eq(courseEnrollmentsTable.id, dispute!.enrollmentId)).for("update").limit(1);
    const [escrow] = await tx.select().from(educationEscrowsTable).where(eq(educationEscrowsTable.enrollmentId, dispute!.enrollmentId)).for("update").limit(1);
    if (!dispute || !enrollment || !escrow || !["open", "under_review"].includes(dispute.status)) throw new Error("Spor nije otvoren ili je već rešen.");
    if ((escrow.netPaidAt || escrow.reservePaidAt) && action === "reject") {
      const [rejected] = await tx.update(educationDisputesTable).set({
        status: "rejected", resolutionNote, resolvedByUserId: user.id, resolvedAt: new Date(), updatedAt: new Date(),
      }).where(and(eq(educationDisputesTable.id, dispute.id), inArray(educationDisputesTable.status, ["open", "under_review"]))).returning();
      if (!rejected) throw new Error("Spor je već izmenjen u drugoj operaciji.");
      const reconciledStatus = escrow.reservePaidAt ? "paid_out" : escrow.releaseAt <= new Date() ? "ready_for_payout" : "held";
      if (escrow.status === "frozen") {
        await tx.update(educationEscrowsTable).set({ status: reconciledStatus, updatedAt: new Date() })
          .where(and(eq(educationEscrowsTable.id, escrow.id), eq(educationEscrowsTable.status, "frozen"))).returning();
      }
      await tx.insert(educationFinancialEventsTable).values({
        escrowId: escrow.id, enrollmentId: dispute.enrollmentId, actorUserId: user.id,
        eventType: "dispute_rejected_after_payout", previousStatus: escrow.status, nextStatus: reconciledStatus, note: resolutionNote,
      });
      await recordEducationFinancialAudit(tx, {
        actorUserId: user.id, action: "education_dispute_rejected",
        entityType: "education_dispute", entityId: dispute.id,
        oldValue: { status: dispute.status, escrowStatus: escrow.status },
        newValue: { status: rejected.status, escrowStatus: reconciledStatus },
        reason: resolutionNote,
      });
      return { result: rejected, enrollment };
    }
    if (escrow.status !== "frozen" || escrow.netPaidAt || escrow.reservePaidAt) throw new Error("Ovaj escrow više nije u zamrznutom stanju i ne može se rešiti ovom odlukom.");
    const disputeStatus = action === "refund" ? "resolved_refund" : action === "release" ? "resolved_payout" : "rejected";
    const [updatedDispute] = await tx.update(educationDisputesTable).set({
      status: disputeStatus, resolutionNote, resolvedByUserId: user.id, resolvedAt: new Date(), updatedAt: new Date(),
    }).where(and(eq(educationDisputesTable.id, dispute.id), inArray(educationDisputesTable.status, ["open", "under_review"]))).returning();
    if (!updatedDispute) throw new Error("Spor je već izmenjen u drugoj operaciji.");
      const nextStatus = action === "refund" ? "refunded" : escrow.releaseAt <= new Date() ? "ready_for_payout" : "held";
      const [updatedEscrow] = await tx.update(educationEscrowsTable).set({ status: nextStatus, updatedAt: new Date() })
        .where(and(eq(educationEscrowsTable.id, escrow.id), eq(educationEscrowsTable.status, "frozen"), sql`${educationEscrowsTable.netPaidAt} is null`, sql`${educationEscrowsTable.reservePaidAt} is null`)).returning();
      if (!updatedEscrow) throw new Error("Escrow je izmenjen u drugoj finansijskoj operaciji.");
      await tx.insert(educationFinancialEventsTable).values({
        escrowId: escrow.id, enrollmentId: dispute.enrollmentId, actorUserId: user.id,
        eventType: `dispute_${action}`, previousStatus: escrow.status, nextStatus, amount: action === "refund" ? -escrow.grossAmount : null, note: resolutionNote,
      });
      if (action === "refund") {
        await tx.insert(educationLedgerEntriesTable).values({ escrowId: escrow.id, enrollmentId: dispute.enrollmentId, centerId: escrow.centerId, type: "refund", amount: -escrow.grossAmount, note: resolutionNote, actorUserId: user.id });
        await tx.update(courseEnrollmentsTable).set({ paymentStatus: "refunded", status: "cancelled", updatedAt: new Date() }).where(eq(courseEnrollmentsTable.id, enrollment.id));
        if (enrollment.userId) await recordEducationEnrollmentReferralTransitionInTx(tx, {
          enrollmentId: enrollment.id, studentUserId: enrollment.userId, centerId: escrow.centerId,
          occurredAt: new Date(), valid: false, reason: "admin_dispute_refund",
        });
        // Refunding a live seat frees capacity: release exactly one reserved
        // seat and promote exactly one waiter under this same center lock.
        if (enrollment.sessionId && Boolean((enrollment.auditData as { seatReserved?: boolean } | null)?.seatReserved)) {
          const [refundCourse] = await tx.select().from(coursesTable).where(eq(coursesTable.id, enrollment.courseId)).limit(1);
          if (refundCourse) promotedWaiter = await releaseSeatAndPromoteWaiter(tx, enrollment.sessionId, refundCourse);
        }
      }
    await recordEducationFinancialAudit(tx, {
      actorUserId: user.id, action: `education_dispute_${action}`,
      entityType: "education_dispute", entityId: dispute.id,
      oldValue: { status: dispute.status, escrowStatus: escrow.status, grossAmount: escrow.grossAmount },
      newValue: { status: updatedDispute.status, escrowStatus: nextStatus, refunded: action === "refund" },
      reason: resolutionNote,
    });
    return { result: updatedDispute, enrollment };
    });
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Odluka o sporu nije moguća." });
    return;
  }
  if (resolution.enrollment) {
    await sendTransactionalEmail({
      eventKey: `education-dispute:${resolution.result.id}:resolution`,
      emailType: "education_dispute_resolution",
      to: { email: (await db.select().from(usersTable).where(eq(usersTable.id, resolution.enrollment.purchaserId)).limit(1))[0]?.email ?? "", name: "LUMERA korisnik" },
      subject: "LUMERA Edukacije — odluka o prijavljenom problemu",
      htmlContent: lumeraEmailHtml("Odluka o prijavljenom problemu", `<p>${emailSafe(resolutionNote)}</p>`),
      metadata: { disputeId: resolution.result.id, enrollmentId: resolution.result.enrollmentId, action },
    });
  }
  const promoted: typeof educationWaitlistTable.$inferSelect | null = promotedWaiter;
  if (promoted && resolution.enrollment) {
    const [promotedCourse] = await db.select().from(coursesTable).where(eq(coursesTable.id, resolution.enrollment.courseId)).limit(1);
    if (promotedCourse) await notifyPromotedWaiter(promoted, promotedCourse);
  }
  res.json({ id: resolution.result.id, status: resolution.result.status, resolutionNote: resolution.result.resolutionNote, resolvedAt: resolution.result.resolvedAt?.toISOString() ?? null });
});

// Admin: cancel any session with full escrow refund and notifications.
router.post("/admin/education/sessions/:sessionId/cancel", async (req, res): Promise<void> => {
  const user = await requireSuperAdmin(req, res); if (!user) return;
  const sessionId = String(req.params.sessionId ?? "");
  const reason = typeof req.body?.reason === "string" ? req.body.reason.trim().slice(0, 500) : "";
  if (!reason) { res.status(400).json({ error: "Unesite razlog otkazivanja termina." }); return; }
  const [session] = await db.select().from(courseSessionsTable).where(eq(courseSessionsTable.id, sessionId)).limit(1);
  if (!session) { res.status(404).json({ error: "Termin nije pronađen." }); return; }
  if (session.cancelledAt) { res.status(409).json({ error: "Termin je već otkazan." }); return; }
  try {
    const result = await cancelEducationSession(sessionId, user.id, reason);
    res.json({ ok: true, ...result });
  } catch (error) {
    res.status(409).json({ error: error instanceof Error ? error.message : "Otkazivanje termina nije uspelo." });
  }
});

// Scheduled-job hook: auto-cancel sessions below minimum enrollment and drain
// expired waitlist offers. Protected by the shared admin session so it can be
// triggered by an authenticated admin or a cron caller.
router.post("/admin/education/sessions/process", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  try {
    const result = await processUpcomingEducationSessions();
    res.json({ ok: true, ...result });
  } catch (error) {
    res.status(500).json({ error: error instanceof Error ? error.message : "Obrada termina nije uspela." });
  }
});

// ── Admin Salons ──────────────────────────────────────────────────────────────

router.get("/admin/salons", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;

  const normalizedQuery = normalizeBooleanQuery(req.query, ["active", "featured"]);
  if (!normalizedQuery) { res.status(400).json({ error: "Boolean filteri prihvataju samo true ili false." }); return; }
  const parsedQuery = AdminListSalonsQueryParams.safeParse(normalizedQuery);
  if (!parsedQuery.success) { res.status(400).json({ error: parsedQuery.error.message }); return; }
  const { search, city, active, featured, subscriptionStatus } = parsedQuery.data;
  const { limit, offset } = parsePagination(req.query, 50);

  // Push ALL scalar predicates into SQL so they apply before pagination.
  const sqlPredicates = [];
  if (active !== undefined) sqlPredicates.push(eq(salonsTable.active, active));
  if (featured !== undefined) sqlPredicates.push(eq(salonsTable.featured, featured));
  if (city) sqlPredicates.push(eq(sql`lower(${salonsTable.city})`, city.toLowerCase()));
  if (search) {
    const term = `%${search}%`;
    sqlPredicates.push(or(ilike(salonsTable.name, term), ilike(salonsTable.city, term), ilike(salonsTable.email, term))!);
  }
  // subscriptionStatus was previously filtered in JS after LIMIT 500, which could
  // silently drop older matches. Move it into SQL as an EXISTS predicate so it is
  // applied before pagination. Semantics are unchanged: a salon matches when it
  // has a subscription row whose status equals the requested value.
  if (subscriptionStatus) {
    sqlPredicates.push(sql`exists (select 1 from ${subscriptionsTable} where ${subscriptionsTable.salonId} = ${salonsTable.id} and ${subscriptionsTable.status}::text = ${subscriptionStatus})`);
  }

  const salons = await db.select().from(salonsTable)
    .where(sqlPredicates.length ? and(...sqlPredicates) : undefined)
    .orderBy(desc(salonsTable.createdAt), desc(salonsTable.id))
    .limit(limit).offset(offset);

  if (!salons.length) { res.json([]); return; }

  const salonIds = salons.map((s) => s.id);
  const [subs, loyalties] = await Promise.all([
    db.select().from(subscriptionsTable)
      .innerJoin(subscriptionPlansTable, eq(subscriptionsTable.planId, subscriptionPlansTable.id))
      .where(inArray(subscriptionsTable.salonId, salonIds)),
    db.select().from(salonLoyaltyStatusesTable).where(inArray(salonLoyaltyStatusesTable.salonId, salonIds)),
  ]);

  // Fetch only the tier IDs referenced by the returned loyalty rows (not the full table).
  const tierIds = [...new Set(loyalties.flatMap((l) => (l.tierId ? [l.tierId] : [])))];
  const tiers = tierIds.length
    ? await db.select().from(loyaltyTiersTable).where(inArray(loyaltyTiersTable.id, tierIds))
    : [];

  const subBySalonId = new Map(subs.map((sub) => [sub.subscriptions.salonId, sub]));
  const loyaltyBySalonId = new Map(loyalties.map((l) => [l.salonId, l]));
  const tierById = new Map(tiers.map((t) => [t.id, t]));
  const result = salons.map((s) => {
    const sub = subBySalonId.get(s.id);
    const loyalty = loyaltyBySalonId.get(s.id);
    const tier = loyalty?.tierId ? tierById.get(loyalty.tierId) : undefined;
    return {
      id: s.id,
      name: s.name,
      slug: s.slug,
      city: s.city,
      active: s.active,
      featured: s.featured,
      isVerified: s.isVerified,
      topSalon: s.topSalon,
      videoUrl: s.videoUrl,
      rating: s.rating / 10,
      reviewCount: s.reviewCount,
      subscriptionStatus: sub?.subscriptions.status ?? null,
      subscriptionPlan: sub?.subscription_plans.name ?? null,
      loyaltyTier: tier?.name ?? null,
      loyaltySpend: loyalty?.currentPeriodSpend ?? 0,
      createdAt: safeIsoTimestamp(s.createdAt),
    };
  });

  res.json(result);
});

router.get("/admin/salons/:salonId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsedParams = AdminGetSalonParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const { salonId } = parsedParams.data;

  const [salon, subscriptions, loyaltyStatuses, orders] = await Promise.all([
    db.select().from(salonsTable).where(eq(salonsTable.id, salonId)).limit(1),
    db.select().from(subscriptionsTable)
      .innerJoin(subscriptionPlansTable, eq(subscriptionsTable.planId, subscriptionPlansTable.id))
      .where(eq(subscriptionsTable.salonId, salonId)),
    db.select().from(salonLoyaltyStatusesTable).where(eq(salonLoyaltyStatusesTable.salonId, salonId)).limit(1),
    db.select().from(ordersTable).where(eq(ordersTable.salonId, salonId)).orderBy(desc(ordersTable.createdAt)).limit(500),
  ]);
  const profile = salon[0];
  if (!profile) { res.status(404).json({ error: "Salon nije pronađen." }); return; }

  const subscription = subscriptions[0];
  const loyalty = loyaltyStatuses[0];
  // Fetch only the specific tier referenced by this salon's loyalty row.
  const tier = loyalty?.tierId
    ? (await db.select().from(loyaltyTiersTable).where(eq(loyaltyTiersTable.id, loyalty.tierId)).limit(1))[0]
    : undefined;
  const itemCounts = orders.length
    ? await db.select({
        orderId: orderItemsTable.orderId,
        itemCount: sql<number>`sum(${orderItemsTable.quantity})`,
      }).from(orderItemsTable).where(inArray(orderItemsTable.orderId, orders.map((order) => order.id))).groupBy(orderItemsTable.orderId)
    : [];
  const itemCountByOrder = new Map(itemCounts.map((item) => [item.orderId, Number(item.itemCount)]));
  const orderSummaries = orders.map((order) => ({
    id: order.id,
    createdAt: order.createdAt.toISOString(),
    status: order.status,
    paymentStatus: order.paymentStatus,
    deliveryMethod: order.deliveryMethod,
    total: order.total,
    itemCount: itemCountByOrder.get(order.id) ?? 0,
  }));

  res.json(AdminGetSalonResponse.parse({
    id: profile.id,
    name: profile.name,
    slug: profile.slug,
    city: profile.city,
    address: profile.address,
    postalCode: profile.postalCode ?? null,
    phone: profile.phone,
    email: profile.email,
    active: profile.active,
    featured: profile.featured,
    isVerified: profile.isVerified,
    topSalon: profile.topSalon,
    videoUrl: profile.videoUrl,
    rating: profile.rating / 10,
    reviewCount: profile.reviewCount,
    subscriptionStatus: subscription?.subscriptions.status ?? null,
    subscriptionPlan: subscription?.subscription_plans.name ?? null,
    loyaltyTier: tier?.name ?? null,
    loyaltySpend: loyalty?.currentPeriodSpend ?? 0,
    createdAt: profile.createdAt.toISOString(),
    orderCount: orders.length,
    orderTotal: orders.reduce((sum, order) => sum + order.total, 0),
    orders: orderSummaries,
  }));
});

router.patch("/admin/salons/:salonId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsedParams = AdminUpdateSalonParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const { salonId } = parsedParams.data;
  const parsed = AdminUpdateSalonBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const { active, featured, isVerified, topSalon, videoUrl, pib } = parsed.data;
  if (videoUrl !== undefined && !isHttpVideoUrl(videoUrl)) { res.status(400).json({ error: "Video URL mora početi sa http:// ili https://." }); return; }

  const [salon] = await db.select().from(salonsTable).where(eq(salonsTable.id, salonId)).limit(1);
  if (!salon) { res.status(404).json({ error: "Salon nije pronađen." }); return; }

  const isDeactivating = active === false && salon.active;
  if (isDeactivating) {
    try {
      await requireMediaCachePurgeForVisibilityRevocation();
    } catch (error) {
      res.status(503).json({
        error: error instanceof Error ? error.message : "Nije moguće bezbedno deaktivirati salon dok se ne podesi brisanje keša fotografija.",
      });
      return;
    }
  }

  const updates: Partial<typeof salonsTable.$inferInsert> = {};
  if (active !== undefined) updates.active = active;
  if (featured !== undefined) updates.featured = featured;
  if (isVerified !== undefined) updates.isVerified = isVerified;
  if (topSalon !== undefined) updates.topSalon = topSalon;
  if (videoUrl !== undefined) updates.videoUrl = videoUrl;
  if (pib !== undefined) updates.companyTaxId = pib;

  let legalConflict: LegalEntityOwnerConflictError | null = null;
  const updateResult = await db.transaction(async (tx) => {
    if (pib !== undefined) {
      const legalBinding = await bindLegalEntityBusinessInTx(tx, {
        pib, legalName: salon.companyName ?? salon.name, ownerUserId: salon.ownerId, salonId: salon.id,
      });
      updates.companyTaxId = legalBinding.normalizedPib;
    }
    const rows = await tx.update(salonsTable).set(updates).where(eq(salonsTable.id, salonId)).returning();
    const changed = rows[0]!;
    const changedAssetIds = await publishActiveSalonMediaReferences({
      salonId: changed.id,
      ownerUserId: changed.ownerId,
      active: changed.active,
      imageUrl: changed.imageUrl,
      gallery: changed.gallery,
    }, tx);
    return [changed, changedAssetIds] as const;
  }).catch((error: unknown) => {
    if (error instanceof LegalEntityOwnerConflictError) {
      legalConflict = error;
      return null;
    }
    throw error;
  });
  if (!updateResult) {
    res.status(409).json({
      error: legalConflict!.message, code: legalConflict!.code,
      normalizedPib: legalConflict!.normalizedPib, outcome: "cross_account_conflict",
      conflictingOwnerCount: legalConflict!.existingOwnerUserIds.length,
    });
    return;
  }
  const [updated, changedMediaAssetIds] = updateResult;

  if (isDeactivating && changedMediaAssetIds.length) {
    try {
      await purgeMediaCacheForVisibilityRevocation(changedMediaAssetIds);
    } catch (error) {
      req.log.error({ err: error, salonId, assetIds: changedMediaAssetIds }, "Could not purge cached salon media during deactivation");
      const [restored] = await db.transaction(async (tx) => {
        const rows = await tx.update(salonsTable)
          .set({ active: salon.active })
          .where(and(eq(salonsTable.id, salonId), eq(salonsTable.active, updated.active)))
          .returning();
        const restoredSalon = rows[0];
        if (restoredSalon) {
          await publishActiveSalonMediaReferences({
            salonId: restoredSalon.id,
            ownerUserId: restoredSalon.ownerId,
            active: restoredSalon.active,
            imageUrl: restoredSalon.imageUrl,
            gallery: restoredSalon.gallery,
          }, tx);
        }
        return rows;
      });
      if (!restored) {
        req.log.error({ salonId }, "Could not restore salon visibility after a failed media cache purge");
      }
      res.status(502).json({
        error: restored
          ? "Deaktivacija nije uspela jer keš fotografija nije mogao da se obriše. Salon je vraćen u prethodno stanje."
          : "Keš fotografija nije mogao da se obriše, a vraćanje statusa salona nije potvrđeno. Potrebna je hitna administratorska provera.",
      });
      return;
    }
  }

  // Only after a successful mutation that can affect salon discovery visibility
  // (active/featured/isVerified/topSalon) do we invalidate the shared catalog
  // "salons" tag consumed by /discovery/home. videoUrl-only changes do not.
  if (active !== undefined || featured !== undefined || isVerified !== undefined || topSalon !== undefined) {
    void publishCatalogInvalidation(["salons"]);
  }

  const [subs, loyalties, tiers] = await Promise.all([
    db.select().from(subscriptionsTable)
      .innerJoin(subscriptionPlansTable, eq(subscriptionsTable.planId, subscriptionPlansTable.id))
      .where(eq(subscriptionsTable.salonId, salonId)),
    db.select().from(salonLoyaltyStatusesTable).where(eq(salonLoyaltyStatusesTable.salonId, salonId)),
    db.select().from(loyaltyTiersTable),
  ]);
  const sub = subs[0];
  const loyalty = loyalties[0];
  const tier = tiers.find((t) => t.id === loyalty?.tierId);

  res.json({
    id: updated!.id,
    name: updated!.name,
    slug: updated!.slug,
    city: updated!.city,
    active: updated!.active,
    featured: updated!.featured,
    isVerified: updated!.isVerified,
    topSalon: updated!.topSalon,
    videoUrl: updated!.videoUrl,
    rating: updated!.rating / 10,
    reviewCount: updated!.reviewCount,
    subscriptionStatus: sub?.subscriptions.status ?? null,
    subscriptionPlan: sub?.subscription_plans.name ?? null,
    loyaltyTier: tier?.name ?? null,
    loyaltySpend: loyalty?.currentPeriodSpend ?? 0,
    createdAt: updated!.createdAt.toISOString(),
  });
});

// ── Admin Users ───────────────────────────────────────────────────────────────

router.get("/admin/users", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;

  const normalizedQuery = normalizeBooleanQuery(req.query, ["active"]);
  if (!normalizedQuery) { res.status(400).json({ error: "Boolean filter prihvata samo true ili false." }); return; }
  const parsedQuery = AdminListUsersQueryParams.safeParse(normalizedQuery);
  if (!parsedQuery.success) { res.status(400).json({ error: parsedQuery.error.message }); return; }
  const { search, role, active } = parsedQuery.data;
  const { limit, offset } = parsePagination(req.query, 50);

  // Push ALL scalar predicates into SQL so they apply before pagination.
  const sqlPredicates = [];
  if (role) sqlPredicates.push(eq(usersTable.role, role as typeof usersTable.role["_"]["data"]));
  if (active !== undefined) sqlPredicates.push(eq(usersTable.active, active));
  if (search) {
    const term = `%${search}%`;
    sqlPredicates.push(or(
      ilike(usersTable.email, term),
      ilike(usersTable.firstName, term),
      ilike(usersTable.lastName, term),
      sql`lower(${usersTable.firstName} || ' ' || ${usersTable.lastName}) like lower(${term})`,
    )!);
  }

  const users = await db.select().from(usersTable)
    .where(sqlPredicates.length ? and(...sqlPredicates) : undefined)
    .orderBy(desc(usersTable.createdAt), desc(usersTable.id))
    .limit(limit).offset(offset);

  res.json(users.map((u) => ({
    id: u.id,
    firstName: u.firstName,
    lastName: u.lastName,
    email: u.email,
    phone: u.phone,
    role: u.role,
    active: u.active,
    passwordSetAt: safeIsoTimestamp(u.passwordSetAt),
    createdAt: safeIsoTimestamp(u.createdAt),
  })));
});

router.post("/admin/customers/setup", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const admitted = await admitCustomerSetupRequest("issue", admin.id, 10, 60 * 60 * 1000);
  if (!admitted) {
    res.setHeader("Retry-After", "3600");
    res.status(429).json({ error: "Previše zahteva. Pokušajte ponovo kasnije." });
    return;
  }
  const parsed = AdminCreateCustomerSetupBody.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Unesite ispravno ime, prezime i e-mail adresu." });
    return;
  }
  const email = parsed.data.email.trim().toLowerCase();
  const firstName = parsed.data.firstName.trim();
  const lastName = parsed.data.lastName.trim();
  if (!firstName || !lastName) {
    res.status(400).json({ error: "Ime i prezime su obavezni." });
    return;
  }

  const rawToken = randomBytes(32).toString("base64url");
  const tokenHash = customerSetupDigest(rawToken);
  const passwordHash = await hashPassword(randomBytes(32).toString("base64url"));
  const expiresAt = new Date(Date.now() + CUSTOMER_SETUP_TTL_MS);
  const setupBaseUrl = customerSetupBaseUrl(req);
  try {
    const customer = await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${email}))`);
      const [existing] = await tx.select({ id: usersTable.id })
        .from(usersTable)
        .where(sql`lower(${usersTable.email}) = ${email}`)
        .limit(1);
      if (existing) return null;
      const [created] = await tx.insert(usersTable).values({
        firstName,
        lastName,
        email,
        passwordHash,
        passwordSetAt: null,
        role: "CUSTOMER",
        active: true,
        mustChangePassword: false,
      }).returning();
      if (!created) throw new Error("Customer account insert returned no row.");

      await tx.update(customerPasswordSetupTokensTable)
        .set({ invalidatedAt: new Date() })
        .where(and(
          eq(customerPasswordSetupTokensTable.userId, created.id),
          isNull(customerPasswordSetupTokensTable.consumedAt),
          isNull(customerPasswordSetupTokensTable.invalidatedAt),
        ));
      await tx.insert(customerPasswordSetupTokensTable).values({
        userId: created.id,
        issuedByUserId: admin.id,
        tokenHash,
        expiresAt,
        maxAttempts: CUSTOMER_SETUP_MAX_ATTEMPTS,
      });
      await tx.insert(customerPasswordSetupAuditsTable).values({
        administratorUserId: admin.id,
        targetUserId: created.id,
        action: "CUSTOMER_CREATED",
      });
      return created;
    });
    if (!customer) {
      res.status(409).json({ error: "Korisnik sa ovom e-mail adresom već postoji." });
      return;
    }
    const setupUrl = `${setupBaseUrl}/postavi-lozinku#token=${encodeURIComponent(rawToken)}`;
    res.status(201).json({
      user: {
        id: customer.id,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email,
        phone: customer.phone,
        role: customer.role,
        active: customer.active,
        passwordSetAt: customer.passwordSetAt?.toISOString() ?? null,
        createdAt: customer.createdAt.toISOString(),
      },
      setupUrl,
      expiresAt: expiresAt.toISOString(),
    });
  } catch (error) {
    if ((error as { code?: string }).code === "23505") {
      res.status(409).json({ error: "Korisnik sa ovom e-mail adresom već postoji." });
      return;
    }
    throw error;
  }
});

type AdminBusinessAccountSetupInput = {
  firstName: string;
  lastName: string;
  email: string;
  role: "ADMIN" | "SALON_OWNER" | "SALON_EMPLOYEE" | "EDUKATIVNI_CENTAR" | "INSTRUCTOR" | "CUSTOMER" | "STUDENT" | "JOBSEEKER";
  salon?: {
    name: string; slug: string; city: string; municipality: string; address: string;
    postalCode?: string; phone: string; email: string; companyName: string;
    companyTaxId: string; companyRegistrationNumber: string; companyAddress: string;
    companyCity: string; companyPostalCode?: string; shortDescription: string; description: string;
  };
  employee?: { salonId: string; jobTitle: string; bio?: string };
  educationCenter?: {
    name: string; city: string; description: string; contactEmail: string;
    contactPhone: string; contactAddress: string; pib: string;
  };
  instructor?: {
    centerId: string; biography?: string; industryYears?: number; experienceYears?: number;
    specializations?: string[]; qualifications?: string[];
  };
};

const adminAccountRoleObjects = ["salon", "employee", "educationCenter", "instructor"] as const;
const adminAccountRoles = new Set<AdminBusinessAccountSetupInput["role"]>([
  "ADMIN", "SALON_OWNER", "SALON_EMPLOYEE", "EDUKATIVNI_CENTAR", "INSTRUCTOR", "CUSTOMER", "STUDENT", "JOBSEEKER",
]);
const adminAccountRoleObject: Partial<Record<AdminBusinessAccountSetupInput["role"], typeof adminAccountRoleObjects[number]>> = {
  SALON_OWNER: "salon",
  SALON_EMPLOYEE: "employee",
  EDUKATIVNI_CENTAR: "educationCenter",
  INSTRUCTOR: "instructor",
};
const uuidInputPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const emailInputPattern = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

type BusinessMutationResource = { kind: "salon" | "education-center"; id: string };

/**
 * Global lock protocol for account/business graph mutations. Every caller
 * locks resources first and users second, each lexically, before taking row
 * locks. Resource owners may be discovered after resource advisory locks but
 * before the user phase, which prevents transfer-vs-conversion lock inversion.
 */
async function lockBusinessMutationParticipants(
  tx: MarketplaceTransaction,
  input: {
    userIds: string[];
    resources?: BusinessMutationResource[];
    discoverUserIds?: () => Promise<string[]>;
  },
) {
  const resourceKeys = [...new Set((input.resources ?? []).map((resource) =>
    `business-resource:${resource.kind}:${resource.id}`))].sort();
  for (const key of resourceKeys) {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${key}))`);
  }
  const discovered = input.discoverUserIds ? await input.discoverUserIds() : [];
  const userIds = [...new Set([...input.userIds, ...discovered])].sort();
  for (const id of userIds) {
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`business-conversion:${id}`}))`);
  }
  return userIds;
}

function isRecordInput(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function hasOnlyKeys(value: Record<string, unknown>, allowed: readonly string[]): boolean {
  return Object.keys(value).every((key) => allowed.includes(key));
}

function nonBlankInput(value: unknown, maxLength = 2000): value is string {
  return typeof value === "string" && value.trim().length > 0 && value.length <= maxLength;
}

function optionalTextInput(value: unknown, maxLength = 2000): value is string | undefined {
  return value === undefined || (typeof value === "string" && value.length <= maxLength);
}

function validPibInput(value: unknown): value is string {
  if (!nonBlankInput(value, 50)) return false;
  const digits = value.replace(/\D/g, "");
  return digits.length >= 8 && digits.length <= 14;
}

function parseAdminAccountSetupInput(value: unknown): AdminBusinessAccountSetupInput | null {
  if (!isRecordInput(value) || !hasOnlyKeys(value, [
    "firstName", "lastName", "email", "role", ...adminAccountRoleObjects,
  ])) return null;
  if (!nonBlankInput(value.firstName, 100) || !nonBlankInput(value.lastName, 100)
    || !nonBlankInput(value.email, 320) || !emailInputPattern.test(value.email)
    || typeof value.role !== "string" || !adminAccountRoles.has(value.role as AdminBusinessAccountSetupInput["role"])) return null;
  const role = value.role as AdminBusinessAccountSetupInput["role"];
  const expectedObject = adminAccountRoleObject[role];
  const presentObjects = adminAccountRoleObjects.filter((key) => Object.prototype.hasOwnProperty.call(value, key));
  if ((expectedObject && (presentObjects.length !== 1 || presentObjects[0] !== expectedObject))
    || (!expectedObject && presentObjects.length !== 0)) return null;

  const common = {
    firstName: value.firstName.trim(), lastName: value.lastName.trim(),
    email: value.email.trim().toLowerCase(), role,
  };
  if (role === "SALON_OWNER") {
    const salon = value.salon;
    const required = [
      "name", "slug", "city", "municipality", "address", "phone", "email", "companyName",
      "companyTaxId", "companyRegistrationNumber", "companyAddress", "companyCity",
      "shortDescription", "description",
    ] as const;
    if (!isRecordInput(salon) || !hasOnlyKeys(salon, [...required, "postalCode", "companyPostalCode"])
      || required.some((key) => !nonBlankInput(salon[key], key === "description" ? 4000 : 500))
      || !validPibInput(salon.companyTaxId)
      || !emailInputPattern.test(salon.email as string)
      || !optionalTextInput(salon.postalCode, 50) || !optionalTextInput(salon.companyPostalCode, 50)) return null;
    return { ...common, role, salon: {
      name: (salon.name as string).trim(), slug: (salon.slug as string).trim(),
      city: (salon.city as string).trim(), municipality: (salon.municipality as string).trim(),
      address: (salon.address as string).trim(), postalCode: (salon.postalCode as string | undefined)?.trim(),
      phone: (salon.phone as string).trim(), email: (salon.email as string).trim().toLowerCase(),
      companyName: (salon.companyName as string).trim(), companyTaxId: (salon.companyTaxId as string).trim(),
      companyRegistrationNumber: (salon.companyRegistrationNumber as string).trim(),
      companyAddress: (salon.companyAddress as string).trim(), companyCity: (salon.companyCity as string).trim(),
      companyPostalCode: (salon.companyPostalCode as string | undefined)?.trim(),
      shortDescription: (salon.shortDescription as string).trim(), description: (salon.description as string).trim(),
    } };
  }
  if (role === "SALON_EMPLOYEE") {
    const employee = value.employee;
    if (!isRecordInput(employee) || !hasOnlyKeys(employee, ["salonId", "jobTitle", "bio"])
      || typeof employee.salonId !== "string" || !uuidInputPattern.test(employee.salonId)
      || !nonBlankInput(employee.jobTitle, 200) || !optionalTextInput(employee.bio, 4000)) return null;
    return { ...common, role, employee: {
      salonId: employee.salonId, jobTitle: employee.jobTitle.trim(),
      bio: (employee.bio as string | undefined)?.trim(),
    } };
  }
  if (role === "EDUKATIVNI_CENTAR") {
    const center = value.educationCenter;
    const required = ["name", "city", "description", "contactEmail", "contactPhone", "contactAddress", "pib"] as const;
    if (!isRecordInput(center) || !hasOnlyKeys(center, required)
      || required.some((key) => !nonBlankInput(center[key], key === "description" ? 4000 : 500))
      || !validPibInput(center.pib)
      || !emailInputPattern.test(center.contactEmail as string)) return null;
    return { ...common, role, educationCenter: {
      name: (center.name as string).trim(), city: (center.city as string).trim(),
      description: (center.description as string).trim(), contactEmail: (center.contactEmail as string).trim().toLowerCase(),
      contactPhone: (center.contactPhone as string).trim(), contactAddress: (center.contactAddress as string).trim(),
      pib: (center.pib as string).trim(),
    } };
  }
  if (role === "INSTRUCTOR") {
    const instructor = value.instructor;
    if (!isRecordInput(instructor) || !hasOnlyKeys(instructor, [
      "centerId", "biography", "industryYears", "experienceYears", "specializations", "qualifications",
    ]) || typeof instructor.centerId !== "string" || !uuidInputPattern.test(instructor.centerId)
      || !optionalTextInput(instructor.biography, 4000)
      || (instructor.industryYears !== undefined && (!Number.isInteger(instructor.industryYears) || (instructor.industryYears as number) < 0))
      || (instructor.experienceYears !== undefined && (!Number.isInteger(instructor.experienceYears) || (instructor.experienceYears as number) < 0))
      || !["specializations", "qualifications"].every((key) => instructor[key] === undefined
        || (Array.isArray(instructor[key]) && (instructor[key] as unknown[]).every((item) => nonBlankInput(item, 200))))) return null;
    return { ...common, role, instructor: {
      centerId: instructor.centerId, biography: (instructor.biography as string | undefined)?.trim(),
      industryYears: instructor.industryYears as number | undefined,
      experienceYears: instructor.experienceYears as number | undefined,
      specializations: (instructor.specializations as string[] | undefined)?.map((item) => item.trim()),
      qualifications: (instructor.qualifications as string[] | undefined)?.map((item) => item.trim()),
    } };
  }
  return common;
}

function parseAdminBusinessConversionInput(value: unknown): AdminBusinessAccountSetupInput | null {
  if (!isRecordInput(value)
    || !hasOnlyKeys(value, ["role", ...adminAccountRoleObjects])
    || typeof value.role !== "string"
    || !adminAccountRoleObject[value.role as AdminBusinessAccountSetupInput["role"]]) return null;
  return parseAdminAccountSetupInput({
    firstName: "Existing",
    lastName: "Account",
    email: "existing-account@lumera.invalid",
    ...value,
  });
}

router.post("/admin/accounts/setup", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  if (!isRecordInput(req.body)
    || !nonBlankInput(req.body.firstName, 100) || !nonBlankInput(req.body.lastName, 100)
    || !nonBlankInput(req.body.email, 320) || !emailInputPattern.test(req.body.email)
    || typeof req.body.role !== "string"
    || !adminAccountRoles.has(req.body.role as AdminBusinessAccountSetupInput["role"])) {
    res.status(400).json({ error: "Unesite ispravne osnovne podatke naloga." });
    return;
  }
  const parsed = parseAdminAccountSetupInput(req.body);
  if (!parsed) { res.status(422).json({ error: "Unesite tačno one poslovne podatke koji odgovaraju izabranoj ulozi." }); return; }
  const admitted = await admitCustomerSetupRequest("issue", admin.id, 10, 60 * 60 * 1000);
  if (!admitted) { res.setHeader("Retry-After", "3600"); res.status(429).json({ error: "Previše zahteva. Pokušajte ponovo kasnije." }); return; }
  const { email, firstName, lastName } = parsed;
  const rawToken = randomBytes(32).toString("base64url");
  const expiresAt = new Date(Date.now() + CUSTOMER_SETUP_TTL_MS);
  const setupBaseUrl = customerSetupBaseUrl(req);
  const passwordHash = await hashPassword(randomBytes(32).toString("base64url"));
  try {
    const account = await db.transaction(async (tx) => {
      await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`account-setup:${email}`}))`);
      const [existing] = await tx.select({ id: usersTable.id }).from(usersTable)
        .where(sql`lower(${usersTable.email}) = ${email}`).limit(1);
      if (existing) return null;
      const createdUserId = randomUUID();
      const resources: BusinessMutationResource[] = parsed.role === "SALON_EMPLOYEE"
        ? [{ kind: "salon", id: parsed.employee!.salonId }]
        : parsed.role === "INSTRUCTOR"
          ? [{ kind: "education-center", id: parsed.instructor!.centerId }]
          : [];
      // Resource advisory locks always precede owner/new-account locks. This
      // shares the transition/conversion protocol and prevents setup from
      // holding a new user row while waiting on a transferred resource.
      await lockBusinessMutationParticipants(tx, {
        userIds: [createdUserId],
        resources,
        discoverUserIds: async () => {
          if (parsed.role === "SALON_EMPLOYEE") {
            const [resource] = await tx.select({ ownerId: salonsTable.ownerId }).from(salonsTable)
              .where(eq(salonsTable.id, parsed.employee!.salonId)).limit(1);
            return resource ? [resource.ownerId] : [];
          }
          if (parsed.role === "INSTRUCTOR") {
            const [resource] = await tx.select({ ownerId: educationCentersTable.ownerId }).from(educationCentersTable)
              .where(eq(educationCentersTable.id, parsed.instructor!.centerId)).limit(1);
            return resource ? [resource.ownerId] : [];
          }
          return [];
        },
      });
      const [created] = await tx.insert(usersTable).values({
        id: createdUserId, firstName, lastName, email, passwordHash, passwordSetAt: null,
        role: parsed.role, active: true, mustChangePassword: false,
      }).returning();
      if (!created) throw new Error("Account insert returned no row.");
      if (parsed.role === "SALON_OWNER") {
        const input = parsed.salon!;
        const [salon] = await tx.insert(salonsTable).values({
          ownerId: created.id, name: input.name, slug: input.slug, city: input.city,
          municipality: input.municipality, address: input.address, postalCode: input.postalCode,
          phone: input.phone, email: input.email, companyName: input.companyName,
          companyTaxId: input.companyTaxId, companyRegistrationNumber: input.companyRegistrationNumber,
          companyAddress: input.companyAddress, companyCity: input.companyCity,
          companyPostalCode: input.companyPostalCode, shortDescription: input.shortDescription,
          description: input.description,
          imageUrl: "https://images.unsplash.com/photo-1560066984-138dadb4c035?q=80&w=1200&auto=format&fit=crop",
          active: true,
        }).returning({ id: salonsTable.id });
        const binding = await bindLegalEntityBusinessInTx(tx, {
          pib: input.companyTaxId, legalName: input.companyName, ownerUserId: created.id, salonId: salon!.id,
        });
        await tx.update(salonsTable).set({ companyTaxId: binding.normalizedPib }).where(eq(salonsTable.id, salon!.id));
        await tx.update(usersTable).set({ activeSalonId: salon!.id, updatedAt: new Date() }).where(eq(usersTable.id, created.id));
      } else if (parsed.role === "SALON_EMPLOYEE") {
        const input = parsed.employee!;
        const [salon] = await tx.select({ id: salonsTable.id, ownerId: salonsTable.ownerId })
          .from(salonsTable).where(and(eq(salonsTable.id, input.salonId), eq(salonsTable.active, true)))
          .for("update").limit(1);
        if (!salon) throw new Error("SETUP_TARGET_SALON_NOT_FOUND");
        const [owner] = await tx.select({ active: usersTable.active }).from(usersTable)
          .where(eq(usersTable.id, salon.ownerId)).for("update").limit(1);
        if (!owner?.active) throw new Error("SETUP_TARGET_SALON_NOT_FOUND");
        const [employee] = await tx.insert(employeesTable).values({
          salonId: salon.id, userId: created.id, name: `${firstName} ${lastName}`,
          role: input.jobTitle, bio: input.bio ?? "", email,
          avatarUrl: "/lumera-media/therapist-1.jpg", active: true,
        }).returning({ id: employeesTable.id });
        await tx.insert(employeeLocationAssignmentsTable).values({
          employeeId: employee!.id, salonId: salon.id, active: true, isDefault: true,
        });
        await tx.update(usersTable).set({ activeSalonId: salon.id, updatedAt: new Date() }).where(eq(usersTable.id, created.id));
      } else if (parsed.role === "EDUKATIVNI_CENTAR") {
        const input = parsed.educationCenter!;
        const [center] = await tx.insert(educationCentersTable).values({
          ownerId: created.id, name: input.name, city: input.city, description: input.description,
          imageUrl: "https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?q=80&w=1200&auto=format&fit=crop",
          contactEmail: input.contactEmail, contactPhone: input.contactPhone,
          contactAddress: input.contactAddress, pib: input.pib,
        }).returning({ id: educationCentersTable.id });
        const binding = await bindLegalEntityBusinessInTx(tx, {
          pib: input.pib, legalName: input.name, ownerUserId: created.id, educationCenterId: center!.id,
        });
        await tx.update(educationCentersTable).set({ pib: binding.normalizedPib }).where(eq(educationCentersTable.id, center!.id));
      } else if (parsed.role === "INSTRUCTOR") {
        const input = parsed.instructor!;
        const [center] = await tx.select({ id: educationCentersTable.id, ownerId: educationCentersTable.ownerId })
          .from(educationCentersTable)
          .where(and(eq(educationCentersTable.id, input.centerId), notInArray(educationCentersTable.verificationStatus, ["rejected", "suspended"])))
          .for("update").limit(1);
        if (!center) throw new Error("SETUP_TARGET_CENTER_NOT_FOUND");
        const [owner] = await tx.select({ active: usersTable.active }).from(usersTable)
          .where(eq(usersTable.id, center.ownerId)).for("update").limit(1);
        if (!owner?.active) throw new Error("SETUP_TARGET_CENTER_NOT_FOUND");
        await tx.insert(educationInstructorsTable).values({
          centerId: center.id, userId: created.id, fullName: `${firstName} ${lastName}`,
          photoUrl: "/lumera-media/therapist-1.jpg", biography: input.biography ?? "",
          industryYears: input.industryYears ?? 0, experienceYears: input.experienceYears ?? 0,
          specializations: input.specializations ?? [], qualifications: input.qualifications ?? [],
        });
      }
      await tx.insert(customerPasswordSetupTokensTable).values({
        userId: created.id, issuedByUserId: admin.id, tokenHash: customerSetupDigest(rawToken),
        expiresAt, maxAttempts: CUSTOMER_SETUP_MAX_ATTEMPTS,
      });
      await tx.insert(customerPasswordSetupAuditsTable).values({
        administratorUserId: admin.id, targetUserId: created.id, action: "CUSTOMER_CREATED",
      });
      return created;
    });
    if (!account) { res.status(409).json({ error: "Korisnik sa ovom e-mail adresom već postoji." }); return; }
    res.status(201).json({
      user: { id: account.id, firstName: account.firstName, lastName: account.lastName, email: account.email, phone: account.phone, role: account.role, active: account.active, passwordSetAt: account.passwordSetAt?.toISOString() ?? null, createdAt: account.createdAt.toISOString() },
      setupUrl: `${setupBaseUrl}/postavi-lozinku#token=${encodeURIComponent(rawToken)}`, expiresAt: expiresAt.toISOString(),
    });
  } catch (error) {
    if (["40001", "40P01"].includes((error as { code?: string }).code ?? "")) {
      res.status(409).json({ error: "Istovremeno kreiranje poslovnog naloga je u toku. Osvežite podatke i pokušajte ponovo." });
      return;
    }
    if (error instanceof LegalEntityOwnerConflictError) {
      res.status(409).json({ error: error.message, code: error.code, normalizedPib: error.normalizedPib, outcome: "cross_account_conflict" });
      return;
    }
    if (error instanceof Error && error.message === "SETUP_TARGET_SALON_NOT_FOUND") {
      res.status(404).json({ error: "Aktivni salon nije pronađen." }); return;
    }
    if (error instanceof Error && error.message === "SETUP_TARGET_CENTER_NOT_FOUND") {
      res.status(404).json({ error: "Aktivni edukativni centar nije pronađen." }); return;
    }
    if ((error as { code?: string }).code === "23505"
      || (error as { cause?: { code?: string } })?.cause?.code === "23505") {
      res.status(409).json({ error: "Nalog ili povezani poslovni podaci već postoje." });
      return;
    }
    throw error;
  }
});

router.post(["/admin/customers/:userId/setup", "/admin/accounts/:userId/setup"], async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsedParams = (req.path.startsWith("/admin/accounts/")
    ? AdminReissueAccountSetupParams
    : AdminReissueCustomerSetupParams).safeParse(req.params);
  if (!parsedParams.success) { res.status(404).json({ error: "Korisnik nije pronađen." }); return; }
  const admitted = await admitCustomerSetupRequest("issue", admin.id, 10, 60 * 60 * 1000);
  if (!admitted) { res.setHeader("Retry-After", "3600"); res.status(429).json({ error: "Previše zahteva. Pokušajte ponovo kasnije." }); return; }
  const rawToken = randomBytes(32).toString("base64url");
  const tokenHash = customerSetupDigest(rawToken);
  const expiresAt = new Date(Date.now() + CUSTOMER_SETUP_TTL_MS);
  const setupBaseUrl = customerSetupBaseUrl(req);
  const customer = await db.transaction(async (tx) => {
    const userId = parsedParams.data.userId;
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`customer-setup:${userId}`}))`);
    const [target] = await tx.select().from(usersTable).where(eq(usersTable.id, userId)).for("update").limit(1);
    if (!target || target.role === "SUPER_ADMIN" || !target.active || target.passwordSetAt) return null;
    await tx.update(customerPasswordSetupTokensTable)
      .set({ invalidatedAt: new Date() })
      .where(and(eq(customerPasswordSetupTokensTable.userId, target.id), isNull(customerPasswordSetupTokensTable.consumedAt), isNull(customerPasswordSetupTokensTable.invalidatedAt)));
    await tx.insert(customerPasswordSetupTokensTable).values({
      userId: target.id, issuedByUserId: admin.id, tokenHash, expiresAt, maxAttempts: CUSTOMER_SETUP_MAX_ATTEMPTS,
    });
    await tx.insert(customerPasswordSetupAuditsTable).values({
      administratorUserId: admin.id, targetUserId: target.id, action: "CUSTOMER_CREATED",
    });
    return target;
  });
  if (!customer) { res.status(404).json({ error: "Korisnik nije pronađen." }); return; }
  res.status(201).json({
    user: { id: customer.id, firstName: customer.firstName, lastName: customer.lastName, email: customer.email, phone: customer.phone, role: customer.role, active: customer.active, passwordSetAt: customer.passwordSetAt?.toISOString() ?? null, createdAt: customer.createdAt.toISOString() },
    setupUrl: `${setupBaseUrl}/postavi-lozinku#token=${encodeURIComponent(rawToken)}`,
    expiresAt: expiresAt.toISOString(),
  });
});

router.post("/admin/users/:userId/business-conversion", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsedParams = AdminConvertUserToBusinessAccountParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const contractBody = AdminConvertUserToBusinessAccountBody.safeParse(req.body);
  if (!contractBody.success) {
    res.status(422).json({ error: "Unesite tačno one poslovne podatke koji odgovaraju izabranoj ulozi." });
    return;
  }
  // Zod normalizes valid objects by stripping unknown keys. The conversion
  // contract intentionally has exact role-specific shapes, so validate the
  // unmodified request as well before accepting normalized input.
  const parsed = parseAdminBusinessConversionInput(req.body);
  if (!parsed) {
    res.status(422).json({ error: "Unesite tačno one poslovne podatke koji odgovaraju izabranoj ulozi." });
    return;
  }

  try {
    const result = await db.transaction(async (tx) => {
      const userId = parsedParams.data.userId;
      const resources: BusinessMutationResource[] = parsed.role === "SALON_EMPLOYEE"
        ? [{ kind: "salon", id: parsed.employee!.salonId }]
        : parsed.role === "INSTRUCTOR"
          ? [{ kind: "education-center", id: parsed.instructor!.centerId }]
          : [];
      await lockBusinessMutationParticipants(tx, {
        userIds: [userId],
        resources,
        discoverUserIds: async () => {
          if (parsed.role === "SALON_EMPLOYEE") {
            const [resource] = await tx.select({ ownerId: salonsTable.ownerId }).from(salonsTable)
              .where(eq(salonsTable.id, parsed.employee!.salonId)).limit(1);
            return resource ? [resource.ownerId] : [];
          }
          if (parsed.role === "INSTRUCTOR") {
            const [resource] = await tx.select({ ownerId: educationCentersTable.ownerId }).from(educationCentersTable)
              .where(eq(educationCentersTable.id, parsed.instructor!.centerId)).limit(1);
            return resource ? [resource.ownerId] : [];
          }
          return [];
        },
      });
      const [target] = await tx.select().from(usersTable)
        .where(eq(usersTable.id, userId)).for("update").limit(1);
      if (!target) return { status: "not-found" as const };

      const standaloneRoles = new Set(["ADMIN", "CUSTOMER", "STUDENT", "JOBSEEKER"]);
      if (!target.active || !standaloneRoles.has(target.role)) {
        return { status: "unsupported-source" as const };
      }

      // Role alone is not sufficient evidence of a standalone account. Lock and
      // reject every supported business companion before creating a new one.
      const [ownedSalon] = await tx.select({ id: salonsTable.id }).from(salonsTable)
        .where(eq(salonsTable.ownerId, target.id)).for("update").limit(1);
      const [employeeProfile] = await tx.select({ id: employeesTable.id }).from(employeesTable)
        .where(eq(employeesTable.userId, target.id)).for("update").limit(1);
      const [ownedCenter] = await tx.select({ id: educationCentersTable.id }).from(educationCentersTable)
        .where(eq(educationCentersTable.ownerId, target.id)).for("update").limit(1);
      const [instructorProfile] = await tx.select({ id: educationInstructorsTable.id }).from(educationInstructorsTable)
        .where(eq(educationInstructorsTable.userId, target.id)).for("update").limit(1);
      if (ownedSalon || employeeProfile || ownedCenter || instructorProfile || target.activeSalonId) {
        return { status: "unsupported-source" as const };
      }

      if (parsed.role === "SALON_OWNER") {
        const input = parsed.salon!;
        const [salon] = await tx.insert(salonsTable).values({
          ownerId: target.id, name: input.name, slug: input.slug, city: input.city,
          municipality: input.municipality, address: input.address, postalCode: input.postalCode,
          phone: input.phone, email: input.email, companyName: input.companyName,
          companyTaxId: input.companyTaxId, companyRegistrationNumber: input.companyRegistrationNumber,
          companyAddress: input.companyAddress, companyCity: input.companyCity,
          companyPostalCode: input.companyPostalCode, shortDescription: input.shortDescription,
          description: input.description,
          imageUrl: "https://images.unsplash.com/photo-1560066984-138dadb4c035?q=80&w=1200&auto=format&fit=crop",
          active: true,
        }).returning({ id: salonsTable.id });
        if (!salon) throw new Error("Business conversion salon insert returned no row.");
        const binding = await bindLegalEntityBusinessInTx(tx, {
          pib: input.companyTaxId, legalName: input.companyName, ownerUserId: target.id, salonId: salon.id,
        });
        await tx.update(salonsTable).set({ companyTaxId: binding.normalizedPib }).where(eq(salonsTable.id, salon.id));
        await tx.update(usersTable).set({
          role: parsed.role, activeSalonId: salon.id, updatedAt: new Date(),
        }).where(eq(usersTable.id, target.id));
      } else if (parsed.role === "SALON_EMPLOYEE") {
        const input = parsed.employee!;
        const [salon] = await tx.select({ id: salonsTable.id, ownerId: salonsTable.ownerId })
          .from(salonsTable).where(and(eq(salonsTable.id, input.salonId), eq(salonsTable.active, true)))
          .for("update").limit(1);
        if (!salon) throw new Error("CONVERSION_TARGET_SALON_NOT_FOUND");
        const [owner] = await tx.select({ active: usersTable.active }).from(usersTable)
          .where(eq(usersTable.id, salon.ownerId)).for("update").limit(1);
        if (!owner?.active) throw new Error("CONVERSION_TARGET_SALON_NOT_FOUND");
        const [employee] = await tx.insert(employeesTable).values({
          salonId: salon.id, userId: target.id, name: `${target.firstName} ${target.lastName}`,
          role: input.jobTitle, bio: input.bio ?? "", email: target.email,
          avatarUrl: "/lumera-media/therapist-1.jpg", active: true,
        }).returning({ id: employeesTable.id });
        if (!employee) throw new Error("Business conversion employee insert returned no row.");
        await tx.insert(employeeLocationAssignmentsTable).values({
          employeeId: employee.id, salonId: salon.id, active: true, isDefault: true,
        });
        await tx.update(usersTable).set({
          role: parsed.role, activeSalonId: salon.id, updatedAt: new Date(),
        }).where(eq(usersTable.id, target.id));
      } else if (parsed.role === "EDUKATIVNI_CENTAR") {
        const input = parsed.educationCenter!;
        const [center] = await tx.insert(educationCentersTable).values({
          ownerId: target.id, name: input.name, city: input.city, description: input.description,
          imageUrl: "https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?q=80&w=1200&auto=format&fit=crop",
          contactEmail: input.contactEmail, contactPhone: input.contactPhone,
          contactAddress: input.contactAddress, pib: input.pib,
        }).returning({ id: educationCentersTable.id });
        if (!center) throw new Error("Business conversion education insert returned no row.");
        const binding = await bindLegalEntityBusinessInTx(tx, {
          pib: input.pib, legalName: input.name, ownerUserId: target.id, educationCenterId: center.id,
        });
        await tx.update(educationCentersTable).set({ pib: binding.normalizedPib }).where(eq(educationCentersTable.id, center.id));
        await tx.update(usersTable).set({
          role: parsed.role, activeSalonId: null, updatedAt: new Date(),
        }).where(eq(usersTable.id, target.id));
      } else {
        const input = parsed.instructor!;
        const [center] = await tx.select({ id: educationCentersTable.id, ownerId: educationCentersTable.ownerId })
          .from(educationCentersTable)
          .where(and(eq(educationCentersTable.id, input.centerId), notInArray(educationCentersTable.verificationStatus, ["rejected", "suspended"])))
          .for("update").limit(1);
        if (!center) throw new Error("CONVERSION_TARGET_CENTER_NOT_FOUND");
        const [owner] = await tx.select({ active: usersTable.active }).from(usersTable)
          .where(eq(usersTable.id, center.ownerId)).for("update").limit(1);
        if (!owner?.active) throw new Error("CONVERSION_TARGET_CENTER_NOT_FOUND");
        await tx.insert(educationInstructorsTable).values({
          centerId: center.id, userId: target.id, fullName: `${target.firstName} ${target.lastName}`,
          photoUrl: "/lumera-media/therapist-1.jpg", biography: input.biography ?? "",
          industryYears: input.industryYears ?? 0, experienceYears: input.experienceYears ?? 0,
          specializations: input.specializations ?? [], qualifications: input.qualifications ?? [],
        });
        await tx.update(usersTable).set({ role: parsed.role, updatedAt: new Date() })
          .where(eq(usersTable.id, target.id));
      }

      const [updated] = await tx.select().from(usersTable)
        .where(eq(usersTable.id, target.id)).limit(1);
      if (!updated) throw new Error("Converted account disappeared.");
      return { status: "converted" as const, user: updated };
    });

    if (result.status === "not-found") { res.status(404).json({ error: "Korisnik nije pronađen." }); return; }
    if (result.status === "unsupported-source") {
      res.status(422).json({ error: "Konverzija je dozvoljena samo za aktivan samostalni nalog bez poslovnih veza." });
      return;
    }
    const updated = result.user;
    res.json(AdminConvertUserToBusinessAccountResponse.parse({
      id: updated.id, firstName: updated.firstName, lastName: updated.lastName,
      email: updated.email, phone: updated.phone, role: updated.role, active: updated.active,
      passwordSetAt: updated.passwordSetAt?.toISOString() ?? null,
      createdAt: updated.createdAt.toISOString(),
    }));
  } catch (error) {
    if (error instanceof LegalEntityOwnerConflictError) {
      res.status(409).json({ error: error.message, code: error.code, normalizedPib: error.normalizedPib, outcome: "cross_account_conflict" });
      return;
    }
    if (error instanceof Error && error.message === "CONVERSION_TARGET_SALON_NOT_FOUND") {
      res.status(404).json({ error: "Aktivni salon nije pronađen." }); return;
    }
    if (error instanceof Error && error.message === "CONVERSION_TARGET_CENTER_NOT_FOUND") {
      res.status(404).json({ error: "Aktivni edukativni centar nije pronađen." }); return;
    }
    if ((error as { code?: string }).code === "23505"
      || (error as { cause?: { code?: string } })?.cause?.code === "23505") {
      res.status(409).json({ error: "Nalog ili povezani poslovni podaci već postoje." });
      return;
    }
    throw error;
  }
});

type BusinessTransitionRows = {
  salons: Array<{ id: string; name: string; active: boolean }>;
  employees: Array<{ id: string; name: string; active: boolean }>;
  centers: Array<{ id: string; name: string; verificationStatus: string }>;
  instructors: Array<{ id: string; fullName: string }>;
};

function adminBusinessTransitionView(
  user: typeof usersTable.$inferSelect,
  rows: BusinessTransitionRows,
) {
  return {
    user: {
      id: user.id, firstName: user.firstName, lastName: user.lastName, email: user.email,
      phone: user.phone, role: user.role, active: user.active,
      passwordSetAt: user.passwordSetAt?.toISOString() ?? null,
      createdAt: user.createdAt.toISOString(),
    },
    salonOwnerships: rows.salons.map((row) => ({
      id: row.id, name: row.name, active: row.active,
      allowedActions: ["transfer", "deactivate", "retain"] as const,
    })),
    employments: rows.employees.map((row) => ({
      id: row.id, name: row.name, active: row.active,
      allowedActions: ["deactivate", "retain", "unlink"] as const,
    })),
    educationCenterOwnerships: rows.centers.map((row) => ({
      id: row.id, name: row.name,
      active: !["rejected", "suspended"].includes(row.verificationStatus),
      allowedActions: ["transfer", "deactivate", "retain"] as const,
    })),
    instructorRelations: rows.instructors.map((row) => ({
      id: row.id, name: row.fullName, active: true,
      allowedActions: ["retain", "unlink"] as const,
    })),
  };
}

router.get("/admin/users/:userId/business-role-transition", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsedParams = AdminGetBusinessRoleTransitionParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const state = await db.transaction(async (tx) => {
    const userId = parsedParams.data.userId;
    // Inspection is a repeatable-read snapshot, not a planning lock. Holding
    // no account/business row locks prevents an inspector from inverting the
    // resource-first mutation protocol while still returning one coherent view.
    await tx.execute(sql`set transaction isolation level repeatable read`);
    const [target] = await tx.select().from(usersTable)
      .where(eq(usersTable.id, userId)).limit(1);
    if (!target) return null;
    const salons = await tx.select({ id: salonsTable.id, name: salonsTable.name, active: salonsTable.active })
        .from(salonsTable).where(eq(salonsTable.ownerId, userId))
        .orderBy(asc(salonsTable.id));
    const employees = await tx.select({ id: employeesTable.id, name: employeesTable.name, active: employeesTable.active })
        .from(employeesTable).where(eq(employeesTable.userId, userId))
        .orderBy(asc(employeesTable.id));
    const centers = await tx.select({
        id: educationCentersTable.id, name: educationCentersTable.name,
        verificationStatus: educationCentersTable.verificationStatus,
      }).from(educationCentersTable).where(eq(educationCentersTable.ownerId, userId))
        .orderBy(asc(educationCentersTable.id));
    const instructors = await tx.select({
        id: educationInstructorsTable.id, fullName: educationInstructorsTable.fullName,
      }).from(educationInstructorsTable).where(eq(educationInstructorsTable.userId, userId))
        .orderBy(asc(educationInstructorsTable.id));
    return adminBusinessTransitionView(target, { salons, employees, centers, instructors });
  });
  if (!state) { res.status(404).json({ error: "Korisnik nije pronađen." }); return; }
  res.json(AdminGetBusinessRoleTransitionResponse.parse(state));
});

router.post("/admin/users/:userId/business-role-transition", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsedParams = AdminTransitionBusinessRoleParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const parsedBody = AdminTransitionBusinessRoleBody.safeParse(req.body);
  if (!parsedBody.success) { res.status(400).json({ error: parsedBody.error.message }); return; }
  const body = parsedBody.data;
  const userId = parsedParams.data.userId;

  const decisionLists = [
    body.salonOwnerships, body.employments, body.educationCenterOwnerships, body.instructorRelations,
  ];
  if (decisionLists.some((list) => new Set(list.map((item) => item.relationId)).size !== list.length)
    || body.salonOwnerships.some((item) => (item.action === "transfer") !== Boolean(item.targetUserId))
    || body.educationCenterOwnerships.some((item) => (item.action === "transfer") !== Boolean(item.targetUserId))) {
    res.status(422).json({ error: "Svaka poslovna veza mora imati tačno jednu potpunu odluku." });
    return;
  }

  try {
    const result = await db.transaction(async (tx) => {
      const transferIds = [
        ...body.salonOwnerships.map((item) => item.targetUserId),
        ...body.educationCenterOwnerships.map((item) => item.targetUserId),
      ].filter((id): id is string => Boolean(id));
      const salonResourceIds = [...new Set([
        ...body.salonOwnerships.map((item) => item.relationId),
        ...(body.activeSalonId ? [body.activeSalonId] : []),
      ])];
      const centerResourceIds = [...new Set(body.educationCenterOwnerships.map((item) => item.relationId))];
      const lockUserIds = await lockBusinessMutationParticipants(tx, {
        userIds: [userId, ...transferIds],
        resources: [
          ...salonResourceIds.map((id) => ({ kind: "salon" as const, id })),
          ...centerResourceIds.map((id) => ({ kind: "education-center" as const, id })),
        ],
      });
      const deactivatedCenterIds = body.educationCenterOwnerships
        .filter((item) => item.action === "deactivate")
        .map((item) => item.relationId)
        .sort();
      // Paid enrollment issuance uses the same center lock. Take it before any
      // center row lock so a shutdown cannot race a purchase into existence.
      for (const centerId of deactivatedCenterIds) {
        await lockEducationCenterFinancials(tx, centerId);
      }

      // Discover the legal-entity closure without row locks only after every
      // selected business resource is advisory-locked. Then lock entities and
      // every binding in deterministic order before any account/business row.
      const selectedBindings = salonResourceIds.length || centerResourceIds.length
        ? await tx.select({ legalEntityId: legalEntityBusinessesTable.legalEntityId })
          .from(legalEntityBusinessesTable).where(or(
            salonResourceIds.length ? inArray(legalEntityBusinessesTable.salonId, salonResourceIds) : undefined,
            centerResourceIds.length ? inArray(legalEntityBusinessesTable.educationCenterId, centerResourceIds) : undefined,
          ))
        : [];
      const legalEntityIds = [...new Set(selectedBindings.map((row) => row.legalEntityId))].sort();
      for (const id of legalEntityIds) {
        await tx.execute(sql`select pg_advisory_xact_lock(hashtext(${`business-legal-entity:${id}`}))`);
      }
      if (legalEntityIds.length) {
        await tx.select({ id: legalEntitiesTable.id }).from(legalEntitiesTable)
          .where(inArray(legalEntitiesTable.id, legalEntityIds)).orderBy(asc(legalEntitiesTable.id)).for("update");
      }
      const lockedLegalBindings = legalEntityIds.length
        ? await tx.select().from(legalEntityBusinessesTable)
          .where(inArray(legalEntityBusinessesTable.legalEntityId, legalEntityIds))
          .orderBy(asc(legalEntityBusinessesTable.legalEntityId), asc(legalEntityBusinessesTable.id)).for("update")
        : [];
      const lockedUsers = await tx.select().from(usersTable)
        .where(inArray(usersTable.id, lockUserIds)).orderBy(asc(usersTable.id)).for("update");
      const target = lockedUsers.find((row) => row.id === userId);
      if (!target) return { status: "not-found" as const };
      if (target.role === "SUPER_ADMIN") return { status: "unsafe" as const, message: "SUPER_ADMIN nalog se ne menja ovim tokom." };

      const salons = await tx.select({ id: salonsTable.id, name: salonsTable.name, active: salonsTable.active })
          .from(salonsTable).where(eq(salonsTable.ownerId, userId))
          .orderBy(asc(salonsTable.id)).for("update");
      const employees = await tx.select({ id: employeesTable.id, name: employeesTable.name, active: employeesTable.active })
          .from(employeesTable).where(eq(employeesTable.userId, userId))
          .orderBy(asc(employeesTable.id)).for("update");
      const centers = await tx.select({
          id: educationCentersTable.id, name: educationCentersTable.name,
          verificationStatus: educationCentersTable.verificationStatus,
        }).from(educationCentersTable).where(eq(educationCentersTable.ownerId, userId))
          .orderBy(asc(educationCentersTable.id)).for("update");
      const instructors = await tx.select({ id: educationInstructorsTable.id, fullName: educationInstructorsTable.fullName })
          .from(educationInstructorsTable).where(eq(educationInstructorsTable.userId, userId))
          .orderBy(asc(educationInstructorsTable.id)).for("update");
      const sameIds = (rows: Array<{ id: string }>, decisions: Array<{ relationId: string }>) =>
        rows.length === decisions.length
        && rows.every((row, index) => row.id === [...decisions].sort((a, b) => a.relationId.localeCompare(b.relationId))[index]?.relationId);
      if (!sameIds(salons, body.salonOwnerships)
        || !sameIds(employees, body.employments)
        || !sameIds(centers, body.educationCenterOwnerships)
        || !sameIds(instructors, body.instructorRelations)) {
        return { status: "unsafe" as const, message: "Spisak poslovnih veza je promenjen ili sadrži vezu drugog korisnika." };
      }
      if (deactivatedCenterIds.length) {
        const deactivatedCourses = await tx.select({ id: coursesTable.id }).from(coursesTable)
          .where(inArray(coursesTable.centerId, deactivatedCenterIds))
          .orderBy(asc(coursesTable.id))
          .for("update");
        if (await lockCurrentPurchasedEducationEntitlement(tx, deactivatedCourses.map((course) => course.id))) {
          return {
            status: "conflict" as const,
            message: "Centar nije moguće deaktivirati dok najmanje jedan polaznik ima važeći kupljeni pristup njegovom sadržaju.",
          };
        }
      }
      const salonTransfers = new Map(body.salonOwnerships
        .filter((item) => item.action === "transfer")
        .map((item) => [item.relationId, item.targetUserId!]));
      const centerTransfers = new Map(body.educationCenterOwnerships
        .filter((item) => item.action === "transfer")
        .map((item) => [item.relationId, item.targetUserId!]));
      for (const legalEntityId of legalEntityIds) {
        const closure = lockedLegalBindings.filter((binding) => binding.legalEntityId === legalEntityId);
        const resultingOwners = new Set(closure.map((binding) =>
          (binding.salonId ? salonTransfers.get(binding.salonId) : undefined)
          ?? (binding.educationCenterId ? centerTransfers.get(binding.educationCenterId) : undefined)
          ?? binding.ownerUserId));
        if (resultingOwners.size !== 1) {
          return {
            status: "conflict" as const,
            message: "Svi saloni i edukativni centri istog pravnog lica moraju biti preneti istom vlasniku u jednoj transakciji.",
          };
        }
      }

      const usersById = new Map(lockedUsers.map((row) => [row.id, row]));
      for (const decision of body.salonOwnerships) {
        if (decision.action === "transfer") {
          const recipient = usersById.get(decision.targetUserId!);
          if (!recipient || recipient.id === userId || !recipient.active || recipient.role !== "SALON_OWNER") {
            return { status: "conflict" as const, message: "Primalac salona mora biti drugi aktivan vlasnik salona." };
          }
        } else if (decision.action === "retain" && body.role !== "SALON_OWNER") {
          return { status: "unsafe" as const, message: "Aktivno vlasništvo salona zahteva ulogu vlasnika salona." };
        }
      }
      for (const decision of body.educationCenterOwnerships) {
        if (decision.action === "transfer") {
          const recipient = usersById.get(decision.targetUserId!);
          if (!recipient || recipient.id === userId || !recipient.active || recipient.role !== "EDUKATIVNI_CENTAR") {
            return { status: "conflict" as const, message: "Primalac centra mora biti drugi aktivan vlasnik edukativnog centra." };
          }
        } else if (decision.action === "retain" && body.role !== "EDUKATIVNI_CENTAR") {
          return { status: "unsafe" as const, message: "Aktivno vlasništvo centra zahteva ulogu vlasnika centra." };
        }
      }
      if (body.employments.some((item) => item.action === "retain") && body.role !== "SALON_EMPLOYEE") {
        return { status: "unsafe" as const, message: "Aktivno zaposlenje zahteva ulogu zaposlenog." };
      }
      if (body.instructorRelations.some((item) => item.action === "retain") && body.role !== "INSTRUCTOR") {
        return { status: "unsafe" as const, message: "Aktivna instruktorska veza zahteva ulogu instruktora." };
      }

      const retainedSalonIds = new Set(body.salonOwnerships.filter((item) => item.action === "retain").map((item) => item.relationId));
      const retainedEmployeeIds = new Set(body.employments.filter((item) => item.action === "retain").map((item) => item.relationId));
      const retainedCenterIds = new Set(body.educationCenterOwnerships.filter((item) => item.action === "retain").map((item) => item.relationId));
      const retainedInstructorIds = new Set(body.instructorRelations.filter((item) => item.action === "retain").map((item) => item.relationId));
      if ((body.role === "SALON_OWNER" && !salons.some((row) => row.active && retainedSalonIds.has(row.id)))
        || (body.role === "SALON_EMPLOYEE" && !employees.some((row) => row.active && retainedEmployeeIds.has(row.id)))
        || (body.role === "EDUKATIVNI_CENTAR" && !centers.some((row) => !["rejected", "suspended"].includes(row.verificationStatus) && retainedCenterIds.has(row.id)))
        || (body.role === "INSTRUCTOR" && retainedInstructorIds.size === 0)) {
        return { status: "unsafe" as const, message: "Izabrana poslovna uloga ne sme ostati bez aktivne odgovarajuće veze." };
      }
      if (body.activeSalonId) {
        const owned = salons.some((row) => row.id === body.activeSalonId && row.active && retainedSalonIds.has(row.id));
        const retainedEmployees = employees.filter((row) => retainedEmployeeIds.has(row.id) && row.active);
        let employed = false;
        if (retainedEmployees.length) {
          const [assignment] = await tx.select({ id: employeeLocationAssignmentsTable.id })
            .from(employeeLocationAssignmentsTable).where(and(
              inArray(employeeLocationAssignmentsTable.employeeId, retainedEmployees.map((row) => row.id)),
              eq(employeeLocationAssignmentsTable.salonId, body.activeSalonId),
              eq(employeeLocationAssignmentsTable.active, true),
            )).for("update").limit(1);
          employed = Boolean(assignment);
        }
        if (!owned && !employed) {
          return { status: "unsafe" as const, message: "Aktivni salon mora pripadati zadržanoj aktivnoj poslovnoj vezi korisnika." };
        }
      }

      for (const decision of body.salonOwnerships) {
        if (decision.action === "transfer") {
          await tx.update(salonsTable).set({ ownerId: decision.targetUserId! }).where(and(
            eq(salonsTable.id, decision.relationId), eq(salonsTable.ownerId, userId),
          ));
          await tx.update(legalEntityBusinessesTable).set({ ownerUserId: decision.targetUserId! })
            .where(eq(legalEntityBusinessesTable.salonId, decision.relationId));
          const recipient = usersById.get(decision.targetUserId!)!;
          if (!recipient.activeSalonId) {
            await tx.update(usersTable).set({ activeSalonId: decision.relationId, updatedAt: new Date() })
              .where(eq(usersTable.id, recipient.id));
          }
        } else if (decision.action === "deactivate") {
          await tx.update(salonsTable).set({ active: false }).where(and(
            eq(salonsTable.id, decision.relationId), eq(salonsTable.ownerId, userId),
          ));
        }
      }
      for (const decision of body.employments) {
        if (decision.action === "deactivate") {
          await tx.update(employeesTable).set({ active: false }).where(and(
            eq(employeesTable.id, decision.relationId), eq(employeesTable.userId, userId),
          ));
          await tx.update(employeeLocationAssignmentsTable).set({ active: false, isDefault: false, updatedAt: new Date() })
            .where(eq(employeeLocationAssignmentsTable.employeeId, decision.relationId));
        } else if (decision.action === "unlink") {
          await tx.update(employeesTable).set({ userId: null }).where(and(
            eq(employeesTable.id, decision.relationId), eq(employeesTable.userId, userId),
          ));
        }
      }
      for (const decision of body.educationCenterOwnerships) {
        if (decision.action === "transfer") {
          await tx.update(educationCentersTable).set({
            ownerId: decision.targetUserId!, updatedAt: new Date(),
          }).where(and(eq(educationCentersTable.id, decision.relationId), eq(educationCentersTable.ownerId, userId)));
          await tx.update(legalEntityBusinessesTable).set({ ownerUserId: decision.targetUserId! })
            .where(eq(legalEntityBusinessesTable.educationCenterId, decision.relationId));
        } else if (decision.action === "deactivate") {
          await tx.update(educationCentersTable).set({
            verificationStatus: "suspended", verificationNote: "Deaktivirano tokom bezbedne promene poslovne uloge.",
            updatedAt: new Date(),
          }).where(and(eq(educationCentersTable.id, decision.relationId), eq(educationCentersTable.ownerId, userId)));
        }
      }
      for (const decision of body.instructorRelations) {
        if (decision.action === "unlink") {
          await tx.update(educationInstructorsTable).set({ userId: null, updatedAt: new Date() }).where(and(
            eq(educationInstructorsTable.id, decision.relationId), eq(educationInstructorsTable.userId, userId),
          ));
          // Course and profile history remain; only live account authorization
          // is severed so an old course cannot continue granting instructor access.
          await tx.update(coursesTable).set({ instructorId: null, updatedAt: new Date() })
            .where(eq(coursesTable.instructorProfileId, decision.relationId));
        }
      }

      const [updated] = await tx.update(usersTable).set({
        role: body.role, active: body.active, activeSalonId: body.activeSalonId, updatedAt: new Date(),
      }).where(eq(usersTable.id, userId)).returning();
      if (!updated) throw new Error("Transition target disappeared.");
      const nextSalons = await tx.select({ id: salonsTable.id, name: salonsTable.name, active: salonsTable.active }).from(salonsTable)
        .where(eq(salonsTable.ownerId, userId)).orderBy(asc(salonsTable.id));
      const nextEmployees = await tx.select({ id: employeesTable.id, name: employeesTable.name, active: employeesTable.active }).from(employeesTable)
        .where(eq(employeesTable.userId, userId)).orderBy(asc(employeesTable.id));
      const nextCenters = await tx.select({ id: educationCentersTable.id, name: educationCentersTable.name, verificationStatus: educationCentersTable.verificationStatus })
        .from(educationCentersTable).where(eq(educationCentersTable.ownerId, userId)).orderBy(asc(educationCentersTable.id));
      const nextInstructors = await tx.select({ id: educationInstructorsTable.id, fullName: educationInstructorsTable.fullName })
        .from(educationInstructorsTable).where(eq(educationInstructorsTable.userId, userId)).orderBy(asc(educationInstructorsTable.id));
      return {
        status: "updated" as const,
        state: adminBusinessTransitionView(updated, {
          salons: nextSalons, employees: nextEmployees, centers: nextCenters, instructors: nextInstructors,
        }),
      };
    });
    if (result.status === "not-found") { res.status(404).json({ error: "Korisnik nije pronađen." }); return; }
    if (result.status === "conflict") { res.status(409).json({ error: result.message }); return; }
    if (result.status === "unsafe") { res.status(422).json({ error: result.message }); return; }
    res.json(AdminTransitionBusinessRoleResponse.parse(result.state));
  } catch (error) {
    if (["40001", "40P01"].includes((error as { code?: string }).code ?? "")) {
      res.status(409).json({ error: "Istovremena poslovna promena je u toku. Osvežite podatke i pokušajte ponovo." });
      return;
    }
    if ((error as { code?: string }).code === "23503") {
      res.status(409).json({ error: "Poslovna veza je promenjena tokom obrade. Osvežite podatke i pokušajte ponovo." });
      return;
    }
    throw error;
  }
});

router.patch("/admin/users/:userId", async (req, res): Promise<void> => {
  const admin = await requireSuperAdmin(req, res); if (!admin) return;
  const parsedParams = AdminUpdateUserParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const { userId } = parsedParams.data;
  const parsed = AdminUpdateUserBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const { role, active } = parsed.data;

  const result = await db.transaction(async (tx) => {
    // This is deliberately acquired before the global super-admin guard. The
    // business-conversion flow uses this same per-user lock, so a generic role
    // PATCH cannot observe a standalone account while a companion is being
    // created (or vice versa).
    await lockBusinessMutationParticipants(tx, { userIds: [userId] });
    await tx.execute(sql`select pg_advisory_xact_lock(hashtext('lumera_active_super_admin_guard'))`);
    const [target] = await tx.select().from(usersTable).where(eq(usersTable.id, userId)).for("update").limit(1);
    if (!target) return { status: "not-found" as const };
    const targetHasBusinessCompanion = adminAccountRoleObject[target.role as AdminBusinessAccountSetupInput["role"]] !== undefined;
    const nextNeedsBusinessCompanion = role !== undefined
      && adminAccountRoleObject[role as AdminBusinessAccountSetupInput["role"]] !== undefined;
    if (role !== undefined && role !== target.role && (targetHasBusinessCompanion || nextNeedsBusinessCompanion)) {
      return { status: "business-role-transition" as const };
    }

    const willRemoveActiveSuperAdmin =
      target.role === "SUPER_ADMIN" &&
      target.active &&
      ((role !== undefined && role !== "SUPER_ADMIN") || active === false);

    if (willRemoveActiveSuperAdmin) {
      const [activeSuperAdmins] = await tx.select({ count: count() }).from(usersTable)
        .where(and(eq(usersTable.role, "SUPER_ADMIN"), eq(usersTable.active, true)));
      if ((activeSuperAdmins?.count ?? 0) <= 1) return { status: "protected" as const };
    }

    const updates: Partial<typeof usersTable.$inferInsert> = {};
    if (role !== undefined) updates.role = role as typeof usersTable.role["_"]["data"];
    if (active !== undefined) updates.active = active;
    const [updated] = await tx.update(usersTable).set(updates).where(eq(usersTable.id, userId)).returning();
    return { status: "updated" as const, user: updated! };
  });

  if (result.status === "not-found") { res.status(404).json({ error: "Korisnik nije pronađen." }); return; }
  if (result.status === "business-role-transition") {
    res.status(422).json({ error: "Poslovne uloge se kreiraju i menjaju samo kroz tok koji istovremeno upravlja povezanim poslovnim profilom." });
    return;
  }
  if (result.status === "protected") {
    res.status(409).json({ error: "Nije moguće ukloniti ili deaktivirati poslednjeg aktivnog super administratora." });
    return;
  }
  const updated = result.user;

  res.json({
    id: updated!.id,
    firstName: updated!.firstName,
    lastName: updated!.lastName,
    email: updated!.email,
    phone: updated!.phone,
    role: updated!.role,
    active: updated!.active,
    passwordSetAt: updated!.passwordSetAt?.toISOString() ?? null,
    createdAt: updated!.createdAt.toISOString(),
  });
});

