router.get("/admin/products", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsed = AdminListProductsQueryParams.safeParse({
    ...req.query,
    page: req.query.page !== undefined ? Number(req.query.page) : undefined,
    pageSize: req.query.pageSize !== undefined ? Number(req.query.pageSize) : undefined,
  });
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const q = parsed.data;
  const filters: Parameters<typeof and>[0][] = [];
  const productIds = q.productIds
    ? [...new Set(q.productIds.split(",").map((id) => id.trim()).filter(Boolean))]
    : [];
  const productIdPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
  if (productIds.length > 100 || productIds.some((id) => !productIdPattern.test(id))) {
    res.status(400).json({ error: "Lista proizvoda nije ispravna." });
    return;
  }
  if (q.search) filters.push(sql`lower(${productsTable.name} || ' ' || ${productsTable.sku} || ' ' || coalesce(${productsTable.brand}, '') || ' ' || ${productsTable.description}) like ${`%${q.search.toLowerCase()}%`}`);
  if (q.category) filters.push(eq(productsTable.categoryName, q.category));
  if (q.subcategory) filters.push(eq(productsTable.subcategoryName, q.subcategory));
  if (q.brand) filters.push(sql`lower(${productsTable.brand}) = ${q.brand.toLowerCase()}`);
  if (q.supplierId) filters.push(eq(productsTable.supplierId, q.supplierId));
  if (productIds.length) filters.push(inArray(productsTable.id, productIds));
  if (q.market === "B2B") filters.push(eq(productsTable.professionalEnabled, true));
  if (q.market === "B2C") filters.push(eq(productsTable.retailEnabled, true));
  if (q.lowStock) filters.push(sql`${productsTable.stock} > 0 AND ${productsTable.stock} <= 5`);
  if (q.status === "in-stock") filters.push(gt(productsTable.stock, 0));
  if (q.status === "out-of-stock") filters.push(sql`${productsTable.stock} <= 0`);
  if (q.status === "new") filters.push(eq(productsTable.isNew, true));
  if (q.status === "on-sale") filters.push(activeProductSaleConditionSql("B2B"));
  if (q.status === "inactive") filters.push(eq(productsTable.active, false));
  const whereClause = filters.length ? and(...filters) : undefined;
  const sortBy = q.sortBy ?? "createdAt";
  const sortDir = (q.sortDir ?? "desc") === "asc" ? asc : desc;
  const sortExpr = sortBy === "name" ? sortDir(productsTable.name)
    : sortBy === "price" ? sortDir(sql`coalesce(${activeProductSalePriceSql("B2B")}, ${productsTable.price})`)
    : sortBy === "stock" ? sortDir(productsTable.stock)
    : sortDir(productsTable.createdAt);
  const page = q.page ?? 1;
  const pageSize = q.pageSize ?? 20;
  const offset = (page - 1) * pageSize;
  const [[countRow], items] = await Promise.all([
    db.select({ count: count() }).from(productsTable).where(whereClause),
    db.select().from(productsTable).where(whereClause).orderBy(sortExpr).limit(pageSize).offset(offset),
  ]);
  const total = Number(countRow?.count ?? 0);
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const treatments = await productTreatmentIds(items.map((item) => item.id));
  res.json({ items: items.map((item) => adminProductDto(item, treatments.get(item.id))), total, page, pageSize, totalPages });
});

router.post("/admin/products", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsed = AdminCreateProductBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const body = parsed.data;
  if (!body.supplierId) { res.status(400).json({ error: "Dobavljač je obavezan." }); return; }
  if (body.discountPrice != null && body.discountPrice >= body.price) {
    res.status(400).json({ error: "Akcijska cena mora biti niža od redovne cene." }); return;
  }
  if (body.discountPriceEndsAt && body.discountPrice == null) {
    res.status(400).json({ error: "Datum isteka B2B akcije zahteva akcijsku cenu." }); return;
  }
  if (body.publicDiscountPriceEndsAt && body.publicDiscountPrice == null) {
    res.status(400).json({ error: "Datum isteka B2C akcije zahteva javnu akcijsku cenu." }); return;
  }
  const publicError = publicStorefrontError(body);
  if (publicError) { res.status(400).json({ error: publicError }); return; }
  if (!body.categoryId) { res.status(400).json({ error: "Kategorija je obavezna." }); return; }
  const assignment = await categoryAssignment(body.categoryId, body.supplierId);
  if (!assignment) { res.status(404).json({ error: "Kategorija nije pronađena." }); return; }
  const [supplier] = await db.select().from(suppliersTable).where(eq(suppliersTable.id, body.supplierId)).limit(1);
  if (!supplier) { res.status(404).json({ error: "Dobavljač nije pronađen." }); return; }
  if ((body.retailEnabled && supplier.scope === "B2B") || (body.professionalEnabled && supplier.scope === "B2C")) {
    res.status(400).json({ error: "Izabrani kanali prodaje nisu dozvoljeni za dobavljača." }); return;
  }
  const variantError = validateVariantInventory(body.variants ?? null, body.stock);
  if (variantError) { res.status(400).json({ error: variantError }); return; }
  const merchandising = canonicalMerchandisingConfig(body);
  if (!merchandising.data) { res.status(400).json({ error: merchandising.error }); return; }
  const relationshipError = await validateMerchandisingRelationships(body.supplierId, null, merchandising.data);
  if (relationshipError) { res.status(400).json({ error: relationshipError }); return; }
  const needTagIds = [...new Set(body.needTagIds ?? [])];
  if (body.productTypeId) {
    const [type] = await db.select({ id: b2cProductTypesTable.id }).from(b2cProductTypesTable)
      .where(and(eq(b2cProductTypesTable.id, body.productTypeId), eq(b2cProductTypesTable.active, true))).limit(1);
    if (!type) { res.status(400).json({ error: "Tip proizvoda nije aktivan." }); return; }
  }
  if (needTagIds.length) {
    const tags = await db.select({ id: b2cNeedTagsTable.id }).from(b2cNeedTagsTable)
      .where(and(inArray(b2cNeedTagsTable.id, needTagIds), eq(b2cNeedTagsTable.active, true)));
    if (tags.length !== needTagIds.length) { res.status(400).json({ error: "Jedna ili više oznaka potreba nisu aktivne." }); return; }
  }
  const imageReferences = [...new Set([
    body.imageUrl, ...(body.images ?? []),
    ...(body.variants ?? []).flatMap((variant) => [variant.mainImageUrl, variant.swatch?.kind === "IMAGE" ? variant.swatch.imageUrl : undefined]).filter((url): url is string => Boolean(url)),
  ])];
  const imageOwnership = await Promise.all(imageReferences.map((url) => canClaimMediaReference({
    userId: user.id, url, scope: "product",
  })));
  if (imageOwnership.some((owned) => !owned)) {
    res.status(400).json({ error: "Proizvod sadrži fotografiju koja nije otpremljena sa ovog administratorskog naloga." }); return;
  }
  const [existingSku] = await db.select({ id: productsTable.id }).from(productsTable).where(eq(productsTable.sku, body.sku)).limit(1);
  if (existingSku) { res.status(409).json({ error: "Proizvod sa ovim SKU već postoji." }); return; }
  let product: typeof productsTable.$inferSelect | undefined;
  try {
    [product] = await db.transaction(async (tx) => {
      const relationshipIds = [...new Set([...merchandising.data!.similarProductIds, ...merchandising.data!.crossSellProductIds])];
      if (relationshipIds.length) {
        const locked = await tx.execute<{ id: string }>(sql`
          SELECT id FROM products
          WHERE id IN (${sql.join(relationshipIds.map((id) => sql`${id}`), sql`, `)})
            AND supplier_id = ${body.supplierId}
          FOR SHARE
        `);
        if (locked.rows.length !== relationshipIds.length) throw new ProductRelationshipConflictError();
      }
      const rows = await tx.insert(productsTable).values({
        supplierId: body.supplierId,
        name: body.name,
        ...assignment,
        brand: body.brand ?? null,
        description: body.description,
        shortDescription: body.shortDescription ?? null,
        imageUrl: body.imageUrl,
        images: body.images ?? [],
        price: body.price,
        costPriceRsd: body.costPriceRsd ?? null,
        averageDurationDays: body.averageDurationDays ?? null,
        discountPrice: body.discountPrice ?? null,
        discountPriceEndsAt: body.discountPriceEndsAt ? new Date(body.discountPriceEndsAt) : null,
        retailEnabled: body.retailEnabled ?? false,
        professionalEnabled: body.professionalEnabled ?? true,
        priceOnRequest: body.priceOnRequest ?? false,
        bulkMatrixEnabled: body.bulkMatrixEnabled ?? false,
        publicDescription: body.publicDescription?.trim() || null,
        publicPrice: body.publicPrice ?? null,
        publicDiscountPrice: body.publicDiscountPrice ?? null,
        publicDiscountPriceEndsAt: body.publicDiscountPriceEndsAt ? new Date(body.publicDiscountPriceEndsAt) : null,
        productTypeId: body.productTypeId ?? null,
        ingredients: body.ingredients?.trim() || null,
        usageInstructions: body.usageInstructions?.trim() || null,
        characteristics: body.characteristics ?? [],
        searchSynonyms: body.searchSynonyms?.map((value) => value.trim()) ?? [],
        stock: body.stock,
        sku: body.sku,
        unit: body.unit,
        weightGrams: body.weightGrams,
        isNew: body.isNew ?? false,
        isBestseller: body.isBestseller ?? false,
        variantType: body.variantType?.trim() || null,
        variants: body.variants ?? null,
        ...merchandising.data,
        loyaltyPricingExcluded: body.loyaltyPricingExcluded ?? false,
        active: body.active ?? true,
      }).returning();
      if (needTagIds.length) {
        await tx.insert(b2cProductNeedTagsTable).values(needTagIds.map((needTagId) => ({
          productId: rows[0]!.id, needTagId,
        })));
      }
      const treatmentTaxonomyIds = [...new Set(body.treatmentTaxonomyIds ?? [])];
      if (treatmentTaxonomyIds.length) {
        const activeTerms = await tx.select({ id: treatmentTaxonomyTable.id }).from(treatmentTaxonomyTable)
          .where(and(inArray(treatmentTaxonomyTable.id, treatmentTaxonomyIds), eq(treatmentTaxonomyTable.active, true)));
        if (activeTerms.length !== treatmentTaxonomyIds.length) throw new Error("aftercare_treatment_inactive");
        await tx.insert(productTreatmentMappingsTable).values(treatmentTaxonomyIds.map((treatmentId) => ({ productId: rows[0]!.id, treatmentId })));
      }
      await replaceProductUpsells(tx, rows[0]!, body.upsellProductIds ?? []);
      for (const url of imageReferences) {
        if (!await claimMediaReference({
          userId: user.id,
          url,
          scope: "product",
          resourceId: rows[0]!.id,
          visibility: rows[0]!.active ? "public" : "private",
        }, tx)) {
          throw new MediaClaimConflictError();
        }
      }
      return rows;
    });
  } catch (error) {
    if (error instanceof ProductRelationshipConflictError) {
      res.status(409).json({ error: "Povezani proizvod je promenjen tokom čuvanja." }); return;
    }
    if (error instanceof Error && error.message === "aftercare_treatment_inactive") {
      res.status(400).json({ error: "Jedan ili više tretmana ne postoje ili nisu aktivni." }); return;
    }
    if (!(error instanceof MediaClaimConflictError)) throw error;
    res.status(409).json({ error: "Jedna fotografija je u međuvremenu povezana sa drugim zapisom." });
    return;
  }
  res.status(201).json(adminProductDto(product!, body.treatmentTaxonomyIds ?? []));
});

router.post("/admin/products/bulk", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsed = AdminBulkUpdateProductsBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const { productIds, action, categoryId, pricePercent } = parsed.data;
  const products = await db.select().from(productsTable).where(inArray(productsTable.id, productIds));
  if (!products.length) { res.status(404).json({ error: "Nijedan proizvod nije pronađen." }); return; }
  let updated = 0;
  if (action === "activate" || action === "deactivate") {
    const revokedProductAssetIds = action === "deactivate"
      ? products.flatMap((product) => [product.imageUrl, ...product.images])
        .map(mediaAssetIdFromUrl)
        .filter((id): id is string => Boolean(id))
      : [];
    if (revokedProductAssetIds.length) {
      try {
        await requireMediaCachePurgeForVisibilityRevocation();
        await purgeMediaCacheForVisibilityRevocation(revokedProductAssetIds);
      } catch (error) {
        res.status(503).json({ error: error instanceof Error ? error.message : "Nije moguće bezbedno opozvati keš fotografija proizvoda." });
        return;
      }
    }
    let result: { id: string }[];
    try {
      result = await db.transaction(async (tx) => {
        if (action === "activate") {
          for (const product of products) {
            for (const url of [product.imageUrl, ...product.images]) {
              if (mediaAssetIdFromUrl(url) && !await claimMediaReference({
                userId: user.id,
                url,
                scope: "product",
                resourceId: product.id,
                visibility: "public",
              }, tx)) {
                throw new MediaClaimConflictError();
              }
            }
          }
        }
        const rows = await tx.update(productsTable).set({ active: action === "activate" }).where(inArray(productsTable.id, productIds))
          .returning({ id: productsTable.id });
      for (const product of products) {
        const urls = [product.imageUrl, ...product.images];
        if (action === "deactivate") {
          await releaseMediaReferenceClaims({
            urls,
            resourceId: product.id,
            visibility: "private",
          }, tx);
        }
      }
      return rows;
      });
    } catch (error) {
      if (!(error instanceof MediaClaimConflictError)) throw error;
      res.status(409).json({ error: "Jedna fotografija je u međuvremenu povezana sa drugim zapisom." });
      return;
    }
    updated = result.length;
  } else if (action === "set-new" || action === "unset-new") {
    const result = await db.update(productsTable).set({ isNew: action === "set-new" }).where(inArray(productsTable.id, productIds)).returning({ id: productsTable.id });
    updated = result.length;
  } else if (action === "set-category") {
    if (!categoryId) { res.status(400).json({ error: "categoryId je obavezan za promenu kategorije." }); return; }
    const [category] = await db.select().from(productCategoriesTable).where(eq(productCategoriesTable.id, categoryId)).limit(1);
    if (!category) { res.status(404).json({ error: "Kategorija nije pronađena." }); return; }
    const parent = category.parentId
      ? (await db.select().from(productCategoriesTable).where(eq(productCategoriesTable.id, category.parentId)).limit(1))[0]
      : null;
    const result = await db.update(productsTable).set({
      categoryId: category.id,
      categoryName: parent ? parent.name : category.name,
      subcategoryName: parent ? category.name : null,
    }).where(inArray(productsTable.id, productIds)).returning({ id: productsTable.id });
    updated = result.length;
  } else if (action === "adjust-price-percent") {
    if (pricePercent === undefined || pricePercent === 0) { res.status(400).json({ error: "pricePercent je obavezan za promenu cena." }); return; }
    for (const product of products) {
      const factor = 1 + pricePercent / 100;
      const newPrice = Math.max(1, Math.round(product.price * factor));
      const newDiscount = product.discountPrice != null ? Math.max(1, Math.round(product.discountPrice * factor)) : null;
      await db.update(productsTable).set({ price: newPrice, discountPrice: newDiscount }).where(eq(productsTable.id, product.id));
      updated += 1;
    }
  }
  res.json({ updated });
});

router.get("/admin/products/:productId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsed = AdminUpdateProductParams.safeParse(req.params);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const [product] = await db.select().from(productsTable).where(eq(productsTable.id, parsed.data.productId)).limit(1);
  if (!product) { res.status(404).json({ error: "Proizvod nije pronađen." }); return; }
  const treatments = await productTreatmentIds([product.id]);
  res.json(adminProductDto(product, treatments.get(product.id)));
});

router.patch("/admin/products/:productId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsedParams = AdminUpdateProductParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const { productId } = parsedParams.data;
  const [existing] = await db.select().from(productsTable).where(eq(productsTable.id, productId)).limit(1);
  if (!existing) { res.status(404).json({ error: "Proizvod nije pronađen." }); return; }
  const parsed = AdminUpdateProductBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const body = parsed.data;
  if (!Object.keys(body).length) { res.status(400).json({ error: "Pošaljite najmanje jedno polje za izmenu." }); return; }
  const nextPrice = body.price ?? existing.price;
  const nextDiscount = body.discountPrice !== undefined ? body.discountPrice : existing.discountPrice;
  if (nextDiscount != null && nextDiscount >= nextPrice) {
    res.status(400).json({ error: "Akcijska cena mora biti niža od redovne cene." }); return;
  }
  const nextDiscountEndsAt = body.discountPriceEndsAt !== undefined ? body.discountPriceEndsAt : existing.discountPriceEndsAt;
  const nextPublicDiscount = body.publicDiscountPrice !== undefined ? body.publicDiscountPrice : existing.publicDiscountPrice;
  const nextPublicDiscountEndsAt = body.publicDiscountPriceEndsAt !== undefined ? body.publicDiscountPriceEndsAt : existing.publicDiscountPriceEndsAt;
  if (nextDiscountEndsAt && nextDiscount == null) {
    res.status(400).json({ error: "Datum isteka B2B akcije zahteva akcijsku cenu." }); return;
  }
  if (nextPublicDiscountEndsAt && nextPublicDiscount == null) {
    res.status(400).json({ error: "Datum isteka B2C akcije zahteva javnu akcijsku cenu." }); return;
  }
  const publicError = publicStorefrontError({
    retailEnabled: body.retailEnabled ?? existing.retailEnabled,
    publicDescription: body.publicDescription !== undefined ? body.publicDescription : existing.publicDescription,
    publicPrice: body.publicPrice !== undefined ? body.publicPrice : existing.publicPrice,
    publicDiscountPrice: body.publicDiscountPrice !== undefined ? body.publicDiscountPrice : existing.publicDiscountPrice,
    variants: body.variants !== undefined ? body.variants : existing.variants,
  });
  if (publicError) { res.status(400).json({ error: publicError }); return; }
  if (body.sku && body.sku !== existing.sku) {
    const [skuTaken] = await db.select({ id: productsTable.id }).from(productsTable).where(eq(productsTable.sku, body.sku)).limit(1);
    if (skuTaken) { res.status(409).json({ error: "Proizvod sa ovim SKU već postoji." }); return; }
  }
  const nextStock = body.stock ?? existing.stock;
  const nextVariants = body.variants !== undefined ? body.variants : existing.variants;
  const variantError = validateVariantInventory(nextVariants, nextStock);
  if (variantError) { res.status(400).json({ error: variantError }); return; }
  const merchandising = canonicalMerchandisingConfig(body, {
    similarProductsMode: existing.similarProductsMode,
    similarProductIds: existing.similarProductIds,
    crossSellProductIds: existing.crossSellProductIds,
    quantityPricingTiers: existing.quantityPricingTiers,
    minimumOrderQuantity: existing.minimumOrderQuantity,
    deliveryBusinessDaysOverride: existing.deliveryBusinessDaysOverride,
    subscriptionAllowed: existing.subscriptionAllowed,
    subscriptionDiscountPercent: existing.subscriptionDiscountPercent,
  });
  if (!merchandising.data) { res.status(400).json({ error: merchandising.error }); return; }
  const nextImageUrl = body.imageUrl ?? existing.imageUrl;
  const nextImages = body.images ?? existing.images;
  const nextActive = body.active ?? existing.active;
  const imageReferences = [...new Set([
    nextImageUrl, ...nextImages,
    ...(nextVariants ?? []).flatMap((variant) => [variant.mainImageUrl, variant.swatch?.kind === "IMAGE" ? variant.swatch.imageUrl : undefined]).filter((url): url is string => Boolean(url)),
  ])];
  const imageOwnership = await Promise.all(imageReferences.map((url) => canClaimMediaReference({
    userId: user.id,
    url,
    scope: "product",
    resourceId: existing.id,
    existingUrls: [existing.imageUrl, ...existing.images],
  })));
  if (imageOwnership.some((owned) => !owned)) {
    res.status(400).json({ error: "Proizvod sadrži fotografiju koja nije otpremljena sa ovog administratorskog naloga." }); return;
  }
  const existingImageReferences = [...new Set([existing.imageUrl, ...existing.images])];
  const revokedProductAssetIds = [
    ...existingImageReferences
      .filter((url) => !imageReferences.includes(url))
      .map(mediaAssetIdFromUrl),
    ...(!nextActive ? existingImageReferences.map(mediaAssetIdFromUrl) : []),
  ].filter((id): id is string => Boolean(id));
  if (revokedProductAssetIds.length) {
    try {
      await requireMediaCachePurgeForVisibilityRevocation();
      await purgeMediaCacheForVisibilityRevocation(revokedProductAssetIds);
    } catch (error) {
      res.status(503).json({ error: error instanceof Error ? error.message : "Nije moguće bezbedno opozvati keš fotografija proizvoda." });
      return;
    }
  }
  let assignment: { categoryId: string; categoryName: string; subcategoryName: string | null } | null = null;
  const nextSupplierId = body.supplierId ?? existing.supplierId;
  if (body.categoryId !== undefined) {
    if (!body.categoryId) { res.status(400).json({ error: "Kategorija je obavezna." }); return; }
    assignment = await categoryAssignment(body.categoryId, nextSupplierId);
    if (!assignment) { res.status(404).json({ error: "Kategorija nije pronađena." }); return; }
  } else if (body.supplierId && body.supplierId !== existing.supplierId) {
    // Supplier cannot be swapped while retaining a category owned by another supplier.
    assignment = existing.categoryId ? await categoryAssignment(existing.categoryId, nextSupplierId) : null;
    if (existing.categoryId && !assignment) { res.status(400).json({ error: "Promena dobavljača zahteva kategoriju tog dobavljača." }); return; }
  }
  const [nextSupplier] = await db.select().from(suppliersTable).where(eq(suppliersTable.id, nextSupplierId)).limit(1);
  if (!nextSupplier) { res.status(404).json({ error: "Dobavljač nije pronađen." }); return; }
  if (((body.retailEnabled ?? existing.retailEnabled) && nextSupplier.scope === "B2B")
    || ((body.professionalEnabled ?? existing.professionalEnabled) && nextSupplier.scope === "B2C")) {
    res.status(400).json({ error: "Izabrani kanali prodaje nisu dozvoljeni za dobavljača." }); return;
  }
  const relationshipError = await validateMerchandisingRelationships(nextSupplierId, existing.id, merchandising.data);
  if (relationshipError) { res.status(400).json({ error: relationshipError }); return; }
  const needTagIds = body.needTagIds === undefined ? undefined : [...new Set(body.needTagIds)];
  const nextProductTypeId = body.productTypeId !== undefined ? body.productTypeId : existing.productTypeId;
  if (nextProductTypeId) {
    const [type] = await db.select({ id: b2cProductTypesTable.id }).from(b2cProductTypesTable)
      .where(and(eq(b2cProductTypesTable.id, nextProductTypeId), eq(b2cProductTypesTable.active, true))).limit(1);
    if (!type) { res.status(400).json({ error: "Tip proizvoda nije aktivan." }); return; }
  }
  if (needTagIds?.length) {
    const tags = await db.select({ id: b2cNeedTagsTable.id }).from(b2cNeedTagsTable)
      .where(and(inArray(b2cNeedTagsTable.id, needTagIds), eq(b2cNeedTagsTable.active, true)));
    if (tags.length !== needTagIds.length) { res.status(400).json({ error: "Jedna ili više oznaka potreba nisu aktivne." }); return; }
  }
  const managedImageReferences = imageReferences.filter((url) => mediaAssetIdFromUrl(url));
  let product: typeof productsTable.$inferSelect | undefined;
  try {
    [product] = await db.transaction(async (tx) => {
      await tx.execute(sql`SELECT id FROM products WHERE id = ${existing.id} FOR UPDATE`);
      if (nextSupplierId !== existing.supplierId) {
        const inboundRelationships = await tx.execute<{ id: string }>(sql`
          SELECT id
          FROM products
          WHERE id <> ${existing.id}
            AND (
              similar_product_ids @> jsonb_build_array(${existing.id}::text)
              OR cross_sell_product_ids @> jsonb_build_array(${existing.id}::text)
            )
          ORDER BY id
          FOR UPDATE
        `);
        if (inboundRelationships.rows.length) throw new ProductRelationshipConflictError();
      }
      const relationshipIds = [...new Set([...merchandising.data!.similarProductIds, ...merchandising.data!.crossSellProductIds])];
      if (relationshipIds.length) {
        const locked = await tx.execute<{ id: string }>(sql`
          SELECT id FROM products
          WHERE id IN (${sql.join(relationshipIds.map((id) => sql`${id}`), sql`, `)})
            AND supplier_id = ${nextSupplierId}
            AND id <> ${existing.id}
          FOR SHARE
        `);
        if (locked.rows.length !== relationshipIds.length) throw new ProductRelationshipConflictError();
      }
      for (const url of managedImageReferences) {
        if (!await claimMediaReference({
          userId: user.id,
          url,
          scope: "product",
          resourceId: existing.id,
          visibility: nextActive ? "public" : "private",
        }, tx)) {
          throw new MediaClaimConflictError();
        }
      }
      const rows = await tx.update(productsTable).set({
        supplierId: nextSupplierId,
        name: body.name ?? existing.name,
        categoryId: assignment?.categoryId ?? existing.categoryId,
        categoryName: assignment?.categoryName ?? existing.categoryName,
        subcategoryName: assignment ? assignment.subcategoryName : existing.subcategoryName,
        brand: body.brand !== undefined ? body.brand : existing.brand,
        description: body.description ?? existing.description,
        shortDescription: body.shortDescription !== undefined ? body.shortDescription : existing.shortDescription,
        imageUrl: nextImageUrl,
        images: nextImages,
        price: nextPrice,
        costPriceRsd: body.costPriceRsd !== undefined ? body.costPriceRsd : existing.costPriceRsd,
        averageDurationDays: body.averageDurationDays !== undefined ? body.averageDurationDays : existing.averageDurationDays,
        discountPrice: nextDiscount,
        discountPriceEndsAt: body.discountPriceEndsAt !== undefined
          ? body.discountPriceEndsAt ? new Date(body.discountPriceEndsAt) : null
          : existing.discountPriceEndsAt,
        retailEnabled: body.retailEnabled ?? existing.retailEnabled,
        professionalEnabled: body.professionalEnabled ?? existing.professionalEnabled,
        priceOnRequest: body.priceOnRequest ?? existing.priceOnRequest,
        bulkMatrixEnabled: body.bulkMatrixEnabled ?? existing.bulkMatrixEnabled,
        publicDescription: body.publicDescription !== undefined ? body.publicDescription?.trim() || null : existing.publicDescription,
        publicPrice: body.publicPrice !== undefined ? body.publicPrice : existing.publicPrice,
        publicDiscountPrice: body.publicDiscountPrice !== undefined ? body.publicDiscountPrice : existing.publicDiscountPrice,
        publicDiscountPriceEndsAt: body.publicDiscountPriceEndsAt !== undefined
          ? body.publicDiscountPriceEndsAt ? new Date(body.publicDiscountPriceEndsAt) : null
          : existing.publicDiscountPriceEndsAt,
        productTypeId: nextProductTypeId,
        ingredients: body.ingredients !== undefined ? body.ingredients?.trim() || null : existing.ingredients,
        usageInstructions: body.usageInstructions !== undefined ? body.usageInstructions?.trim() || null : existing.usageInstructions,
        characteristics: body.characteristics ?? existing.characteristics,
        searchSynonyms: body.searchSynonyms?.map((value) => value.trim()) ?? existing.searchSynonyms,
        stock: nextStock,
        sku: body.sku ?? existing.sku,
        unit: body.unit ?? existing.unit,
        weightGrams: body.weightGrams ?? existing.weightGrams,
        isNew: body.isNew ?? existing.isNew,
        isBestseller: body.isBestseller ?? existing.isBestseller,
        variantType: body.variantType !== undefined ? body.variantType?.trim() || null : existing.variantType,
        variants: nextVariants,
        ...merchandising.data,
        loyaltyPricingExcluded: body.loyaltyPricingExcluded ?? existing.loyaltyPricingExcluded,
        active: nextActive,
      }).where(and(
        eq(productsTable.id, productId),
        eq(productsTable.supplierId, existing.supplierId),
        eq(productsTable.similarProductsMode, existing.similarProductsMode),
        sql`${productsTable.similarProductIds} = ${JSON.stringify(existing.similarProductIds)}::jsonb`,
        sql`${productsTable.crossSellProductIds} = ${JSON.stringify(existing.crossSellProductIds)}::jsonb`,
        sql`${productsTable.quantityPricingTiers} = ${JSON.stringify(existing.quantityPricingTiers)}::jsonb`,
        eq(productsTable.minimumOrderQuantity, existing.minimumOrderQuantity),
        existing.deliveryBusinessDaysOverride === null
          ? isNull(productsTable.deliveryBusinessDaysOverride)
          : eq(productsTable.deliveryBusinessDaysOverride, existing.deliveryBusinessDaysOverride),
        eq(productsTable.subscriptionAllowed, existing.subscriptionAllowed),
        existing.subscriptionDiscountPercent === null
          ? isNull(productsTable.subscriptionDiscountPercent)
          : eq(productsTable.subscriptionDiscountPercent, existing.subscriptionDiscountPercent),
      )).returning();
      if (!rows.length) throw new ProductRelationshipConflictError();
      if (needTagIds !== undefined) {
        await tx.delete(b2cProductNeedTagsTable).where(eq(b2cProductNeedTagsTable.productId, existing.id));
        if (needTagIds.length) await tx.insert(b2cProductNeedTagsTable).values(needTagIds.map((needTagId) => ({
          productId: existing.id, needTagId,
        })));
      }
      if (body.treatmentTaxonomyIds !== undefined) {
        const treatmentTaxonomyIds = [...new Set(body.treatmentTaxonomyIds)];
        if (treatmentTaxonomyIds.length) {
          const activeTerms = await tx.select({ id: treatmentTaxonomyTable.id }).from(treatmentTaxonomyTable)
            .where(and(inArray(treatmentTaxonomyTable.id, treatmentTaxonomyIds), eq(treatmentTaxonomyTable.active, true)));
          if (activeTerms.length !== treatmentTaxonomyIds.length) throw new Error("aftercare_treatment_inactive");
        }
        await tx.delete(productTreatmentMappingsTable).where(eq(productTreatmentMappingsTable.productId, existing.id));
        if (treatmentTaxonomyIds.length) await tx.insert(productTreatmentMappingsTable)
          .values(treatmentTaxonomyIds.map((treatmentId) => ({ productId: existing.id, treatmentId })));
      }
      if (body.upsellProductIds !== undefined) {
        await replaceProductUpsells(tx, rows[0]!, body.upsellProductIds);
      }
      if (revokedProductAssetIds.length) {
        await releaseMediaReferenceClaims({
          urls: existingImageReferences.filter((url) => revokedProductAssetIds.includes(mediaAssetIdFromUrl(url) ?? "")),
          resourceId: existing.id,
          visibility: "private",
        }, tx);
      }
      return rows;
    });
  } catch (error) {
    if (error instanceof ProductRelationshipConflictError) {
      res.status(409).json({ error: "Povezani proizvod je promenjen tokom čuvanja." }); return;
    }
    if (error instanceof Error && error.message === "aftercare_treatment_inactive") {
      res.status(400).json({ error: "Jedan ili više tretmana ne postoje ili nisu aktivni." }); return;
    }
    if (!(error instanceof MediaClaimConflictError)) throw error;
    res.status(409).json({ error: "Jedna fotografija je u međuvremenu povezana sa drugim zapisom." });
    return;
  }
  const treatments = body.treatmentTaxonomyIds ?? (await productTreatmentIds([product!.id])).get(product!.id) ?? [];
  res.json(adminProductDto(product!, treatments));
});

router.delete("/admin/products/:productId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsedParams = AdminDeleteProductParams.safeParse(req.params);
  if (!parsedParams.success) { res.status(400).json({ error: parsedParams.error.message }); return; }
  const { productId } = parsedParams.data;
  const [existing] = await db.select().from(productsTable).where(eq(productsTable.id, productId)).limit(1);
  if (!existing) { res.status(404).json({ error: "Proizvod nije pronađen." }); return; }
  const revokedProductAssetIds = [...new Set([existing.imageUrl, ...existing.images])]
    .map(mediaAssetIdFromUrl)
    .filter((id): id is string => Boolean(id));
  if (revokedProductAssetIds.length) {
    try {
      await requireMediaCachePurgeForVisibilityRevocation();
      await purgeMediaCacheForVisibilityRevocation(revokedProductAssetIds);
    } catch (error) {
      res.status(503).json({ error: error instanceof Error ? error.message : "Nije moguće bezbedno opozvati keš fotografija proizvoda." });
      return;
    }
  }
  const [inOrders] = await db.select({ count: count() }).from(orderItemsTable).where(eq(orderItemsTable.productId, productId));
  if ((inOrders?.count ?? 0) > 0) {
    const [deactivated] = await db.transaction(async (tx) => {
      const rows = await tx.update(productsTable).set({ active: false }).where(eq(productsTable.id, productId)).returning();
      await releaseMediaReferenceClaims({
        urls: [existing.imageUrl, ...existing.images],
        resourceId: existing.id,
        visibility: "private",
      }, tx);
      return rows;
    });
    res.json(adminProductDto(deactivated!));
    return;
  }
  try {
    await db.transaction(async (tx) => {
      await tx.execute(sql`SELECT id FROM products WHERE id = ${productId} FOR UPDATE`);
      const inboundRelationships = await tx.execute<{ id: string }>(sql`
        SELECT id
        FROM products
        WHERE id <> ${productId}
          AND (
            similar_product_ids @> jsonb_build_array(${productId}::text)
            OR cross_sell_product_ids @> jsonb_build_array(${productId}::text)
          )
        ORDER BY id
        FOR UPDATE
      `);
      if (inboundRelationships.rows.length) throw new ProductRelationshipConflictError();
      await releaseMediaReferenceClaims({
        urls: [existing.imageUrl, ...existing.images],
        resourceId: existing.id,
        visibility: "private",
      }, tx);
      await tx.delete(productsTable).where(eq(productsTable.id, productId));
    });
  } catch (error) {
    if (!(error instanceof ProductRelationshipConflictError)) throw error;
    res.status(409).json({ error: "Proizvod je povezan sa drugim proizvodom i ne može biti obrisan." });
    return;
  }
  res.json(adminProductDto({ ...existing, active: false }));
});

