router.put("/admin/shop-settings", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const body = req.body as Record<string, unknown>;
  const integer = (value: unknown, min: number, max: number) => Number.isInteger(value) && (value as number) >= min && (value as number) <= max;
  if (typeof body.showLoyaltyPoints !== "boolean"
    || !integer(body.pointsPer100Rsd, 0, 1_000_000)
    || !integer(body.lowStockThreshold, 1, 1_000_000)
    || !integer(body.defaultDeliveryBusinessDays, 1, 365)
    || (body.retailCartReminderEnabled !== undefined && typeof body.retailCartReminderEnabled !== "boolean")
    || (body.retailCartReminderDelayHours !== undefined && !integer(body.retailCartReminderDelayHours, 1, 720))
    || (body.retailCartReminderBrevoTemplateId !== undefined && body.retailCartReminderBrevoTemplateId !== null && !integer(body.retailCartReminderBrevoTemplateId, 1, 2_147_483_647))
    || (body.retailCartReminderEnabled === true && !integer(body.retailCartReminderBrevoTemplateId, 1, 2_147_483_647))
    || !integer(body.freeShippingThreshold, 0, 2_147_483_647)
    || !integer(body.version, 1, 2_147_483_647)) {
    res.status(400).json({ error: "Neispravna podešavanja prodavnice." }); return;
  }
  const seller = body.seller;
  if (seller !== undefined && (!seller || typeof seller !== "object" || Object.values(seller).some((value) => typeof value !== "string" || value.trim().length > 300))) {
    res.status(400).json({ error: "Unesite ispravne podatke prodavca." }); return;
  }
  const sellerFields = seller as Record<string, string> | undefined;
  if (sellerFields && !["companyName", "taxId", "registrationNumber", "address", "city", "postalCode", "bankAccount", "contactEmail", "contactPhone"].every((key) => sellerFields[key]?.trim())) {
    res.status(400).json({ error: "Svi podaci prodavca su obavezni za B2B fakture." }); return;
  }
  const result = await db.transaction(async (tx) => {
    const [current] = await tx.select().from(shopSettingsTable).limit(1).for("update");
    if (!current) throw new Error("shop_settings_missing");
    if (current.version !== body.version) return null;
    const [shipping] = await tx.select().from(shippingRulesTable).orderBy(asc(shippingRulesTable.id)).limit(1).for("update");
    if (!shipping) throw new Error("shop_shipping_missing");
    const [saved] = await tx.update(shopSettingsTable).set({
      showLoyaltyPoints: body.showLoyaltyPoints as boolean,
      pointsPer100Rsd: body.pointsPer100Rsd as number,
      lowStockThreshold: body.lowStockThreshold as number,
      defaultDeliveryBusinessDays: body.defaultDeliveryBusinessDays as number,
      retailCartReminderEnabled: body.retailCartReminderEnabled === undefined ? current.retailCartReminderEnabled : body.retailCartReminderEnabled as boolean,
      retailCartReminderDelayHours: body.retailCartReminderDelayHours === undefined ? current.retailCartReminderDelayHours : body.retailCartReminderDelayHours as number,
      retailCartReminderBrevoTemplateId: body.retailCartReminderBrevoTemplateId === undefined ? current.retailCartReminderBrevoTemplateId : body.retailCartReminderBrevoTemplateId as number | null,
      ...(sellerFields ? {
        sellerCompanyName: sellerFields.companyName.trim(), sellerTaxId: sellerFields.taxId.trim(),
        sellerRegistrationNumber: sellerFields.registrationNumber.trim(), sellerAddress: sellerFields.address.trim(),
        sellerCity: sellerFields.city.trim(), sellerPostalCode: sellerFields.postalCode.trim(),
        sellerBankAccount: sellerFields.bankAccount.trim(), sellerContactEmail: sellerFields.contactEmail.trim().toLowerCase(),
        sellerContactPhone: sellerFields.contactPhone.trim(),
      } : {}),
      version: current.version + 1,
      updatedAt: new Date(),
    }).where(eq(shopSettingsTable.id, current.id)).returning();
    const [savedShipping] = await tx.update(shippingRulesTable).set({
      freeShippingThreshold: body.freeShippingThreshold as number, updatedAt: new Date(),
    }).where(eq(shippingRulesTable.id, shipping.id)).returning();
    return { settings: saved!, shipping: savedShipping! };
  }).catch((error: unknown) => {
    if (error instanceof Error && (error.message === "shop_settings_missing" || error.message === "shop_shipping_missing")) return "missing" as const;
    throw error;
  });
  if (result === "missing") { res.status(503).json({ error: "Podešavanja prodavnice nisu inicijalizovana." }); return; }
  if (!result) { res.status(409).json({ error: "Podešavanja su izmenjena u međuvremenu.", code: "SETTINGS_VERSION_CONFLICT" }); return; }
  res.json(shopSettingsDto(result.settings, result.shipping.freeShippingThreshold));
});

router.get("/admin/shipping", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const config = await getShippingConfig();
  res.json({
    freeShippingThreshold: config.freeShippingThreshold, tiers: config.tiers,
    personalDeliveryEnabled: config.personalDeliveryEnabled, personalDeliveryName: config.personalDeliveryName,
    personalDeliveryPrice: config.personalDeliveryPrice, personalDeliveryDescription: config.personalDeliveryDescription,
    updatedAt: config.updatedAt.toISOString(),
  });
});

router.put("/admin/shipping", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsed = AdminUpdateShippingConfigBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const body = parsed.data;
  if (!body.personalDeliveryName.trim()) {
    res.status(400).json({ error: "Naziv lične dostave ne može biti prazan." });
    return;
  }
  const seen = new Set<number>();
  for (const tier of body.tiers) {
    if (seen.has(tier.maxWeightGrams)) { res.status(400).json({ error: "Dva ranga ne mogu imati istu maksimalnu težinu." }); return; }
    seen.add(tier.maxWeightGrams);
  }
  const existing = await getShippingConfig();
  const [config] = await db.update(shippingRulesTable).set({
    freeShippingThreshold: body.freeShippingThreshold,
    tiers: [...body.tiers].sort((a, b) => a.maxWeightGrams - b.maxWeightGrams),
    personalDeliveryEnabled: body.personalDeliveryEnabled,
    personalDeliveryName: body.personalDeliveryName,
    personalDeliveryPrice: body.personalDeliveryPrice,
    personalDeliveryDescription: body.personalDeliveryDescription,
    updatedAt: new Date(),
  }).where(eq(shippingRulesTable.id, existing.id)).returning();
  res.json({
    freeShippingThreshold: config!.freeShippingThreshold, tiers: config!.tiers,
    personalDeliveryEnabled: config!.personalDeliveryEnabled, personalDeliveryName: config!.personalDeliveryName,
    personalDeliveryPrice: config!.personalDeliveryPrice, personalDeliveryDescription: config!.personalDeliveryDescription,
    updatedAt: config!.updatedAt.toISOString(),
  });
});

// ── Admin Courier Service Catalog ─────────────────────────────────────────────

router.get("/admin/courier-services", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const services = await db.select().from(courierServicesTable).orderBy(asc(courierServicesTable.name));
  res.json(AdminListCourierServicesResponse.parse(services.map(courierServiceDto)));
});

router.post("/admin/courier-services", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const parsed = AdminCreateCourierServiceBody.safeParse(req.body);
  if (!parsed.success) { res.status(400).json({ error: parsed.error.message }); return; }
  const name = parsed.data.name.trim();
  if (!name) { res.status(400).json({ error: "Naziv kurirske službe ne može biti prazan." }); return; }
  const trackingUrlTemplate = cleanTrackingTemplate(parsed.data.trackingUrlTemplate);
  if (!validTrackingTemplate(trackingUrlTemplate)) {
    res.status(400).json({ error: "URL šablon mora koristiti http/https i sadržati {trackingNumber}." }); return;
  }
  const code = courierCode(name);
  const [existing] = await db.select({ id: courierServicesTable.id }).from(courierServicesTable)
    .where(or(eq(courierServicesTable.name, name), eq(courierServicesTable.code, code))).limit(1);
  if (existing) { res.status(409).json({ error: "Kurirska služba sa tim nazivom već postoji." }); return; }
  const [service] = await db.insert(courierServicesTable).values({
    code, name, trackingUrlTemplate, active: parsed.data.active ?? true,
  }).returning();
  res.status(201).json(AdminCreateCourierServiceResponse.parse(courierServiceDto(service!)));
});

router.patch("/admin/courier-services/:courierServiceId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const params = AdminUpdateCourierServiceParams.safeParse(req.params);
  const parsed = AdminUpdateCourierServiceBody.safeParse(req.body);
  if (!params.success || !parsed.success) { res.status(400).json({ error: !params.success ? params.error.message : parsed.error?.message ?? "Neispravan zahtev." }); return; }
  if (!Object.keys(parsed.data).length) { res.status(400).json({ error: "Pošaljite najmanje jedno polje za izmenu." }); return; }
  const [existing] = await db.select().from(courierServicesTable).where(eq(courierServicesTable.id, params.data.courierServiceId)).limit(1);
  if (!existing) { res.status(404).json({ error: "Kurirska služba nije pronađena." }); return; }
  const name = parsed.data.name?.trim();
  const trackingUrlTemplate = parsed.data.trackingUrlTemplate === undefined ? undefined : cleanTrackingTemplate(parsed.data.trackingUrlTemplate);
  if (!validTrackingTemplate(trackingUrlTemplate)) {
    res.status(400).json({ error: "URL šablon mora koristiti http/https i sadržati {trackingNumber}." }); return;
  }
  if (name && name !== existing.name) {
    const [sameName] = await db.select({ id: courierServicesTable.id }).from(courierServicesTable).where(eq(courierServicesTable.name, name)).limit(1);
    if (sameName) { res.status(409).json({ error: "Kurirska služba sa tim nazivom već postoji." }); return; }
  }
  const [service] = await db.update(courierServicesTable).set({
    ...(name ? { name } : {}),
    ...(trackingUrlTemplate !== undefined ? { trackingUrlTemplate } : {}),
    ...(parsed.data.active !== undefined ? { active: parsed.data.active } : {}),
    updatedAt: new Date(),
  }).where(eq(courierServicesTable.id, existing.id)).returning();
  res.json(AdminUpdateCourierServiceResponse.parse(courierServiceDto(service!)));
});

router.delete("/admin/courier-services/:courierServiceId", async (req, res): Promise<void> => {
  const user = await requireAdmin(req, res); if (!user) return;
  const params = AdminDeleteCourierServiceParams.safeParse(req.params);
  if (!params.success) { res.status(400).json({ error: params.error.message }); return; }
  const [deleted] = await db.delete(courierServicesTable).where(eq(courierServicesTable.id, params.data.courierServiceId)).returning();
  if (!deleted) { res.status(404).json({ error: "Kurirska služba nije pronađena." }); return; }
  res.sendStatus(204);
});

function couponDto(coupon: typeof couponsTable.$inferSelect) {
  return {
    ...coupon,
    startsAt: safeIsoTimestamp(coupon.startsAt),
    endsAt: safeIsoTimestamp(coupon.endsAt),
    createdAt: safeIsoTimestamp(coupon.createdAt),
    updatedAt: safeIsoTimestamp(coupon.updatedAt),
  };
}

function parseCouponInput(body: unknown) {
  if (!body || typeof body !== "object") return null;
  const value = body as Record<string, unknown>;
  const code = typeof value.code === "string" ? value.code.trim().toUpperCase() : "";
  const integerOrNull = (input: unknown) => input === null || input === undefined || input === ""
    ? null
    : Number.isInteger(input) ? input as number : Number.NaN;
  const stringIds = (input: unknown) => Array.isArray(input)
    ? [...new Set(input.filter((item): item is string => typeof item === "string" && /^[0-9a-f-]{36}$/i.test(item)))]
    : [];
  const startsAt = value.startsAt ? new Date(String(value.startsAt)) : null;
  const endsAt = value.endsAt ? new Date(String(value.endsAt)) : null;
  const discountValue = value.discountValue;
  const minimumSpendRsd = value.minimumSpendRsd ?? 0;
  const maximumSpendRsd = integerOrNull(value.maximumSpendRsd);
  const usageLimit = integerOrNull(value.usageLimit);
  const perCustomerUsageLimit = integerOrNull(value.perCustomerUsageLimit);
  if (!/^[A-Z0-9_-]{2,40}$/.test(code)
    || !["PERCENTAGE", "FIXED_RSD"].includes(String(value.discountType))
    || !Number.isInteger(discountValue) || (discountValue as number) <= 0
    || (value.discountType === "PERCENTAGE" && (discountValue as number) > 100)
    || !Number.isInteger(minimumSpendRsd) || (minimumSpendRsd as number) < 0
    || Number.isNaN(maximumSpendRsd) || (maximumSpendRsd !== null && maximumSpendRsd < (minimumSpendRsd as number))
    || Number.isNaN(usageLimit) || (usageLimit !== null && usageLimit < 1)
    || Number.isNaN(perCustomerUsageLimit) || (perCustomerUsageLimit !== null && perCustomerUsageLimit < 1)
    || (value.audience !== null && value.audience !== undefined && !["B2B", "B2C"].includes(String(value.audience)))
    || (startsAt && Number.isNaN(startsAt.getTime())) || (endsAt && Number.isNaN(endsAt.getTime()))
    || (startsAt && endsAt && endsAt <= startsAt)) return null;
  return {
    code,
    active: value.active !== false,
    audience: value.audience === "B2B" ? "B2B" as const : value.audience === "B2C" ? "B2C" as const : null,
    discountType: value.discountType as "PERCENTAGE" | "FIXED_RSD",
    discountValue: discountValue as number,
    startsAt, endsAt,
    minimumSpendRsd: minimumSpendRsd as number,
    maximumSpendRsd,
    freeShipping: value.freeShipping === true,
    includeProductIds: stringIds(value.includeProductIds),
    excludeProductIds: stringIds(value.excludeProductIds),
    includeCategoryIds: stringIds(value.includeCategoryIds),
    excludeCategoryIds: stringIds(value.excludeCategoryIds),
    includeBundleIds: stringIds(value.includeBundleIds),
    excludeBundleIds: stringIds(value.excludeBundleIds),
    usageLimit, perCustomerUsageLimit,
    updatedAt: new Date(),
  };
}

router.get("/admin/coupons", async (req, res): Promise<void> => {
  if (!await requireAdmin(req, res)) return;
  const coupons = await db.select().from(couponsTable).orderBy(desc(couponsTable.createdAt), asc(couponsTable.code));
  res.json(coupons.map(couponDto));
});

router.post("/admin/coupons", async (req, res): Promise<void> => {
  if (!await requireAdmin(req, res)) return;
  const input = parseCouponInput(req.body);
  if (!input) { res.status(400).json({ error: "Unesite ispravna pravila kupona." }); return; }
  const [duplicate] = await db.select({ id: couponsTable.id }).from(couponsTable).where(eq(couponsTable.code, input.code)).limit(1);
  if (duplicate) { res.status(409).json({ error: "Kupon sa tim kodom već postoji.", code: "COUPON_CODE_EXISTS" }); return; }
  const [coupon] = await db.insert(couponsTable).values(input).returning();
  res.status(201).json(couponDto(coupon!));
});

router.put("/admin/coupons/:couponId", async (req, res): Promise<void> => {
  if (!await requireAdmin(req, res)) return;
  const input = parseCouponInput(req.body);
  if (!input) { res.status(400).json({ error: "Unesite ispravna pravila kupona." }); return; }
  const [duplicate] = await db.select({ id: couponsTable.id }).from(couponsTable)
    .where(and(eq(couponsTable.code, input.code), ne(couponsTable.id, req.params.couponId))).limit(1);
  if (duplicate) { res.status(409).json({ error: "Kupon sa tim kodom već postoji.", code: "COUPON_CODE_EXISTS" }); return; }
  const [coupon] = await db.update(couponsTable).set(input).where(eq(couponsTable.id, req.params.couponId)).returning();
  if (!coupon) { res.status(404).json({ error: "Kupon nije pronađen." }); return; }
  res.json(couponDto(coupon));
});

router.delete("/admin/coupons/:couponId", async (req, res): Promise<void> => {
  if (!await requireAdmin(req, res)) return;
  const [coupon] = await db.update(couponsTable).set({ active: false, updatedAt: new Date() })
    .where(eq(couponsTable.id, req.params.couponId)).returning();
  if (!coupon) { res.status(404).json({ error: "Kupon nije pronađen." }); return; }
  res.status(204).send();
});

export default router;
